                for b = 0, 15 do
                    local x, y, v, w, p = a, b, 0, 0, 1
                    for _ = 1, 4 do
                        local q, r = x % 2, y % 2
                        if q == 1 and r == 1 then
                            v = v + p
                        end
                        if q ~= r then
                            w = w + p
                        end
