                        compiler,
                        "return {band=function(a,b)return (a & b) & 0xffffffff end,bxor=function(a,b)return (a ~ b) & 0xffffffff end,rrotate=function(a,n)return ((a >> n) | (a << (32-n))) & 0xffffffff end}"
                    )
                    if good and type(f) == "function" then
