            function M.sha256(s, raw, maxBytes)
                assert(type(s) == "string" and #s <= (maxBytes or 32768) and #s <= 16777216, "SHA256 input limit")
                local len = #s
                s = s
                    .. string.char(128)
                    .. string.rep("\0", (55 - len) % 64)
                    .. be(floor(len / 536870912))
                    .. be(len * 8 % U)
                local h =
                    { 0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19 }
                local w = {}
                for start = 1, #s, 64 do
                    for j = 0, 15 do
                        local a, b, c, d = s:byte(start + j * 4, start + j * 4 + 3)
                        w[j] = a * 16777216 + b * 65536 + c * 256 + d
                    end
                    for j = 16, 63 do
                        local x, y = w[j - 15], w[j - 2]
                        w[j] = (
                            w[j - 16]
                            + xor3(rr(x, 7), rr(x, 18), floor(x / 8))
                            + w[j - 7]
                            + xor3(rr(y, 17), rr(y, 19), floor(y / 1024))
                        ) % U
                    end
                    local a, b, c, d, e, f, g, z = h[1], h[2], h[3], h[4], h[5], h[6], h[7], h[8]
                    for j = 0, 63 do
