            local values = {}
            for i = 1, 64 do
                values[alphabet:sub(i, i)] = i - 1
            end
            function M.b64(s)
                assert(
                    type(s) == "string" and #s > 0 and #s <= 16384 and #s % 4 ~= 1 and not s:find("[^A-Za-z0-9_-]"),
                    "Invalid base64url"
