                local carry = 0
                for i = 1, k do
                    local v = a[i] * 2 + carry
                    a[i] = v % B
                    carry = floor(v / B)
                end
                if carry > 0 or ge(a, n, k) then
                    sub(a, n, k)
                end
            end
