                )
                local modulus = modulusHex:gsub("..", function(c)
                    return string.char(tonumber(c, 16))
                end)
                local n = fromBytes(modulus)
                local k = #n
                assert(n[k] >= 32768 and n[1] % 2 == 1, "Invalid RSA key")
                local inverse = 1
                for _ = 1, 5 do
                    inverse = (inverse * (2 - n[1] * inverse)) % B
                end
                inverse = -inverse % B
                local r2 = {}
                for i = 1, k do
                    r2[i] = 0
                end
                r2[1] = 1
                for _ = 1, k * 32 do
                    double(r2, n, k)
                end
                local one = {}
                for i = 1, k do
                    one[i] = 0
                end
                one[1] = 1
                local function mul(a, b)
                    local t = {}
                    for i = 1, 2 * k + 2 do
                        t[i] = 0
                    end
                    for i = 1, k do
                        local carry = 0
                        for j = 1, k do
                            local pos = i + j - 1
                            local v = t[pos] + a[i] * b[j] + carry
                            t[pos] = v % B
                            carry = floor(v / B)
                        end
                        t[i + k] = carry
                    end
