                        local m = t[i] * inverse % B
                        local carry = 0
                        for j = 1, k do
                            local pos = i + j - 1
                            local v = t[pos] + m * n[j] + carry
                            t[pos] = v % B
                            carry = floor(v / B)
                        end
                        local pos = i + k
                        while carry > 0 do
                            local v = t[pos] + carry
                            t[pos] = v % B
                            carry = floor(v / B)
                            pos = pos + 1
                        end
                    end
                    local a = {}
                    for i = 1, k do
                        a[i] = t[i + k]
                    end
