                local function ws()
                    while i <= n and raw:sub(i, i):match("%s") do
                        i = i + 1
                    end
                end
                local function str()
                    assert(raw:sub(i, i) == '"', "JSON string")
                    i = i + 1
                    local out = {}
                    while i <= n do
                        local c = raw:sub(i, i)
                        i = i + 1
                        if c == '"' then
                            return table.concat(out)
                        end
                        assert(c:byte() >= 32, "JSON control character")
                        if c == "\\" then
                            local e = raw:sub(i, i)
                            i = i + 1
                            local escapes =
                                { ['"'] = '"', ["\\"] = "\\", ["/"] = "/", b = "\b", f = "\f", n = "\n", r = "\r", t = "\t" }
                            if e == "u" then
                                local h = raw:sub(i, i + 3)
                                assert(#h == 4 and not h:find("[^%x]"), "JSON unicode")
