                            else
                                c = assert(escapes[e], "JSON escape")
                            end
                        end
                        out[#out + 1] = c
                    end
                    error("Unclosed JSON string")
                end
                ws()
                assert(raw:sub(i, i) == "{", "JSON object")
                i = i + 1
                ws()
                local out = {}
                if raw:sub(i, i) == "}" then
                    i = i + 1
                else
                    while true do
