                        assert(raw:sub(i, i) == ":", "JSON colon")
                        i = i + 1
                        ws()
                        local c = raw:sub(i, i)
                        if c == '"' then
                            out[key] = str()
                        else
                            local number = raw:sub(i):match("^%-?%d+")
                            assert(number and not number:match("^%-?0%d"), "JSON integer")
                            local v = tonumber(number)
                            assert(v and math.abs(v) <= 9007199254740991, "JSON integer range")
                            out[key] = v
                            i = i + #number
                        end
                        ws()
                        local endc = raw:sub(i, i)
                        i = i + 1
                        if endc == "}" then
                            break
                        end
                        assert(endc == ",", "JSON delimiter")
                        ws()
                    end
                end
                ws()
                assert(i == n + 1, "JSON trailing data")
                return out
            end
