                local head = M.flatJSON(M.b64(h))
                local count = 0
                for _ in pairs(head) do
                    count = count + 1
                end
                assert(count == 2 and head.alg == "RS256" and head.typ == typ, "Token type invalid")
                return M.flatJSON(M.b64(b))
            end
            return M
        end)()

        local MasterLicenseCore = (function()
            local Primitives = (function()
                local floor, abs, max = math.floor, math.abs, math.max
                local byte, char, format = string.byte, string.char, string.format
                local U32 = 4294967296
                local AND, XOR = {}, {}
                for a = 0, 15 do
                    for b = 0, 15 do
                        local av, bv, both, different, place = a, b, 0, 0, 1
                        for _ = 1, 4 do
                            local x, y = av % 2, bv % 2
                            if x == 1 and y == 1 then
                                both = both + place
                            end
                            if x ~= y then
                                different = different + place
                            end
                            av, bv, place = floor(av / 2), floor(bv / 2), place * 2
                        end
                        AND[a * 16 + b], XOR[a * 16 + b] = both, different
                    end
                end
                -- bitop
                local function bitop(a, b, lookup)
                    local value, place = 0, 1
                    for _ = 1, 8 do
                        value = value + lookup[(a % 16) * 16 + b % 16] * place
                        a, b, place = floor(a / 16), floor(b / 16), place * 16
                    end
                    return value
                end
                -- band
                local function band(a, b)
                    return bitop(a, b, AND)
                end
                -- bxor
                local function bxor(a, b)
                    return bitop(a, b, XOR)
                end
                -- rol
                local function rol(value, amount)
                    local divisor = 2 ^ (32 - amount)
                    return (value % divisor) * 2 ^ amount + floor(value / divisor)
                end
                -- little32
                local function little32(value)
                    return char(
                        value % 256,
                        floor(value / 256) % 256,
                        floor(value / 65536) % 256,
                        floor(value / 16777216) % 256
                    )
                end
                local K = {
                    0xd76aa478,
                    0xe8c7b756,
                    0x242070db,
                    0xc1bdceee,
                    0xf57c0faf,
                    0x4787c62a,
                    0xa8304613,
                    0xfd469501,
                    0x698098d8,
                    0x8b44f7af,
                    0xffff5bb1,
                    0x895cd7be,
                    0x6b901122,
                    0xfd987193,
                    0xa679438e,
                    0x49b40821,
                    0xf61e2562,
                    0xc040b340,
                    0x265e5a51,
                    0xe9b6c7aa,
                    0xd62f105d,
                    0x02441453,
                    0xd8a1e681,
                    0xe7d3fbc8,
                    0x21e1cde6,
                    0xc33707d6,
                    0xf4d50d87,
                    0x455a14ed,
                    0xa9e3e905,
                    0xfcefa3f8,
                    0x676f02d9,
                    0x8d2a4c8a,
                    0xfffa3942,
                    0x8771f681,
                    0x6d9d6122,
                    0xfde5380c,
                    0xa4beea44,
                    0x4bdecfa9,
                    0xf6bb4b60,
                    0xbebfbc70,
                    0x289b7ec6,
                    0xeaa127fa,
                    0xd4ef3085,
                    0x04881d05,
                    0xd9d4d039,
                    0xe6db99e5,
                    0x1fa27cf8,
                    0xc4ac5665,
                    0xf4292244,
                    0x432aff97,
                    0xab9423a7,
                    0xfc93a039,
                    0x655b59c3,
                    0x8f0ccc92,
                    0xffeff47d,
                    0x85845dd1,
                    0x6fa87e4f,
                    0xfe2ce6e0,
                    0xa3014314,
                    0x4e0811a1,
                    0xf7537e82,
                    0xbd3af235,
                    0x2ad7d2bb,
                    0xeb86d391,
                }
                local SHIFT = { 7, 12, 17, 22, 5, 9, 14, 20, 4, 11, 16, 23, 6, 10, 15, 21 }
                -- md5_raw
                local function md5_raw(input)
                    assert(type(input) == "string", "MD5 input must be a string")
                    local size = #input
                    local message = input
                        .. char(128)
                        .. string.rep(char(0), (55 - size) % 64)
                        .. little32((size * 8) % U32)
                        .. little32(floor(size / 536870912))
                    local h0, h1, h2, h3 = 0x67452301, 0xefcdab89, 0x98badcfe, 0x10325476
                    local words = {}
                    for offset = 1, #message, 64 do
                        for j = 0, 15 do
                            local a, b, c, d = byte(message, offset + j * 4, offset + j * 4 + 3)
                            words[j] = a + b * 256 + c * 65536 + d * 16777216
                        end
                        local a, b, c, d = h0, h1, h2, h3
                        for i = 0, 63 do
                            local f, g, shiftBase
                            if i < 16 then
                                f, g, shiftBase = band(b, c) + band(U32 - 1 - b, d), i, 0
                            elseif i < 32 then
                                f, g, shiftBase = band(d, b) + band(U32 - 1 - d, c), (5 * i + 1) % 16, 4
                            elseif i < 48 then
                                f, g, shiftBase = bxor(bxor(b, c), d), (3 * i + 5) % 16, 8
                            else
                                local bOrNotD = U32 - 1 - band(U32 - 1 - b, d)
                                f, g, shiftBase = bxor(c, bOrNotD), (7 * i) % 16, 12
                            end
                            local nextB = (b + rol((a + f + K[i + 1] + words[g]) % U32, SHIFT[shiftBase + i % 4 + 1]))
                                % U32
                            a, b, c, d = d, nextB, b, c
                        end
                        h0, h1, h2, h3 = (h0 + a) % U32, (h1 + b) % U32, (h2 + c) % U32, (h3 + d) % U32
                    end
                    return little32(h0) .. little32(h1) .. little32(h2) .. little32(h3)
                end
                -- hex
                local function hex(input)
                    return (
                        input:gsub(".", function(c)
                            return format("%02x", byte(c))
                        end)
                    )
                end
                -- md5
                local function md5(input)
                    return hex(md5_raw(input))
                end
                -- form_encode
                local function form_encode(input)
                    assert(type(input) == "string", "Form value must be a string")
                    return (
                        input
                            :gsub("[^A-Za-z0-9%-%._~ ]", function(c)
                                return format("%%%02X", byte(c))
                            end)
                            :gsub(" ", "+")
                    )
                end
                -- constant_time_equal
                local function constant_time_equal(a, b)
                    if type(a) ~= "string" or type(b) ~= "string" then
                        return false
                    end
                    local difference = abs(#a - #b)
                    for i = 1, max(#a, #b) do
                        difference = difference + abs((byte(a, i) or 0) - (byte(b, i) or 0))
                    end
                    return difference == 0
                end
                -- name_uuid
                local function name_uuid(input)
                    local digest = md5_raw(input)
                    local h = hex(
                        digest:sub(1, 6)
                            .. char(byte(digest, 7) % 16 + 48)
                            .. digest:sub(8, 8)
                            .. char(byte(digest, 9) % 64 + 128)
                            .. digest:sub(10)
                    )
                    return h:sub(1, 8)
                        .. "-"
                        .. h:sub(9, 12)
                        .. "-"
                        .. h:sub(13, 16)
                        .. "-"
                        .. h:sub(17, 20)
                        .. "-"
                        .. h:sub(21, 32)
                end
                return {
                    md5 = md5,
                    md5_raw = md5_raw,
                    form_encode = form_encode,
                    constant_time_equal = constant_time_equal,
                    name_uuid = name_uuid,
                }
            end)()

            local CreateAuth = function(P, cfg, deps)
                local A = {}
                local pending, generation, allowed = nil, 0, false
                local expiresAt, deadline, lastClock, lastWorld, serverNow
                local phase, message = "locked", "Enter your key to sign in."
                local startFn, stopFn, payloadStarted, restartRequired
                local verify, admissionToken, admissionClaims, policyAt, policyPending, policyStarted
                local function clock()
                    local ok, t, w = pcall(deps.clock)
                    if ok and type(t) == "number" and t == t and t >= 0 and t < math.huge and w ~= nil then
                        return t, w
                    end
                end
                local function notify(text, state)
                    message, phase = text, state
                    if deps.status then
                        pcall(deps.status, text, state)
                    end
                end
                local function revoke(text, state)
                    generation = generation + 1
                    if pending and pending.request and deps.cancel then
                        pcall(deps.cancel, pending.request)
                    end
                    pending = nil
                    allowed = false
                    deadline = nil
                    expiresAt = nil
                    admissionToken = nil
                    admissionClaims = nil
                    policyPending = false
                    rawset(_G, "__LunarLicenseSessionV7", nil)
                    if payloadStarted then
                        payloadStarted = false
                        if stopFn then
                            local ok, res = pcall(stopFn)
                            if not ok or res == false then
                                restartRequired = true
                            end
                        end
                    end
                    notify(text or "Sign in required.", state or "locked")
                end
                local function current()
                    if not allowed then
                        return false
                    end
                    local t, w = clock()
                    if t and w == lastWorld and t >= deadline then
                        revoke("Your license has expired. Contact your seller.", "disabled")
                        return false
                    end
                    if not t or w ~= lastWorld or t < lastClock then
                        revoke("Session expired or clock context changed. Sign in again.", "locked")
                        return false
                    end
                    lastClock = t
                    return true
                end
                local function ensureVerifier()
                    if not verify then
                        verify = UniversalCrypto.rsaVerifier(cfg.publicModulus)
                    end
                    return verify
                end
                local function signed(raw, typ)
                    assert(type(raw) == "string" and #raw <= 16384, "Response size invalid")
                    local envelope = UniversalCrypto.flatJSON(raw)
                    local count = 0
                    for _ in pairs(envelope) do
                        count = count + 1
                    end
                    assert(count == 1 and type(envelope.token) == "string", "Invalid server response")
                    return UniversalCrypto.claims(envelope.token, typ, ensureVerifier()), envelope.token
                end
                local errors = {
                    FREE_LOCAL_ONLY = "Free keys use local Lua only. No online upload is required.",
                    FREE_KEY_ONLY = "This key is valid only for Free Lua.",
                    PAID_KEY_ONLY = "This key is valid only for Paid Lua.",
                    LUA_KEY_REQUIRED = "Create a Lua key in this panel.",
                    LUA_CHANGED_RETRY = "Lua was updated. Sign in again.",
                    LUA_SERVICE_UNAVAILABLE = "Lua service unavailable. Contact your seller.",
                    FREE_PAK_KEY_ONLY = "This key is valid only for Free PAKs. Use a Paid key for this PAK.",
                    PAID_PAK_KEY_ONLY = "This key is valid only for Paid PAKs. Use a Free key for this PAK.",
                    PAK_INTEGRITY_MISMATCH = "PAK SHA256 does not match the registered release.",
                    PAK_UNAVAILABLE = "This PAK profile is paused or unavailable.",
                    LUA_RELEASE_UNAVAILABLE = "Online Lua is not published yet. Contact the owner.",
                    LUA_RELEASE_CHANGED = "Lua was updated. Sign in again to get the latest release.",
                    WRONG_PRODUCT = "This key belongs to another product.",
                    PRODUCT_KEY_REQUIRED = "Generate a Universal product key in the panel.",
                    DEVICE_LIMIT_REACHED = "Maximum devices reached.",
                    NOT_AUTHORIZED = "Key is invalid, blocked, or unavailable.",
                    LICENSE_EXPIRED = "Your license has expired.",
                    CLIENT_VERSION_REJECTED = "Update this Lua file to the accepted version.",
                    ISSUER_PRODUCT_REVOKED = "Issuer product access has been removed.",
                    PRODUCT_UNAVAILABLE = "This product is unavailable.",
                    RATE_LIMITED = "Too many requests. Wait one minute and retry.",
                    AUTH_UNAVAILABLE = "Authentication server unavailable.",
                    INVALID_REQUEST = "Login request expired or invalid. Please retry.",
                    HTTPS_REQUIRED = "Secure connection required.",
                }
                local function responseError(raw)
                    local statusOK, status = pcall(signed, raw, "lua-status+jwt")
                    local wallOK, wall = pcall(deps.wall)
                    if
                        statusOK
                        and wallOK
                        and type(wall) == "number"
                        and status.iss == "meow-lua-v1"
                        and status.aud == "lua-policy-v1"
                        and status.pack_id == cfg.packId
                        and type(status.iat) == "number"
                        and type(status.exp) == "number"
                        and status.iat <= wall + 120
                        and status.exp > wall
                        and status.exp - status.iat == 90
                        and status.allowed == 0
                    then
                        local good, text = pcall(UniversalCrypto.b64, status.message_b64)
                        if
                            good
                            and type(text) == "string"
                            and #text > 0
                            and #text <= 2000
                            and not text:find("[%z\1-\8\11\12\14-\31\127]")
                        then
                            return text, true
                        end
                    end
                    local ok, r = pcall(function()
                        return require("common.json_util").decode(raw)
                    end)
