                        return errors[r.code], r.code == "LICENSE_EXPIRED" or r.code == "NOT_AUTHORIZED"
                    end
                    return "Server request failed. Check connection or panel setup."
                end
                local function validPending(id)
                    if not pending or pending.id ~= id or generation ~= id then
                        return false
                    end
                    local t, w = clock()
                    if not t or w ~= pending.world or t < pending.started or t >= pending.timeoutAt then
                        revoke("Login timed out or context changed. Please retry.", "error")
                        return false
                    end
                    return t, w
                end
                function A.Login(key)
                    if pending or current() or restartRequired then
                        return false
                    end
                    if type(key) ~= "string" then
                        key = ""
                    end
                    key = key:match("^%s*(.-)%s*$")
                    if #key == 0 or #key > 191 or key:find("[%c]") then
                        notify("Enter a valid key (maximum 191 bytes).", "denied")
                        return false
                    end
                    local t, w = clock()
                    if not t then
                        notify("Clock unavailable.", "error")
                        return false
                    end
                    local good, device = pcall(deps.serial, key)
                    if not good or type(device) ~= "string" or #device ~= 64 or device:find("[^a-f0-9]") then
                        notify("Device identity could not be saved. Check game storage.", "error")
                        return false
                    end
                    generation = generation + 1
                    local id = generation
                    pending =
                        { id = id, started = t, world = w, timeoutAt = t + cfg.timeout, device = device, key = key }
                    notify("Connecting securely...", "pending")
                    local function challenged(success, raw)
                        local received = validPending(id)
                        if not received then
                            return
                        end
                        if success ~= true then
                            local text, blocked = responseError(raw)
                            revoke(text, blocked and "disabled" or "error")
                            return
                        end
                        local ok, c, challenge = pcall(signed, raw, "universal-challenge+jwt")
                        local wallOK, wall = pcall(deps.wall)
                        if not ok then
                            revoke("Server signature or challenge invalid.", "error")
                            return
                        end
                        if
                            not wallOK
                            or type(wall) ~= "number"
                            or type(c.iat) ~= "number"
                            or type(c.exp) ~= "number"
                            or math.abs(wall - c.iat) > 120
                            or c.exp <= wall
                            or c.iss ~= "universal-v1"
                            or c.aud ~= "universal-challenge-v1"
                            or c.rebrand ~= cfg.rebrand
                            or c.product ~= cfg.product
                            or type(c.iat) ~= "number"
                            or c.iat % 1 ~= 0
                            or type(c.exp) ~= "number"
                            or c.exp - c.iat ~= 90
                            or type(c.nonce) ~= "string"
                            or #c.nonce ~= 64
                            or c.nonce:find("[^a-f0-9]")
                        then
                            revoke("Challenge binding invalid.", "error")
                            return
                        end
                        local json = require("common.json_util")
                        if c.pack_id ~= nil and c.pack_id ~= (cfg.packId or "local-paid") then
                            revoke("Challenge PAK profile mismatch.", "error")
                            return
                        end
                        local requestData = {
                            protocol = 1,
                            rebrand = cfg.rebrand,
                            product = cfg.product,
                            key = key,
                            device_id = device,
                            nonce = c.nonce,
                            timestamp = c.iat,
                            client_version = cfg.version,
                            challenge = challenge,
                            pack_id = cfg.packId or "local-paid",
                        }
                        if c.pak_sha256 ~= nil and c.pak_sha256 ~= "" then
                            if
                                type(c.pak_sha256) ~= "string"
                                or #c.pak_sha256 ~= 64
                                or c.pak_sha256:find("[^a-f0-9]")
                            then
                                revoke("Invalid signed PAK hash.", "error")
                                return
                            end
                            notify("Checking PAK integrity...", "pending")
                            local hashOK, digest = pcall(deps.pakHash)
                            if not hashOK or digest ~= c.pak_sha256 then
                                revoke("PAK SHA256 mismatch or PAK file unreadable. Install the correct PAK.", "denied")
                                return
                            end
                            requestData.pak_sha256 = digest
                        end
                        local body = json.encode(requestData)
                        if type(body) ~= "string" or #body > 8192 then
                            revoke("Login request could not be encoded.", "error")
                            return
                        end
                        local function admitted(success2, raw2)
                            local now, world = validPending(id)
                            if not now then
                                return
                            end
                            if success2 ~= true then
                                local text, blocked = responseError(raw2)
                                revoke(text, blocked and "disabled" or "denied")
                                return
                            end
                            local valid, claims, signedAdmission = pcall(signed, raw2, "universal-license+jwt")
                            local wallOK2, wall2 = pcall(deps.wall)
                            if not valid then
                                revoke(
                                    responseError(raw2) == "Server request failed. Check connection or panel setup."
                                            and "Server signature or response invalid."
                                        or responseError(raw2),
                                    "denied"
                                )
                                return
                            end
                            if
                                not wallOK2
                                or type(wall2) ~= "number"
                                or claims.iss ~= "universal-v1"
                                or claims.aud ~= "universal-license-v1"
                                or claims.protocol ~= 1
                                or claims.rebrand ~= cfg.rebrand
                                or claims.product ~= cfg.product
                                or claims.client_version ~= cfg.version
                                or claims.device_id ~= device
                                or claims.nonce ~= c.nonce
                                or claims.request_hash ~= UniversalCrypto.sha256(body)
                                or type(claims.sub) ~= "string"
                                or #claims.sub == 0
                                or #claims.sub > 191
                                or type(claims.iat) ~= "number"
                                or type(claims.exp) ~= "number"
                                or type(claims.license_exp) ~= "number"
                                or claims.iat % 1 ~= 0
                                or claims.exp % 1 ~= 0
                                or claims.license_exp % 1 ~= 0
                                or claims.iat < c.iat - 5
                                or claims.iat > c.exp
                                or claims.exp <= claims.iat
                                or claims.exp - claims.iat > 300
                                or claims.license_exp < claims.exp
                                or claims.exp <= wall2
                                or claims.license_exp <= wall2
                                or claims.license_exp - claims.iat > 3153600000
                            then
                                revoke("Signed login claims do not match this request.", "denied")
                                return
                            end
                            if
                                claims.pack_id ~= (cfg.packId or "local-paid")
                                or claims.lua_edition ~= (cfg.edition or "paid")
                                or claims.lua_delivery ~= (cfg.delivery or "local")
                            then
                                revoke("Signed PAK profile does not match this Lua.", "denied")
                                return
                            end
                            if
                                claims.lua_delivery == "online"
                                and (
                                    type(claims.lua_release) ~= "string"
                                    or #claims.lua_release ~= 32
                                    or claims.lua_release:find("[^a-f0-9]")
                                    or type(claims.lua_sha256) ~= "string"
                                    or #claims.lua_sha256 ~= 64
                                    or claims.lua_sha256:find("[^a-f0-9]")
                                    or type(claims.lua_size) ~= "number"
                                    or claims.lua_size % 1 ~= 0
                                    or claims.lua_size < 1
                                    or claims.lua_size > 2097152
                                )
                            then
                                revoke("Invalid signed online release.", "denied")
                                return
                            end
                            if
                                type(claims.session_token) ~= "string"
                                or #claims.session_token < 32
                                or #claims.session_token > 4096
                            then
                                revoke("Session policy token missing. Update the server.", "error")
                                return
                            end
                            -- Subtract the full elapsed request interval conservatively.
                            local elapsed = now - pending.started
                            if claims.exp <= c.iat + elapsed or claims.license_exp <= c.iat + elapsed then
                                revoke("License expired.", "denied")
                                return
                            end
                            if
                                claims.branding_v ~= 1
                                or type(claims.display_name_b64) ~= "string"
                                or #claims.display_name_b64 > 256
                                or type(claims.channel_link) ~= "string"
                                or #claims.channel_link > 255
                            then
                                revoke("Panel branding unavailable. Update the website source.", "error")
                                return
                            end
                            local nameOK, issuerName = pcall(UniversalCrypto.b64, claims.display_name_b64)
                            local channel = claims.channel_link
                            local channelPath = channel:match("^https://t%.me/(.+)$")
                            local channelOK = channel == ""
                                or (
                                    channelPath
                                    and (
                                        channelPath:match("^[A-Za-z0-9_]+$")
                                        or channelPath:match("^%+[A-Za-z0-9_-]+$")
                                        or channelPath:match("^joinchat/[A-Za-z0-9_-]+$")
                                    )
                                )
                            if
                                not nameOK
                                or type(issuerName) ~= "string"
                                or #issuerName == 0
                                or #issuerName > 192
                                or issuerName:find("[%z\1-\31\127]")
                                or not channelOK
                            then
                                revoke("Invalid signed account branding.", "error")
                                return
                            end
                            if deps.branding then
                                deps.branding(issuerName, channel)
                            end
                            pending = nil
                            allowed = true
                            expiresAt = claims.license_exp
                            admissionToken = signedAdmission
                            admissionClaims = claims
                            policyAt = now + 120
                            deadline = now + (claims.license_exp - math.max(c.iat + elapsed, wall2))
                            lastClock = now
                            lastWorld = world
                            serverNow = c.iat + elapsed
                            if startFn then
                                payloadStarted = true
                                local started, accepted = pcall(startFn)
                                if not started or accepted == false then
                                    restartRequired = true
                                    revoke("Startup failed. Restart required.", "error")
                                    return
                                end
                            end
                            notify("Login successful.", "active")
                        end
                        notify("Verifying key...", "pending")
                        local started, request = pcall(
                            deps.post,
                            cfg.url,
                            { ["Content-Type"] = "application/json" },
                            body,
                            admitted,
                            cfg.timeout
                        )
                        if not started or type(request) ~= "number" or request <= 0 then
                            revoke("HTTP request could not start.", "error")
                        elseif pending and pending.id == id then
                            pending.request = request
                        end
                    end
                    local url = cfg.url
                        .. (cfg.url:find("?", 1, true) and "&" or "?")
                        .. "rebrand="
                        .. P.form_encode(cfg.rebrand)
                        .. "&product="
                        .. P.form_encode(cfg.product)
                        .. "&pack_id="
                        .. P.form_encode(cfg.packId or "local-paid")
                    local started, request =
                        pcall(deps.get, url, { ["Accept"] = "application/json" }, challenged, cfg.timeout)
                    if not started or type(request) ~= "number" or request <= 0 then
                        revoke("HTTP request could not start.", "error")
                        return false
                    end
                    if pending and pending.id == id then
                        pending.request = request
                    end
                    return true
                end
                function A.GetAdmission()
                    if current() then
                        return admissionToken, admissionClaims
                    end
                end
                function A.Tick()
                    if pending then
                        validPending(pending.id)
                        return
                    end
                    if not current() then
                        return
                    end
                    local t = clock()
                    if not t then
                        return
                    end
                    if policyPending then
                        if policyStarted and t - policyStarted >= cfg.timeout then
                            revoke("Connection check timed out. Reconnecting automatically...", "retry")
                        end
                        return
                    end
                    if not policyAt or t < policyAt then
                        return
                    end
                    policyAt = t + 120
                    policyPending = true
                    policyStarted = t
                    local token = admissionToken
                    local policyNonce = UniversalCrypto.sha256(token .. tostring(t) .. tostring(generation))
                    local started, request = pcall(
                        deps.get,
                        cfg.url:gsub("action=login", "action=status") .. "&check_nonce=" .. policyNonce,
                        { ["Accept"] = "application/json", ["Authorization"] = "Bearer "
                            .. admissionClaims.session_token },
                        function(success, raw)
                            policyPending = false
                            if not current() or admissionToken ~= token then
                                return
                            end
                            if success ~= true then
                                local text, blocked = responseError(raw)
                                revoke(blocked and text or "Connection unavailable. Reconnecting automatically...", blocked and "disabled" or "retry")
                                return
                            end
                            local valid, c = pcall(signed, raw, "lua-status+jwt")
                            local wallOK, wall = pcall(deps.wall)
                            if
                                success ~= true
                                or not valid
                                or not wallOK
                                or c.iss ~= "meow-lua-v1"
                                or c.aud ~= "lua-policy-v1"
                                or c.pack_id ~= cfg.packId
                                or type(c.iat) ~= "number"
                                or type(c.exp) ~= "number"
                                or c.iat > wall + 120
                                or c.exp <= wall
                                or c.exp - c.iat ~= 90
                                or (c.allowed ~= 0 and c.allowed ~= 1)
                                or c.sub ~= admissionClaims.sub
                                or c.device_id ~= admissionClaims.device_id
                                or c.check_nonce ~= policyNonce
                            then
                                revoke("Server signature or status invalid. Contact your seller.", "disabled")
                                return
                            end
                            if c.allowed == 0 then
                                local text, blocked = responseError(raw)
                                revoke(text, blocked and "disabled" or "error")
                            end
                        end,
                        cfg.timeout
                    )
                    if not started or type(request) ~= "number" or request <= 0 then
