        -- MEOW_CHANNEL_GATE_BEGIN: deterministic state machine, tested independently from Unreal widgets.
        local function createMeowChannelGate(deps)
            local G = { Ready = false, Waiting = false, BackgroundSeen = false, Name = "", URL = "", Error = nil }
            function G.Reset()
                G.Ready = false
                G.Waiting = false
                G.BackgroundSeen = false
                G.Error = nil
            end
            function G.Configure(name, url)
                G.Reset()
                G.Name = name
                G.URL = url
            end
            function G.Complete()
                if G.Ready or not deps.licensed() then
                    return false
                end
                G.Ready = true
                G.Waiting = false
                G.BackgroundSeen = false
                G.Error = nil
                deps.complete()
                return true
            end
            function G.Join()
                if G.Ready or G.Waiting or not deps.licensed() then
                    return false
                end
                if G.URL == "" then
                    G.Error = "Channel link has not been set. You can continue."
                    deps.wake()
                    return false
                end
                G.Waiting = true
                G.BackgroundSeen = false
                G.Error = nil
                local ok, result = pcall(deps.open, G.URL)
                if not ok or result == false then
                    G.Waiting = false
                    G.Error = "Could not open the channel. Cancel to continue."
                    deps.wake()
                    return false
                end
                deps.wake()
                return true
            end
            function G.Background()
                if G.Waiting then
                    G.BackgroundSeen = true
                end
            end
            function G.Foreground()
                if G.Waiting and G.BackgroundSeen then
                    return G.Complete()
                end
                return false
            end
            G.Cancel = G.Complete
            -- Explicit return fallback when this game build does not expose lifecycle delegates.
            function G.Continue()
                if G.Waiting then
                    return G.Complete()
                end
                return false
            end
            return G
        end
