                    local left = string.format("%02dh %02dm %02ds", hours, minutes, seconds)
                    if days > 0 then
                        left = tostring(days) .. "d " .. left
                    end
                    local ok, date = pcall(os.date, "%d %b %Y %H:%M", expiry)
                    return "Expires "
                        .. (ok and type(date) == "string" and date or "date unavailable")
