                        d.FitWidth = d.Width
                    end
                    setChanged(d, "Clock", expiryLine(license, now))
                end
                function M.Branding(name, license)
                    local p = D.Parent()
                    if not p then
                        return nil
                    end
                    local sourceParent = p
                    -- Prefer the outermost available canvas so nested safe-area panels do not clip edge text.
                    local cursor = p
                    for _ = 1, 8 do
                        local getParent = member(cursor, "GetParent")
                        if type(getParent) ~= "function" then
                            break
                        end
                        local ok, nextParent = pcall(getParent, cursor)
                        if not ok or not valid(nextParent) then
                            break
                        end
                        if type(member(nextParent, "AddChildToCanvas")) == "function" then
                            p = nextParent
                        end
                        cursor = nextParent
                    end
                    local d = {
                        Parent = p,
                        SourceParent = sourceParent,
                        Visible = false,
                        Labels = {},
                        Values = {},
                        RowSlots = {},
                        RowHeights = { Version = 30, Clock = 28, Brand = 34 },
                        IsHUD = true,
                    }
                    local hud = D.Info.HUD
                    local ok, err = pcall(function()
                        local width = hud.Width
                        d.DesignWidth = width
                        d.DesignHeight = hud.Height
                        d.Container = make("CanvasPanel", p)
                        local slot = add(p, d.Container, 0, 0, width, hud.Height, 9201)
                        d.RootSlot = slot
                        anchor(slot, 0, 0)
                        show(d.Container, false)
                        d.Labels.Version, d.RowSlots.Version = text(
                            d,
                            "Version " .. D.Info.Version,
                            0,
                            0,
                            width,
                            30,
                            hud.FontSize,
                            true,
                            hudColors.Version,
                            false,
                            true
                        )
                        d.Labels.Clock, d.RowSlots.Clock =
                            text(d, "", 0, 32, width, 28, hud.FontSize - 2, true, hudColors.Clock, false, true)
                        d.Labels.Brand, d.RowSlots.Brand =
                            text(d, "", 0, 63, width, 34, hud.FontSize, true, hudColors.Brand, false, true)
                        for _, label in pairs(d.Labels) do
                            -- This game exposes AutoWrapText as a property, not a SetAutoWrapText UFunction.
                            local updated = pcall(function()
                                label:SetAutoWrapText(false)
                            end)
                            if not updated then
                                pcall(function()
                                    label.AutoWrapText = false
                                end)
                            end
                        end
                        M.Reflow(d)
                    end)
                    if not ok then
                        D.Owner.LastHUDError = tostring(err)
                        D.Destroy(d)
                        return nil
                    end
                    d.Visible = true
                    M.UpdateBranding(d, name, os.time(), license)
                    return d
                end
                return M
            end
        end)()
        -- MEOW_UI_MODULE_END

        local UI = { Version = "MeowUI.4" }
        -- member
        local function member(o, k)
            if o == nil then
                return nil
            end
            local ok, v = pcall(function()
                return o[k]
            end)
            if ok then
                return v
            end
        end
        -- valid
        local function valid(o)
            if o == nil then
                return false
            end
            local ok, v = pcall(slua.isValid, o)
            return ok and v == true
        end
        local vectorClass = rawget(_G, "FVector2D") or import("Vector2D")
        local colorClass = rawget(_G, "FLinearColor") or import("LinearColor")
        local anchorClass = rawget(_G, "Anchors")
        local importedAnchorClass
        pcall(function()
            importedAnchorClass = import("Anchors")
        end)
        -- vector
        local function vector(x, y)
            return vectorClass(x, y)
        end
        -- color
        local function color(r, g, b, a)
            -- linear
            local function linear(v)
                v = v / 255
                if v <= 0.04045 then
                    return v / 12.92
                end
                return ((v + 0.055) / 1.055) ^ 2.4
            end
            return colorClass(linear(r), linear(g), linear(b), a or 1)
        end
        -- visibility
        local function visibility(w, v)
            local fn = member(w, "SetWidgetVisibility") or member(w, "SetVisibility")
            assert(type(fn) == "function", "UI_VISIBILITY_UNAVAILABLE")
            fn(w, v)
        end
        -- parent
        local function parent()
            local ok, t = pcall(require, "GameLua.Mod.BaseMod.Common.UI.InGameUITools")
            if not ok or type(member(t, "GetMainControlBaseUI")) ~= "function" then
                return
            end
            local found, root = pcall(t.GetMainControlBaseUI)
            if not found or not valid(root) then
                return
            end
            local p = member(root, "CanvasPanel_0")
            if not valid(p) then
                p = member(root, "CanvasPanel_42")
            end
            if valid(p) then
                return p
            end
        end
        -- destroy
        local function destroy(d)
            if not d then
                return
            end
            d.Visible = false
            if d.Event and d.Handle ~= nil then
                pcall(function()
                    d.Event:Remove(d.Handle)
                end)
            end
            for _, binding in ipairs(d.Events or {}) do
                pcall(function()
                    binding.Event:Remove(binding.Handle)
                end)
            end
            d.Events = nil
            if valid(d.Container) then
                pcall(function()
                    d.Container:RemoveFromParent()
                end)
            end
            d.Submit = nil
            d.Event = nil
            d.Handle = nil
            d.Container = nil
            d.Parent = nil
            d.Input = nil
            d.Button = nil
            d.Status = nil
            d.Title = nil
            d.Detail = nil
            d.Hint = nil
            d.Design = nil
            d.Cache = nil
            d.Labels = nil
            d.Values = nil
            d.RootSlot = nil
            d.RowSlots = nil
            d.RowHeights = nil
        end

        -- Editable source: modules/meow_ui.lua; bundled here for single-file deployment.
        local meowUI = createMeowUI({
            Info = MeowBuild,
            Owner = UI,
            Parent = parent,
            Member = member,
            Valid = valid,
            Vector = vector,
            Color = color,
            Visibility = visibility,
            Destroy = destroy,
        })
        UI.Build = meowUI.Build
        UI.Branding = meowUI.Branding
        UI.UpdateBranding = meowUI.UpdateBranding
        UI.Reflow = meowUI.Reflow
        _G.LunarUIAssetCache = nil

        local existing = _G.LunarLoginRuntime
        if
            existing
            and existing.UIFactory
            and existing.UIFactory.Version ~= UI.Version
            and existing.Scope
                == MasterLicenseCore.Primitives.md5(
                    MasterLicenseConfig.url .. "\0" .. MasterLicenseConfig.game .. "\0" .. MasterLicenseConfig.secret
                )
        then
            local visibleWelcome = existing.WelcomeUI and existing.WelcomeUI.Visible
            if existing.DestroyUI then
                existing.DestroyUI()
            end
            existing.UIFactory.Build = UI.Build
            existing.UIFactory.Version = UI.Version
            if visibleWelcome and not _G.__LUNAR_WELCOME_SHOWN then
                existing.WelcomeShown = false
            end
            existing.NeedsUpdate = true
        end
        -- hex
        local function hex(s)
            return (
                s:gsub(".", function(c)
                    return string.format("%02x", string.byte(c))
                end)
            )
        end
        -- unhex
        local function unhex(s)
            if type(s) ~= "string" or #s > 1024 or #s % 2 ~= 0 or s:find("[^%x]") then
                return nil
            end
            return (s:gsub("..", function(v)
                return string.char(tonumber(v, 16))
            end))
        end
        local current = _G.LunarLoginRuntime

        local expectedScope = MasterLicenseCore.Primitives.md5(
            MasterLicenseConfig.url .. "\0" .. MasterLicenseConfig.game .. "\0" .. MasterLicenseConfig.secret
        )
        if not current or current.Scope ~= expectedScope then
            if current and current.DestroyUI then
                current.DestroyUI()
            end
            local L = {
                Authorized = false,
                Pending = false,
                NeedsUpdate = true,
                WelcomeShown = false,
                Key = "",
                Seed = "",
                Scope = expectedScope,
                StorageVersion = 1,
                Status = "Enter your key",
                Diagnostics = { HTTP = 0, DeviceReads = 0 },
            }
            _G.LunarLoginRuntime = L
            L.UIFactory = UI

            local paths = g_adityaorg_ESPSettingsPaths()
            for i, path in ipairs(paths) do
                paths[i] = path:gsub("ADITYA_UMG_ESP_settings.lua$", "UNIVERSAL_LOGIN_V1_settings.lua")
            end
            -- loginPath
            local function loginPath(featurePath)
                if type(featurePath) ~= "string" then
                    return nil
                end
                local prefix = featurePath:match("^(.*[/\\])[^/\\]+$")
                return (prefix or "") .. "UNIVERSAL_LOGIN_V1_settings.lua"
            end
            -- identityPath
            local function identityPath(path)
                return path:gsub("UNIVERSAL_LOGIN_V1_settings%.lua$", "UNIVERSAL_DEVICE_V1_settings.lua")
            end
            -- digest
            local function digest(key, seed)
                return MasterLicenseCore.Primitives.md5("LUNAR-DEVICE-1\0" .. L.Scope .. "\0" .. key .. "\0" .. seed)
            end
            -- readRecord
            local function readRecord(path, identity)
                if not (io and type(io.open) == "function") then
                    return nil, "unreadable"
                end
                local ok, file, reason, code = pcall(io.open, path, "r")
                if not ok then
                    return nil, "unreadable"
                end
                if not file then
                    local text = type(reason) == "string" and reason:lower() or ""
                    if
                        reason == nil
                        or code == 2
                        or text:find("no such file", 1, true)
                        or text:find("not found", 1, true)
                        or text:find("does not exist", 1, true)
                    then
                        return nil, "missing"
                    end
                    return nil, "unreadable"
                end
                local good, data = pcall(function()
                    return file:read(4097)
                end)
                pcall(function()
                    file:close()
                end)
                if not good or type(data) ~= "string" then
                    return nil, "unreadable"
                end
                if #data > 4096 then
                    return nil, "invalid"
                end
                local scope = data:match('%f[%w_]Scope%s*=%s*"([%x]+)"')
                if scope and scope ~= L.Scope then
                    return nil, "other_scope"
                end
                if scope ~= L.Scope then
                    return nil, "invalid"
                end
                local key = unhex(data:match('%f[%w_]KeyHex%s*=%s*"([^"]*)"'))
                local seed = unhex(data:match('%f[%w_]SeedHex%s*=%s*"([^"]*)"'))
                if key == nil or seed == nil or #seed == 0 or #seed > 512 then
                    return nil, "invalid"
                end
                local check = data:match('%f[%w_]Check%s*=%s*"([%x]+)"')
                local version = data:match("%f[%w_]Version%s*=%s*(%d+)")
                if identity or check or version then
                    if version ~= "1" or check ~= digest(key, seed) then
                        return nil, "invalid"
                    end
                end
                return { Key = key, Seed = seed, Path = path, Identity = identity, Checked = version == "1" }, "valid"
            end
            -- candidates
            local function candidates()
                local list, seen = {}, {}
                -- add
                local function add(path)
                    if type(path) == "string" and not seen[path] then
                        seen[path] = true
                        list[#list + 1] = path
                    end
                end
                add(L.Path)
                add(L.PreferredPath)
                for _, path in ipairs(paths) do
                    add(path)
                end
                return list
            end
            -- recover
            local function recover()
                if L.IdentityPinned then
                    return true
                end
                local identities, legacy, issues = {}, {}, {}
                -- collect
                local function collect(base, path, identity)
                    local record, state = readRecord(path, identity)
                    if record then
                        record.Base = base
                        local list = identity and identities or legacy
                        list[#list + 1] = record
                    elseif state == "invalid" or (state == "unreadable" and base == L.PreferredPath) then
                        issues[#issues + 1] = state
                    end
                end
                for _, base in ipairs(candidates()) do
                    local device = identityPath(base)
                    collect(base, device, true)
                    collect(base, device .. ".bak", true)
                    collect(base, base, false)
                    collect(base, base .. ".bak", false)
                end
                local list = #identities > 0 and identities or legacy
                local first = list[1]
                if first then
                    for _, record in ipairs(list) do
                        if record.Seed ~= first.Seed then
                            L.IdentityError = "DEVICE_CACHE_CONFLICT"
                            L.Diagnostics.Identity = "conflict"
                            return false
                        end
                    end
                    L.Seed = first.Seed
                    L.Key = first.Key
                    L.Path = first.Base
                    if L.Key == "" then
                        for _, record in ipairs(list) do
                            if record.Key ~= "" then
                                L.Key = record.Key
                                break
                            end
                        end
                    end

                    if L.Key == "" then
                        for _, record in ipairs(legacy) do
                            if record.Seed == L.Seed and record.Key ~= "" then
                                L.Key = record.Key
                                break
                            end
                        end
                    end
                    L.IdentityPinned = true
                    L.IdentityPersisted = true
                    L.HasIdentityRecord = first.Identity
                    L.IdentityError = nil
                    L.Dirty = true
                    L.Diagnostics.Identity = first.Identity and "restored" or "legacy_migration"
                    return true
                end
                if #issues > 0 then
                    L.IdentityError = "DEVICE_CACHE_RECOVERY_REQUIRED"
                    L.Diagnostics.Identity = "recovery_required"
                    return false
                end
                L.IdentityError = nil
                L.Diagnostics.Identity = "new_install"
                return true
            end
            -- payload
            local function payload(key, seed)
                return 'return { Version = 1, Scope = "'
                    .. L.Scope
                    .. '", KeyHex = "'
                    .. hex(key)
                    .. '", SeedHex = "'
                    .. hex(seed)
                    .. '", Check = "'
                    .. digest(key, seed)
                    .. '" }'
            end
            -- verifiedWrite
            local function verifiedWrite(path, identity, key, seed, data)
                local current, state = readRecord(path, identity)
                if current and current.Checked and current.Seed == seed and current.Key == key then
                    return true
                end
                if state == "unreadable" or state == "other_scope" then
                    return false
                end
                if current and current.Seed ~= seed and (identity or not L.HasIdentityRecord) then
                    return false
                end
                local ok = g_adityaorg_ESPWriteSettings(path, data)
                if not ok then
                    return false
                end
                local result = readRecord(path, identity)
                return result ~= nil and result.Checked and result.Seed == seed and result.Key == key
            end
            L.Save = function()
                if L.Seed == "" or L.IdentityError then
                    return false
                end
                local key = L.AttemptKey or L.Key
                local data = payload(key, L.Seed)
                local preferred = candidates()
                for _, base in ipairs(preferred) do
                    local device = identityPath(base)
                    local old, oldState = readRecord(base, false)
                    local current, currentState = readRecord(device, true)

                    if
                        oldState ~= "unreadable"
                        and currentState ~= "unreadable"
                        and oldState ~= "other_scope"
                        and currentState ~= "other_scope"
                        and (not old or old.Seed == L.Seed or L.HasIdentityRecord)
                        and (not current or current.Seed == L.Seed)
                    then
                        local a = verifiedWrite(device, true, key, L.Seed, data)
                        local b = verifiedWrite(device .. ".bak", true, key, L.Seed, data)
                        local c = verifiedWrite(base, false, key, L.Seed, data)
                        local d = verifiedWrite(base .. ".bak", false, key, L.Seed, data)
                        if (a or b) and ((a and b) or c or d) then
                            L.Path = base
                            L.Key = key
                            L.IdentityPinned = true
                            L.IdentityPersisted = true
                            L.HasIdentityRecord = true
                            L.IdentityError = nil
                            L.Dirty = not (a and b and c and d)
                            L.SaveRetryAt = L.Dirty and (os.time() + 30) or nil
                            L.SaveError = L.Dirty and "Device backup repair pending" or nil
                            L.Diagnostics.Identity = L.Dirty and "backup_pending" or "saved"
                            return true
                        end
                    end
                end
                L.Dirty = true
                L.SaveRetryAt = os.time() + 30
                L.SaveError = "Device cache could not be verified"
                L.Diagnostics.Identity = "save_failed"
                return false
            end
            L.BindSettingsPath = function(featurePath)
                L.PreferredPath = loginPath(featurePath)

                if not L.IdentityPinned then
                    recover()
                end
                if L.Seed ~= "" and not L.IdentityError and (L.Dirty or not L.IdentityPersisted) then
                    L.Save()
                end
            end
            L.EnsureIdentity = function()
                if not L.IdentityPinned then
                    L.Seed = ""
                    assert(recover(), L.IdentityError or "DEVICE_CACHE_RECOVERY_REQUIRED")
                end
                if L.Seed == "" then
                    L.Diagnostics.DeviceReads = L.Diagnostics.DeviceReads + 1
                    local id = Client.GetPhoneDeviceID()
                    assert(type(id) == "string" and #id > 0 and #id <= 512, "DEVICE_ID_UNAVAILABLE")
                    L.Seed = id
                end
                local saved = L.Save()

                assert(saved or L.IdentityPersisted, "DEVICE_CACHE_SAVE_FAILED")
            end
            -- Plain key cache is data only: never executed and never authorizes by itself.
            local package = MeowPack.Package or "com.pubg.imobile"
            pcall(function()
                local value = import("KismetSystemLibrary").GetGameBundleId()
                if type(value) == "string" and value:match("^[%w_.]+$") then package = value end
            end)
            L.KeyFilePath = "/storage/emulated/0/Android/data/" .. package .. "/files/MEOW/SuperPakUserKey.txt"
            local function validSavedKey(value)
                if type(value) ~= "string" then return nil end
                value = value:match("^%s*(.-)%s*$")
                if #value < 1 or #value > 191 or value:find("[%c]") then return nil end
                return value
            end
            L.ReadSavedKey = function()
                local ok, value = pcall(function()
                    local file = io.open(L.KeyFilePath, "r")
                    if not file then return nil end
                    local data = file:read(193)
                    file:close()
                    return validSavedKey(data)
                end)
                return ok and value or nil
            end
            L.SaveVerifiedKey = function(key)
                key = validSavedKey(key)
                if not key then return false end
                local ok, saved = pcall(function()
                    local temporary = L.KeyFilePath .. ".tmp"
                    local file = io.open(temporary, "w")
                    if not file then return false end
                    local written = file:write(key .. "\n")
                    file:close()
                    if not written or not os.rename(temporary, L.KeyFilePath) then return false end
                    return L.ReadSavedKey() == key
                end)
                L.KeyFileError = (not ok or not saved) and "Saved key file could not be written." or nil
                return ok and saved == true
            end
            recover()
            L.Key = L.ReadSavedKey() or L.Key
            local function wake()
                if _G.AdityaOrgLogin and _G.AdityaOrgLogin._Wake then
                    _G.AdityaOrgLogin._Wake()
                end
            end
            L.DestroyUI = function()
                destroy(L.LoginUI)
                destroy(L.WelcomeUI)
                destroy(L.ChannelUI)
                destroy(L.BrandUI)
                L.LoginUI = nil
                L.WelcomeUI = nil
                L.ChannelUI = nil
                L.BrandUI = nil
            end
            L.Licensed = false
            L.ClearLifecycle = function()
                for _, b in ipairs(L.LifecycleBindings or {}) do
                    pcall(function()
                        b.Event:Remove(b.Handle)
                    end)
                end
                L.LifecycleBindings = nil
                if L.LifecycleComponent then
                    pcall(function()
                        L.LifecycleComponent:DestroyComponent()
                    end)
                end
                L.LifecycleComponent = nil
                L.LifecycleBound = false
            end
            L.ChannelGate = createMeowChannelGate({
                licensed = function()
                    return L.Licensed and L.Auth and L.Auth.IsAuthorized()
                end,
                wake = wake,
                open = function(url)
                    local KSL = rawget(_G, "UKismetSystemLibrary") or import("KismetSystemLibrary")
                    local fn = member(KSL, "LaunchURL")
                    if type(fn) ~= "function" then
                        return false
                    end
                    local ok = pcall(fn, url)
                    if not ok then
                        ok = pcall(fn, KSL, url)
                    end
                    return ok
                end,
                complete = function()
                    if not L.Licensed or not L.Auth.IsAuthorized() then
                        return
                    end
                    destroy(L.ChannelUI)
                    L.ChannelUI = nil
                    L.ClearLifecycle()
                    L.Authorized = true
                    L.WelcomeShown = true
                    _G.__LUNAR_WELCOME_SHOWN = true
                    L.NeedsUpdate = true
                    wake()
                end,
            })
            L.BindLifecycle = function()
                if L.LifecycleBound then
                    return
                end
                local sources = {}
                pcall(function()
                    local util = require("client.common.ui_util")
                    local gi = util.GetGameInstance()
                    if gi then
                        sources[#sources + 1] = gi
                    end
                end)
                local function attach(source)
                    local foreground = member(source, "ApplicationHasEnteredForegroundDelegate")
                    local background = member(source, "ApplicationWillEnterBackgroundDelegate")
                    if not foreground or not background then
                        return false
                    end
                    local added = {}
                    local ok = pcall(function()
                        added[#added + 1] = { Event = background, Handle = background:Add(L.ChannelGate.Background) }
                        added[#added + 1] = { Event = foreground, Handle = foreground:Add(L.ChannelGate.Foreground) }
                    end)
                    if not ok then
                        for _, b in ipairs(added) do
                            pcall(function()
                                b.Event:Remove(b.Handle)
                            end)
                        end
                        return false
                    end
                    L.LifecycleBindings = added
                    L.LifecycleBound = true
                    return true
                end
                for _, source in ipairs(sources) do
                    if attach(source) then
                        return
                    end
                end
                pcall(function()
                    local root = parent()
                    if not root then
                        return
                    end
                    local owner = root:GetOwningPlayer()
                    if not valid(owner) then
                        return
                    end
                    local component = CGame:NewObjectFromPath("/Script/Engine.ApplicationLifecycleComponent", owner)
                    component:RegisterComponent()
                    if attach(component) then
                        L.LifecycleComponent = component
                    else
                        component:DestroyComponent()
                    end
                end)
            end
            L.Core = MasterLicenseCore
            L.Auth = MasterLicenseCore.new(MasterLicenseConfig, {
                -- Stable across map/UI changes; backward wall-clock movement revokes this session.
                clock = function()
                    return os.time(), L.Scope
                end,
                wall = function()
                    return os.time()
                end,
                serial = function(key)
                    L.EnsureIdentity()
                    return UniversalCrypto.sha256("UNIVERSAL-DEVICE-V1\0" .. L.Seed)
                end,
                pakHash = function()
                    local fileName = MeowPack.PakFile or "game_patch_4.6.0.21572.pak"
                    assert(not fileName:find("[^A-Za-z0-9._-]"), "Invalid PAK filename")
                    local prefix = "/storage/emulated/0/Android/data/"
                    local packages = {
                        "com.pubg.imobile",
                        "com.tencent.ig",
                        "com.pubg.krmobile",
                        "com.vng.pubgmobile",
                        "com.rekoo.pubgm",
                    }
                    local active = MeowPack.Package
                    if not active then
                        -- Use the storage package of this running game, when exposed by the engine.
                        pcall(function()
                            active = import("KismetSystemLibrary").GetGameBundleId()
                        end)
                    end
                    local candidates = {}
                    for _, packageName in ipairs(packages) do
                        if not active or active == "" or packageName == active then
                            candidates[#candidates + 1] = prefix
                                .. packageName
                                .. "/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/Paks/"
                                .. fileName
                        end
                    end
                    local data
                    for _, path in ipairs(candidates) do
                        local f = io.open(path, "rb")
                        if f then
                            local size = f:seek("end")
                            f:seek("set", 0)
                            if size and size > 0 and size <= 16777216 then
                                data = f:read("*a")
                            end
                            f:close()
                            if data then
                                break
                            end
                        end
                    end
                    assert(data, "PAK unavailable or above 16 MiB; clear optional hash or configure a supported file")
                    return UniversalCrypto.sha256(data, false, 16777216)
                end,
                branding = function(name, url)
                    L.ClearLifecycle()
                    L.DestroyUI()
                    L.ChannelGate.Configure(name, url)
                    L.DisplayName = name
                    L.ChannelURL = url
                    _G.ADITYA_JOIN_URL = url -- Existing channel buttons must follow the same signed issuer.
                end,
                decode = function(raw)
                    local json = require("common.json_util")
                    return json.decode(raw)
                end,
                get = function(url, headers, callback, timeout)
                    local http = ModuleManager.GetModule(ModuleManager.CommonModuleConfig.http_manager)
                    L.Diagnostics.HTTP = L.Diagnostics.HTTP + 1
                    return http:Get(url, headers, "", nil, callback, timeout)
                end,
                cancel = function(id)
                    local http = ModuleManager.GetModule(ModuleManager.CommonModuleConfig.http_manager)
                    if http and http.Cancel then
                        http:Cancel(id)
                    end
                end,
                post = function(url, headers, body, callback, timeout)
                    local http = ModuleManager.GetModule(ModuleManager.CommonModuleConfig.http_manager)
                    L.Diagnostics.HTTP = L.Diagnostics.HTTP + 1
                    return http:Post(url, headers, body, nil, callback, timeout)
                end,
                status = function(message, phase)
                    L.Status = message
                    L.Pending = phase == "pending"
                    L.Reconnecting = phase == "retry" or (L.Reconnecting and (phase == "error" or phase == "pending"))
                    L.PolicyBlocked = phase == "disabled" or L.Reconnecting == true
                    if phase == "retry" or (phase == "error" and L.Reconnecting) then
                        L.AutoRetryAt = os.time() + 30
                    end
                    if phase == "active" then
                        L.Licensed = true
                        L.Authorized = false
                        L.Key = L.AttemptKey or L.Key
                        L.Save()
                        L.SaveVerifiedKey(L.Key)
                        if L.ChannelAccepted and L.SessionKey == L.Key
                            and L.SessionChannelURL == L.ChannelURL and L.SessionDisplayName == L.DisplayName then
                            L.ChannelGate.Cancel()
                        else
                            L.ChannelAccepted = false
                        end
                        L.SessionKey, L.SessionChannelURL, L.SessionDisplayName = L.Key, L.ChannelURL, L.DisplayName
                        destroy(L.LoginUI)
                        L.LoginUI = nil
                    else
                        L.Licensed = false
                        L.Authorized = false
                        L.ChannelGate.Reset()
                        L.ClearLifecycle()
                        destroy(L.ChannelUI)
                        destroy(L.BrandUI)
                        L.ChannelUI = nil
                        L.BrandUI = nil
                    end
                    L.NeedsUpdate = true
                    local d = L.LoginUI
                    if d then
                        if d.Status and d.StatusText ~= message then
                            d.Status:SetText(message)
                            d.StatusText = message
                        end
                        if d.Busy ~= L.Pending then
                            d.Busy = L.Pending
                            pcall(function()
                                d.Input:SetIsEnabled(not L.Pending)
                                d.Button:SetIsEnabled(not L.Pending)
                            end)
                        end
                    end
                    wake()
                end,
            })
            L.Licensed = L.Auth.IsAuthorized()
            L.Authorized = false
            L.Login = function(key)
                if L.Licensed or L.Pending then
                    return false
                end
                L.AttemptKey = type(key) == "string" and key:match("^%s*(.-)%s*$") or ""
                local ok, result = pcall(L.Auth.Login, L.AttemptKey)
                if not ok then
                    L.Status = "Login could not start"
                    L.Pending = false
                    L.NeedsUpdate = true
                    wake()
                    return false
                end
                return result
            end
            L.Logout = function()
                L.AutoLoginDone, L.Reconnecting = true, false
                L.Auth.Logout()
                L.Licensed = false
                L.Authorized = false
                L.ChannelGate.Reset()
                L.ClearLifecycle()
                L.DestroyUI()
                L.NeedsUpdate = true
                wake()
            end
            L.Update = function()
                L.Auth.Tick()
                if not L.Licensed and not L.Pending and not L.IdentityError
                    and (not L.AutoLoginDone or (L.Reconnecting and os.time() >= (L.AutoRetryAt or 0))) then
                    L.AutoLoginDone = true
                    local key = validSavedKey(L.Key)
                    if key then
                        L.Reconnecting = true
                        L.AutoRetryAt = os.time() + 30
                        L.Login(key)
                    end
                end
                if L.PolicyBlocked then
                    if L.LoginUI and not L.LoginUI.IsNotice then
                        destroy(L.LoginUI)
                        L.LoginUI = nil
                    end
                    destroy(L.ChannelUI)
                    destroy(L.BrandUI)
                    L.ChannelUI = nil
                    L.BrandUI = nil
                    if not L.LoginUI then
                        L.LoginUI = UI.Build("notice", "", L.Status, function() end)
                    end
                    local d = L.LoginUI
                    if d then
                        pcall(function()
                            d.Detail:SetText(L.Status)
                        end)
                        UI.Reflow(d)
                    end
                    L.NeedsUpdate = not d
                    return
                end
                if L.Dirty and (not L.SaveRetryAt or os.time() >= L.SaveRetryAt or os.time() < L.SaveRetryAt - 30) then
                    L.Save()
                end
                if L.Licensed then
                    local p = parent()
                    if not L.ChannelGate.Ready then
                        if
                            L.ChannelUI
                            and (
                                not valid(L.ChannelUI.Container)
                                or L.ChannelUI.Parent ~= p
                                or L.ChannelUI.Waiting ~= L.ChannelGate.Waiting
                                or L.ChannelUI.Error ~= L.ChannelGate.Error
                            )
                        then
                            destroy(L.ChannelUI)
                            L.ChannelUI = nil
                        end
                        if not L.ChannelUI then
                            local gate = L.ChannelGate
                            local hint = gate.Error
                                or (
                                    gate.Waiting and "Return to the game. Tap Continue if needed."
                                    or (
                                        gate.URL == "" and "Channel not set. Cancel to continue."
                                        or "Join for updates, or Cancel to continue."
                                    )
                                )
                            L.ChannelUI = UI.Build(
                                "channel",
                                gate.Name,
                                hint,
                                {
                                    cancel = gate.Cancel,
                                    join = gate.Join,
                                    continue = gate.Continue,
                                    waiting = gate.Waiting,
                                    noLink = gate.URL == "",
                                }
                            )
                            if L.ChannelUI then
                                L.ChannelUI.Waiting = gate.Waiting
                                L.ChannelUI.Error = gate.Error
                                L.BindLifecycle()
                            end
                        end
                        if L.ChannelUI then
                            UI.Reflow(L.ChannelUI)
                        end
                        L.NeedsUpdate = true
                        return
                    end
                    if
                        L.BrandUI
                        and (not valid(L.BrandUI.Container) or (L.BrandUI.SourceParent or L.BrandUI.Parent) ~= p)
                    then
                        destroy(L.BrandUI)
                        L.BrandUI = nil
                    end
                    L.ChannelAccepted = true
                    local license =
                        { expiresAt = L.Auth.GetState().expiresAt, remainingSeconds = L.Auth.GetRemainingSeconds() }
                    if not L.BrandUI then
                        L.BrandUI = UI.Branding(L.DisplayName or "Meow", license)
                    end
                    if L.BrandUI then
                        UI.UpdateBranding(L.BrandUI, L.DisplayName or "Meow", os.time(), license)
                    end
                    L.NeedsUpdate = L.Dirty or not L.BrandUI
                    return
                end
                local p = parent()
                if L.LoginUI and (not valid(L.LoginUI.Container) or p ~= L.LoginUI.Parent) then
                    destroy(L.LoginUI)
                    L.LoginUI = nil
                end
                if not L.LoginUI then
                    local d = UI.Build("login", L.Key, L.Status, L.Login)
                    if d then
                        d.Busy = L.Pending
                        d.StatusText = L.Status
                        L.LoginUI = d
                        pcall(function()
                            d.Input:SetIsEnabled(not L.Pending)
                            d.Button:SetIsEnabled(not L.Pending)
                        end)
                    end
                end
                if L.LoginUI then
                    UI.Reflow(L.LoginUI)
                end
                L.NeedsUpdate = true
            end
        end
        _G.MasterLicenseLogin = function(key)
            return _G.LunarLoginRuntime.Login(key)
        end
        _G.MasterLicenseLogout = function()
            return _G.LunarLoginRuntime.Logout()
        end
        _G.MasterLicenseStatus = function()
            local l = _G.LunarLoginRuntime
            return {
                authorized = l.Authorized,
                pending = l.Pending,
                message = l.Status,
                periodicRecheck = false,
                expiryCheckPolicy = "signed_license_deadline",
                channelPending = l.Licensed and not l.ChannelGate.Ready,
                displayName = l.DisplayName,
                saveOK = not l.Dirty,
                identityState = l.Diagnostics.Identity,
            }
        end

        -- Download only the release bound into the verified login grant. No downloaded cache is executed.
        function API.FetchOnline(callback)
            local L = _G.LunarLoginRuntime
            if type(callback) ~= "function" or not API.IsAuthorized() then
                return false
            end
            local token, claims = L.Auth.GetAdmission()
            if not token or not claims or claims.lua_delivery ~= "online" then
                return false
            end
            local completed = false
            local function finish(fn, err)
                if not completed then
                    completed = true
                    callback(fn, err)
                end
            end
            local started, request = pcall(function()
                local http = ModuleManager.GetModule(ModuleManager.CommonModuleConfig.http_manager)
                return http:Get(
                    MasterLicenseConfig.url:gsub("action=login", "action=payload"),
                    { ["Authorization"] = "Bearer " .. token, ["Accept"] = "text/plain" },
                    "",
                    nil,
                    function(success, raw)
                        if not API.IsAuthorized() then
                            finish(nil, "Session ended. Sign in again.")
                            return
                        end
                        local currentToken = L.Auth.GetAdmission()
                        if currentToken ~= token then
                            finish(nil, "Session changed. Sign in again.")
                            return
                        end
                        if success ~= true or type(raw) ~= "string" then
                            finish(nil, "Online Lua download failed. Sign in again.")
                            return
                        end
                        if
                            #raw ~= claims.lua_size
                            or UniversalCrypto.sha256(raw, false, 2097152) ~= claims.lua_sha256
                        then
                            finish(nil, "Online Lua integrity check failed. Sign in again.")
                            return
                        end
                        local compile = type(loadstring) == "function" and loadstring or load
                        if type(compile) ~= "function" then
                            finish(nil, "This runtime cannot load online Lua. Use the local build.")
                            return
                        end
                        local compiled, fn = pcall(compile, raw, "@meow-online-" .. claims.lua_release)
                        if not compiled or type(fn) ~= "function" then
                            finish(nil, "Online Lua could not compile. Contact the owner.")
                            return
                        end
                        finish(fn)
                    end,
                    MasterLicenseConfig.timeout
                )
            end)
            if not started or type(request) ~= "number" or request <= 0 then
                finish(nil, "Online download could not start.")
                return false
            end
            return true
        end
    end

    local L = _G.LunarLoginRuntime
    API.Runtime = L
    local ticker
    pcall(function()
        ticker = require("common.time_ticker")
    end)
    -- dispatch
    local function dispatch()
        local authorized = L.Authorized == true
        for _, binding in pairs(API.Subscribers) do
            if binding.Last ~= authorized then
                binding.Last = authorized
                local callback
                if authorized then
                    callback = binding.OnAuthorized
                else
                    callback = binding.OnLocked
                end
                if callback then
                    local ok, why = pcall(callback, L.Status)
                    if not ok then
                        API.Errors = API.Errors + 1
                        API.LastError = tostring(why)
                    end
                end
            end
        end
    end
    -- update
    local function update()
        if not API.Started or API.Stopped then
            return
        end
        local ok, why = pcall(L.Update)
        if not ok then
            API.Errors = API.Errors + 1
            API.LastError = tostring(why)
        end
        dispatch()
    end
    local schedule
    schedule = function(delay)
        if API.Stopped or not API.Started or API.PendingTimer then
            return
        end
        if not ticker or type(ticker.AddTimerOnce) ~= "function" then
            API.LastError = "TIMER_UNAVAILABLE"
            return
        end
        API.PendingTimer = true
        local ok, why = pcall(ticker.AddTimerOnce, delay, function()
            if API.Stopped or _G.AdityaOrgLogin ~= API then
                return
            end
            API.PendingTimer = false
            update()
            if L.NeedsUpdate or L.Pending or L.Dirty or L.Licensed then
                schedule(L.Authorized and 1.0 or 0.5)
            end
        end)
        if not ok then
            API.PendingTimer = false
            API.Errors = API.Errors + 1
            API.LastError = tostring(why)
        end
    end
    API._Wake = function()
        if API.Started and not API.Stopped then
            schedule(0.01)
        end
    end
    -- Start
    function API.Start(options)
        if API.Stopped then
            return false, "MODULE_STOPPED"
        end
        options = options or {}
        if options.settingsPath then
            L.BindSettingsPath(options.settingsPath)
        elseif not API.StorageLocated then
            API.StorageLocated = true
            for _, suffix in ipairs({ "ADITYA_FEATURES_V3_settings.lua", "ADITYA_UMG_ESP_settings.lua" }) do
                for _, path in ipairs(g_adityaorg_ESPSettingsPaths()) do
                    path = path:gsub("ADITYA_UMG_ESP_settings%.lua$", suffix)
                    local ok, file = pcall(function()
                        return io.open(path, "r")
                    end)
                    if ok and file then
                        local good, first = pcall(function()
                            return file:read(1)
                        end)
                        pcall(function()
                            file:close()
                        end)
                        if good and type(first) == "string" and first ~= "" then
                            API.StoragePath = path
                            break
                        end
                    end
                end
                if API.StoragePath then
                    break
                end
            end
            if API.StoragePath then
                L.BindSettingsPath(API.StoragePath)
            end
        end
        API.Started = true
        L.NeedsUpdate = true
        if options.onAuthorized or options.onLocked then
            API.Bind(options.onAuthorized, options.onLocked)
        end
        update()
        schedule(0.01)
        return true
    end
    -- Bind
    function API.Bind(onAuthorized, onLocked)
        assert(type(onAuthorized) == "function" or type(onLocked) == "function", "CALLBACK_REQUIRED")
        local handle = { OnAuthorized = onAuthorized, OnLocked = onLocked, Last = nil }
        API.Subscribers[handle] = handle
        if API.Started then
            dispatch()
        end
        return function()
            API.Subscribers[handle] = nil
        end
    end
    -- IsAuthorized
    function API.IsAuthorized()
        return not API.Stopped and L.Authorized == true
    end
    -- Login
    function API.Login(key)
        if not API.Started then
            API.Start()
        end
        if API.Stopped then
            return false
        end
        local result = L.Login(key)
        API._Wake()
        return result
    end
    -- Logout
    function API.Logout()
        if API.Stopped then
            return
        end
        L.Logout()
        dispatch()
        API._Wake()
    end
    function API.OnlineError(message, restartRequired)
        L.Auth.FailClosed(message or "Online Lua unavailable. Sign in again.", restartRequired == true)
        API._Wake()
    end
    function API.SetBuildInfo(info)
        for k, v in pairs(info) do
            MeowBuild[k] = v
        end
        L.NeedsUpdate = true
        API._Wake()
    end
    -- Status
    function API.Status()
        return {
            authorized = API.IsAuthorized(),
            pending = L.Pending,
            message = L.Status,
            luaVersion = MeowBuild.Version,
            errors = API.Errors,
            lastError = API.LastError,
            endpoint = MeowPack.ConnectionURL or "",
        }
    end
    -- Update
    function API.Update()
        update()
    end
    -- Stop
    function API.Stop()
        if API.Stopped then
            return
        end

        L.Logout()
        dispatch()
        API.Stopped = true
        API.Started = false
        L.DestroyUI()
        API.Subscribers = {}
    end

    return API
end)()

-- ============================================================================
-- // PERFORMANCE SETTINGS / SHARED CACHE //
-- ============================================================================
-- startBaselineHacks
-- ============================================================================
-- PERFORMANCE CONFIGURATION / SHARED SERVICES
-- Refresh rates below are overlay work rates, not the game's FPS limit.
-- No global garbage-collector or game rendering-quality settings are changed.
-- ============================================================================
local MeowPerformance = {
    Revision = "2026.11.14.2",
    LineFPS = 30,
    ESP2FPS = 30,
    PawnScanSeconds = 0.25,
    VisibilitySeconds = 0.35,
    CanvasTransformSeconds = 0.50,
    WallCleanupSeconds = 0.10,
    WallApplySeconds = 0.30,
    WallRefreshSeconds = 1.50,
    PixelEpsilon = 0.25,
    AngleEpsilon = 0.10,
    MenuMaintenanceSeconds = 5.0,
    Diagnostics = false,
}

local MeowPerf = { Config = MeowPerformance, Counters = {}, PawnAt = -math.huge }
_G.MeowPerformanceRuntime = MeowPerf

function MeowPerf.Count(name, amount)
    if MeowPerformance.Diagnostics then
        MeowPerf.Counters[name] = (MeowPerf.Counters[name] or 0) + (amount or 1)
    end
end

-- One bounded roster cache is shared by render, wall and legacy ESP consumers.
-- Cache empty results too; an empty world must not cause 60 fallback scans/sec.
function MeowPerf.Pawns(fetch, now, world)
    if
        MeowPerf.PawnList
        and MeowPerf.PawnWorld == world
        and now >= MeowPerf.PawnAt
        and now - MeowPerf.PawnAt < MeowPerformance.PawnScanSeconds
    then
        return MeowPerf.PawnList
    end
    local found = fetch()
    local list, seen = {}, {}
    if found then
        for _, actor in pairs(found) do
            if actor ~= nil and not seen[actor] then
                seen[actor] = true
                list[#list + 1] = actor
            end
        end
    end
    MeowPerf.PawnList, MeowPerf.PawnWorld, MeowPerf.PawnAt = list, world, now
    MeowPerf.Count("PawnScans")
    return list
end

function MeowPerf.InvalidatePawns()
    MeowPerf.PawnList, MeowPerf.PawnWorld = nil, nil
    MeowPerf.PawnAt = -math.huge
end

function MeowPerf.Now()
    if MeowPerf.Clock then
        return MeowPerf.Clock()
    end
    return os.clock()
end

function MeowPerf.Palette(cfg)
    local p = MeowPerf.PaletteState
    if
        p
        and p.Config == cfg
        and p.Enabled == cfg.WallHackEnabled
        and p.EV == cfg.ColorEnemyWHVis
        and p.EO == cfg.ColorEnemyWHOcc
        and p.BV == cfg.ColorBotWHVis
        and p.BO == cfg.ColorBotWHOcc
        and p.Glow == cfg.GlowIntensity
    then
        return p.Key
    end
    p = p or {}
    p.Config, p.Enabled = cfg, cfg.WallHackEnabled
    p.EV, p.EO, p.BV, p.BO, p.Glow =
        cfg.ColorEnemyWHVis, cfg.ColorEnemyWHOcc, cfg.ColorBotWHVis, cfg.ColorBotWHOcc, cfg.GlowIntensity
    p.Key = cfg.WallHackEnabled
            and table.concat({
                tostring(p.EV),
                tostring(p.EO),
                tostring(p.BV),
                tostring(p.BO),
                tostring(p.Glow),
            }, ":")
        or "default"
    MeowPerf.PaletteState = p
    return p.Key
end

function MeowPerf.HideLine(data)
    if not data or data._Visible == false then
        return
    end
    if data.Widget and slua.isValid(data.Widget) then
        local ok = pcall(data.Widget.SetWidgetVisibility, data.Widget, UEnums.ESlateVisibility.Collapsed)
        if ok then
            data._Visible = false
        end
    end
end

-- A getter/setter result is cached only after success; failed native calls retry.
function MeowPerf.LineGeometry(data, widget, slot, x, y, width, height, angle, fresh)
    local epsilon = MeowPerformance.PixelEpsilon
    local positionChanged = fresh
        or data._LastX == nil
        or math.abs(data._LastX - x) >= epsilon
        or math.abs(data._LastY - y) >= epsilon
    local sizeChanged = fresh
        or data._LastW == nil
        or math.abs(data._LastW - width) >= epsilon
        or math.abs(data._LastH - height) >= 0.05
    local angleChanged = fresh
        or data._LastAngle == nil
        or math.abs(data._LastAngle - angle) >= MeowPerformance.AngleEpsilon
    if positionChanged then
        local ok = pcall(slot.SetPosition, slot, data._CachedPosVec)
        if ok then
            data._LastX, data._LastY = x, y
        end
        MeowPerf.Count("LinePositionWrites")
    end
    if sizeChanged then
        local ok = pcall(slot.SetSize, slot, data._CachedSizeVec)
        if ok then
            data._LastW, data._LastH = width, height
        end
        MeowPerf.Count("LineSizeWrites")
    end
    if angleChanged then
        local ok = pcall(widget.SetRenderAngle, widget, angle)
        if ok then
            data._LastAngle = angle
        end
        MeowPerf.Count("LineAngleWrites")
    end
    if fresh then
        pcall(slot.SetZOrder, slot, 1)
    end
end

function MeowPerf.Diagnostics()
    local copy = { Revision = MeowPerformance.Revision, LineFPS = MeowPerformance.LineFPS }
    for name, value in pairs(MeowPerf.Counters) do
        copy[name] = value
    end
    return copy
end

-- ============================================================================
-- // FEATURE HOST / SAVED SETTINGS / IPAD VIEW //
-- ============================================================================
local function startBaselineHacks()
    local GameplayData = require("GameLua.GameCore.Data.GameplayData")
    local EPawnState = import("EPawnState")
    local UKismetSystemLibrary = import("KismetSystemLibrary")
    _G.g_adityaorg = _G.g_adityaorg or "@ADITYA_ORG"
    local g_adityaorg_StartSettingsMaintenance

    _G.LexusConfig = _G.LexusConfig or {}
    _G.LexusConfig.IpadView = _G.LexusConfig.IpadView or false
    _G.LexusState = _G.LexusState or {}
    _G.LexusState.CustomTextData = _G.LexusState.CustomTextData or {}
    _G.LexusState.CustomTextData.IpadViewFOV = _G.LexusState.CustomTextData.IpadViewFOV or 120

    -- g_adityaorg_GetLocalPlayer
    local function g_adityaorg_GetLocalPlayer()
        local ok, GDP = pcall(require, "GameLua.GameCore.Data.GameplayData")
        if not ok or not GDP then
            return nil
        end
        local player = GDP.GetPlayerCharacter()
        if player and slua.isValid(player) then
            return player
        end
        return nil
    end

    -- g_adityaorg_ApplyiPadView
    local function g_adityaorg_ApplyiPadView()
        local player = g_adityaorg_GetLocalPlayer()
        if not player then
            return
        end
        local cam = player.ThirdPersonCameraComponent
        if not cam or not slua.isValid(cam) then
            return
        end
        if player.bIsWeaponAiming then
            return
        end

        if _G.LexusConfig.IpadView and _G.LunarLoginRuntime and _G.LunarLoginRuntime.Authorized then
            local targetFOV = _G.LexusState.CustomTextData.IpadViewFOV or 120
            if cam.FieldOfView ~= targetFOV then
                cam.FieldOfView = targetFOV
            end
        else
            if cam.FieldOfView ~= 90 then
                cam.FieldOfView = 90
            end
        end
    end

    local g_adityaorg_ESPOptionDefaults = {
        Line = false,
        Box = false,
    }
    _G.g_adityaorg_ESPOptions = _G.g_adityaorg_ESPOptions or {}
    for k, v in pairs(g_adityaorg_ESPOptionDefaults) do
        if _G.g_adityaorg_ESPOptions[k] == nil then
            _G.g_adityaorg_ESPOptions[k] = v
        end
    end
    local g_adityaorg_ESPSettingsFile = "ADITYA_UMG_ESP_settings.lua"
    -- g_adityaorg_ESPSettingsPaths
    local function g_adityaorg_ESPSettingsPaths()
        local paths = {
            "//storage/emulated/0/Android/data/com.tencent.ig/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/SaveGames/"
                .. g_adityaorg_ESPSettingsFile,
            "//storage/emulated/0/Android/data/com.vng.pubgmobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/SaveGames/"
                .. g_adityaorg_ESPSettingsFile,
            "//storage/emulated/0/Android/data/com.pubg.krmobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/SaveGames/"
                .. g_adityaorg_ESPSettingsFile,
            "//storage/emulated/0/Android/data/com.rekoo.pubgm/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/SaveGames/"
                .. g_adityaorg_ESPSettingsFile,
            "//storage/emulated/0/Android/data/com.pubg.imobile/files/UE4Game/ShadowTrackerExtra/ShadowTrackerExtra/Saved/SaveGames/"
                .. g_adityaorg_ESPSettingsFile,
            "Documents/ShadowTrackerExtra/Saved/SaveGames/" .. g_adityaorg_ESPSettingsFile,
            "ShadowTrackerExtra/Saved/SaveGames/" .. g_adityaorg_ESPSettingsFile,
            g_adityaorg_ESPSettingsFile,
        }
        local home = nil
        pcall(function()
            if os and os.getenv then
                home = os.getenv("HOME")
            end
        end)
        if type(home) == "string" and home ~= "" then
            table.insert(
                paths,
                1,
                home .. "/Documents/ShadowTrackerExtra/Saved/SaveGames/" .. g_adityaorg_ESPSettingsFile
            )
        end
        return paths
    end

    -- g_adityaorg_ESPWriteSettings
    local function g_adityaorg_ESPWriteSettings(path, payload)
        local atomic = os and type(os.rename) == "function"
        local target = atomic and path .. ".tmp" or path
        local opened, file = pcall(io.open, target, "w")
        if not opened or not file then
            return false, "Open failed: " .. target
        end
        local closed = false
        local ok, err = pcall(function()
            local result, reason = file:write(payload)
            assert(result, reason or "Settings write failed")
            if file.flush then
                local flushed, why = file:flush()
                assert(flushed, why or "Settings flush failed")
            end
            local result, reason = file:close()
            closed = true
            assert(result, reason or "Settings close failed")
        end)
        if not closed then
            pcall(function()
                file:close()
            end)
        end
        if ok and atomic then
            local called, result, reason = pcall(os.rename, target, path)
            ok = called and result ~= nil and result ~= false
            err = ok and nil or (reason or result or "Settings rename failed")
        end
        if not ok and atomic and os.remove then
            pcall(os.remove, target)
        end
        return ok, err, atomic
    end

    local g_adityaorg_ESPLoadedSettingsPath = nil

    -- g_adityaorg_ESPLoadSettings
    local function g_adityaorg_ESPLoadSettings()
        if not io or type(io.open) ~= "function" then
            return false
        end
        local paths = g_adityaorg_ESPSettingsPaths()
        local content = nil
        for _, path in ipairs(paths) do
            local ok, f = pcall(io.open, path, "r")
            if ok and f then
                local rok, text = pcall(function()
                    return f:read("*a")
                end)
                pcall(function()
                    f:close()
                end)
                if rok and type(text) == "string" and text ~= "" then
                    content = text
                    g_adityaorg_ESPLoadedSettingsPath = path
                    break
                end
            end
        end
        if not content then
            return false
        end
        for k in pairs(g_adityaorg_ESPOptionDefaults) do
            local v = content:match(k .. "%s*=%s*(true)") or content:match(k .. "%s*=%s*(false)")
            if v then
                _G.g_adityaorg_ESPOptions[k] = (v == "true")
            end
        end
        return true
    end
    g_adityaorg_ESPLoadSettings()

    -- ============================================================================
    -- // WELCOME DIALOG //
    -- ============================================================================
    do
        local UI = { Version = "LunarStandaloneWelcome.1" }
        -- member
        local function member(o, k)
            if o == nil then
                return nil
            end
            local ok, v = pcall(function()
                return o[k]
            end)
            if ok then
                return v
            end
        end
        -- valid
        local function valid(o)
            if o == nil then
                return false
            end
            local ok, v = pcall(slua.isValid, o)
            return ok and v == true
        end
        local vectorClass = rawget(_G, "FVector2D") or import("Vector2D")
        local colorClass = rawget(_G, "FLinearColor") or import("LinearColor")
        local anchorClass = rawget(_G, "Anchors")
        local importedAnchorClass
        pcall(function()
            importedAnchorClass = import("Anchors")
        end)
        -- vector
        local function vector(x, y)
            return vectorClass(x, y)
        end
        -- color
        local function color(r, g, b, a)
            -- linear
            local function linear(v)
                v = v / 255
                if v <= 0.04045 then
                    return v / 12.92
                end
                return ((v + 0.055) / 1.055) ^ 2.4
            end
            return colorClass(linear(r), linear(g), linear(b), a or 1)
        end
        -- visibility
        local function visibility(w, v)
            local fn = member(w, "SetWidgetVisibility") or member(w, "SetVisibility")
            assert(type(fn) == "function", "UI_VISIBILITY_UNAVAILABLE")
            fn(w, v)
        end
        -- parent
        local function parent()
            local ok, t = pcall(require, "GameLua.Mod.BaseMod.Common.UI.InGameUITools")
            if not ok or type(member(t, "GetMainControlBaseUI")) ~= "function" then
                return
            end
            local found, root = pcall(t.GetMainControlBaseUI)
            if not found or not valid(root) then
                return
            end
            local p = member(root, "CanvasPanel_0")
            if not valid(p) then
                p = member(root, "CanvasPanel_42")
            end
            if valid(p) then
                return p
            end
        end
        -- destroy
        local function destroy(d)
            if not d then
                return
            end
            d.Visible = false
            if d.Event and d.Handle ~= nil then
                pcall(function()
                    d.Event:Remove(d.Handle)
                end)
            end
            if valid(d.Container) then
                pcall(function()
                    d.Container:RemoveFromParent()
                end)
            end
            d.Submit = nil
            d.Event = nil
            d.Handle = nil
            d.Container = nil
            d.Parent = nil
            d.Input = nil
            d.Button = nil
            d.Status = nil
            d.Title = nil
            d.Detail = nil
            d.Hint = nil
            d.Design = nil
            d.Cache = nil
        end

        -- Build
        function UI.Build(kind, key, status, submit)
            local p = parent()
            if not p then
                return nil, "UI_NOT_READY"
            end
            local enums = UEnums.ESlateVisibility
            local passive = enums.SelfHitTestInvisible
            if enums.Visible == nil or passive == nil then
                return nil, "UI_ENUM_UNAVAILABLE"
            end
            local welcome = true
            local W, H = welcome and 600 or 500, 322
            local scale = welcome and 0.8 or 1
            pcall(function()
                local v = p:GetCachedGeometry():GetLocalSize()
                if v.X > 24 and v.Y > 24 then
                    scale = math.min(scale, (v.X - 24) / W, (v.Y - 24) / H)
                end
            end)
            local d = { Parent = p, Visible = false, Submit = submit, Scale = scale }
            local ok, buildError = pcall(function()
                -- make
                local function make(class, outer)
                    local w = CGame:NewObjectFromPath("/Script/UMG." .. class, outer)
                    assert(valid(w), "UI_WIDGET_UNAVAILABLE")
                    return w
                end
                d.Container = make("CanvasPanel", p)

                local slot = p:AddChildToCanvas(d.Container)
                assert(slot ~= nil, "UI_CANVAS_SLOT_UNAVAILABLE")
                local got, anchors = pcall(function()
                    return anchorClass()
                end)
                if not got or not anchors then
                    got, anchors = pcall(function()
                        return importedAnchorClass()
                    end)
                end
                if not got or not anchors then
                    local getter = member(slot, "GetAnchors")
                    if type(getter) == "function" then
                        got, anchors = pcall(getter, slot)
                    end
                end
                assert(got and anchors, "UI_ANCHORS_UNAVAILABLE")
                anchors.Minimum = vector(0.5, 0.5)
                anchors.Maximum = vector(0.5, 0.5)
                slot:SetAutoSize(false)
                slot:SetSize(vector(W, H))
                slot:SetZOrder(9200)
                slot:SetAnchors(anchors)
                slot:SetAlignment(vector(0.5, 0.5))
                slot:SetPosition(vector(0, 0))
                local pivot = member(d.Container, "SetRenderTransformPivot")
                if type(pivot) == "function" then
                    pcall(pivot, d.Container, vector(0.5, 0.5))
                end
                local resize = member(d.Container, "SetRenderScale")
                if type(resize) == "function" then
                    pcall(resize, d.Container, vector(scale, scale))
                end
                visibility(d.Container, passive)
                local design = make("CanvasPanel", d.Container)
                d.Design = design
                local artRoot = design
                local canCache, cache = pcall(make, "InvalidationBox", d.Container)
                if canCache and valid(cache) and type(member(cache, "SetCanCache")) == "function" then
                    local attached = pcall(function()
                        cache:AddChild(design)
                        cache:SetCanCache(true)
                        visibility(cache, passive)
                    end)
                    if attached then
                        artRoot = cache
                        d.Cache = cache
                    end
                end
                local artSlot = d.Container:AddChildToCanvas(artRoot)
                artSlot:SetAutoSize(false)
                artSlot:SetPosition(vector(0, 0))
                artSlot:SetSize(vector(W, H))
                artSlot:SetZOrder(1)
                visibility(design, passive)
                -- add
                local function add(w, x, y, ww, hh, z, dynamic)
                    local slot = (dynamic and d.Container or design):AddChildToCanvas(w)
                    slot:SetAutoSize(false)
                    slot:SetPosition(vector(x, y))
                    slot:SetSize(vector(ww, hh))
                    slot:SetZOrder(z)
                    return slot
                end

                local artwork = {}
                -- drawRect
                local function drawRect(x, y, ww, hh, c, z, opacity)
                    local w = make("Border", d.Container)
                    w:SetBrushColor(colorClass(c.R, c.G, c.B, opacity or 0.5))
                    visibility(w, passive)
                    add(w, x, y, ww, hh, z)
                    return w
                end
                -- rect
                local function rect(x, y, ww, hh, c, z, opacity)
                    artwork[#artwork + 1] =
                        { X = x, Y = y, W = ww, H = hh, C = c, Z = z, A = opacity or 0.5, Order = #artwork + 1 }
                end
                -- renderArt
                local function renderArt()
                    table.sort(artwork, function(a, b)
                        if a.Z == b.Z then
                            return a.Order > b.Order
                        end
                        return a.Z > b.Z
                    end)
                    local covered = {}
                    -- put
                    local function put(out, x, y, w, h)
                        if w > 0.00001 and h > 0.00001 then
                            out[#out + 1] = { X = x, Y = y, W = w, H = h }
                        end
                    end
                    for _, shape in ipairs(artwork) do
                        local pieces = { { X = shape.X, Y = shape.Y, W = shape.W, H = shape.H } }
                        for _, cover in ipairs(covered) do
                            local nextPieces = {}
                            for _, piece in ipairs(pieces) do
                                local x1 = math.max(piece.X, cover.X)
                                local y1 = math.max(piece.Y, cover.Y)
                                local x2 = math.min(piece.X + piece.W, cover.X + cover.W)
                                local y2 = math.min(piece.Y + piece.H, cover.Y + cover.H)
                                if x2 <= x1 or y2 <= y1 then
                                    nextPieces[#nextPieces + 1] = piece
                                else
                                    put(nextPieces, piece.X, piece.Y, piece.W, y1 - piece.Y)
                                    put(nextPieces, piece.X, y2, piece.W, piece.Y + piece.H - y2)
                                    put(nextPieces, piece.X, y1, x1 - piece.X, y2 - y1)
                                    put(nextPieces, x2, y1, piece.X + piece.W - x2, y2 - y1)
                                end
                            end
                            pieces = nextPieces
                            if #pieces == 0 then
                                break
                            end
                        end

                        local changed = true
                        while changed do
                            changed = false
                            for i = 1, #pieces do
                                local a = pieces[i]
                                for j = i + 1, #pieces do
                                    local b = pieces[j]
                                    local vertical = math.abs(a.X - b.X) < 0.00001
                                        and math.abs(a.W - b.W) < 0.00001
                                        and (math.abs(a.Y + a.H - b.Y) < 0.00001 or math.abs(b.Y + b.H - a.Y) < 0.00001)
                                    local horizontal = math.abs(a.Y - b.Y) < 0.00001
                                        and math.abs(a.H - b.H) < 0.00001
                                        and (math.abs(a.X + a.W - b.X) < 0.00001 or math.abs(b.X + b.W - a.X) < 0.00001)
                                    if vertical or horizontal then
                                        local x, y = math.min(a.X, b.X), math.min(a.Y, b.Y)
                                        a.W = math.max(a.X + a.W, b.X + b.W) - x
                                        a.H = math.max(a.Y + a.H, b.Y + b.H) - y
                                        a.X = x
                                        a.Y = y
                                        table.remove(pieces, j)
                                        changed = true
                                        break
                                    end
                                end
                                if changed then
                                    break
                                end
                            end
                        end
                        for _, piece in ipairs(pieces) do
                            drawRect(piece.X, piece.Y, piece.W, piece.H, shape.C, shape.Z, shape.A)
                        end
                        covered[#covered + 1] = shape
                    end
                    artwork = nil
                end
                -- sample
                local function sample(stops, t, opacity)
                    t = math.max(0, math.min(1, t))
                    local a, b, u
                    if t <= 0.5 then
                        a, b, u = stops[1], stops[2], t * 2
                    else
                        a, b, u = stops[2], stops[3], (t - 0.5) * 2
                    end
                    return color(a[1] + (b[1] - a[1]) * u, a[2] + (b[2] - a[2]) * u, a[3] + (b[3] - a[3]) * u, opacity)
                end
                -- panel
                local function panel(x, y, ww, hh, cut, stops, z, columns, opacity)
                    columns = math.min(columns, 12)
                    for i = 0, columns - 1 do
                        local a = ww * i / columns
                        local b = ww * (i + 1) / columns
                        local inset = math.max(0, cut - math.min(a, ww - b))
                        rect(
                            x + a,
                            y + inset,
                            b - a,
                            hh - inset * 2,
                            sample(stops, (i + 0.5) / columns, opacity),
                            z,
                            opacity
                        )
                    end
                end
                -- rail
                local function rail(x, y, ww, hh, stops, z, columns)
                    columns = math.min(columns, 12)
                    for i = 0, columns - 1 do
                        rect(x + ww * i / columns, y, ww / columns, hh, sample(stops, (i + 0.5) / columns), z)
                    end
                end
                -- line
                local function line(ax, ay, bx, by, th, c, z)
                    local dx, dy = bx - ax, by - ay
                    local len = math.sqrt(dx * dx + dy * dy)
                    if len <= 0 then
                        return
                    end
                    local angle
                    if dx == 0 then
                        angle = dy >= 0 and 90 or -90
                    else
                        angle = math.atan(dy / dx) * 180 / math.pi
                        if dx < 0 then
                            angle = angle + 180
                        end
                    end
                    local w = drawRect((ax + bx - len) / 2, (ay + by - th) / 2, len, th, c, z, z >= 7 and 1 or 0.5)
                    w:SetRenderTransformPivot(vector(0.5, 0.5))
                    w:SetRenderAngle(angle)
                end
                local slate = import("SlateColor")
                local fontObject
                if slua and type(slua.loadObject) == "function" then
                    local loaded, obj = pcall(slua.loadObject, "/Engine/EngineFonts/Roboto.Roboto")
                    if loaded and valid(obj) then
                        fontObject = obj
                    end
                end
                -- style
                local function style(w, size, c, bold)
                    local font = member(w, "Font")
                    if font then
                        if type(font) == "table" then
                            local copy = {}
                            for k, v in pairs(font) do
                                copy[k] = v
                            end
                            font = copy
                        end
                        font.Size = size
                        if fontObject then
                            font.FontObject = fontObject
                            font.TypefaceFontName = bold and "Bold" or "Regular"
                        end
                        if font.OutlineSettings then
                            local outline = font.OutlineSettings
                            if type(outline) == "table" then
                                local copy = {}
                                for k, v in pairs(outline) do
                                    copy[k] = v
                                end
                                outline = copy
                            end
                            outline.OutlineSize = 0
                            font.OutlineSettings = outline
                        end
                        w:SetFont(font)
                    end
                    w:SetColorAndOpacity(slate(c))
                    pcall(function()
                        w:SetShadowOffset(vector(0, 0))
                        w:SetShadowColorAndOpacity(color(0, 0, 0, 0))
                    end)
                    pcall(function()
                        w:SetAutoWrapText(true)
                    end)
                end
                -- text
                local function text(value, x, y, ww, hh, size, c, z, bold, center, dynamic)
                    local w = make("TextBlock", d.Container)
                    w:SetText(value)
                    style(w, size, c, bold)
                    visibility(w, passive)
                    add(w, x, y, ww, hh, z, dynamic)
                    if center then
                        pcall(function()
                            w:SetJustification(1)
                        end)
                    end
                    return w
                end
                local frame = { { 0, 229, 255 }, { 255, 0, 229 }, { 0, 229, 255 } }
                local bright = { { 180, 255, 255 }, { 255, 180, 255 }, { 255, 255, 255 } }
                local edge = { { 0, 55, 75 }, { 60, 0, 70 }, { 0, 40, 60 } }
                local body = { { 5, 8, 18 }, { 10, 16, 30 }, { 14, 22, 42 } }
                local header = { { 6, 14, 30 }, { 10, 40, 70 }, { 8, 70, 110 } }
                local gold = { { 60, 40, 5 }, { 150, 110, 20 }, { 245, 180, 40 } }
                local white = color(255, 255, 255)
                local forest = color(231, 243, 255)
                local burgundy = color(192, 221, 255)

                panel(6, 6, W - 12, H - 12, 10, body, 2, 24, 0.5)
                rail(13, 0, W - 26, 6, frame, 3, 24)
                rail(13, H - 6, W - 26, 6, frame, 3, 24)
                rect(0, 13, 6, H - 26, color(4, 13, 29), 3)
                rect(W - 6, 13, 6, H - 26, color(14, 126, 255), 3)
                rail(13, 1, W - 26, 1.5, bright, 3, 24)
                rail(13, H - 3, W - 26, 1.5, edge, 3, 24)
                rect(1, 13, 1.5, H - 26, color(68, 134, 211), 3)
                rect(W - 3, 13, 1.5, H - 26, color(180, 222, 255), 3)
                for _, s in ipairs({ { 1, 13, 13, 1 }, { 1, H - 13, 13, H - 1 } }) do
                    line(s[1], s[2], s[3], s[4], 2, color(91, 159, 239), 3)
                end
                for _, s in ipairs({ { W - 13, 1, W - 1, 13 }, { W - 13, H - 1, W - 1, H - 13 } }) do
                    line(s[1], s[2], s[3], s[4], 2, color(154, 211, 255), 3)
                end
                panel(10, 10, W - 20, 65, 16, gold, 4, 24, 1)
                panel(13, 13, W - 26, 59, 14, header, 5, 32, 1)
                d.Title = text("Welcome to ADITYA_ORG PREMIUM LUA", 24, 22, W - 48, 42, 19, white, 7, true, true)
                local pw = math.min(340, W - 72)
                local px = (W - pw) / 2
                panel(px, 99, pw, 51, 12, gold, 4, 16)
                panel(px + 3, 102, pw - 6, 45, 10, { { 4, 19, 42 }, { 13, 68, 132 }, { 4, 28, 64 } }, 5, 20)
                d.Detail = text("Kill limit 8-10", px + 16, 109, pw - 32, 34, 23, white, 7, true, true)
                d.Hint = text("Play smart and avoid report", 30, 165, W - 60, 32, 17, forest, 7, true, true)
                local button = make("Button", d.Container)
                d.Button = button
                local by = welcome and 212 or 201
                local bh = welcome and 42 or 34
                local bw = welcome and 202 or 190
                local bx = (W - bw) / 2
                panel(bx - 4, by - 3, bw + 8, bh + 6, 9, gold, 4, 16)
                panel(bx, by, bw, bh, 8, { { 6, 50, 25 }, { 18, 140, 70 }, { 6, 50, 25 } }, 5, 16)
                pcall(function()
                    button:SetBackgroundColor(color(255, 255, 255, 0))
                end)
                visibility(button, enums.Visible)
                local label = make("TextBlock", button)
                label:SetText("OK")
                style(label, 17, white, true)
                visibility(label, passive)
                local labelSlot = button:AddChild(label)
                pcall(function()
                    labelSlot:SetHorizontalAlignment(2)
                    labelSlot:SetVerticalAlignment(2)
                end)
                add(button, bx, by, bw, bh, 9, true)
                d.Event = button.OnClicked
                d.Handle = d.Event:Add(function()
                    if not d.Visible or d.Busy then
                        return
                    end
                    if welcome then
                        destroy(d)
                        d.Dismissed = true
                        local l = _G.LunarStandaloneWelcome
                        if l and l.WelcomeUI == d then
                            l.WelcomeUI = nil
                            l.Dismissed = true
                            l.NeedsUpdate = false
                        end
                        return
                    end
                    local okRead, k = pcall(function()
                        return d.Input:GetText()
                    end)
                    if not okRead or type(k) ~= "string" then
                        return
                    end
                    k = k:match("^%s*(.-)%s*$")
                    if #k == 0 or #k > 512 then
                        d.Status:SetText("Enter a valid key")
                        return
                    end
                    if d.Submit then
                        d.Submit(k)
                    end
                end)

                do
                    -- linkButton
                    local function linkButton(x, y, ww, hh, label, stops, url)
                        local b = make("Button", d.Container)
                        panel(x - 3, y - 3, ww + 6, hh + 6, 8, gold, 4, 16)
                        panel(x, y, ww, hh, 7, stops, 5, 16)
                        pcall(function()
                            b:SetBackgroundColor(color(255, 255, 255, 0))
                        end)
                        visibility(b, enums.Visible)
                        local lb = make("TextBlock", b)
                        lb:SetText(label)
                        style(lb, 15, white, true)
                        visibility(lb, passive)
                        local ls = b:AddChild(lb)
                        pcall(function()
                            ls:SetHorizontalAlignment(2)
                            ls:SetVerticalAlignment(2)
                        end)
                        add(b, x, y, ww, hh, 9, true)
                        local ev = b.OnClicked
                        if ev and ev.Add then
                            ev:Add(function()
                                if _G.OpenExternalLink then
                                    pcall(_G.OpenExternalLink, url or _G.ADITYA_JOIN_URL)
                                end
                            end)
                        end
                        return b
                    end
                    local bh2 = 36
                    local by2 = 268
                    local bwA = math.floor((W - 72) * 0.5)
                    local bwB = math.floor((W - 72) * 0.5)
                    linkButton(
                        24,
                        by2,
                        bwA,
                        bh2,
                        "@ADITYA_ORG",
                        { { 4, 40, 60 }, { 10, 110, 150 }, { 4, 40, 60 } },
                        _G.ADITYA_JOIN_URL
                    )
                    linkButton(
                        W - 24 - bwB,
                        by2,
                        bwB,
                        bh2,
                        "GET KEY",
                        { { 6, 50, 25 }, { 18, 140, 70 }, { 6, 50, 25 } },
                        _G.ADITYA_JOIN_URL
                    )
                end
                renderArt()
            end)
            if not ok then
                UI.LastBuildError = tostring(buildError)
                destroy(d)
                return nil, "UI_BUILD_UNAVAILABLE"
            end
            UI.LastBuildError = nil
            d.Visible = true
            return d
        end

        local old = _G.LunarStandaloneWelcome
        if old and old.DestroyUI then
            pcall(old.DestroyUI)
        end
        local W = { WelcomeShown = false, NeedsUpdate = true, UIFactory = UI, Attempts = 0, BuildAttempts = 0 }
        _G.LunarStandaloneWelcome = W
        W.DestroyUI = function()
            destroy(W.WelcomeUI)
            W.WelcomeUI = nil
        end
        W.ContextChanged = function(world, pc, pawn, now)
            W.World = world
            W.PC = pc
            W.Pawn = pawn
            W.LastClock = now
            W.ReadyAt = nil
            W.Due = nil
            W.Attempts = 0
            W.Blocked = false
            W.NeedsUpdate = not W.WelcomeShown and not W.Dismissed
        end
        W.Update = function(now, world, pc, pawn)
            if W.WelcomeShown or W.Dismissed then
                W.NeedsUpdate = false
                W.Due = nil
                return
            end
            if W.World ~= world or W.PC ~= pc or W.Pawn ~= pawn or (W.LastClock and now < W.LastClock) then
                W.ContextChanged(world, pc, pawn, now)
            end
            W.LastClock = now
            if W.Blocked then
                return
            end
            if not world or not pc or not pawn then
                W.ReadyAt = nil
                W.Due = nil
                return
            end
            if W.Due and now < W.Due then
                return
            end

            if member(pawn, "bHidden") == true or member(pawn, "bHiddenInGame") == true then
                W.ReadyAt = nil
                W.Due = now + 0.5
                return
            end
            if not W.ReadyAt then
                W.ReadyAt = now
                W.Due = now + 3
                return
            end
            if now < W.ReadyAt + 3 then
                W.Due = W.ReadyAt + 3
                return
            end
            W.BuildAttempts = W.BuildAttempts + 1
            if _G.__LUNAR_WELCOME_SHOWN then
                W.WelcomeShown = true
                W.NeedsUpdate = false
                W.Due = nil
                return
            end
            local d, why = UI.Build("welcome")
            if d then
                W.WelcomeUI = d
                W.WelcomeShown = true
                W.NeedsUpdate = false
                W.Due = nil
                W.LastError = nil
                _G.__LUNAR_WELCOME_SHOWN = true
            else
                W.LastError = why
                if why == "UI_NOT_READY" then
                    W.Due = now + 0.5
                else
                    W.Attempts = W.Attempts + 1
                    if W.Attempts >= 3 then
                        W.Blocked = true
                        W.NeedsUpdate = false
                        W.Due = nil
                    else
                        W.Due = now + W.Attempts
                    end
                end
            end
        end
    end

    -- ============================================================================
    -- // NATIVE SETTINGS MENU //
    -- ============================================================================
    _G.ADITYA_JOIN_URL = _G.ADITYA_JOIN_URL or "https://t.me/ADITYA_ORG"
    _G.OpenExternalLink = _G.OpenExternalLink
        or function(url)
            url = (type(url) == "string" and url ~= "") and url or _G.ADITYA_JOIN_URL
            local ok = false
            pcall(function()
                local KSL = rawget(_G, "UKismetSystemLibrary") or import("KismetSystemLibrary")
                if KSL and KSL.LaunchURL then
                    KSL.LaunchURL(url)
                    ok = true
                end
            end)
            if not ok then
                pcall(function()
                    local KSL = import("KismetSystemLibrary")
                    if KSL and KSL.LaunchURL then
                        KSL:LaunchURL(url)
                        ok = true
                    end
                end)
            end
            if not ok then
                print("[LINK] " .. tostring(url))
            end
            return ok
        end

    local g_adityaorg_EnsureHackMenu
    do
        local VERSION = "LunarSettings.V9.2.MenuFix"
        -- runtime
        local function runtime()
            local state = _G.LunarNativeSettingsRuntime
            if type(state) ~= "table" then
                state = {}
                _G.LunarNativeSettingsRuntime = state
            end
            return state
        end
        -- member
        local function member(object, key)
            if object == nil then
                return nil
            end
            local ok, value = pcall(function()
                return object[key]
            end)
            if ok then
                return value
            end
        end
        -- loadTable
        local function loadTable(name)
            local ok, value = pcall(require, name)
            if not ok then
                if package and package.loaded and type(package.loaded[name]) ~= "table" then
                    package.loaded[name] = nil
                end
                error(name .. ": " .. tostring(value), 0)
            end
            assert(type(value) == "table", name .. ": SETTINGS_MODULE_NOT_READY")
            return value
        end
        -- register
        local function register(catalog, page)
            if type(catalog) ~= "table" or type(page) ~= "table" then
                return false
            end
            local found = false
            for i = #catalog, 1, -1 do
                local entry = catalog[i]
                if type(entry) == "table" and entry.Key == "HackMenu" then
                    if found then
                        table.remove(catalog, i)
                    else
                        catalog[i] = page
                        found = true
                    end
                end
            end
            if not found then
                table.insert(catalog, 1, page)
            end
            return true
        end
        -- looksLikeCatalog
        local function looksLikeCatalog(value, allowEmpty)
            if type(value) ~= "table" then
                return false
            end
            local first = value[1]
            if type(first) == "table" and first.Key ~= nil then
                return true
            end
            return allowEmpty and next(value) == nil
        end
        -- isMainSettings
        local function isMainSettings(config)
            local key
            if type(config) == "string" then
                key = config
            else
                key = member(config, "keyName")
                    or member(config, "KeyName")
                    or member(config, "key")
                    or member(config, "Key")
            end
            if key == nil then
                return false
            end
            local lower = string.lower(tostring(key))
            return lower:find("setting_main", 1, true) ~= nil and lower:find("custom", 1, true) == nil
        end
        -- injectShowCatalog
        local function injectShowCatalog(manager, config, args, count)
            local actual, first = config, 1
            if config == manager then
                actual, first = args[1], 2
            end
            if not isMainSettings(actual) then
                return
            end
            local state = runtime()
            if not state.Page then
                return
            end
            state.LastShowUIInjected = false
            for i = first, count do
                if looksLikeCatalog(args[i], false) then
                    state.LastShowUIInjected = register(args[i], state.Page)
                    state.LastShowUICatalogIndex = i
                    break
                end
            end
            if not state.LastShowUIInjected and looksLikeCatalog(args[first], true) then
                state.LastShowUIInjected = register(args[first], state.Page)
                state.LastShowUICatalogIndex = first
            end
        end
        -- installManagers
        local function installManagers(state)
            local managers = {}
            -- add
            local function add(manager)
                if manager == nil then
                    return
                end
                for _, current in ipairs(managers) do
                    if current == manager then
                        return
                    end
                end
                managers[#managers + 1] = manager
            end
            add(_G.UIManager)
            local ok, loaded = pcall(loadTable, "client.slua_ui_framework.manager")
            if ok then
                add(loaded)
                state.ManagerModuleError = nil
            else
                state.ManagerModuleError = tostring(loaded)
            end
            local count = 0
            for _, manager in ipairs(managers) do
                local show = member(manager, "ShowUI")
                if type(show) == "function" then
                    local record = member(manager, "__LunarSettingsUIHook")
                    if type(record) ~= "table" or record.Version ~= VERSION or record.Wrapper ~= show then
                        record = { Version = VERSION, Original = show }
                        record.Wrapper = function(config, ...)
                            local current = runtime()

                            if not current.Initializing and type(current.Ensure) == "function" then
                                pcall(current.Ensure)
                            end
                            local args, n = { ... }, select("#", ...)
                            injectShowCatalog(manager, config, args, n)
                            return record.Original(config, (table.unpack or unpack)(args, 1, n))
                        end
                        manager.ShowUI = record.Wrapper
                        manager.__LunarSettingsUIHook = record
                    end
                    count = count + 1
                end
            end
            state.Managers = managers
            state.HookCount = count
            state.HookInstalled = count > 0
            return state.HookInstalled
        end
        -- restoreAliases
        local function restoreAliases(state, aliases)
            for _, manager in ipairs(state.Managers or {}) do
                local config = member(manager, "UI_Config")
                if config then
                    for _, key in ipairs({ "Switcher", "Slider" }) do
                        if type(aliases[key]) ~= "table" then
                            local value = member(config, "Setting_Option_" .. key)
                            if type(value) == "table" then
                                aliases[key] = value
                            end
                        end
                    end
                end
            end
        end
        -- syncModeCatalogs
        local function syncModeCatalogs(state)
            local names = {
                "GameLua.Mod.BaseMod.Client.Config.SettingCatalog",
                "GameLua.Mod.D350.Client.Config.SettingCatalog",
                "GameLua.Mod.PlanPH.Client.Config.SettingCatalog",
            }
            for i, name in ipairs(names) do
                local catalog = package and package.loaded and package.loaded[name]
                if type(catalog) ~= "table" and i == 1 then
                    local ok, value = pcall(loadTable, name)
                    if ok then
                        catalog = value
                        state.ModeCatalogError = nil
                    else
                        state.ModeCatalogError = tostring(value)
                    end
                end
                if type(catalog) == "table" then
                    register(catalog, state.Page)
                end
            end
        end
        -- buildPage
        local function buildPage(F, AliasMap, sliderReady)
            -- featureState
            local function featureState()
                return _G.LunarFeatures
            end
            -- value
            local function value(c, v)
                if v == nil then
                    return c
                end
                return v
            end
            -- espAll
            local function espAll(version)
                return {
                    Key = "LunarV" .. version .. "_All",
                    UI = AliasMap.Switcher,
                    Text = "All ESP",
                    LunarBulk = true,
                    SwitcherText = { "All On", "All Off" },
                    EventType = F.ESPSettingsEventType,
                    EventID = F.ESPSettingsEventID,
                    GetFunc = function()
                        return featureState().GetESPAll(version)
                    end,
                    SetFunc = function(c, v)
                        return featureState().SetESPAll(version, value(c, v))
                    end,
                }
            end
            -- espSwitch
            local function espSwitch(version, key, label)
                return {
                    Key = version == 1 and ("LunarV1_" .. key) or ("ADITYAESP_" .. key),
                    UI = AliasMap.Switcher,
                    Text = label,
                    EventType = F.ESPSettingsEventType,
                    EventID = F.ESPSettingsEventID,
                    GetFunc = function()
                        local options = version == 1 and _G.g_Botmater_ESPOptions or _G.g_adityaorg_ESPOptions
                        return options[key] == true
                    end,
                    SetFunc = function(c, v)
                        return featureState().SetESP(version, key, value(c, v))
                    end,
                }
            end

            local V2 = { espAll(2), espSwitch(2, "Box", "ESP BOX"), espSwitch(2, "Line", "ESP SNAPLINE") }
            local Other = {
                {
                    Key = "LunarWall",
                    UI = AliasMap.Switcher,
                    Text = "Wall Hack",
                    ExpandIndex = 0,
                    EventType = F.ESPSettingsEventType,
                    EventID = 3,
                    GetFunc = function()
                        return featureState().Settings.WallEnabled
                    end,
                    SetFunc = function(c, v)
                        featureState().SetWall(value(c, v))
                        return true
                    end,
                },
                {
                    Key = "LunarIpad",
                    UI = AliasMap.Switcher,
                    Text = "iPad View",
                    ExpandIndex = 0,
                    GetFunc = function()
                        return _G.LexusConfig.IpadView
                    end,
                    SetFunc = function(c, v)
                        featureState().SetIpad(value(c, v))
                        return true
                    end,
                },
                {
                    Key = "LunarAim",
                    UI = AliasMap.Switcher,
                    Text = "Aimbot V1",
                    ExpandIndex = 0,
                    EventType = F.AimSettingsEventType,
                    EventID = F.AimSettingsEventID,
                    GetFunc = function()
                        return featureState().Settings.AimEnabled
                    end,
                    SetFunc = function(c, v)
                        featureState().SetAim(value(c, v))
                        return true
                    end,
                },
            }

            -- rangeItem
            local function rangeItem(key, label, lo, hi, parent, get, set)
                return {
                    Key = key,
                    UI = AliasMap.Slider,
                    Text = label,
                    Min = lo,
                    Max = hi,
                    ExpandHandle = parent,
                    GetFunc = function()
                        return get()
                    end,
                    SetFunc = function(c, v)
                        featureState()[set](value(c, v))
                        if set ~= "SetAimCircle" and set ~= "SetAimSpeed" then
                            featureState().Save(true)
                        end
                        return true
                    end,
                }
            end
            if sliderReady then
                table.insert(
                    Other,
                    3,
                    rangeItem("LunarIpadFOV", "iPad FOV", 90, 120, "LunarIpad", function()
                        return featureState().Settings.IpadFOV
                    end, "SetIpadFOV")
                )
            end
            if sliderReady then
                Other[#Other + 1] = rangeItem("LunarAimSpeed", "Aim speed", 120, 150, nil, function()
                    return featureState().Settings.AimSpeed
                end, "SetAimSpeed")
            end
            Other[#Other + 1] = {
                Key = "LunarAimTarget",
                UI = AliasMap.Switcher,
                Text = "Aim target",
                ExpandHandle = "LunarAim",
                SwitcherText = { "Head", "Body", "Leg" },
                SwitcherValue = { 1, 2, 3 },
                GetFunc = function()
                    return featureState().Settings.AimTarget
                end,
                SetFunc = function(c, v)
                    featureState().SetAimTarget(value(c, v))
                    return true
                end,
            }
            if sliderReady then
                Other[#Other + 1] = rangeItem("LunarAimCircle", "Aim circle / distance", 120, 240, nil, function()
                    return featureState().Settings.AimCircle
                end, "SetAimCircle")
            end
            Other[#Other + 1] = {
                Key = "LunarMortarAim",
                UI = AliasMap.Switcher,
                Text = "Mortar aim",
                GetFunc = function()
                    return featureState().Settings.MortarEnabled
                end,
                SetFunc = function(c, v)
                    featureState().SetMortar(value(c, v))
                    return true
                end,
            }
            Other[#Other + 1] = {
                Key = "LunarSmallCrosshair",
                UI = AliasMap.Switcher,
                Text = "Small Crosshair",
                GetFunc = function()
                    return _G.LexusConfig and _G.LexusConfig.SmallCrosshairEnabled == true
                end,
                SetFunc = function(c, v)
                    local on = value(c, v)
                    _G.LexusConfig = _G.LexusConfig or {}
                    _G.LexusConfig.SmallCrosshairEnabled = (on == true)
                    if _G.ApplySmallCrosshair then
                        pcall(_G.ApplySmallCrosshair, true)
                    end
                    return true
                end,
            }
            local names = { "Pink", "White", "Cyan", "Green", "Yellow", "Saffron", "Red" }
            for i, entry in ipairs({ { "WallVisible", "Visible color" }, { "WallOccluded", "Behind-wall color" } }) do
                local key, label = entry[1], entry[2]
                table.insert(Other, 1 + i, {
                    Key = "Lunar" .. key,
                    UI = AliasMap.CompactSwitcher or AliasMap.Switcher,
                    Text = label,
                    EventType = F.ESPSettingsEventType,
                    EventID = 3,
                    ExpandHandle = "LunarWall",
                    SwitcherText = names,
                    SwitcherValue = { 1, 2, 3, 4, 5, 6, 7 },
                    GetFunc = function()
                        return featureState().Settings[key]
                    end,
                    SetFunc = function(c, v)
                        return featureState().SetWallColor(key, value(c, v))
                    end,
                })
            end
            local LagESP = {
                {
                    Key = "LAGESP_All",
                    UI = AliasMap.Switcher,
                    Text = "ESP ALL(On/Off)",
                    LunarBulk = true,
                    SwitcherText = { "All On", "All Off" },
                    GetFunc = function()
                        return _G.LAG_ESP_GetAll and _G.LAG_ESP_GetAll()
                    end,
                    SetFunc = function(c, v)
                        return _G.LAG_ESP_SetAll and _G.LAG_ESP_SetAll(v)
                    end,
                },
                {
                    Key = "LAGESP_HP",
                    UI = AliasMap.Switcher,
                    Text = "ESP HP BAR",
                    GetFunc = function()
                        return _G.LexusConfig and _G.LexusConfig.HealthBarESPEnabled
                    end,
                    SetFunc = function(c, v)
                        return _G.LAG_ESP_Toggle("HealthBarESPEnabled", v)
                    end,
                },
                {
                    Key = "LAGESP_Box",
                    UI = AliasMap.Switcher,
                    Text = "ESP BOX",
                    GetFunc = function()
                        return _G.LexusConfig and _G.LexusConfig.BoxESPEnabled
                    end,
                    SetFunc = function(c, v)
                        return _G.LAG_ESP_Toggle("BoxESPEnabled", v)
                    end,
                },
                {
                    Key = "LAGESP_Map",
                    UI = AliasMap.Switcher,
                    Text = "ESP MINI MAKER",
                    GetFunc = function()
                        return _G.LexusConfig and _G.LexusConfig.MapESPEnabled
                    end,
                    SetFunc = function(c, v)
                        return _G.LAG_ESP_Toggle("MapESPEnabled", v)
                    end,
                },
                {
                    Key = "LAGESP_Counter",
                    UI = AliasMap.Switcher,
                    Text = "ENEMY COUNTER",
                    GetFunc = function()
                        return _G.LexusConfig and _G.LexusConfig.EnemyCounterEnabled
                    end,
                    SetFunc = function(c, v)
                        return _G.LAG_ESP_Toggle("EnemyCounterEnabled", v)
                    end,
                },
                {
                    Key = "LAGESP_Vehicle",
                    UI = AliasMap.Switcher,
                    Text = "ESP VEHICLE",
                    GetFunc = function()
                        return _G.LexusConfig and _G.LexusConfig.VehicleESPEnabled
                    end,
                    SetFunc = function(c, v)
                        return _G.LAG_ESP_Toggle("VehicleESPEnabled", v)
                    end,
                },
                {
                    Key = "LAGESP_Loot",
                    UI = AliasMap.Switcher,
                    Text = "ESP LOOTS",
                    GetFunc = function()
                        return _G.LexusConfig and _G.LexusConfig.LootESPEnabled
                    end,
                    SetFunc = function(c, v)
                        return _G.LAG_ESP_Toggle("LootESPEnabled", v)
                    end,
                },
                {
                    Key = "LAGESP_Snapline",
                    UI = AliasMap.Switcher,
                    Text = "ESP LINE",
                    GetFunc = function()
                        return _G.LexusConfig and _G.LexusConfig.SnaplineESPEnabled
                    end,
                    SetFunc = function(c, v)
                        return _G.LAG_ESP_Toggle("SnaplineESPEnabled", v)
                    end,
                },
            }
            local page = {
                Key = "HackMenu",
                Text = "LUA MENU",
                UIKey = "Setting_Page_Privacy",
                Category = {
                    { Key = "Lunar_LagESP", Text = "ESP MENU", Stack = LagESP },
                    { Key = "Lunar_Other", Text = "COMBAT", Stack = Other },
                },
            }

            return page
        end
        -- initialize
        local function initialize(state)
            local F = _G.LunarFeatures
            assert(type(F) == "table", "FEATURE_RUNTIME_NOT_READY")
            local pages = loadTable("client.logic.NewSetting.SettingPageDefine")
            local catalog = loadTable("client.logic.NewSetting.SettingCatalog")
            local aliases = loadTable("client.slua.umg.NewSetting.Item.AliasMap")
            restoreAliases(state, aliases)
            assert(type(aliases.Switcher) == "table", "AliasMap.Switcher_not_ready")

            local sliderReady = type(aliases.Slider) == "table"
            local compact = aliases.CompactSwitcher or aliases.Switcher
            local rebuild = state.Version ~= VERSION
                or not state.Page
                or state.Features ~= F
                or state.Alias ~= aliases
                or state.Switcher ~= aliases.Switcher
                or state.Slider ~= aliases.Slider
                or state.CompactSwitcher ~= compact
            if rebuild then
                state.Page = buildPage(F, aliases, sliderReady)
                state.PageBuilds = (state.PageBuilds or 0) + 1
            end
            state.Version, state.Features, state.PageDefine, state.Catalog = VERSION, F, pages, catalog
            state.Alias, state.Switcher, state.Slider = aliases, aliases.Switcher, aliases.Slider
            state.CompactSwitcher = compact
            state.SliderReady = sliderReady
            state.DeferredSliderRows = sliderReady and 0 or 3
            pages.HackMenu = state.Page
            state.Registered = register(catalog, state.Page)
            syncModeCatalogs(state)

            local okSlider, sliderClass = pcall(loadTable, "client.slua.umg.NewSetting.Item.Setting_Option_Slider")
            if okSlider and type(F.InstallNativeLiveSlider) == "function" then
                local ok, result = pcall(F.InstallNativeLiveSlider, sliderClass)
                state.LiveRangeReady = ok and result == true
            end

            local okClass, switchClass = pcall(loadTable, "client.slua.umg.NewSetting.Item.Setting_Option_Switcher")
            if okClass and type(F.InstallNativeBulkSwitch) == "function" then
                local okBulk, result = pcall(F.InstallNativeBulkSwitch, switchClass)
                state.BulkSwitchReady = okBulk and result == true
                state.BulkSwitchError = not okBulk and tostring(result) or nil
            else
                state.BulkSwitchReady = false
                state.BulkSwitchError = not okClass and tostring(switchClass) or "BULK_SWITCH_HELPER_UNAVAILABLE"
            end
            state.Ready = state.Registered and state.HookInstalled == true
            if state.Ready then
                state.LastError = nil
                _G.HackMenuInitialized = "ADITYAORG_NATIVE_SETTINGS_V9_2"
            else
                state.LastError = "SETTINGS_UI_MANAGER_NOT_READY"
            end
            return state.Ready
        end
        g_adityaorg_EnsureHackMenu = function()
            local state = runtime()
            state.Ensure = g_adityaorg_EnsureHackMenu
            if state.Initializing then
                return false
            end
            state.Initializing = true
            state.Attempts = (state.Attempts or 0) + 1

            local okHook, hookError = pcall(installManagers, state)
            if not okHook then
                state.HookInstalled = false
                state.HookError = tostring(hookError)
            else
                state.HookError = nil
            end
            local ok, result = pcall(initialize, state)
            state.Initializing = false
            if not ok then
                state.Ready = false
                state.LastError = tostring(result)
            end
            return ok and result == true
        end
        _G.LunarSettingsDiagnostics = function()
            local state = runtime()
            local timer = _G.__MasterShotFastRunner
            return {
                version = state.Version,
                ready = state.Ready == true,
                registered = state.Registered == true,
                attempts = state.Attempts or 0,
                lastError = state.LastError,
                hookInstalled = state.HookInstalled == true,
                hookCount = state.HookCount or 0,
                hookError = state.HookError,
                managerModuleError = state.ManagerModuleError,
                pageBuilt = state.Page ~= nil,
                pageBuilds = state.PageBuilds or 0,
                pageUIKey = state.Page and state.Page.UIKey or nil,
                sliderReady = state.SliderReady == true,
                deferredSliderRows = state.DeferredSliderRows,
                lastShowUIInjected = state.LastShowUIInjected,
                lastShowUICatalogIndex = state.LastShowUICatalogIndex,
                maintenanceProvider = type(timer) == "table" and timer.Provider or nil,
                maintenanceError = type(timer) == "table" and timer.LastError or nil,
            }
        end
    end

    -- ============================================================================
    -- // ESP V2 CONFIGURATION / STATE //
    -- ============================================================================
    _G.g_adityaorg_MasterShotESP = _G.g_adityaorg_MasterShotESP
        or {

            Enabled = false,
            MaxRangeMeters = 450.0,

            ScanInterval = 0.35,
            UpdateInterval = 1.0 / MeowPerformance.ESP2FPS,
            WidgetBuildBudget = 96,
            Profile = false,
            TransformInterval = 0.60,
            MaxRendered = 8,

            TracerThickness = 1.80,
            NameGap = 2.0,
            NameFontSize = 14,
            DistanceFontSize = 20,
            DistanceBelowFeet = 8.0,
        }
    if (tonumber(_G.g_adityaorg_MasterShotESP.MaxRendered) or 0) < 1 then
        _G.g_adityaorg_MasterShotESP.MaxRendered = 8
    end
    if (tonumber(_G.g_adityaorg_MasterShotESP.MaxRangeMeters) or 0) < 400.0 then
        _G.g_adityaorg_MasterShotESP.MaxRangeMeters = 450.0
    end

    if (tonumber(_G.g_adityaorg_MasterShotESP.DistanceFontSize) or 0) < 20 then
        _G.g_adityaorg_MasterShotESP.DistanceFontSize = 20
    end

    if _G.g_adityaorg_MasterShotESP.PerformanceRevision ~= MeowPerformance.Revision then
        _G.g_adityaorg_MasterShotESP.UpdateInterval = 1.0 / MeowPerformance.ESP2FPS
        _G.g_adityaorg_MasterShotESP.PerformanceRevision = MeowPerformance.Revision
    end
    _G.MasterShotESP = _G.g_adityaorg_MasterShotESP

    local g_adityaorg_ShotESP = {
        Canvas = nil,
        RootUI = nil,
        Enemies = {},
        Lines = {},
        BuildStage = {},
        BoneNameCache = {},
        Decorations = {},
        TemplateFont = nil,
        TemplateFontObject = nil,
        TemplateTypeface = nil,
        TemplateColorAndOpacity = nil,
        LastScanClock = -999.0,
        LastTransformClock = -999.0,
        LastWorld = nil,
        TracerOrigin = nil,

        CanvasScaleX = 1.0,
        CanvasScaleY = 1.0,
        CanvasOffsetX = 0.0,
        CanvasOffsetY = 0.0,
        ViewportW = nil,
        ViewportH = nil,
        RawViewportW = nil,
        RawViewportH = nil,
        Active = {},
        Alive = {},
        TimerClock = 0.0,
        Now = 0.0,
        Disabled = false,

        _BotCache = {},
        RealCount = 0,
        BotCount = 0,
    }

    local V2 = _G.FVector2D
    if not V2 then
        pcall(function()
            V2 = import("Vector2D")
        end)
    end
    local V3 = _G.FVector
    if not V3 then
        pcall(function()
            V3 = import("Vector")
        end)
    end
    local LinearColor = _G.FLinearColor
    if not LinearColor then
        pcall(function()
            LinearColor = import("LinearColor")
        end)
    end
    local Anchors = _G.FAnchors
    if not Anchors then
