        SlateBlueprintLibrary = import("SlateBlueprintLibrary")
    end)
    local WidgetLayoutLibrary = nil
    pcall(function()
        WidgetLayoutLibrary = import("WidgetLayoutLibrary")
    end)
    local SlateColor = nil
    pcall(function()
        SlateColor = import("SlateColor") or import("/Script/SlateCore.SlateColor")
    end)
    local KismetTextLibrary = nil
    pcall(function()
        KismetTextLibrary = import("KismetTextLibrary") or import("/Script/Engine.KismetTextLibrary")
    end)
    local GameplayStaticsESP = nil
    pcall(function()
        GameplayStaticsESP = import("GameplayStatics")
    end)
