        ESPGameplayData = require("GameLua.GameCore.Data.GameplayData")
    end)

    -- ============================================================================
    -- // ESP SHARED ACTORS / EVENTS / POOL / PROJECTION //
    -- ============================================================================
    -- g_adityaorg_ESPV2
    local function g_adityaorg_ESPV2(x, y)
        if V2 then
            return V2(x, y)
        end
        return { X = x, Y = y }
    end

    -- g_adityaorg_ESPV3
    local function g_adityaorg_ESPV3(x, y, z)
        if V3 then
            local ok, v = pcall(V3, x, y, z)
            if ok and v then
                return v
            end
        end
        return { X = x, Y = y, Z = z }
    end

    -- g_adityaorg_ESPColor
    local function g_adityaorg_ESPColor(r, g, b, a)
        if LinearColor then
            return LinearColor(r, g, b, a or 1.0)
        end
        return { R = r, G = g, B = b, A = a or 1.0 }
    end

    local ESP_REAL = g_adityaorg_ESPColor(0.90, 0.14, 0.14, 0.98)
    local ESP_BOT = g_adityaorg_ESPColor(0.18, 0.86, 0.36, 0.98)
    local ESP_WHITE = g_adityaorg_ESPColor(1.0, 1.0, 1.0, 1.0)
    local ESP_LINE_VIS = g_adityaorg_ESPColor(0.0, 1.0, 0.0, 1.0)
    local ESP_LINE_HID = g_adityaorg_ESPColor(1.0, 1.0, 0.0, 1.0)

    -- g_adityaorg_ESPScaleColor
    local function g_adityaorg_ESPScaleColor(color, factor, alphaMul)
        if not color then
            return g_adityaorg_ESPColor(1, 1, 1, 1)
        end
        local r = math.max(0.0, math.min(1.0, (tonumber(color.R) or 1.0) * (factor or 1.0)))
        local g = math.max(0.0, math.min(1.0, (tonumber(color.G) or 1.0) * (factor or 1.0)))
        local b = math.max(0.0, math.min(1.0, (tonumber(color.B) or 1.0) * (factor or 1.0)))
        local a = math.max(0.0, math.min(1.0, (tonumber(color.A) or 1.0) * (alphaMul or 1.0)))
        return g_adityaorg_ESPColor(r, g, b, a)
    end

    local ESP_REAL_LIGHT = g_adityaorg_ESPScaleColor(ESP_REAL, 1.12, 0.82)
    local ESP_BOT_LIGHT = g_adityaorg_ESPScaleColor(ESP_BOT, 1.10, 0.82)

    local g_adityaorg_ESPTheme
    do
        local ESP_REAL_THEME = {
            Key = "REAL",
            Main = ESP_REAL,
            Light = ESP_REAL_LIGHT,
            Text = g_adityaorg_ESPColor(1.0, 0.86, 0.84, 1.0),
            Background = g_adityaorg_ESPColor(0.05, 0.005, 0.005, 0.97),
            Empty = g_adityaorg_ESPColor(0.055, 0.008, 0.008, 1.0),
        }
        local ESP_BOT_THEME = {
            Key = "BOT",
            Main = ESP_BOT,
            Light = ESP_BOT_LIGHT,
            Text = g_adityaorg_ESPColor(0.82, 1.0, 0.87, 1.0),
            Background = g_adityaorg_ESPColor(0.005, 0.05, 0.015, 0.97),
            Empty = g_adityaorg_ESPColor(0.008, 0.055, 0.018, 1.0),
        }
        g_adityaorg_ESPTheme = function(isBot)
            return isBot and ESP_BOT_THEME or ESP_REAL_THEME
        end
    end

    -- g_adityaorg_ESPValid
    local function g_adityaorg_ESPValid(obj)
        if not obj then
            return false
        end
        if not slua or not slua.isValid then
            return false
        end
        local ok, valid = pcall(slua.isValid, obj)
        return ok and valid == true
    end

    local ESPShared = {}
    -- Finite
    function ESPShared.Finite(n)
        return type(n) == "number" and n == n and n > -math.huge and n < math.huge
    end
    -- SafeNumber
    function ESPShared.SafeNumber(value, fallback, lo, hi)
        local n = tonumber(value)
        if not ESPShared.Finite(n) then
            n = fallback
        end
        return math.max(lo, math.min(hi, n))
    end
    -- VectorComponents
    function ESPShared.VectorComponents(v)
        return tonumber(v.X), tonumber(v.Y), tonumber(v.Z)
    end
    -- VectorValues
    function ESPShared.VectorValues(v)
        if v == nil then
            return nil
        end
        local ok, x, y, z = pcall(ESPShared.VectorComponents, v)
        if
            ok
            and ESPShared.Finite(x)
            and ESPShared.Finite(y)
            and ESPShared.Finite(z)
            and math.abs(x) < 1e12
            and math.abs(y) < 1e12
            and math.abs(z) < 1e12
        then
            return x, y, z
        end
    end

    -- g_adityaorg_ESPNow
    local function g_adityaorg_ESPNow()
        local t = nil
        pcall(function()
            local w = (slua and slua.getWorld and slua.getWorld()) or nil
            if GameplayStaticsESP and w and GameplayStaticsESP.GetRealTimeSeconds then
                t = GameplayStaticsESP.GetRealTimeSeconds(w)
            end
        end)
        t = tonumber(t)
        if ESPShared.Finite(t) and t >= 0 then
            return t
        end

        return ESPShared.SafeNumber(g_adityaorg_ShotESP.TimerClock, 0.0, 0.0, 1e12)
    end

    -- g_adityaorg_ESPWorld
    local function g_adityaorg_ESPWorld()
        local frame = ESPShared.Frame
        if frame and frame.Active and frame.WorldChecked then
            return frame.World
        end
        local w = nil
        pcall(function()
            if slua and slua.getWorld then
                w = slua.getWorld()
            end
        end)
        if frame and frame.Active then
            frame.World, frame.WorldChecked = w, true
        end
        return w
    end

    -- g_adityaorg_ESPGetController
    local function g_adityaorg_ESPGetController()
        local frame = ESPShared.Frame
        if frame and frame.Active and frame.ControllerChecked then
            return frame.Controller
        end
        local pc = nil
        pcall(function()
            local GDP = ESPGameplayData
            if GDP and GDP.GetPlayerController then
                pc = GDP.GetPlayerController()
            end
        end)
        if not g_adityaorg_ESPValid(pc) then
            pcall(function()
                if slua_GameFrontendHUD then
                    pc = slua_GameFrontendHUD:GetPlayerController()
                end
            end)
        end
        pc = g_adityaorg_ESPValid(pc) and pc or nil
        if frame and frame.Active then
            frame.Controller, frame.ControllerChecked = pc, true
        end
        return pc
    end

    -- g_adityaorg_ESPGetLocalCharacter
    local function g_adityaorg_ESPGetLocalCharacter()
        local frame = ESPShared.Frame
        if frame and frame.Active and frame.LocalPawnChecked then
            return frame.LocalPawn
        end
        local c = nil
        pcall(function()
            local GDP = ESPGameplayData
            if GDP then
                if GDP.GetPlayerCharacter then
                    c = GDP.GetPlayerCharacter()
                end
                if not g_adityaorg_ESPValid(c) and GDP.GetLocalCharacter then
                    c = GDP.GetLocalCharacter()
                end
            end
        end)
        if not g_adityaorg_ESPValid(c) then
            local pc = g_adityaorg_ESPGetController()
            pcall(function()
                if pc and pc.GetPawn then
                    c = pc:GetPawn()
                end
            end)
        end
        c = g_adityaorg_ESPValid(c) and c or nil
        if frame and frame.Active then
            frame.LocalPawn, frame.LocalPawnChecked = c, true
        end
        return c
    end

    -- g_adityaorg_ESPGetPlayerState
    local function g_adityaorg_ESPGetPlayerState(character)
        if not g_adityaorg_ESPValid(character) then
            return nil
        end
        local ps = nil
        pcall(function()
            if character.GetPlayerStateSafety then
                ps = character:GetPlayerStateSafety()
            end
        end)
        if not g_adityaorg_ESPValid(ps) then
            pcall(function()
                if character.GetPlayerState then
                    ps = character:GetPlayerState()
                end
            end)
        end
        if not g_adityaorg_ESPValid(ps) then
            pcall(function()
                ps = character.PlayerState
            end)
        end
        return g_adityaorg_ESPValid(ps) and ps or nil
    end

    -- g_adityaorg_ESPGetPlayerKey
    local function g_adityaorg_ESPGetPlayerKey(character)
        local key = nil
        pcall(function()
            if character.GetPlayerKey then
                key = character:GetPlayerKey()
            end
        end)
        if key == nil then
            pcall(function()
                key = character.PlayerKey
            end)
        end
        if key == nil then
            local ps = g_adityaorg_ESPGetPlayerState(character)
            if ps then
                pcall(function()
                    key = ps.PlayerKey
                end)
            end
        end
        if key == nil or tostring(key) == "" or tostring(key) == "0" or tostring(key) == "-1" then
            return tostring(character)
        end
        return tostring(key) .. "_" .. tostring(character)
    end

    -- g_adityaorg_ESPGetTeamID
    local function g_adityaorg_ESPGetTeamID(character)
        if not g_adityaorg_ESPValid(character) then
            return nil
        end
        local id = nil
        pcall(function()
            if character.GetTeamID then
                id = character:GetTeamID()
            end
        end)
        if id == nil then
            pcall(function()
                id = character.TeamID
            end)
        end
        if id == nil then
            local ps = g_adityaorg_ESPGetPlayerState(character)
            if ps then
                pcall(function()
                    if ps.GetTeamID then
                        id = ps:GetTeamID()
                    end
                end)
                if id == nil then
                    pcall(function()
                        id = ps.TeamID
                    end)
                end
            end
        end
        return id
    end

    local ESPFinishedLastBreath, ESPDeadPawnState
    pcall(function()
        ESPFinishedLastBreath = import("ECharacterHealthStatus").FinishedLastBreath
    end)
    pcall(function()
        ESPDeadPawnState = EPawnState and EPawnState.Dead
    end)
    -- ESPActorField
    local function ESPActorField(actor, key)
        return actor[key]
    end
    -- ESPReadActorField
    local function ESPReadActorField(actor, key)
        local ok, value = pcall(ESPActorField, actor, key)
        if ok then
            return value
        end
    end
    -- ESPReadActorMethod
    local function ESPReadActorMethod(actor, key, ...)
        local method = ESPReadActorField(actor, key)
        if type(method) == "function" then
            local ok, value = pcall(method, actor, ...)
            if ok then
                return value
            end
        end
    end
    -- ESPActorDeadFlag
    local function ESPActorDeadFlag(actor, key)
        local value = ESPReadActorField(actor, key)
        return value == true or value == 1
    end
    -- g_adityaorg_ESPIsAlive
    local function g_adityaorg_ESPIsAlive(character)
        if not g_adityaorg_ESPValid(character) then
            return false, "invalid"
        end
        if
            ESPActorDeadFlag(character, "bDead")
            or ESPActorDeadFlag(character, "bIsDead")
            or ESPActorDeadFlag(character, "bIsDeadFlag")
        then
            return false, "dead"
        end
        if ESPFinishedLastBreath ~= nil and ESPReadActorField(character, "HealthStatus") == ESPFinishedLastBreath then
            return false, "dead"
        end
        if ESPDeadPawnState ~= nil then
            local state = ESPReadActorMethod(character, "HasPawnState", ESPDeadPawnState)
            if state == true or state == 1 then
                return false, "dead"
            end
            state = ESPReadActorMethod(character, "HasState", ESPDeadPawnState)
            if state == true or state == 1 then
                return false, "dead"
            end
        end
        local dead = ESPReadActorMethod(character, "IsDead")
        if dead == true or dead == 1 then
            return false, "dead"
        end

        local alive = ESPReadActorMethod(character, "IsAlive")
        if alive == true or alive == 1 then
            return true, "alive"
        end
        local knocked = ESPReadActorMethod(character, "IsNearDeath")
        if knocked == true or knocked == 1 then
            return true, "knocked"
        end
        if alive == false or alive == 0 then
            return false, "dead"
        end
        local hp = ESPReadActorField(character, "Health")
        if not ESPShared.Finite(hp) then
            hp = ESPReadActorField(character, "HP")
        end
        if not ESPShared.Finite(hp) then
            hp = ESPReadActorMethod(character, "GetHealth")
        end
        if ESPShared.Finite(hp) then
            return hp > 0, hp > 0 and "alive" or "unknown"
        end

        return false, "unknown"
    end

    ESPShared.Events = { Records = setmetatable({}, { __mode = "k" }), Clearers = {} }
    _G.LunarESPEvents = ESPShared.Events
    do
        local E = ESPShared.Events
        -- WorldChanged
        function E.WorldChanged(world)
            if world == nil then
                return
            end
            if E.World ~= nil and E.World ~= world then
                if E.UnbindAll then
                    E.UnbindAll()
                end
                E.Records = setmetatable({}, { __mode = "k" })
            end
            E.World = world
        end

        -- eventActor
        local function eventActor(self)
            if not Client then
                return nil
            end

            E.WorldChanged(g_adityaorg_ESPWorld())
            return self and self.Object
        end

        -- Clear
        function E.Clear(actor)
            for _, clear in ipairs(E.Clearers) do
                pcall(clear, actor)
            end
        end

        -- Spawn
        function E.Spawn(self)
            local actor = eventActor(self)
            if actor ~= nil then
                E.Records[actor] = nil
            end
        end

        -- Death
        function E.Death(self)
            local actor = eventActor(self)
            if actor == nil then
                return
            end
            if E.Records[actor] ~= 2 then
                E.Records[actor] = 2
                E.Clear(actor)
            end
        end

        -- NearDeath
        function E.NearDeath(self, isNearDeath)
            local actor = eventActor(self)
            if actor == nil or E.Records[actor] == 2 then
                return
            end
            local status = ESPReadActorField(actor, "HealthStatus")
            if ESPFinishedLastBreath ~= nil and status == ESPFinishedLastBreath then
                E.Records[actor] = 2
                E.Clear(actor)
            elseif isNearDeath == true or isNearDeath == 1 then
                if E.Records[actor] ~= 1 then
                    E.Records[actor] = 1
                    E.Clear(actor)
                end
            elseif isNearDeath == false or isNearDeath == 0 then
                if E.Records[actor] == 1 then
                    E.Records[actor] = 3
                    E.Clear(actor)
                end
            end
        end

        -- Counted
        function E.Counted(actor)
            return E.Records[actor] ~= 2
        end

        -- Visible
        function E.Visible(actor, snapshot)
            local state = E.Records[actor]
            if state == 2 or state == 1 then
                return false
            end
            if state == 3 then
                if not snapshot or not snapshot.Alive or snapshot.LifeState == "knocked" then
                    return false
                end

                E.Records[actor] = nil
            end
            return snapshot and snapshot.Alive and snapshot.LifeState ~= "knocked"
        end

        -- Project
        function E.Project(pc, actor, state)
            local snapshot = ESPShared.GetFrameRecord(actor)
            if not E.Visible(actor, snapshot) then
                return nil, nil, false, "life"
            end
            local head, feet, onScreen, reason = ESPShared.ProjectActor(pc, actor, state)

            if not E.Visible(actor, snapshot) then
                return nil, nil, false, "life"
            end
            return head, feet, onScreen, reason
        end

        -- ClearIn
        function E.ClearIn(state, prune, actor)
            for _, item in ipairs(state.Enemies) do
                if item.Character == actor then
                    local key = item.Key
                    local keep = setmetatable({ [key] = false }, {
                        __index = function()
                            return true
                        end,
                    })
                    state.Active[key] = nil
                    state.Alive[key] = nil
                    if state.LastProjected then
                        state.LastProjected[key] = nil
                    end
                    prune(keep, keep)
                end
            end
        end

        local oldObserver = _G.__LunarESPEventObserver
        if oldObserver and oldObserver ~= E and type(oldObserver.UnbindAll) == "function" then
            pcall(oldObserver.UnbindAll)
        end
        _G.__LunarESPEventObserver = E
        E.Bindings = {}
        E.BindingCount = 0
        E.BindingLimit = 512
        E.ObserverDiagnostics = { Bound = 0, Unsupported = 0, AddErrors = 0, RemoveErrors = 0 }
        local observerGeneration = 1
        local dispatchDepth = 0
        local pendingAll = false
        local pendingActors = {}

        -- observerMember
        local function observerMember(object, key)
            if object == nil then
                return nil
            end
            local ok, value = pcall(function()
                return object[key]
            end)
            if ok then
                return value
            end
        end
        -- observerValid
        local function observerValid(actor)
            if actor == nil then
                return false
            end
            if not slua or type(slua.isValid) ~= "function" then
                return false
            end
            local ok, yes = pcall(slua.isValid, actor)
            return ok and yes == true
        end
        -- removeBinding
        local function removeBinding(actor, row)
            if E.Bindings[actor] ~= row then
                return
            end
            E.Bindings[actor] = nil
            E.BindingCount = math.max(0, E.BindingCount - 1)
            row.Active = false
            local tracked = _G.g_adityaorg_TrackedCharacters
            local key = tostring(actor)
            if tracked and tracked[key] == actor then
                tracked[key] = nil
            end
            row.Actor[1] = nil
            for _, owned in ipairs(row.Handles) do
                local remove = observerMember(owned.Delegate, "Remove")
                if type(remove) == "function" then
                    local ok = pcall(remove, owned.Delegate, owned.Handle)
                    if not ok then
                        E.ObserverDiagnostics.RemoveErrors = E.ObserverDiagnostics.RemoveErrors + 1
                    end
                end
            end
            row.Handles = {}
        end
        -- flushObserverCleanup
        local function flushObserverCleanup()
            if dispatchDepth ~= 0 then
                return
            end
            if pendingAll then
                pendingAll = false
                for actor, row in pairs(E.Bindings) do
                    removeBinding(actor, row)
                end
                pendingActors = {}
            else
                for actor in pairs(pendingActors) do
                    pendingActors[actor] = nil
                    local row = E.Bindings[actor]
                    if row then
                        removeBinding(actor, row)
                    end
                end
            end
        end
        -- UnbindAll
        function E.UnbindAll()
            observerGeneration = observerGeneration + 1
            pendingAll = true
            for _, row in pairs(E.Bindings) do
                row.Active = false
            end
            flushObserverCleanup()
        end
        -- Unobserve
        function E.Unobserve(actor)
            local row = E.Bindings[actor]
            if not row then
                return
            end
            row.Active = false
            if dispatchDepth ~= 0 then
                pendingActors[actor] = true
            else
                removeBinding(actor, row)
            end
        end
        local eventSpecs = {
            { Name = "IsEnterNearDeathDelegate", Handler = "NearDeath" },
            { Name = "OnDeathDelegate", Handler = "Death" },
            { Name = "OnPawnRespawnDelegate", Handler = "Spawn" },
        }
        -- Observe
        function E.Observe(actor)
            if not Client or actor == nil then
                return false
            end
            if pendingAll or next(pendingActors) ~= nil then
                flushObserverCleanup()
            end
            local row = E.Bindings[actor]
            if row then
                return row.Bound
            end
            if not observerValid(actor) then
                return false
            end

            if E.BindingCount >= E.BindingLimit then
                return false
            end
            row = {
                Active = true,
                Generation = observerGeneration,
                Actor = setmetatable({ actor }, { __mode = "v" }),
                Handles = {},
                Bound = false,
            }
            E.Bindings[actor] = row
            E.BindingCount = E.BindingCount + 1

            _G.g_adityaorg_TrackedCharacters = _G.g_adityaorg_TrackedCharacters or {}
            _G.g_adityaorg_TrackedCharacters[tostring(actor)] = actor
            if g_adityaorg_StartSettingsMaintenance then
                pcall(g_adityaorg_StartSettingsMaintenance, actor)
            end
            for _, spec in ipairs(eventSpecs) do
                local delegate = observerMember(actor, spec.Name)
                local add = observerMember(delegate, "Add")
                local remove = observerMember(delegate, "Remove")
                if type(add) == "function" and type(remove) == "function" then
                    local handler = spec.Handler
                    -- observed
                    local function observed(...)
                        local current = row.Actor[1]
                        if
                            not row.Active
                            or row.Generation ~= observerGeneration
                            or _G.LunarESPEvents ~= E
                            or not observerValid(current)
                        then
                            return
                        end
                        dispatchDepth = dispatchDepth + 1

                        pcall(E[handler], { Object = current }, ...)
                        dispatchDepth = dispatchDepth - 1
                    end
                    local ok, handle = pcall(add, delegate, observed)
                    if ok and type(handle) == "number" and handle > 0 then
                        row.Handles[#row.Handles + 1] = { Delegate = delegate, Handle = handle }
                        row.Bound = true
                        E.ObserverDiagnostics.Bound = E.ObserverDiagnostics.Bound + 1
                    else
                        E.ObserverDiagnostics.AddErrors = E.ObserverDiagnostics.AddErrors + 1
                    end
                else
                    E.ObserverDiagnostics.Unsupported = E.ObserverDiagnostics.Unsupported + 1
                end
            end
            return row.Bound
        end
        -- SyncObservedPawns
        function E.SyncObservedPawns(pawns)
            flushObserverCleanup()
            for actor, row in pairs(E.Bindings) do
                if not observerValid(actor) then
                    E.Unobserve(actor)
                    E.Records[actor] = nil
                end
            end

            if type(pawns) ~= "table" then
                return
            end
            for _, actor in pairs(pawns) do
                if actor ~= nil then
                    E.Observe(actor)
                end
            end
        end
    end

    -- SelectVisible
    function ESPShared.Events.SelectVisible(enemies, limit, reuse)
        local selected = reuse or {}
        local count = 0
        for _, item in ipairs(enemies) do
            if count >= limit then
                break
            end
            if ESPShared.Events.Visible(item.Character, ESPShared.GetFrameRecord(item.Character)) then
                count = count + 1
                selected[count] = item
            end
        end
        for i = #selected, count + 1, -1 do
            selected[i] = nil
        end
        return selected, count
    end
    -- ReleaseSelected
    function ESPShared.Events.ReleaseSelected(selected)
        if selected then
            for i = #selected, 1, -1 do
                selected[i] = nil
            end
        end
    end

    -- g_adityaorg_ESPIsBot
    local function g_adityaorg_ESPIsBot(character, key, providedCache, providedNow)
        if not g_adityaorg_ESPValid(character) then
            return false
        end
        key = key or g_adityaorg_ESPGetPlayerKey(character)
        local cache = providedCache or g_adityaorg_ShotESP._BotCache
        local now = providedNow or g_adityaorg_ShotESP.Now
        local entry = cache[key]
        if entry and now >= entry.Clock and now - entry.Clock < 2.0 then
            return entry.Value
        end
        local result = nil
        -- take
        local function take(v)
            if result == nil and (v == true or v == false or v == 1 or v == 0) then
                result = (v == true or v == 1)
            end
        end
        pcall(function()
            if Game and Game.IsAI then
                take(Game:IsAI(character))
            end
        end)
        if result == nil then
            pcall(function()
                take(character.bIsAI)
            end)
        end
        if result == nil then
            pcall(function()
                if character.IsBot then
                    take(character:IsBot())
                end
            end)
        end
        if result == nil then
            local ps = g_adityaorg_ESPGetPlayerState(character)
            if ps then
                pcall(function()
                    take(ps.bIsABot)
                end)
                pcall(function()
                    take(ps.bIsBot)
                end)
                pcall(function()
                    take(ps.bIsAI)
                end)
                if result == nil then
                    pcall(function()
                        if ps.IsBot then
                            take(ps:IsBot())
                        end
                    end)
                end
            end
        end

        cache[key] = result ~= nil and { Value = result, Clock = now } or nil
        return result == true
    end

    -- g_adityaorg_ESPActorLocation
    local function g_adityaorg_ESPActorLocation(character)
        local loc = nil
        if not g_adityaorg_ESPValid(character) then
            return nil
        end
        pcall(function()
            if character.K2_GetActorLocation then
                loc = character:K2_GetActorLocation()
            elseif Game and Game.GetActorLocation then
                loc = Game:GetActorLocation(character)
            end
        end)
        return loc
    end

    ESPShared.Frame = {
        Active = false,
        Entries = {},
        Pool = {},
        PoolLimit = 256,
        Now = 0,
        ViewAt = -999,
        Controllers = {},
        Transforms = {},
        TransformPool = {},
    }
    -- Finish
    function ESPShared.Frame.Finish()
        local frame = ESPShared.Frame
        for actor, entry in pairs(frame.Entries) do
            frame.Entries[actor] = nil
            entry.Location = nil
            entry.LocationX = nil
            entry.LocationY = nil
            entry.LocationZ = nil
            entry.DistanceOrigin = nil
            entry.DistanceSquared = nil
            entry.DistanceMeters = nil
            entry.Alive = false
            entry.Projected = false
            entry.OnScreen = false
            entry.HasHead = false
            entry.HasFeet = false
            entry.PC = nil
            if #frame.Pool < frame.PoolLimit then
                frame.Pool[#frame.Pool + 1] = entry
            end
        end
        for pc in pairs(frame.Controllers) do
            frame.Controllers[pc] = nil
        end
        for state, value in pairs(frame.Transforms) do
            frame.Transforms[state] = nil
            if #frame.TransformPool < 4 then
                frame.TransformPool[#frame.TransformPool + 1] = value
            end
        end
        frame.DistanceOrigin = nil
        frame.OriginX = nil
        frame.OriginY = nil
        frame.OriginZ = nil
        frame.Pawns = nil
        frame.Active = false
        frame.V1CanvasChecked = false
        frame.World, frame.Controller, frame.LocalPawn = nil, nil, nil
        frame.WorldChecked, frame.ControllerChecked, frame.LocalPawnChecked = false, false, false
    end
    -- Begin
    function ESPShared.Frame.Begin(now)
        ESPShared.Frame.Finish()
        ESPShared.Frame.Now = now
        ESPShared.Frame.Active = true
    end
    -- GetFrameRecord
    function ESPShared.GetFrameRecord(actor)
        local frame = ESPShared.Frame
        local entry = frame.Active and frame.Entries[actor]
        if entry then
            return entry
        end
        if ESPShared.Events.Observe then
            ESPShared.Events.Observe(actor)
        end
        entry = frame.Active and table.remove(frame.Pool) or nil
        if not entry then
            entry = {}
        end
        entry.Alive, entry.LifeState = g_adityaorg_ESPIsAlive(actor)
        entry.Projected = false
        entry.OnScreen = false
        entry.HasHead = false
        entry.HasFeet = false
        entry.Location = entry.Alive and g_adityaorg_ESPActorLocation(actor) or nil
        entry.LocationX, entry.LocationY, entry.LocationZ = ESPShared.VectorValues(entry.Location)
        if not entry.LocationX then
            entry.Location = nil
        end
        if frame.Active and actor ~= nil then
            frame.Entries[actor] = entry
        end
        return entry
    end
    -- GetFramePawns
    local function capturePlayerPawns()
        local pawns
        pcall(function()
            if Game and Game.GetAllPlayerPawns then
                pawns = Game:GetAllPlayerPawns()
            end
        end)
        if not pawns and GameplayData then
            if type(GameplayData.GetAllPlayerCharacters) == "function" then
                pcall(function()
                    pawns = GameplayData.GetAllPlayerCharacters()
                end)
            end
            if not pawns and type(GameplayData.GetAllCharacters) == "function" then
                pcall(function()
                    pawns = GameplayData.GetAllCharacters()
                end)
            end
        end
        return pawns
    end
    function ESPShared.GetFramePawns()
        local frame = ESPShared.Frame
        if frame.Active and frame.Pawns then
            return frame.Pawns
        end
        local now = frame.Active and frame.Now or g_adityaorg_ESPNow()
        local pawns = MeowPerf.Pawns(capturePlayerPawns, now, g_adityaorg_ESPWorld())
        if frame.Active then
            frame.Pawns = pawns
        end
        local events = ESPShared.Events
        if
            events.SyncObservedPawns
            and (not events.SyncDue or now >= events.SyncDue or now < (events.SyncClock or now))
        then
            events.SyncObservedPawns(pawns)
            events.SyncDue, events.SyncClock = now + 1, now
        end
        return pawns
    end
    MeowPerf.PlayerPawns = ESPShared.GetFramePawns
    MeowPerf.Clock = g_adityaorg_ESPNow

    -- DistanceSquaredFrom
    function ESPShared.DistanceSquaredFrom(entry, origin)
        if not entry or not entry.LocationX then
            return math.huge
        end
        local frame = ESPShared.Frame
        if frame.Active and entry.DistanceOrigin == origin and entry.DistanceSquared ~= nil then
            return entry.DistanceSquared
        end
        local x, y, z
        if frame.Active and frame.DistanceOrigin == origin then
            x, y, z = frame.OriginX, frame.OriginY, frame.OriginZ
        else
            x, y, z = ESPShared.VectorValues(origin)
            if frame.Active then
                frame.DistanceOrigin = origin
                frame.OriginX = x
                frame.OriginY = y
                frame.OriginZ = z
            end
        end
        if not x then
            if frame.Active then
                entry.DistanceOrigin = origin
                entry.DistanceSquared = math.huge
                entry.DistanceMeters = nil
            end
            return math.huge
        end
        local dx, dy, dz = x - entry.LocationX, y - entry.LocationY, z - entry.LocationZ
        local squared = dx * dx + dy * dy + dz * dz
        if frame.Active then
            entry.DistanceOrigin = origin
            entry.DistanceSquared = squared
            entry.DistanceMeters = nil
        end
        return squared
    end
    -- DistanceMetersFrom
    function ESPShared.DistanceMetersFrom(entry, origin)
        local squared = ESPShared.DistanceSquaredFrom(entry, origin)
        if ESPShared.Frame.Active and entry.DistanceMeters ~= nil then
            return entry.DistanceMeters
        end
        local distance = math.sqrt(squared) / 100.0
        if ESPShared.Frame.Active then
            entry.DistanceMeters = distance
        end
        return distance
    end
    -- InRange
    function ESPShared.InRange(entry, origin, maxRange)
        if not ESPShared.Finite(maxRange) or maxRange <= 0 then
            return ESPShared.DistanceMetersFrom(entry, origin) <= maxRange
        end
        local squared = ESPShared.DistanceSquaredFrom(entry, origin)
        if squared == math.huge then
            return false
        end
        local limit = maxRange * 100.0
        limit = limit * limit

        if math.abs(squared - limit) <= math.max(1, limit) * 1e-12 then
            return ESPShared.DistanceMetersFrom(entry, origin) <= maxRange
        end
        return squared < limit
    end
    -- ProjectionControllerValid
    function ESPShared.ProjectionControllerValid(pc)
        if pc == nil then
            return false
        end
        local frame = ESPShared.Frame
        if frame.Active then
            local cached = frame.Controllers[pc]
            if cached ~= nil then
                return cached
            end
            local valid = g_adityaorg_ESPValid(pc)
            frame.Controllers[pc] = valid
            return valid
        end
        return g_adityaorg_ESPValid(pc)
    end
    -- CanvasTransform
    function ESPShared.CanvasTransform(state)
        local frame = ESPShared.Frame
        local value = frame.Active and frame.Transforms[state]
        local rx, ry, rox, roy = state.CanvasScaleX, state.CanvasScaleY, state.CanvasOffsetX, state.CanvasOffsetY
        if not value or value.RX ~= rx or value.RY ~= ry or value.ROX ~= rox or value.ROY ~= roy then
            value = value or (frame.Active and table.remove(frame.TransformPool)) or {}
            value.RX = rx
            value.RY = ry
            value.ROX = rox
            value.ROY = roy
            value.SX = ESPShared.SafeNumber(rx, 1, 0.00001, 100)
            value.SY = ESPShared.SafeNumber(ry, 1, 0.00001, 100)
            value.OX = ESPShared.SafeNumber(rox, 0, -1e7, 1e7)
            value.OY = ESPShared.SafeNumber(roy, 0, -1e7, 1e7)
            if frame.Active then
                frame.Transforms[state] = value
            end
        end
        return value.SX, value.SY, value.OX, value.OY
    end
    -- AssignProbeVector
    function ESPShared.AssignProbeVector(vector, x, y, z)
        vector.X = x
        vector.Y = y
        vector.Z = z
    end
    -- UpdateProbeVector
    function ESPShared.UpdateProbeVector(vector, x, y, z)
        if vector and pcall(ESPShared.AssignProbeVector, vector, x, y, z) then
            return vector
        end
        return g_adityaorg_ESPV3(x, y, z)
    end

    -- g_adityaorg_ESPFilterEnemies
    local function g_adityaorg_ESPFilterEnemies(list, myLocation, maxRange, alive)
        for key in pairs(alive) do
            alive[key] = nil
        end
        local count, kept, realCount, botCount = #list, 0, 0, 0
        maxRange = tonumber(maxRange) or 450.0
        if maxRange ~= maxRange or maxRange <= 0 or maxRange == math.huge then
            maxRange = 450.0
        end
        for i = 1, count do
            local item = list[i]
            local character = item and item.Character
            local snapshot = item and item.Key and ESPShared.GetFrameRecord(character)
            if snapshot and snapshot.Alive and ESPShared.Events.Counted(character) then
                local location = snapshot.Location
                local distance = ESPShared.DistanceMetersFrom(snapshot, myLocation)
                if distance <= maxRange then
                    item.Distance = distance
                    kept = kept + 1
                    list[kept] = item
                    alive[item.Key] = true
                    if item.IsBot then
                        botCount = botCount + 1
                    else
                        realCount = realCount + 1
                    end
                end
            end
        end
        for i = kept + 1, count do
            list[i] = nil
        end
        return realCount, botCount
    end

    -- g_adityaorg_ESPGetCharacterVerticalBounds
    local function g_adityaorg_ESPGetCharacterVerticalBounds(character, cachedLocation)
        if not g_adityaorg_ESPValid(character) then
            return nil, nil
        end

        local center, halfHeight = nil, nil
        local capsule = nil

        pcall(function()
            if character.GetCapsuleComponent then
                capsule = character:GetCapsuleComponent()
            elseif character.CapsuleComponent then
                capsule = character.CapsuleComponent
            end
        end)

        if capsule and g_adityaorg_ESPValid(capsule) then
            pcall(function()
                if capsule.K2_GetComponentLocation then
                    center = capsule:K2_GetComponentLocation()
                elseif capsule.GetComponentLocation then
                    center = capsule:GetComponentLocation()
                end

                if capsule.GetScaledCapsuleHalfHeight then
                    halfHeight = capsule:GetScaledCapsuleHalfHeight()
                elseif capsule.GetUnscaledCapsuleHalfHeight then
                    halfHeight = capsule:GetUnscaledCapsuleHalfHeight()
                elseif capsule.CapsuleHalfHeight then
                    halfHeight = capsule.CapsuleHalfHeight
                end
            end)
        end

        local cx, cy, cz = ESPShared.VectorValues(center)
        if center and not cx then
            center = nil
        end
        if not center then
            center = cachedLocation
        end
        if not center then
            pcall(function()
                if character.K2_GetActorLocation then
                    center = character:K2_GetActorLocation()
                end
            end)
        end

        if not center then
            pcall(function()
                if Game and Game.GetActorLocation then
                    center = Game:GetActorLocation(character)
                end
            end)
        end

        if not cx then
            cx, cy, cz = ESPShared.VectorValues(center)
        end
        if not cx then
            return nil, nil
        end

        halfHeight = tonumber(halfHeight)
        if not ESPShared.Finite(halfHeight) or halfHeight < 10 or halfHeight > 200 then
            halfHeight = 85
            pcall(function()
                if character.bIsCrouched then
                    halfHeight = 60
                end
                if character.IsProne and character:IsProne() then
                    halfHeight = 25
                end
            end)
        end

        return center, halfHeight, cx, cy, cz
    end

    local ESPWidgetPool = {}
    do
        local shapes = {
            Line = {
                Fields = { "Widget", "Slot", "PosVec", "SizeVec", "VectorReuseDisabled" },
                Check = { "Widget", "Slot" },
                Limit = 256,
            },
            NameV2 = {
                Fields = { "Widget", "Text", "DistanceText", "TextSlot", "DistanceSlot", "Slot" },
                Check = { "Widget", "Text", "DistanceText", "TextSlot", "DistanceSlot", "Slot" },
                Limit = 16,
            },
            CardV1 = { Fields = { "Widget", "Slot", "Nodes" }, Check = { "Widget", "Slot" }, Limit = 64 },

            Decor = { Fields = { "Widget", "Slot", "Groups" }, Check = { "Widget", "Slot" }, Limit = 8 },
            Header = { Fields = { "Widget", "Slot", "Groups" }, Check = { "Widget", "Slot" }, Limit = 8 },
        }
        -- remove
        local function remove(widget, pool)
            if pool and pool.Remove then
                pool.Remove(widget)
            elseif widget then
                pcall(function()
                    widget:RemoveFromParent()
                end)
            end
        end
        -- weight
        local function weight(data)
            local count = 1
            if data.Nodes then
                for _ in pairs(data.Nodes) do
                    count = count + 1
                end
            elseif data.Groups then
                for _, group in pairs(data.Groups) do
                    count = count + #group
                end
            elseif data.Text then
                count = data.BottomLine and 6 or 3
            end
            return count
        end
        -- resetGroups
        local function resetGroups(groups)
            if not groups then
                return
            end
            for _, group in pairs(groups) do
                for field in pairs(group) do
                    if type(field) ~= "number" then
                        group[field] = nil
                    end
                end
                for _, piece in ipairs(group) do
                    local w, s, pv, sv, disabled =
                        piece.Widget, piece.Slot, piece.PosVec, piece.SizeVec, piece.VectorReuseDisabled
                    for field in pairs(piece) do
                        piece[field] = nil
                    end
                    piece.Widget, piece.Slot, piece.PosVec, piece.SizeVec, piece.VectorReuseDisabled =
                        w, s, pv, sv, disabled
                    piece.Visible = false
                end
            end
        end
        -- New
        function ESPWidgetPool.New(capacity)
            return {
                Bins = {},
                Canvas = nil,
                Enabled = true,
                Weight = 0,
                Capacity = capacity,
                Reused = 0,
                Released = 0,
                Created = 0,
                Discarded = 0,
            }
        end
        ESPWidgetPool.V2 = ESPWidgetPool.New(1024)
        ESPWidgetPool.V1 = ESPWidgetPool.New(1536)
        -- Flush
        function ESPWidgetPool.Flush(pool)
            for kind, bin in pairs(pool.Bins) do
                for i = #bin, 1, -1 do
                    local item = bin[i]
                    bin[i] = nil
                    remove(item.Widget, pool)
                    for key in pairs(item) do
                        item[key] = nil
                    end
                end
                pool.Bins[kind] = nil
            end
            pool.Canvas = nil
            pool.Weight = 0
        end
        -- Tag
        function ESPWidgetPool.Tag(pool, kind, canvas, data)
            if pool.Canvas ~= canvas then
                ESPWidgetPool.Flush(pool)
                pool.Canvas = canvas
            end
            data.PoolOwner = pool
            data.PoolKind = kind
            data.PoolCanvas = canvas
            pool.Created = pool.Created + 1
            return data
        end
        -- Release
        function ESPWidgetPool.Release(data)
            if data.PoolReleased then
                return true
            end
            local pool, kind, canvas = data.PoolOwner, data.PoolKind, data.PoolCanvas
            if
                not pool
                or not pool.Enabled
                or pool.Canvas ~= canvas
                or data.Broken
                or not g_adityaorg_ESPValid(data.Widget)
            then
                return false
            end
            local shape = shapes[kind]
            if not shape then
                return false
            end
            local bin = pool.Bins[kind]
            if not bin then
                bin = {}
                pool.Bins[kind] = bin
            end
            local cost = weight(data)
            if #bin >= shape.Limit or pool.Weight + cost > pool.Capacity then
                return false
            end
            local ok = pcall(function()
                data.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
                if data.Nodes then
                    for _, node in pairs(data.Nodes) do
                        if node.Broken then
                            error("POOL_BROKEN_CARD")
                        end
                        if node.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed) == false then
                            error("POOL_HIDE_FAILED")
                        end
                        if node.Kind == "TextBlock" and node.Widget:SetText("") == false then
                            error("POOL_TEXT_FAILED")
                        end
                    end
                end
                if data.Text then
                    data.Text:SetText("")
                end
                if data.DistanceText then
                    data.DistanceText:SetText("")
                end
                if data.Groups then
                    for _, group in pairs(data.Groups) do
                        for _, piece in ipairs(group) do
                            if piece.Broken then
                                error("POOL_BROKEN_PIECE")
                            end
                            if piece.Visible ~= false then
                                piece.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
                            end
                        end
                    end
                end
            end)
            if not ok then
                return false
            end
            resetGroups(data.Groups)
            if data.Nodes and data.Nodes.FlagImage and data.Nodes.FlagImage.AsyncPath then
                local flag = data.Nodes.FlagImage.Widget
                remove(flag, pool)
                local ok, parent = pcall(function()
                    return flag:GetParent()
                end)
                if not ok or parent ~= nil then
                    return false
                end
                data.Nodes.FlagImage = nil
                cost = weight(data)
            end
            if data.Nodes then
                for _, node in pairs(data.Nodes) do
                    local widget, slot, kind, pv, sv, disabled =
                        node.Widget, node.Slot, node.Kind, node.PosVec, node.SizeVec, node.VectorReuseDisabled
                    for field in pairs(node) do
                        node[field] = nil
                    end
                    node.Widget, node.Slot, node.Kind, node.PosVec, node.SizeVec, node.VectorReuseDisabled =
                        widget, slot, kind, pv, sv, disabled
                    node.Visible = false
                end
            end
            local item = { Weight = cost }
            for _, field in ipairs(shape.Fields) do
                item[field] = data[field]
            end

            for field in pairs(data) do
                data[field] = nil
            end
            data.PoolReleased = true
            bin[#bin + 1] = item
            pool.Weight = pool.Weight + cost
            pool.Released = pool.Released + 1
            return true
        end
        -- Take
        function ESPWidgetPool.Take(pool, kind, canvas)
            if pool.Canvas ~= canvas then
                ESPWidgetPool.Flush(pool)
                pool.Canvas = canvas
            end
            if not pool.Enabled then
                return nil
            end
            local shape, bin = shapes[kind], pool.Bins[kind]
            if not shape or not bin then
                return nil
            end
            while #bin > 0 do
                local item = bin[#bin]
                bin[#bin] = nil
                pool.Weight = pool.Weight - item.Weight
                local valid = true
                for _, field in ipairs(shape.Check) do
                    if not g_adityaorg_ESPValid(item[field]) then
                        valid = false
                        break
                    end
                end
                if valid and item.Nodes then
                    for _, node in pairs(item.Nodes) do
                        if not g_adityaorg_ESPValid(node.Widget) or not g_adityaorg_ESPValid(node.Slot) then
                            valid = false
                            break
                        end
                    end
                end
                if valid and item.Groups then
                    for _, group in pairs(item.Groups) do
                        for _, piece in ipairs(group) do
                            if not g_adityaorg_ESPValid(piece.Widget) or not g_adityaorg_ESPValid(piece.Slot) then
                                valid = false
                                break
                            end
                        end
                        if not valid then
                            break
                        end
                    end
                end

                if valid then
                    local ok, parent = pcall(function()
                        return item.Widget:GetParent()
                    end)
                    valid = ok and parent == canvas
                end
                if valid then
                    local data = { PoolOwner = pool, PoolKind = kind, PoolCanvas = canvas }
                    for _, field in ipairs(shape.Fields) do
                        data[field] = item[field]
                    end
                    resetGroups(data.Groups)
                    pool.Reused = pool.Reused + 1
                    return data
                end
                remove(item.Widget, pool)
                pool.Discarded = pool.Discarded + 1
                for key in pairs(item) do
                    item[key] = nil
                end
            end
            return nil
        end
    end

    -- g_adityaorg_ESPDestroyWidgetData
    local function g_adityaorg_ESPDestroyWidgetData(data)
        if not data then
            return
        end
        if ESPWidgetPool.Release(data) then
            return
        end
        if data.Dot then
            pcall(function()
                if data.Dot.Widget and g_adityaorg_ESPValid(data.Dot.Widget) then
                    data.Dot.Widget:RemoveFromParent()
                end
            end)
            data.Dot = nil
        end
        for _, field in ipairs({ "Widget", "Container", "Text", "DistanceText", "Dot" }) do
            local widget = data[field]
            if g_adityaorg_ESPValid(widget) then
                pcall(function()
                    widget:RemoveFromParent()
                end)
            end
        end
    end

    -- g_adityaorg_ESPResetWidgets
    local function g_adityaorg_ESPResetWidgets()
        ESPWidgetPool.V2.Enabled = false
        for _, data in pairs(g_adityaorg_ShotESP.Lines) do
            g_adityaorg_ESPDestroyWidgetData(data)
        end
        g_adityaorg_ShotESP.Lines = {}
        g_adityaorg_ShotESP.BuildStage = {}
        g_adityaorg_ShotESP.BoneNameCache = {}
        for _, data in pairs(g_adityaorg_ShotESP.Decorations) do
            g_adityaorg_ESPDestroyWidgetData(data)
        end
        g_adityaorg_ShotESP.Decorations = {}
        g_adityaorg_ShotESP.Canvas = nil
        g_adityaorg_ShotESP.RootUI = nil
        g_adityaorg_ShotESP.Enemies = {}
        g_adityaorg_ShotESP.Active = {}
        g_adityaorg_ShotESP.Alive = {}
        g_adityaorg_ShotESP.TemplateFont = nil
        g_adityaorg_ShotESP.TemplateFontObject = nil
        g_adityaorg_ShotESP.TemplateTypeface = nil
        g_adityaorg_ShotESP.TemplateColorAndOpacity = nil
        g_adityaorg_ShotESP.ViewportW, g_adityaorg_ShotESP.ViewportH = nil, nil
        g_adityaorg_ShotESP.RawViewportW, g_adityaorg_ShotESP.RawViewportH = nil, nil
        g_adityaorg_ShotESP.TracerOrigin = nil
        g_adityaorg_ShotESP.LastScanClock = -999.0
        g_adityaorg_ShotESP.LastTransformClock = -999.0
        g_adityaorg_ShotESP.LastController = nil
        g_adityaorg_ShotESP.LastPawn = nil
        g_adityaorg_ShotESP._BotCache = {}
        g_adityaorg_ShotESP.RealCount = 0
        g_adityaorg_ShotESP.BotCount = 0
        ESPWidgetPool.Flush(ESPWidgetPool.V2)
        ESPWidgetPool.V2.Enabled = true
    end

    -- g_adityaorg_ESPGetCanvas
    local function g_adityaorg_ESPGetCanvas()
        if g_adityaorg_ESPValid(g_adityaorg_ShotESP.Canvas) then
            return g_adityaorg_ShotESP.Canvas
        end
        local root = nil
        pcall(function()
            local InGameUITools = require("GameLua.Mod.BaseMod.Common.UI.InGameUITools")
            if InGameUITools and InGameUITools.GetMainControlBaseUI then
                root = InGameUITools.GetMainControlBaseUI()
            end
        end)
        if not g_adityaorg_ESPValid(root) then
            return nil
        end
        g_adityaorg_ShotESP.RootUI = root
        local canvas = nil
        pcall(function()
            if g_adityaorg_ESPValid(root.CanvasPanel_0) then
                canvas = root.CanvasPanel_0
            elseif g_adityaorg_ESPValid(root.CanvasPanel_42) then
                canvas = root.CanvasPanel_42
            end
        end)
        if g_adityaorg_ESPValid(canvas) then
            g_adityaorg_ShotESP.Canvas = canvas
            return canvas
        end
        return nil
    end

    -- g_adityaorg_ESPViewport
    local function g_adityaorg_ESPViewport(pc)
        local w, h
        -- take
        local function take(x, y)
            x, y = tonumber(x), tonumber(y)
            if ESPShared.Finite(x) and ESPShared.Finite(y) and x > 200 and y > 200 and x < 1e6 and y < 1e6 then
                w, h = x, y
                return true
            end
        end
        pcall(function()
            if WidgetLayoutLibrary and WidgetLayoutLibrary.GetViewportSize then
                local v = WidgetLayoutLibrary.GetViewportSize(pc)
                if v then
                    take(v.X, v.Y)
                end
            end
        end)
        if not w then
            pcall(function()
                local x, y = pc:GetViewportSize()
                take(x, y)
            end)
        end
        if not w then
            pcall(function()
                local v = g_adityaorg_ESPV2(0, 0)
                pc:GetViewportSize(v)
                take(v.X, v.Y)
            end)
        end
        if not w then
            pcall(function()
                local x, y = pc:GetViewportSize(0, 0)
                take(x, y)
            end)
        end
        return w or 2400.0, h or 1080.0
    end

    -- g_adityaorg_ESPGetCanvasLocalSize
    local function g_adityaorg_ESPGetCanvasLocalSize()
        local canvas = g_adityaorg_ESPGetCanvas()
        if not g_adityaorg_ESPValid(canvas) then
            return nil, nil
        end

        local cw, ch = nil, nil
        pcall(function()
            local geo = canvas:GetCachedGeometry()
            if not geo then
                return
            end

            local size = nil
            if geo.GetLocalSize then
                size = geo:GetLocalSize()
            elseif SlateBlueprintLibrary and SlateBlueprintLibrary.GetLocalSize then
                size = SlateBlueprintLibrary.GetLocalSize(geo)
            end

            if size and ESPShared.Finite(size.X) and ESPShared.Finite(size.Y) and size.X > 100 and size.Y > 100 then
                cw, ch = tonumber(size.X), tonumber(size.Y)
            end
        end)

        return cw, ch
    end

    -- g_adityaorg_ESPUpdateCanvasTransform
    local function g_adityaorg_ESPUpdateCanvasTransform(pc)
        local canvas = g_adityaorg_ESPGetCanvas()
        if not g_adityaorg_ESPValid(canvas) then
            return false
        end

        local calibrated = false

        pcall(function()
            if SlateBlueprintLibrary and SlateBlueprintLibrary.AbsoluteToLocal then
                local geo = canvas:GetCachedGeometry()
                if geo then
                    local p0 = SlateBlueprintLibrary.AbsoluteToLocal(geo, g_adityaorg_ESPV2(0, 0))
                    local p1 = SlateBlueprintLibrary.AbsoluteToLocal(geo, g_adityaorg_ESPV2(100, 100))

                    if
                        p0
                        and p1
                        and ESPShared.Finite(p0.X)
                        and ESPShared.Finite(p0.Y)
                        and ESPShared.Finite(p1.X)
                        and ESPShared.Finite(p1.Y)
                        and math.abs(p0.X) < 1e7
                        and math.abs(p0.Y) < 1e7
                        and p1.X > p0.X
                        and p1.Y > p0.Y
                        and p1.X - p0.X < 10000
                        and p1.Y - p0.Y < 10000
                    then
                        g_adityaorg_ShotESP.CanvasScaleX = (p1.X - p0.X) / 100.0
                        g_adityaorg_ShotESP.CanvasScaleY = (p1.Y - p0.Y) / 100.0
                        g_adityaorg_ShotESP.CanvasOffsetX = p0.X
                        g_adityaorg_ShotESP.CanvasOffsetY = p0.Y
                        calibrated = true
                    end
                end
            end
        end)

        if not calibrated then
            local scale = 1.0
            pcall(function()
                if WidgetLayoutLibrary and WidgetLayoutLibrary.GetViewportScale then
                    local s = WidgetLayoutLibrary.GetViewportScale(pc)
                    if ESPShared.Finite(s) and s >= 0.01 and s <= 100 then
                        scale = s
                    end
                end
            end)

            g_adityaorg_ShotESP.CanvasScaleX = 1.0 / scale
            g_adityaorg_ShotESP.CanvasScaleY = 1.0 / scale
            g_adityaorg_ShotESP.CanvasOffsetX = 0.0
            g_adityaorg_ShotESP.CanvasOffsetY = 0.0
        end

        return true
    end

    -- g_adityaorg_ESPActorOnScreen
    local function g_adityaorg_ESPActorOnScreen(head, feet, minX, minY, maxX, maxY)
        -- usable
        local function usable(p)
            return p and ESPShared.Finite(p.X) and ESPShared.Finite(p.Y)
        end
        head = usable(head) and head or nil
        feet = usable(feet) and feet or nil
        if not head and not feet then
            return false
        end
        head = head or feet
        feet = feet or head
        return math.max(head.X, feet.X) >= minX
            and math.min(head.X, feet.X) <= maxX
            and math.max(head.Y, feet.Y) >= minY
            and math.min(head.Y, feet.Y) <= maxY
    end

    -- ViewSize
    function ESPShared.ViewSize(pc)
        local now = ESPShared.Frame.Active and ESPShared.Frame.Now or g_adityaorg_ESPNow()
        if
            not ESPShared.Frame.Active
            or ESPShared.Frame.ViewPC ~= pc
            or now < ESPShared.Frame.ViewAt
            or now - ESPShared.Frame.ViewAt >= 0.25
        then
            ESPShared.Frame.ViewW, ESPShared.Frame.ViewH = g_adityaorg_ESPViewport(pc)
            ESPShared.Frame.ViewPC = pc
            ESPShared.Frame.ViewAt = now
        end
        return ESPShared.Frame.ViewW, ESPShared.Frame.ViewH
    end
    -- NativeProject
    function ESPShared.NativeProject(pc, location, pix)
        return pc:ProjectWorldLocationToScreen(location, pix, true)
    end
    -- ActorProbeLocations
    function ESPShared.ActorProbeLocations(actor, entry)
        local center, height, x, y, z = g_adityaorg_ESPGetCharacterVerticalBounds(actor, entry.Location)
        if not x or not height then
            return nil, nil
        end
        entry.WorldHead = ESPShared.UpdateProbeVector(entry.WorldHead, x, y, z + height)
        entry.WorldFeet = ESPShared.UpdateProbeVector(entry.WorldFeet, x, y, z - height)
        return entry.WorldHead, entry.WorldFeet
    end
    -- ProjectRaw
    function ESPShared.ProjectRaw(pc, location, pix)
        if not ESPShared.VectorValues(location) or not ESPShared.ProjectionControllerValid(pc) then
            return nil
        end
        pix = pix or g_adityaorg_ESPV2(0, 0)
        pix.X = 0
        pix.Y = 0
        local ok, result, out = pcall(ESPShared.NativeProject, pc, location, pix)
        if out then
            pix = out
        end
        local good, x, y = pcall(function()
            return tonumber(pix.X), tonumber(pix.Y)
        end)
        if
            not ok
            or not good
            or not ESPShared.Finite(x)
            or not ESPShared.Finite(y)
            or math.abs(x) >= 1e7
            or math.abs(y) >= 1e7
        then
            return nil, "unavailable"
        end
        if result == false or result == 0 then
            return nil, "offscreen"
        end
        if result ~= true and result ~= 1 and not (result == nil and (x ~= 0 or y ~= 0)) then
            return nil, "unavailable"
        end
        return pix, "visible"
    end
    -- ProbeActor
    function ESPShared.ProbeActor(pc, actor)
        local entry = ESPShared.GetFrameRecord(actor)
        if entry.Projected and entry.PC == pc then
            return entry
        end
        entry.Projected = true
        entry.PC = pc
        entry.OnScreen = false
        entry.ProjectionReason = "unavailable"
        if not entry.Alive or not entry.Location then
            return entry
        end
        local ok, head, feet = pcall(ESPShared.ActorProbeLocations, actor, entry)
        if not ok then
            return entry
        end
        entry.RawHead = entry.RawHead or g_adityaorg_ESPV2(0, 0)
        entry.RawFeet = entry.RawFeet or g_adityaorg_ESPV2(0, 0)
        local hp, hr = ESPShared.ProjectRaw(pc, head, entry.RawHead)
        local fp, fr = ESPShared.ProjectRaw(pc, feet, entry.RawFeet)
        if hp then
            entry.RawHead = hp
        end
        if fp then
            entry.RawFeet = fp
        end
        entry.HasHead = hp ~= nil
        entry.HasFeet = fp ~= nil
        local width, height = ESPShared.ViewSize(pc)
        entry.OnScreen = g_adityaorg_ESPActorOnScreen(hp, fp, 0, 0, width, height)
        if entry.OnScreen then
            entry.ProjectionReason = "visible"
        elseif hp or fp or hr == "offscreen" or fr == "offscreen" then
            entry.ProjectionReason = "offscreen"
        end
        return entry
    end
    -- CanvasBounds
    function ESPShared.CanvasBounds(pc, state)
        local width, height = ESPShared.ViewSize(pc)
        local sx, sy, ox, oy = ESPShared.CanvasTransform(state)
        local maxX, maxY = ox + width * sx, oy + height * sy
        if ESPShared.Finite(state.ViewportW) and state.ViewportW > 1 then
            maxX = math.min(maxX, ox + state.ViewportW)
        end
        if ESPShared.Finite(state.ViewportH) and state.ViewportH > 1 then
            maxY = math.min(maxY, oy + state.ViewportH)
        end
        return ox, oy, maxX, maxY
    end
    -- ProjectActor
    function ESPShared.ProjectActor(pc, actor, state)
        local entry = ESPShared.ProbeActor(pc, actor)
        if not entry.OnScreen then
            return nil, nil, false, entry.ProjectionReason
        end
        local sx, sy, ox, oy = ESPShared.CanvasTransform(state)
        local prefix = state == g_adityaorg_ShotESP and "V2" or "V1"
        -- convert
        local function convert(raw, field)
            local p = entry[field] or g_adityaorg_ESPV2(0, 0)
            entry[field] = p
            p.X = raw.X * sx + ox
            p.Y = raw.Y * sy + oy
            return p
        end
        local head = entry.HasHead and convert(entry.RawHead, prefix .. "Head") or nil
        local feet = entry.HasFeet and convert(entry.RawFeet, prefix .. "Feet") or nil
        local minX, minY, maxX, maxY = ESPShared.CanvasBounds(pc, state)
        local visible = g_adityaorg_ESPActorOnScreen(head, feet, minX, minY, maxX, maxY)
        return head, feet, visible, visible and "visible" or "offscreen"
    end

    -- ============================================================================
    -- // ESP V2 LINES / BOXES / RENDER SCHEDULER //
    -- ============================================================================
    -- g_adityaorg_ESPCreateLine
    local function g_adityaorg_ESPCreateLine(color, parent)
        local canvas = parent or g_adityaorg_ESPGetCanvas()
        if not g_adityaorg_ESPValid(canvas) then
            return nil
        end
        local budget = g_adityaorg_ShotESP.BuildRemaining
        if budget ~= nil then
            if budget <= 0 then
                return nil
            end
            g_adityaorg_ShotESP.BuildRemaining = budget - 1
        end
        local pooled = canvas == g_adityaorg_ShotESP.Canvas and ESPWidgetPool.Take(ESPWidgetPool.V2, "Line", canvas)
        if pooled then
            local ok = pcall(function()
                pooled.Widget:SetBrushColor(color)
            end)
            if ok then
                pooled.Visible = false
                return pooled
            end
            pcall(function()
                pooled.Widget:RemoveFromParent()
            end)
        end
        local border = nil
        pcall(function()
            border = CGame:NewObjectFromPath("/Script/UMG.Border", canvas)
        end)
        if not g_adityaorg_ESPValid(border) then
            return nil
        end
        pcall(function()
            border:SetBrushColor(color)
            border:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
            border:SetRenderTransformPivot(g_adityaorg_ESPV2(0.0, 0.5))
        end)
        local slot = nil
        pcall(function()
            slot = canvas:AddChildToCanvas(border)
        end)
        if not slot then
            g_adityaorg_ESPDestroyWidgetData({ Widget = border })
            return nil
        end
        pcall(function()
            slot:SetAutoSize(false)
            slot:SetZOrder(30)
        end)
        local data = { Widget = border, Slot = slot }
        if canvas == g_adityaorg_ShotESP.Canvas then
            ESPWidgetPool.Tag(ESPWidgetPool.V2, "Line", canvas, data)
        end
        return data
    end

    -- g_adityaorg_ESPDrawLine
    local function g_adityaorg_ESPDrawLine(data, x1, y1, x2, y2, thickness)
        if not data or not data.Widget or not data.Slot then
            return false
        end
        local dx, dy = x2 - x1, y2 - y1
        local len = math.sqrt(dx * dx + dy * dy)
        if len < 1 then
            if data.Visible ~= false then
                pcall(function()
                    data.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
                end)
                data.Visible = false
            end
            return false
        end
        local angle = ((math.atan2 and math.atan2(dy, dx)) or math.atan(dy, dx)) * 180.0 / math.pi
        local unchanged = data.Visible == true
            and data.X1
            and math.abs(data.X1 - x1) < 0.25
            and math.abs(data.Y1 - y1) < 0.25
            and math.abs(data.X2 - x2) < 0.25
            and math.abs(data.Y2 - y2) < 0.25
            and math.abs((data.Thickness or 0) - thickness) < 0.05
        if unchanged then
            return true
        end

        local setterOK = pcall(function()
            if data.VectorReuseDisabled then
                data.Slot:SetPosition(g_adityaorg_ESPV2(x1, y1 - thickness * 0.5))
                data.Slot:SetSize(g_adityaorg_ESPV2(len, thickness))
            else
                data.PosVec = data.PosVec or g_adityaorg_ESPV2(x1, y1 - thickness * 0.5)
                data.SizeVec = data.SizeVec or g_adityaorg_ESPV2(len, thickness)
                data.PosVec.X = x1
                data.PosVec.Y = y1 - thickness * 0.5
                data.SizeVec.X = len
                data.SizeVec.Y = thickness
                data.Slot:SetPosition(data.PosVec)
                data.Slot:SetSize(data.SizeVec)
            end
            data.Widget:SetRenderAngle(angle)
            if not data.Visible then
                data.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
            end
        end)
        if not setterOK and not data.VectorReuseDisabled then
            data.VectorReuseDisabled = true
            data.PosVec = nil
            data.SizeVec = nil
            setterOK = pcall(function()
                data.Slot:SetPosition(g_adityaorg_ESPV2(x1, y1 - thickness * 0.5))
                data.Slot:SetSize(g_adityaorg_ESPV2(len, thickness))
                data.Widget:SetRenderAngle(angle)
                if not data.Visible then
                    data.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
                end
            end)
        end
        if not setterOK then
            data.Broken = true
            return false
        end
        data.Broken = false
        data.X1, data.Y1, data.X2, data.Y2, data.Thickness = x1, y1, x2, y2, thickness
        data.Visible = true
        return true
    end

    -- g_adityaorg_ESPHide
    local function g_adityaorg_ESPHide(data)
        if data and data.Visible ~= false and data.Widget then
            local ok = pcall(function()
                data.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
            end)
            if not ok then
                data.Broken = true
            end
            data.Visible = false
        end
    end

    -- g_adityaorg_ESPDestroyGroup
    local function g_adityaorg_ESPDestroyGroup(group)
        if not group then
            return
        end
        for _, data in ipairs(group) do
            g_adityaorg_ESPDestroyWidgetData(data)
        end
    end

    -- g_adityaorg_ESPGroupHealthy
    local function g_adityaorg_ESPGroupHealthy(group)
        if not group then
            return false
        end
        local now = g_adityaorg_ShotESP.Now
        local validate = not group.ValidatedAt or now < group.ValidatedAt or now - group.ValidatedAt >= 0.35
        for _, data in ipairs(group) do
            if data.Broken or (validate and not g_adityaorg_ESPValid(data.Widget)) then
                return false
            end
        end
        if validate then
            group.ValidatedAt = now
        end
        return true
    end

    -- g_adityaorg_ESPLineGroup
    local function g_adityaorg_ESPLineGroup(registry, key, count, color, parent)
        local group = registry[key]
        if group and not g_adityaorg_ESPGroupHealthy(group) then
            g_adityaorg_ESPDestroyGroup(group)
            group = nil
        end
        if not group or #group > count then
            g_adityaorg_ESPDestroyGroup(group)
            group = {}
            registry[key] = group
        end
        while #group < count do
            local data = g_adityaorg_ESPCreateLine(color, parent)
            if not data then
                return nil
            end
            group[#group + 1] = data
            g_adityaorg_ESPHide(data)
        end
        return group
    end

    -- g_adityaorg_ESPApplyGroupTheme
    local function g_adityaorg_ESPApplyGroupTheme(group, theme, kind)
        if not group or group.ThemeKey == theme.Key then
            return
        end
        local ok = pcall(function()
            for i, piece in ipairs(group) do
                local color = theme.Main
                if kind == "Header" then
                    if i >= 23 then
                        color = theme.Background
                    elseif i >= 9 and i <= 12 then
                        color = theme.Light
                    end
                elseif kind == "Arcs" then
                    if i >= 11 and i <= 20 then
                        color = theme.Light
                    end
                elseif kind == "Footer" then
                    if i <= 4 then
                        color = theme.Light
                    end
                elseif kind == "Health" then
                    if i == 1 then
                        color = theme.Background
                    elseif i >= 10 then
                        color = theme.Light
                    else
                        color = theme.Empty
                    end
                end
                piece.Widget:SetBrushColor(color)
            end
        end)
        if ok then
            group.ThemeKey = theme.Key
        end
    end

    local g_adityaorg_ESPHealthRatio

    -- g_adityaorg_ESPSetGroupVisible
    local function g_adityaorg_ESPSetGroupVisible(group, visible)
        if not group or group.GroupVisible == visible then
            return
        end
        for _, data in ipairs(group) do
            if visible then
                pcall(function()
                    data.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
                end)
                data.Visible = true
            else
                g_adityaorg_ESPHide(data)
            end
        end
        group.GroupVisible = visible
    end

    -- g_adityaorg_ESPCreateDecorationRoot
    local function g_adityaorg_ESPCreateDecorationRoot(poolKind)
        local canvas = g_adityaorg_ESPGetCanvas()
        if not g_adityaorg_ESPValid(canvas) then
            return nil
        end
        poolKind = poolKind or "Decor"
        local pooled = ESPWidgetPool.Take(ESPWidgetPool.V2, poolKind, canvas)
        if pooled then
            local ok = pcall(function()
                pooled.Slot:SetZOrder(poolKind == "Header" and 30 or 29)
                pooled.Widget:SetRenderScale(g_adityaorg_ESPV2(1.0, 1.0))
                pooled.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
            end)
            if ok then
                pooled.Visible = true
                return pooled
            end
            pcall(function()
                pooled.Widget:RemoveFromParent()
            end)
        end
        local root = nil
        pcall(function()
            root = CGame:NewObjectFromPath("/Script/UMG.CanvasPanel", canvas)
        end)
        if not g_adityaorg_ESPValid(root) then
            return nil
        end
        local slot = nil
        pcall(function()
            slot = canvas:AddChildToCanvas(root)
        end)
        if not slot then
            g_adityaorg_ESPDestroyWidgetData({ Widget = root })
            return nil
        end
        pcall(function()
            slot:SetAutoSize(false)
            slot:SetSize(g_adityaorg_ESPV2(1000.0, 1400.0))
            slot:SetZOrder(29)
            root:SetRenderTransformPivot(g_adityaorg_ESPV2(0.0, 0.0))
            root:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
        end)
        return ESPWidgetPool.Tag(
            ESPWidgetPool.V2,
            poolKind,
            canvas,
            { Widget = root, Slot = slot, Groups = {}, Visible = true }
        )
    end

    -- g_adityaorg_ESPDecorGroup
    local function g_adityaorg_ESPDecorGroup(data, name, count, color)
        return g_adityaorg_ESPLineGroup(data.Groups, name, count, color, data.Widget)
    end

    -- g_adityaorg_ESPBuildArcs
    local function g_adityaorg_ESPBuildArcs(data)
        local group = g_adityaorg_ESPDecorGroup(data, "Arcs", 26, ESP_REAL)
        if not group then
            return nil
        end
        if group.Built then
            return group
        end
        local cx, cy, half, ry = 500.0, 385.0, 268.0, 180.0

        local redThickness = { 6.0, 10.5, 15.0, 10.5, 6.0 }
        local whiteThickness = { 3.0, 5.25, 7.5, 5.25, 3.0 }
        local index = 1
        for _, side in ipairs({ -1, 1 }) do
            local previous = nil
            for step = 0, 5 do
                local angle = (-70 + step * 28) * math.pi / 180
                local p = { X = cx + side * half * math.cos(angle), Y = cy + ry * math.sin(angle) }
                if previous then
                    g_adityaorg_ESPDrawLine(group[index], previous.X, previous.Y, p.X, p.Y, redThickness[step])
                    index = index + 1
                end
                previous = p
            end
        end
        local tickIndex = 21
        for _, side in ipairs({ -1, 1 }) do
            local x = cx + side * half * 1.02
            for _, oy in ipairs({ -24.0, 0.0, 24.0 }) do
                g_adityaorg_ESPDrawLine(group[tickIndex], x - side * 5.0, cy + oy, x + side * 2.0, cy + oy, 2.2)
                tickIndex = tickIndex + 1
            end
        end
        local ih, ir = half * 0.82, ry * 0.76
        for _, side in ipairs({ -1, 1 }) do
            local previous = nil
            for step = 0, 5 do
                local angle = (-54 + step * (108 / 5)) * math.pi / 180
                local p = { X = cx + side * ih * math.cos(angle), Y = cy + ir * math.sin(angle) }
                if previous then
                    pcall(function()
                        group[index].Widget:SetBrushColor(ESP_WHITE)
                    end)
                    g_adityaorg_ESPDrawLine(group[index], previous.X, previous.Y, p.X, p.Y, whiteThickness[step])
                    index = index + 1
                end
                previous = p
            end
        end
        group.Built = true
        group.GroupVisible = true
        return group
    end

    -- g_adityaorg_ESPUpdateDecoration
    local function g_adityaorg_ESPUpdateDecoration(key, character, head, feet, opt, stage, isBot)
        local enabled = opt.Box
        local data = g_adityaorg_ShotESP.Decorations[key]
        if not enabled or not head or not feet then
            if data and data.Visible ~= false then
                pcall(function()
                    data.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
                end)
                data.Visible = false
            end
            return
        end
        if not data or not g_adityaorg_ESPValid(data.Widget) then
            g_adityaorg_ESPDestroyWidgetData(data)
            data = g_adityaorg_ESPCreateDecorationRoot()
            g_adityaorg_ShotESP.Decorations[key] = data
        end
        if not data then
            return
        end
        local h = math.abs(feet.Y - head.Y)
        if h < 8 then
            return
        end
        local scale = h / 1000.0
        local x, y = head.X - 500.0 * scale, head.Y - 200.0 * scale
        local moved = not data.X or math.abs(data.X - x) >= 0.25 or math.abs(data.Y - y) >= 0.25
        local scaled = not data.Scale or math.abs(data.Scale - scale) >= 0.001
        if moved then
            local ok = pcall(function()
                data.Slot:SetPosition(g_adityaorg_ESPV2(x, y))
            end)
            if ok then
                data.X, data.Y = x, y
            end
        end
        if scaled then
            local ok = pcall(function()
                data.Widget:SetRenderScale(g_adityaorg_ESPV2(scale, scale))
            end)
            if ok then
                data.Scale = scale
            else
                data.Scale = nil
            end
        end
        if data.Visible ~= true then
            local ok = pcall(function()
                data.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
            end)
            if ok then
                data.Visible = true
            end
        end

        if data.Groups.Header then
            g_adityaorg_ESPSetGroupVisible(data.Groups.Header, false)
        end
        local theme = g_adityaorg_ESPTheme(isBot)
        local arcs = data.Groups.Arcs
        if opt.Box then
            arcs = g_adityaorg_ESPBuildArcs(data)
        end
        if arcs then
            g_adityaorg_ESPApplyGroupTheme(arcs, theme, "Arcs")
        end
        g_adityaorg_ESPSetGroupVisible(arcs, opt.Box == true)
    end

    g_adityaorg_ESPHealthRatio = function(character)
        local hp, maxHp = nil, nil
        pcall(function()
            hp = character.Health or character.HP or character.CurrentHealth
            maxHp = character.HealthMax or character.MaxHealth or character.MaxHP
            if not tonumber(hp) and character.GetHealth then
                hp = character:GetHealth()
            end
            if not tonumber(maxHp) and character.GetMaxHealth then
                maxHp = character:GetMaxHealth()
            end
        end)
        hp, maxHp = tonumber(hp), tonumber(maxHp)
        if not hp or not maxHp or maxHp <= 0 then
            return 1.0
        end
        return math.max(0.0, math.min(1.0, hp / maxHp))
    end

    -- g_adityaorg_ESPScanEnemies
    local function g_adityaorg_ESPScanEnemies()
        local pc = g_adityaorg_ESPGetController()
        local me = g_adityaorg_ESPGetLocalCharacter()
        if not pc or not me then
            g_adityaorg_ShotESP.Enemies = {}
            return nil, 0, 0
        end
        local myLoc = ESPShared.GetFrameRecord(me).Location
        if not myLoc then
            g_adityaorg_ShotESP.Enemies = {}
            return pc, 0, 0
        end
        local myTeam = g_adityaorg_ESPGetTeamID(me)

        local list = {}
        local realCount, botCount = 0, 0
        local pawns = ESPShared.GetFramePawns()
        pawns = pawns or _G.g_adityaorg_TrackedCharacters
        if pawns then
            for _, character in pairs(pawns) do
                if
                    character ~= me
                    and ESPShared.GetFrameRecord(character).Alive
                    and ESPShared.Events.Counted(character)
                then
                    local team = g_adityaorg_ESPGetTeamID(character)

                    local sameTeam = false
                    if myTeam ~= nil and team ~= nil then
                        local tNum, mNum = tonumber(team), tonumber(myTeam)
                        sameTeam = tNum and mNum and tNum > 0 and mNum > 0 and tNum == mNum
                    end
                    if not sameTeam then
                        local loc = ESPShared.GetFrameRecord(character).Location
                        local dist = ESPShared.DistanceMetersFrom(ESPShared.GetFrameRecord(character), myLoc)
                        if dist <= (tonumber(_G.g_adityaorg_MasterShotESP.MaxRangeMeters) or 400.0) then
                            local key = g_adityaorg_ESPGetPlayerKey(character)
                            local isBot = g_adityaorg_ESPIsBot(character, key)
                            if isBot then
                                botCount = botCount + 1
                            else
                                realCount = realCount + 1
                            end
                            list[#list + 1] = { Character = character, Key = key, IsBot = isBot, Distance = dist }
                        end
                    end
                end
            end
        end
        table.sort(list, function(a, b)
            if a.Distance == b.Distance then
                return a.Key < b.Key
            end
            return (a.Distance or 99999) < (b.Distance or 99999)
        end)
        g_adityaorg_ShotESP.Enemies = list
        return pc, realCount, botCount
    end

    -- g_adityaorg_ESPPrune
    local function g_adityaorg_ESPPrune(active, alive)
        for _, registry in ipairs({ g_adityaorg_ShotESP.Lines, g_adityaorg_ShotESP.Decorations }) do
            for key, data in pairs(registry) do
                if not active[key] then
                    g_adityaorg_ESPDestroyWidgetData(data)
                    registry[key] = nil
                end
            end
        end
        for _, registry in ipairs({ g_adityaorg_ShotESP.BuildStage, g_adityaorg_ShotESP.BoneNameCache }) do
            for key in pairs(registry) do
                if not active[key] then
                    registry[key] = nil
                end
            end
        end
        for key in pairs(g_adityaorg_ShotESP._BotCache) do
            if not alive[key] then
                g_adityaorg_ShotESP._BotCache[key] = nil
            end
        end
    end

    ESPShared.Events.Clearers[#ESPShared.Events.Clearers + 1] = function(actor)
        ESPShared.Events.ClearIn(g_adityaorg_ShotESP, g_adityaorg_ESPPrune, actor)
    end

    -- g_adityaorg_ESPUpdate
    local function g_adityaorg_ESPUpdate()
        local opt = _G.g_adityaorg_ESPOptions
        if opt then
            opt.Name = false
            opt.Health = false
            opt.Distance = false
            opt.Skeleton = false
            opt.Counter = false
            opt.Weapon = false
            opt.Flag = false
            opt.Visibility = false
            opt.Alert = false
        end
        local anyEnabled = opt and (opt.Line or opt.Box)
        if
            not (_G.LunarLoginRuntime and _G.LunarLoginRuntime.Authorized)
            or not _G.g_adityaorg_MasterShotESP.Enabled
            or not anyEnabled
        then
            if not g_adityaorg_ShotESP.Disabled then
                g_adityaorg_ESPResetWidgets()
            end
            g_adityaorg_ShotESP.Disabled = true
            return
        end
        g_adityaorg_ShotESP.Disabled = false
        local buildBudget = tonumber(_G.g_adityaorg_MasterShotESP.WidgetBuildBudget) or 96
        if buildBudget ~= buildBudget or buildBudget == math.huge then
            buildBudget = 96
        end
        g_adityaorg_ShotESP.BuildRemaining = math.max(1, math.floor(buildBudget))

        local world = g_adityaorg_ESPWorld()
        ESPShared.Events.WorldChanged(world)
        if world ~= g_adityaorg_ShotESP.LastWorld then
            g_adityaorg_ESPResetWidgets()
            g_adityaorg_ShotESP.LastWorld = world
            g_adityaorg_ShotESP.LastScanClock = -999.0
            g_adityaorg_ShotESP.LastTransformClock = -999.0
            g_adityaorg_ShotESP.TracerOrigin = nil
        end

        if g_adityaorg_ShotESP.Canvas and not g_adityaorg_ESPValid(g_adityaorg_ShotESP.Canvas) then
            g_adityaorg_ESPResetWidgets()
        end
        local canvas = g_adityaorg_ESPGetCanvas()
        if not canvas then
            return
        end
        local now = g_adityaorg_ESPNow()
        g_adityaorg_ShotESP.Now = now
        if now < g_adityaorg_ShotESP.LastScanClock then
            g_adityaorg_ShotESP.LastScanClock = -999.0
            g_adityaorg_ShotESP.LastTransformClock = -999.0
        end
        local pc = g_adityaorg_ESPGetController()
        local me = g_adityaorg_ESPGetLocalCharacter()
        if pc ~= g_adityaorg_ShotESP.LastController or me ~= g_adityaorg_ShotESP.LastPawn then
            g_adityaorg_ESPResetWidgets()
            g_adityaorg_ShotESP.LastController, g_adityaorg_ShotESP.LastPawn = pc, me
            canvas = g_adityaorg_ESPGetCanvas()
            if not canvas then
                return
            end
        end
        if not pc or not me then
            return
        end
        local myLoc = ESPShared.GetFrameRecord(me).Location
        local realCount, botCount = nil, nil
        if
            (now - g_adityaorg_ShotESP.LastScanClock) >= (tonumber(_G.g_adityaorg_MasterShotESP.ScanInterval) or 0.30)
        then
            pc, realCount, botCount = g_adityaorg_ESPScanEnemies()
            g_adityaorg_ShotESP.LastScanClock = now
            g_adityaorg_ShotESP.RealCount, g_adityaorg_ShotESP.BotCount = realCount, botCount
        end
        pc = pc or g_adityaorg_ESPGetController()
        if not pc then
            return
        end

        if
            (now - (g_adityaorg_ShotESP.LastTransformClock or -999.0))
            >= (tonumber(_G.g_adityaorg_MasterShotESP.TransformInterval) or 0.50)
        then
            g_adityaorg_ESPUpdateCanvasTransform(pc)
            local cw, ch = g_adityaorg_ESPGetCanvasLocalSize()
            if cw and ch then
                g_adityaorg_ShotESP.ViewportW, g_adityaorg_ShotESP.ViewportH = cw, ch
            end
            local rw, rh = g_adityaorg_ESPViewport(pc)
            g_adityaorg_ShotESP.RawViewportW, g_adityaorg_ShotESP.RawViewportH = rw, rh
            g_adityaorg_ShotESP.LastTransformClock = now
        end

        local rawW, rawH = ESPShared.ViewSize(pc)

        local canvasScaleX = ESPShared.SafeNumber(g_adityaorg_ShotESP.CanvasScaleX, 1.0, 0.00001, 100)
        local canvasScaleY = ESPShared.SafeNumber(g_adityaorg_ShotESP.CanvasScaleY, 1.0, 0.00001, 100)
        local canvasOffsetX = ESPShared.SafeNumber(g_adityaorg_ShotESP.CanvasOffsetX, 0.0, -1e7, 1e7)
        local canvasOffsetY = ESPShared.SafeNumber(g_adityaorg_ShotESP.CanvasOffsetY, 0.0, -1e7, 1e7)
        local originCenter =
            g_adityaorg_ESPV2((rawW * 0.5) * canvasScaleX + canvasOffsetX, 4.0 * canvasScaleY + canvasOffsetY)
        local active, alive = g_adityaorg_ShotESP.Active, g_adityaorg_ShotESP.Alive
        g_adityaorg_ShotESP.RealCount, g_adityaorg_ShotESP.BotCount = g_adityaorg_ESPFilterEnemies(
            g_adityaorg_ShotESP.Enemies,
            myLoc,
            _G.g_adityaorg_MasterShotESP.MaxRangeMeters,
            alive
        )

        local detailedEnabled = opt.Line or opt.Box
        if not detailedEnabled then
            for key in pairs(active) do
                active[key] = nil
            end
            g_adityaorg_ESPPrune(active, alive)
            return
        end

        for key in pairs(active) do
            active[key] = nil
        end
        local configuredMax = math.floor(ESPShared.SafeNumber(_G.g_adityaorg_MasterShotESP.MaxRendered, 8, 1, 64))
        local maxRendered = configuredMax
        local renderedCount = 0

        local selected = ESPShared.Events.SelectVisible(
            g_adityaorg_ShotESP.Enemies,
            maxRendered,
            g_adityaorg_ShotESP.RenderCandidates
        )
        g_adityaorg_ShotESP.RenderCandidates = selected
        for index, item in ipairs(selected) do
            if index > maxRendered then
                break
            end
            local c, key = item.Character, item.Key
            local headScreen, footScreen, onScreen = ESPShared.Events.Project(pc, c, g_adityaorg_ShotESP)
            if onScreen then
                if renderedCount < maxRendered then
                    renderedCount = renderedCount + 1
                    active[key] = true
                    local buildStage = g_adityaorg_ShotESP.BuildStage[key] or 1
                    local line = g_adityaorg_ShotESP.Lines[key]

                    local isVisible = false
                    pcall(function()
                        local SE = _G.SnaplineESP
                        if SE and SE.IsPlayerVisible and pc then
                            isVisible = SE.IsPlayerVisible(pc, c) == true
                        end
                    end)
                    local color = isVisible and ESP_LINE_VIS or ESP_LINE_HID
                    local colorKey = isVisible and "VIS" or "HID"
                    if opt.Line and (not line or not g_adityaorg_ESPValid(line.Widget)) then
                        g_adityaorg_ESPDestroyWidgetData(line)
                        line = g_adityaorg_ESPCreateLine(color)
                        if line then
                            line.ColorKey = colorKey
                        end
                        g_adityaorg_ShotESP.Lines[key] = line
                    elseif opt.Line and line and line.ColorKey ~= colorKey then
                        pcall(function()
                            line.Widget:SetBrushColor(color)
                        end)
                        line.ColorKey = colorKey
                    end

                    if opt.Line and line then
                        local tracerTarget = headScreen or footScreen
                        if tracerTarget then
                            g_adityaorg_ESPDrawLine(
                                line,
                                originCenter.X,
                                originCenter.Y,
                                tracerTarget.X,
                                tracerTarget.Y,
                                tonumber(_G.g_adityaorg_MasterShotESP.TracerThickness) or 1.80
                            )

                            if not line.Dot or not g_adityaorg_ESPValid(line.Dot.Widget) then
                                line.Dot = g_adityaorg_ESPCreateLine(color)
                            end
                            if line.Dot then
                                if line.Dot.ColorKey ~= colorKey then
                                    local painted = pcall(function()
                                        if line.Dot.Widget then
                                            line.Dot.Widget:SetBrushColor(color)
                                        end
                                    end)
                                    if painted then
                                        line.Dot.ColorKey = colorKey
                                    end
                                end
                                local dotSize = tonumber(_G.g_adityaorg_MasterShotESP.TracerDotSize) or 9.0
                                g_adityaorg_ESPDrawLine(
                                    line.Dot,
                                    tracerTarget.X - 0.6,
                                    tracerTarget.Y,
                                    tracerTarget.X + 0.6,
                                    tracerTarget.Y,
                                    dotSize
                                )
                            end
                        end
                    elseif line then
                        g_adityaorg_ESPHide(line)
                        if line.Dot then
                            g_adityaorg_ESPHide(line.Dot)
                        end
                    end

                    g_adityaorg_ESPUpdateDecoration(key, c, headScreen, footScreen, opt, buildStage, item.IsBot)

                    g_adityaorg_ShotESP.BuildStage[key] = math.min(5, buildStage + 1)
                end
            end
        end
        g_adityaorg_ESPPrune(active, alive)
    end

    local g_adityaorg_ESPRunnerToken = {}
    if type(_G.__MasterShotESPCleanup) == "function" then
        pcall(_G.__MasterShotESPCleanup)
    end
    _G.__MasterShotESPRunner = g_adityaorg_ESPRunnerToken
    _G.__MasterShotESPCleanup = g_adityaorg_ESPResetWidgets
    local g_adityaorg_ESPDiagnostics = { Updates = 0, Errors = 0, LastError = nil }
    _G.g_adityaorg_ESPDiagnostics = g_adityaorg_ESPDiagnostics
    local g_adityaorg_ESPTicker = nil
    pcall(function()
        g_adityaorg_ESPTicker = require("common.time_ticker")
    end)
    local g_adityaorg_ESPTick
    -- g_adityaorg_ESPSchedule
    local function g_adityaorg_ESPSchedule(delay)
        delay = ESPShared.SafeNumber(delay, 0.50, 0.001, 0.50)
        if _G.__MasterShotESPRunner ~= g_adityaorg_ESPRunnerToken then
            return
        end
        if not g_adityaorg_ESPTicker or not g_adityaorg_ESPTicker.AddTimerOnce then
            g_adityaorg_ESPDiagnostics.LastError = "common.time_ticker.AddTimerOnce unavailable"
            return
        end
        local serial = (g_adityaorg_ESPRunnerToken.Serial or 0) + 1
        g_adityaorg_ESPRunnerToken.Serial = serial
        g_adityaorg_ESPRunnerToken.Due = g_adityaorg_ESPNow() + delay
        local ok, err = pcall(g_adityaorg_ESPTicker.AddTimerOnce, delay, function()
            if
                _G.__MasterShotESPRunner ~= g_adityaorg_ESPRunnerToken
                or g_adityaorg_ESPRunnerToken.Serial ~= serial
            then
                return
            end
            g_adityaorg_ESPRunnerToken.Due = nil
            g_adityaorg_ShotESP.TimerClock = g_adityaorg_ShotESP.TimerClock + delay
            g_adityaorg_ESPTick()
        end)
        if not ok or err == false then
            g_adityaorg_ESPRunnerToken.Due = nil
            g_adityaorg_ESPDiagnostics.Errors = g_adityaorg_ESPDiagnostics.Errors + 1
            g_adityaorg_ESPDiagnostics.LastError = tostring(err)
        end
    end
    g_adityaorg_ESPTick = function()
        local token = g_adityaorg_ESPRunnerToken
        if _G.__MasterShotESPRunner ~= token then
            return
        end
        local now = g_adityaorg_ESPNow()
        local profiling = _G.g_adityaorg_MasterShotESP.Profile and os and type(os.clock) == "function"
        local callbackStarted = profiling and os.clock() or nil
        ESPShared.Frame.Begin(now)
        local F = _G.LunarFeatures
        if F then
            F.TimerClock = g_adityaorg_ShotESP.TimerClock
        end
        if
            not token.RenderDue
            or now >= token.RenderDue - 0.000001
            or (token.LastRenderClock and now < token.LastRenderClock)
        then
            local previous = g_adityaorg_ESPDiagnostics.LastTickSeconds
            if previous and now > previous then
                g_adityaorg_ESPDiagnostics.UpdateHz = 1 / (now - previous)
            end
            g_adityaorg_ESPDiagnostics.LastTickSeconds = now
            local started = profiling and os.clock() or nil
            local ok, err = pcall(g_adityaorg_ESPUpdate)
            ESPShared.Events.ReleaseSelected(g_adityaorg_ShotESP.RenderCandidates)
            g_adityaorg_ESPDiagnostics.LastUpdateOK = ok
            g_adityaorg_ESPDiagnostics.Updates = g_adityaorg_ESPDiagnostics.Updates + 1
            if not ok then
                g_adityaorg_ESPDiagnostics.Errors = g_adityaorg_ESPDiagnostics.Errors + 1
                g_adityaorg_ESPDiagnostics.LastError = tostring(err)
            end
            if started then
                local elapsed = os.clock() - started
                g_adityaorg_ESPDiagnostics.LastUpdateCPUSeconds = elapsed
                g_adityaorg_ESPDiagnostics.MaxUpdateCPUSeconds =
                    math.max(elapsed, g_adityaorg_ESPDiagnostics.MaxUpdateCPUSeconds or 0)
            end
            local o = _G.g_adityaorg_ESPOptions or {}
            local enabled = _G.g_adityaorg_MasterShotESP.Enabled
                and _G.LunarLoginRuntime
                and _G.LunarLoginRuntime.Authorized
            local detailed = enabled and (o.Line or o.Box)
            local interval = tonumber(_G.g_adityaorg_MasterShotESP.UpdateInterval) or 1 / 60
            if not detailed then
                interval = enabled
                        and o.Counter
                        and math.max(0.05, tonumber(_G.g_adityaorg_MasterShotESP.ScanInterval) or 0.35)
                    or 0.50
            end
            if interval ~= interval or math.abs(interval) == math.huge or interval <= 0 then
                interval = 1 / 60
            end
            token.LastRenderClock = now
            token.RenderDue = now + math.max(0.001, interval)
        end
        if profiling then
            g_adityaorg_ESPDiagnostics.LastPumpCPUSeconds = 0
        end
        if F and F.Pump and not F.Token.Stopped then
            local pumpStarted = profiling and os.clock() or nil
            local ok, err = pcall(F.Pump, now)
            if not ok then
                F.Error("Scheduler", err)
            end
            if pumpStarted then
                local elapsed = os.clock() - pumpStarted
                g_adityaorg_ESPDiagnostics.LastPumpCPUSeconds = elapsed
                g_adityaorg_ESPDiagnostics.MaxPumpCPUSeconds =
                    math.max(elapsed, g_adityaorg_ESPDiagnostics.MaxPumpCPUSeconds or 0)
            end
        end
        ESPShared.Frame.Finish()
        local after = g_adityaorg_ESPNow()
        local interval = math.max(0.001, token.RenderDue - after)
        if F and F.NextInterval and not F.Token.Stopped then
            interval = math.min(interval, F.NextInterval(after))
        end
        g_adityaorg_ESPSchedule(interval)
        if callbackStarted then
            local elapsed = os.clock() - callbackStarted
            g_adityaorg_ESPDiagnostics.LastCallbackCPUSeconds = elapsed
            g_adityaorg_ESPDiagnostics.MaxCallbackCPUSeconds =
                math.max(elapsed, g_adityaorg_ESPDiagnostics.MaxCallbackCPUSeconds or 0)
            g_adityaorg_ESPDiagnostics.TotalCallbackCPUSeconds = (
                g_adityaorg_ESPDiagnostics.TotalCallbackCPUSeconds or 0
            ) + elapsed
            g_adityaorg_ESPDiagnostics.CallbackSamples = (g_adityaorg_ESPDiagnostics.CallbackSamples or 0) + 1
        end
    end

    _G.g_adityaorg_MasterShotESPForceRefresh = function()
        if _G.__MasterShotESPRunner ~= g_adityaorg_ESPRunnerToken then
            return
        end
        g_adityaorg_ESPRunnerToken.RenderDue = nil
        g_adityaorg_ShotESP.LastScanClock = -999.0
        g_adityaorg_ShotESP.LastTransformClock = -999.0
        local due = g_adityaorg_ESPRunnerToken.Due
        if not due or due - g_adityaorg_ESPNow() > 0.002 then
            g_adityaorg_ESPSchedule(0.001)
        end
    end

    -- ============================================================================
    -- // AIM CIRCLE HUD //
    -- ============================================================================
    do
        local previous = _G.LunarAimCircleHUD
        if previous and previous.Destroy then
            pcall(previous.Destroy)
        end
        local C = { Segments = 40, BaseDiameter = 120, BuildAttempts = 0 }
        _G.LunarAimCircleHUD = C
        local tools, anchorClass
        pcall(function()
            tools = require("GameLua.Mod.BaseMod.Common.UI.InGameUITools")
        end)
        pcall(function()
            anchorClass = import("Anchors")
        end)
        -- Destroy
        function C.Destroy()
            if C.Widget then
                pcall(function()
                    C.Widget:RemoveFromParent()
                end)
            end
            C.Widget = nil
            C.Parent = nil
            C.Value = nil
            C.Visible = false
            C.Lines = nil
            C.Slot = nil
            C.Due = nil
            C.NextApply = nil
            C.Blocked = false
            C.BuildAttempts = 0
            C.ScaleMode = nil
        end
        -- parent
        local function parent()
            if not tools then
                pcall(function()
                    tools = require("GameLua.Mod.BaseMod.Common.UI.InGameUITools")
                end)
            end
            if not tools then
                return
            end
            local ok, root = pcall(tools.GetMainControlBaseUI)
            if not ok or not g_adityaorg_ESPValid(root) then
                return
            end
            local p = root.CanvasPanel_0 or root.CanvasPanel_42
            if g_adityaorg_ESPValid(p) then
                return p
            end
        end
        -- layout
        local function layout(value)
            local radius = value * 0.5
            C.Slot:SetSize(g_adityaorg_ESPV2(value, value))
            for _, r in ipairs(C.Lines) do
                r.Slot:SetPosition(g_adityaorg_ESPV2(radius + radius * r.X, radius + radius * r.Y - 0.75))
                r.Slot:SetSize(g_adityaorg_ESPV2(radius * r.Length + 0.25, 1.5))
            end
        end
        -- Update
        function C.Update(now)
            local F = _G.LunarFeatures
            if not F then
                return
            end
            if not (_G.LunarLoginRuntime and _G.LunarLoginRuntime.Authorized) then
                if C.Widget and C.Visible then
                    pcall(function()
                        C.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
                    end)
                end
                C.Visible = false
                C.Due = nil
                return
            end
            now = now or F.Now()
            C.Due = nil
            if C.LastClock and now < C.LastClock then
                C.NextApply = nil
            end
            C.LastClock = now
            if not F.Settings.AimEnabled then
                if C.Widget and C.Visible then
                    pcall(function()
                        C.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.Collapsed)
                    end)
                end
                C.Visible = false
                return
            end
            if C.Blocked then
                return
            end
            if C.NextApply and now < C.NextApply then
                C.Due = C.NextApply
                return
            end
            if not C.Widget or not g_adityaorg_ESPValid(C.Widget) then
                local p = parent()
                if not p then
                    C.Due = now + 1
                    return
                end
                local widget, slot, lines
                local ok, why = pcall(function()
                    widget = CGame:NewObjectFromPath("/Script/UMG.CanvasPanel", p)
                    slot = p:AddChildToCanvas(widget)
                    local aOK, anchors = pcall(function()
                        return Anchors()
                    end)
                    if not aOK or not anchors then
                        aOK, anchors = pcall(function()
                            return anchorClass()
                        end)
                    end
                    if not aOK or not anchors then
                        aOK, anchors = pcall(function()
                            return slot:GetAnchors()
                        end)
                    end
                    assert(aOK and anchors, "CIRCLE_ANCHORS_UNAVAILABLE")
                    anchors.Minimum = g_adityaorg_ESPV2(0.5, 0.5)
                    anchors.Maximum = g_adityaorg_ESPV2(0.5, 0.5)
                    slot:SetAnchors(anchors)
                    slot:SetAlignment(g_adityaorg_ESPV2(0.5, 0.5))
                    slot:SetPosition(g_adityaorg_ESPV2(0, 0))
                    slot:SetAutoSize(false)
                    slot:SetSize(g_adityaorg_ESPV2(C.BaseDiameter, C.BaseDiameter))
                    slot:SetZOrder(65)
                    widget:SetRenderTransformPivot(g_adityaorg_ESPV2(0.5, 0.5))
                    local color = LinearColor(0.1, 0.72, 1, 0.92)
                    local radius = C.BaseDiameter * 0.5
                    lines = {}
                    for i = 0, C.Segments - 1 do
                        local a = i * math.pi * 2 / C.Segments
                        local b = (i + 1) * math.pi * 2 / C.Segments
                        local x, y = math.cos(a), math.sin(a)
                        local dx, dy = math.cos(b) - x, math.sin(b) - y
                        local line = CGame:NewObjectFromPath("/Script/UMG.Border", widget)
                        line:SetBrushColor(color)
                        line:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
                        line:SetRenderTransformPivot(g_adityaorg_ESPV2(0, 0.5))
                        line:SetRenderAngle((a + math.pi / C.Segments + math.pi * 0.5) * 180 / math.pi)
                        local ls = widget:AddChildToCanvas(line)
                        ls:SetAutoSize(false)
                        ls:SetPosition(g_adityaorg_ESPV2(radius + radius * x, radius + radius * y - 0.75))
                        local length = math.sqrt(dx * dx + dy * dy)
                        ls:SetSize(g_adityaorg_ESPV2(radius * length + 0.25, 1.5))
                        lines[#lines + 1] = { Slot = ls, X = x, Y = y, Length = length }
                    end
                end)
                if not ok then
                    if widget then
                        pcall(function()
                            widget:RemoveFromParent()
                        end)
                    end
                    C.BuildAttempts = C.BuildAttempts + 1
                    F.Error("AimCircle.Build", why)
                    if C.BuildAttempts >= 3 then
                        C.Blocked = true
                    else
                        C.Due = now + C.BuildAttempts
                    end
                    return
                end
                C.Widget = widget
                C.Slot = slot
                C.Parent = p
                C.Lines = lines
                C.Value = nil
                C.ScaleMode = nil
            end
            local value = F.Settings.AimCircle
            if C.Value ~= value then
                local ok = false
                if C.ScaleMode ~= "layout" then
                    ok = pcall(function()
                        C.Widget:SetRenderScale(g_adityaorg_ESPV2(value / C.BaseDiameter, value / C.BaseDiameter))
                    end)
                    C.ScaleMode = ok and "scale" or "layout"
                end
                if not ok then
                    ok = pcall(layout, value)
                end
                if ok then
                    C.Value = value
                    C.NextApply = now + 0.1
                else
                    C.Blocked = true
                    F.Error("AimCircle.Size", "native size update failed")
                    return
                end
            end
            if not C.Visible then
                local ok = pcall(function()
                    C.Widget:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
                end)
                if ok then
                    C.Visible = true
                end
            end
        end
        -- Request
        function C.Request()
            local F = _G.LunarFeatures
            if F then
                C.Update(F.Now())
            end
        end
    end

    -- ============================================================================
    -- // FEATURE SWITCHES / PERSISTENCE //
    -- ============================================================================
    do
        if type(_G.__LunarFeaturesCleanup) == "function" then
            pcall(_G.__LunarFeaturesCleanup)
        end
        local F = { Token = {}, Diagnostics = { Errors = 0 }, TimerClock = 0, LastWorld = nil }
        _G.LunarFeatures = F
        local settings = _G.LunarFeatureSettings or {}
        _G.LunarFeatureSettings = settings
        F.Settings = settings
        -- number
        local function number(value, lo, hi, fallback)
            local v = tonumber(value)
            if not v or v ~= v or v == math.huge or v == -math.huge then
                v = fallback
            end
            return math.floor(math.max(lo, math.min(hi, v)) + 0.5)
        end
        F.Clamp = number
        settings.IpadFOV = number(settings.IpadFOV or _G.LexusState.CustomTextData.IpadViewFOV, 90, 120, 120)
        settings.AimSpeed = number(settings.AimSpeed, 120, 150, 120)
        settings.AimCircle = number(settings.AimCircle, 120, 240, 120)
        settings.AimTarget = number(settings.AimTarget, 1, 3, 1)
        settings.AimEnabled = settings.AimEnabled == true
        settings.WallEnabled = settings.WallEnabled == true
        settings.WallVisible = number(settings.WallVisible, 1, 7, 1)
        settings.WallOccluded = number(settings.WallOccluded, 1, 7, 2)
        settings.MortarEnabled = settings.MortarEnabled == true
        _G.g_Botmater_ESPOptions = _G.g_Botmater_ESPOptions or {}
        for _, key in ipairs({ "Name", "Line", "Box", "Health", "Distance", "Weapon", "Flag", "Visibility", "Alert" }) do
            if _G.g_Botmater_ESPOptions[key] == nil then
                _G.g_Botmater_ESPOptions[key] = false
            end
        end
        local paths = g_adityaorg_ESPSettingsPaths()
        for i, path in ipairs(paths) do
            paths[i] = path:gsub("ADITYA_UMG_ESP_settings.lua$", "ADITYA_FEATURES_V3_settings.lua")
        end
        if io and io.open then
            for _, path in ipairs(paths) do
                local ok, file = pcall(io.open, path, "r")
                if ok and file then
                    local readOK, payload = pcall(function()
                        return file:read("*a")
                    end)
                    pcall(function()
                        file:close()
                    end)
                    if readOK and type(payload) == "string" then
                        F.SettingsReadPath = path
                        for _, key in ipairs({ "AimEnabled", "WallEnabled", "IpadEnabled", "MortarEnabled" }) do
                            local val = payload:match("%f[%w_]" .. key .. "%s*=%s*(%a+)")
                            if val == "true" or val == "false" then
                                if key == "IpadEnabled" then
                                    _G.LexusConfig.IpadView = val == "true"
                                else
                                    settings[key] = val == "true"
                                end
                            end
                        end
                        for _, key in ipairs({ "IpadFOV", "AimSpeed", "AimCircle", "AimTarget" }) do
                            local val = payload:match("%f[%w_]" .. key .. "%s*=%s*([%d%.%-]+)")
                            if val then
                                settings[key] = number(
                                    val,
                                    key == "IpadFOV" and 90 or ((key == "AimSpeed" or key == "AimCircle") and 120 or 1),
                                    key == "AimTarget" and 3
                                        or (key == "AimCircle" and 240 or (key == "AimSpeed" and 150 or 120)),
                                    settings[key]
                                )
                            end
                        end
                        for _, key in ipairs({ "WallVisible", "WallOccluded" }) do
                            local val = payload:match("%f[%w_]" .. key .. "%s*=%s*([%d%.%-]+)")
                            if val then
                                settings[key] = number(val, 1, 7, settings[key])
                            end
                        end
                        for _, key in ipairs({
                            "Name",
                            "Line",
                            "Box",
                            "Health",
                            "Distance",
                            "Weapon",
                            "Flag",
                            "Visibility",
                            "Alert",
                        }) do
                            local val = payload:match("%f[%w_]V1_" .. key .. "%s*=%s*(%a+)")
                            if val == "true" or val == "false" then
                                _G.g_Botmater_ESPOptions[key] = val == "true"
                            end
                        end
                        for _, key in ipairs({ "Line", "Box" }) do
                            local val = payload:match("%f[%w_]V2_" .. key .. "%s*=%s*(%a+)")
                            if val == "true" or val == "false" then
                                _G.g_adityaorg_ESPOptions[key] = val == "true"
                            end
                        end
                        break
                    end
                end
            end
        end
        if not F.SettingsReadPath and g_adityaorg_ESPLoadedSettingsPath then
            F.SettingsReadPath = g_adityaorg_ESPLoadedSettingsPath:gsub(
                "ADITYA_UMG_ESP_settings%.lua$",
                "ADITYA_FEATURES_V3_settings.lua"
            )
        end
        _G.LexusState.CustomTextData.IpadViewFOV = settings.IpadFOV
        F.Now = function()
            local now = nil
            pcall(function()
                local world = g_adityaorg_ESPWorld()
                if world and GameplayStaticsESP and GameplayStaticsESP.GetRealTimeSeconds then
                    now = GameplayStaticsESP.GetRealTimeSeconds(world)
                end
            end)
            return tonumber(now) or F.TimerClock
        end
        F.Save = function(force)
            if not F.Dirty or not io or not io.open then
                return
            end
            local lines = { "return {", "  IpadEnabled = " .. tostring(_G.LexusConfig.IpadView == true) .. "," }
            for _, key in ipairs({
                "AimEnabled",
                "WallEnabled",
                "MortarEnabled",
                "IpadFOV",
                "AimSpeed",
                "AimCircle",
                "AimTarget",
                "WallVisible",
                "WallOccluded",
            }) do
                lines[#lines + 1] = "  " .. key .. " = " .. tostring(settings[key]) .. ","
            end
            for _, key in ipairs({ "Name", "Line", "Box", "Health", "Distance", "Weapon", "Flag", "Visibility", "Alert" }) do
                lines[#lines + 1] = "  V1_" .. key .. " = " .. tostring(_G.g_Botmater_ESPOptions[key] == true) .. ","
            end
            for _, key in ipairs({ "Line", "Box" }) do
                lines[#lines + 1] = "  V2_" .. key .. " = " .. tostring(_G.g_adityaorg_ESPOptions[key] == true) .. ","
            end
            lines[#lines + 1] = "}"
            local payload = table.concat(lines, "\n")
            local savePaths = F.SettingsReadPath and { F.SettingsReadPath } or paths
            for _, path in ipairs(savePaths) do
                local wrote, reason, atomic = g_adityaorg_ESPWriteSettings(path, payload)
                if wrote then
                    F.SettingsReadPath = path
                    F.Dirty = false
                    F.Diagnostics.LastSaveOK = true
                    F.Diagnostics.LastSavePath = path
                    F.Diagnostics.AtomicSave = atomic
                    return true
                end
                F.Diagnostics.LastSaveError = reason
            end
            F.Diagnostics.LastSaveOK = false
            return false
        end
        F.MarkDirty = function(immediate)
            F.Dirty = true
            if immediate then
                F.Save(true)
            end
        end
        F.SetIpad = function(enabled)
            _G.LexusConfig.IpadView = enabled == true or enabled == 1
            _G.LexusState.CustomTextData.IpadViewFOV = settings.IpadFOV
            pcall(g_adityaorg_ApplyiPadView)
            F.MarkDirty(true)
        end
        F.SetIpadFOV = function(value)
            settings.IpadFOV = number(value, 90, 120, 120)
            _G.LexusState.CustomTextData.IpadViewFOV = settings.IpadFOV
            pcall(g_adityaorg_ApplyiPadView)
            F.MarkDirty()
        end
        F.SetAimSpeed = function(value)
            local nextValue = number(value, 120, 150, 120)
            if nextValue == settings.AimSpeed then
                return
            end
            settings.AimSpeed = nextValue
            if _G.XthrlenState and _G.XthrlenState.CustomTextData then
                local data = _G.XthrlenState.CustomTextData
                data.AimTouchHipSpeed = nextValue
                data.AimTouchScopeSpeed = nextValue
            end
            F.MarkDirty()
            F.SaveDue = F.Now() + 0.3
        end
        F.AimRadiusUI = function()
            return settings.AimCircle * 0.5
        end
        F.SetAimCircle = function(value)
            local nextValue = number(value, 120, 240, 120)
            if nextValue == settings.AimCircle then
                return
            end
            settings.AimCircle = nextValue
            if _G.XthrlenState and _G.XthrlenState.CustomTextData then
                _G.XthrlenState.CustomTextData.AimTouchHipDist = settings.AimCircle
                _G.XthrlenState.CustomTextData.AimTouchScopeDist = settings.AimCircle
            end
            F.MarkDirty()
            F.SaveDue = F.Now() + 0.3
            if _G.LunarAimCircleHUD then
                _G.LunarAimCircleHUD.Request()
            end
        end
        F.SetAimTarget = function(value)
            settings.AimTarget = number(value, 1, 3, 1)
            F.MarkDirty(true)
        end

        F.AimSettingsEventType = -14050701
        F.AimSettingsEventID = 1
        F.SetAimMode = function(value)
            local mode = F.Clamp(value, 0, 2, 0)
            local changed = settings.AimEnabled ~= (mode == 1)
            settings.AimEnabled = mode == 1
            _G.XthrlenConfig.AimTouchEnable = settings.AimEnabled
            if not settings.AimEnabled then
                _G.XthrlenState.offPitch = 0
                _G.XthrlenState.offYaw = 0
                F.AimLastClock = nil
            end
            F.MarkDirty(true)
            if _G.LunarAimCircleHUD then
                _G.LunarAimCircleHUD.Request()
            end
            if F.Wake then
                F.Wake()
            end
            if changed and EventSystem and type(EventSystem.postEvent) == "function" then
                local ok, err = pcall(EventSystem.postEvent, EventSystem, F.AimSettingsEventType, F.AimSettingsEventID)
                if not ok then
                    F.Error("Aim.SettingsRefresh", err)
                end
            end
        end
        F.SetAim = function(enabled)
            local on = enabled == true or enabled == 1
            F.SetAimMode(on and 1 or 0)
        end
        F.SetMortar = function(enabled)
            settings.MortarEnabled = enabled == true or enabled == 1
            if not settings.MortarEnabled and F.Mortar then
                F.Mortar.Stop()
            end
            if F.Mortar then
                F.Mortar.Due = 0
            end
            F.MarkDirty(true)
            if F.Wake then
                F.Wake()
            end
        end

        F.RefreshWallSettings = function()
            if EventSystem and type(EventSystem.postEvent) == "function" then
                local ok, err = pcall(EventSystem.postEvent, EventSystem, -14050701, 3)
                if not ok then
                    F.Error("Wall.SettingsRefresh", err)
                end
            end
        end
        F.SetWall = function(enabled)
            local changed = settings.WallEnabled ~= (enabled == true or enabled == 1)
            settings.WallEnabled = enabled == true or enabled == 1
            if not settings.WallEnabled and F.Wall then
                F.Wall.Stop()
            end
            F.MarkDirty(true)
            if changed then
                F.RefreshWallSettings()
            end
            if F.Wake then
                F.Wake()
            end
        end
        F.SetWallColor = function(key, value)
            if key ~= "WallVisible" and key ~= "WallOccluded" then
                return false
            end
            local v = number(value, 1, 7, settings[key])
            if settings[key] == v then
                return true
            end
            settings[key] = v
            if F.Wall then
                F.Wall.UpdateColors()
            end
            F.MarkDirty(true)
            F.RefreshWallSettings()
            if settings.WallEnabled and F.Wake then
                F.Wake()
            end
            return true
        end

        local v1Keys = { "Name", "Line", "Box", "Health", "Distance", "Weapon", "Flag", "Visibility", "Alert" }
        local v2Keys = { "Name", "Line", "Box", "Health", "Distance", "Skeleton", "Counter" }
        local v1Valid = {}
        for _, key in ipairs(v1Keys) do
            v1Valid[key] = true
        end
        local v1ToV2 =
            { Name = "Name", Line = "Line", Box = "Box", Health = "Health", Distance = "Distance", EnemyCounter = "Counter" }
        local v2ToV1 =
            { Name = "Name", Line = "Line", Box = "Box", Health = "Health", Distance = "Distance", Counter = "EnemyCounter" }
        local v2Valid =
            { Name = true, Line = true, Box = true, Health = true, Distance = true, Skeleton = true, Counter = true }
        F.ESPSettingsEventType = -14050701
        F.ESPSettingsEventID = 2
        -- applyESP
        local function applyESP(version, key, on)
            local first, second = false, false
            local own = version == 1 and _G.g_Botmater_ESPOptions or _G.g_adityaorg_ESPOptions
            local other = version == 1 and _G.g_adityaorg_ESPOptions or _G.g_Botmater_ESPOptions
            local mapped = (version == 1 and v1ToV2 or v2ToV1)[key]
            if (own[key] == true) ~= on then
                own[key] = on
                first = true
            end
            if on and mapped and other[mapped] == true then
                other[mapped] = false
                second = true
            end
            if version == 1 then
                return first, second
            end
            return second, first
        end
        -- commitESP
        local function commitESP(changedV1, changedV2)
            if not changedV1 and not changedV2 then
                if F.Dirty then
                    return F.Save(true)
                end
                return true
            end
            if changedV1 and F.V1 then
                F.V1.Refresh()
                F.V1Due = 0
            end
            F.MarkDirty(true)
            if changedV2 then
                _G.g_adityaorg_MasterShotESPForceRefresh()
            else
                local due = g_adityaorg_ESPRunnerToken.Due
                if not due or due - g_adityaorg_ESPNow() > 0.002 then
                    g_adityaorg_ESPSchedule(0.001)
                end
            end
            if EventSystem and type(EventSystem.postEvent) == "function" then
                local ok, err = pcall(EventSystem.postEvent, EventSystem, F.ESPSettingsEventType, F.ESPSettingsEventID)
                if not ok then
                    F.Error("ESP.SettingsRefresh", err)
                end
            end
            return true
        end
        F.SetESP = function(version, key, value)
            if version ~= 1 and version ~= 2 then
                return false
            end
            if (version == 1 and not v1Valid[key]) or (version == 2 and not v2Valid[key]) then
                return false
            end
            local changedV1, changedV2 = applyESP(version, key, value == true or value == 1)
            return commitESP(changedV1, changedV2)
        end
        F.GetESPAll = function(version)
            if version ~= 1 and version ~= 2 then
                return false
            end
            local own = version == 1 and _G.g_Botmater_ESPOptions or _G.g_adityaorg_ESPOptions
            for _, key in ipairs(version == 1 and v1Keys or v2Keys) do
                if own[key] ~= true then
                    return false
                end
            end
            return true
        end
        F.SetESPAll = function(version, value)
            if version ~= 1 and version ~= 2 then
                return false
            end
            local changedV1, changedV2 = false, false
            for _, key in ipairs(version == 1 and v1Keys or v2Keys) do
                local a, b = applyESP(version, key, value == true or value == 1)
                changedV1, changedV2 = changedV1 or a, changedV2 or b
            end
            return commitESP(changedV1, changedV2)
        end

        F.InstallNativeBulkSwitch = function(class)
            if type(class) ~= "table" or type(class.OnSelected) ~= "function" then
                return false
            end
            if class.__LunarBulkSwitchV7 then
                return true
            end
            local original = class.OnSelected
            class.OnSelected = function(self, index)
                local data = self.Data
                local repeatBulk = data and data.LunarBulk and self.UIRoot.Selector:GetSelectedIndex() == index
                local result = original(self, index)
                if repeatBulk then
                    return data.SetFunc(data.Key, self:_IndexToValue(index))
                end
                return result
            end
            class.__LunarBulkSwitchV7 = true
            return true
        end
        F.SetV1 = function(key, value)
            return F.SetESP(1, key, value)
        end
        F.SetV2 = function(key, value)
            return F.SetESP(2, key, value)
        end

        for key, mapped in pairs(v1ToV2) do
            if _G.g_Botmater_ESPOptions[key] == true and _G.g_adityaorg_ESPOptions[mapped] == true then
                _G.g_adityaorg_ESPOptions[mapped] = false
                F.MarkDirty()
            end
        end
        F.Error = function(area, err)
            F.Diagnostics.Errors = F.Diagnostics.Errors + 1
            F.Diagnostics.LastError = area .. ": " .. tostring(err)
        end
        _G.__LunarFeaturesCleanup = function()
            if _G.LunarAimCircleHUD then
                _G.LunarAimCircleHUD.Destroy()
            end
            F.Token.Stopped = true
            if ESPShared.Events.UnbindAll then
                ESPShared.Events.UnbindAll()
            end
            if F.V1 then
                F.V1.Reset()
            end
            if F.Wall then
                F.Wall.Stop()
            end
            if F.Mortar then
                F.Mortar.Stop()
            end
        end
    end

    -- ============================================================================
    -- // AIM / TARGET SELECTION //
    -- ============================================================================
    do
        local AimV2, AimGameplayStatics, AimMath, AimUI, AimLayout
        pcall(function()
            AimV2 = import("Vector2D")
        end)
        pcall(function()
            AimGameplayStatics = import("GameplayStatics")
        end)
        pcall(function()
            AimMath = import("KismetMathLibrary")
        end)
        pcall(function()
            AimUI = require("client.common.ui_util")
        end)
        pcall(function()
            AimLayout = import("WidgetLayoutLibrary")
        end)
        _G.XthrlenConfig = _G.XthrlenConfig or {}
        _G.XthrlenState = _G.XthrlenState or {}
        _G.XthrlenState.CustomTextData = _G.XthrlenState.CustomTextData or {}

        _G.XthrlenConfig.AimTouchEnable = _G.LunarFeatures.Settings.AimEnabled
        _G.XthrlenConfig.AimTouchHipfire = true
        _G.XthrlenConfig.AimTouchScopeAll = true
        _G.XthrlenConfig.AimTouchHipVisCheck = true
        _G.XthrlenConfig.AimTouchScopeVisCheck = true
        _G.XthrlenConfig.AimTouchHipIgKnock = true
        _G.XthrlenConfig.AimTouchScopeIgKnock = true

        _G.XthrlenConfig.AimTouchHipIgBot = false
        _G.XthrlenConfig.AimTouchScopeIgBot = false
        _G.XthrlenConfig.AimTouchSG = false
        _G.XthrlenConfig.AimTouchSGAutoFire = false
        _G.XthrlenConfig.AimTouchScopeSniper = false
        _G.XthrlenConfig.AimTouchMortar = false
        _G.XthrlenConfig.EspFovCircle = false

        _G.XthrlenState.CustomTextData.AimTouchHipPrio = 1
        _G.XthrlenState.CustomTextData.AimTouchHipBone = 1
        _G.XthrlenState.CustomTextData.AimTouchHipCond = 1
        _G.XthrlenState.CustomTextData.AimTouchHipSpeed = _G.LunarFeatures.Settings.AimSpeed
        _G.XthrlenState.CustomTextData.AimTouchHipDist = _G.LunarFeatures.Settings.AimCircle
        _G.XthrlenState.CustomTextData.AimTouchHipFOV = 30

        _G.XthrlenState.CustomTextData.AimTouchScopePrio = 1
        _G.XthrlenState.CustomTextData.AimTouchScopeBone = 1
        _G.XthrlenState.CustomTextData.AimTouchScopeCond = 1
        _G.XthrlenState.CustomTextData.AimTouchScopeSpeed = _G.LunarFeatures.Settings.AimSpeed
        _G.XthrlenState.CustomTextData.AimTouchScopeDist = _G.LunarFeatures.Settings.AimCircle
        _G.XthrlenState.CustomTextData.AimTouchScopeFOV = 30
        _G.XthrlenState.CustomTextData.AimTouchScopePred = 0

        _G.XthrlenState.offPitch = _G.XthrlenState.offPitch or 0
        _G.XthrlenState.offYaw = _G.XthrlenState.offYaw or 0

        -- clampAngles
        local function clampAngles(angles)
            if angles.Pitch > 180 then
                angles.Pitch = angles.Pitch - 360
            end
            if angles.Pitch < -180 then
                angles.Pitch = angles.Pitch + 360
            end

            if angles.Pitch < -75 then
                angles.Pitch = -75
            elseif angles.Pitch > 75 then
                angles.Pitch = 75
            end

            while angles.Yaw < -180 do
                angles.Yaw = angles.Yaw + 360
            end
            while angles.Yaw > 180 do
                angles.Yaw = angles.Yaw - 360
            end

            return angles
        end

        _G.GetEnemyTargetsFromActors = function(radius)
            local result = {}
            local player = GameplayData.GetPlayerCharacter()
            if not (slua and slua.isValid and slua.isValid(player)) then
                return result
            end

            local allCharacters = {}
            if GameplayData.GetAllPlayerCharacters then
                allCharacters = GameplayData.GetAllPlayerCharacters()
            elseif GameplayData.GameCharacters then
                for _, char in pairs(GameplayData.GameCharacters) do
                    table.insert(allCharacters, char)
                end
            end

            local myTeam = player:GetTeamID()
            for _, actor in pairs(allCharacters) do
                if slua.isValid(actor) and actor ~= player and actor.GetTeamID and actor:IsAlive() then
                    if actor:GetTeamID() ~= myTeam then
                        local dist = player:GetDistanceTo(actor)
                        if dist <= radius then
                            table.insert(result, actor)
                        end
                    end
                end
            end
            return result
        end

        _G.AimTouch = function()
            local ok, err = pcall(function()
                if not _G.XthrlenConfig.AimTouchEnable then
                    return
                end

                local player = GameplayData.GetPlayerCharacter()
                if not (slua and slua.isValid and slua.isValid(player)) then
                    return
                end

                local pc = player:GetPlayerControllerSafety()
                if not (slua and slua.isValid and slua.isValid(pc)) then
                    return
                end

                local isFiring = player.bIsWeaponFiring
                local isADS = player.bIsGunADS

                if not isFiring then
                    return
                end

                local weapon = player.WeaponManagerComponent and player.WeaponManagerComponent.CurrentWeaponReplicated
                if not weapon and type(player.GetCurrentShootWeapon) == "function" then
                    weapon = player:GetCurrentShootWeapon()
                end

                if _G.LunarFeatures.Settings.MortarEnabled and weapon and weapon.MortarState == 2 then
                    return
                end
                local isShotgun = false
                local isSniper = false
                local isMortar = false
                local currentAmmo = 1

                if slua.isValid(weapon) then
                    local wID = type(weapon.GetWeaponID) == "function" and weapon:GetWeaponID() or 0
                    local wName = type(weapon.GetWeaponName) == "function" and weapon:GetWeaponName() or ""

                    if
                        (wID >= 1030000 and wID < 1040000)
                        or wName:find("S686")
                        or wName:find("S1897")
                        or wName:find("S12")
                        or wName:find("DBS")
                        or wName:find("M1014")
                    then
                        isShotgun = true
                    end
                    if
                        wName:find("Kar98")
                        or wName:find("M24")
                        or wName:find("AWM")
                        or wName:find("Mosin")
                        or wName:find("Win94")
                        or wName:find("AMR")
                        or wName:find("SKS")
                        or wName:find("SLR")
                        or wName:find("Mini")
                        or wName:find("Mk14")
                        or wName:find("QBU")
                        or wName:find("Mk12")
                        or wName:find("VSS")
                    then
                        isSniper = true
                    end
                    if wName:lower():find("mortar") or wName:lower():find("cối") then
                        isMortar = true
                    end

                    if type(weapon.GetCurrentAmmo) == "function" then
                        currentAmmo = weapon:GetCurrentAmmo()
                    elseif
                        weapon.ShootWeaponComponent
                        and type(weapon.ShootWeaponComponent.GetCurrentAmmo) == "function"
                    then
                        currentAmmo = weapon.ShootWeaponComponent:GetCurrentAmmo()
                    elseif weapon.CurrentAmmo ~= nil then
                        currentAmmo = weapon.CurrentAmmo
                    end
                end

                if _G.XthrlenState.IsAutoFiring then
                    pcall(function()
                        player.bIsWeaponFiring = false
                        if type(player.SetIsWeaponFiring) == "function" then
                            player:SetIsWeaponFiring(false)
                        end
                        if slua.isValid(pc) and type(pc.SetIsWeaponFiring) == "function" then
                            pc:SetIsWeaponFiring(false)
                        end
                        local wepMgr = player.WeaponManagerComponent
                        if slua.isValid(wepMgr) then
                            wepMgr.bIsWeaponFiring = false
                        end
                    end)
                    _G.XthrlenState.IsAutoFiring = false
                end

                if isShotgun and currentAmmo <= 0 then
                    return
                end

                local cond = 2
                local prioMode = 1
                local boneIdx = 1
                local speedVal = 100
                local fovVal = 30
                local maxDistMeters = 100
                local useVisCheck = false
                local igKnock = false
                local igBot = false
                local predVal = 0

                if isMortar and _G.XthrlenConfig.AimTouchMortar then
                    local isPlaced = false
                    pcall(function()
                        if weapon and weapon.MortarState == 2 then
                            isPlaced = true
                        end
                    end)
                    if not isPlaced then
                        return
                    end

                    cond = 2
                    prioMode = 1
                    boneIdx = 4
                    speedVal = 100
                    fovVal = _G.XthrlenState.CustomTextData.AimTouchMortarFOV or 360
                    maxDistMeters = 2000
                    useVisCheck = false
                    igKnock = false
                    igBot = false
                    predVal = _G.XthrlenState.CustomTextData.AimTouchMortarPred or 0
                elseif isShotgun and _G.XthrlenConfig.AimTouchSG then
                    cond = _G.XthrlenState.CustomTextData.AimTouchSGCond or 1
                    if _G.XthrlenConfig.AimTouchSGAutoFire then
                        cond = 2
                    end
                    if cond == 1 and not isFiring then
                        return
                    end
                    prioMode = _G.XthrlenState.CustomTextData.AimTouchSGPrio or 1
                    boneIdx = _G.XthrlenState.CustomTextData.AimTouchSGBone or 2
                    speedVal = _G.XthrlenState.CustomTextData.AimTouchSGSpeed or 80
                    fovVal = _G.XthrlenState.CustomTextData.AimTouchSGFOV or 40
                    maxDistMeters = _G.XthrlenState.CustomTextData.AimTouchSGDist or 30
                    useVisCheck = _G.XthrlenConfig.AimTouchSGVisCheck
                    igKnock = _G.XthrlenConfig.AimTouchSGIgKnock
                    igBot = _G.XthrlenConfig.AimTouchSGIgBot
                elseif isADS then
                    if isSniper and _G.XthrlenConfig.AimTouchScopeSniper then
                        cond = _G.XthrlenState.CustomTextData.AimTouchSniperCond or 2
                        if cond == 1 and not isFiring then
                            return
                        end
                        prioMode = _G.XthrlenState.CustomTextData.AimTouchSniperPrio or 1
                        boneIdx = _G.XthrlenState.CustomTextData.AimTouchSniperBone or 1
                        speedVal = _G.XthrlenState.CustomTextData.AimTouchSniperSpeed or 30
                        fovVal = _G.XthrlenState.CustomTextData.AimTouchSniperFOV or 20
                        maxDistMeters = _G.XthrlenState.CustomTextData.AimTouchSniperDist or 400
                        useVisCheck = _G.XthrlenConfig.AimTouchSniperVisCheck
                        igKnock = _G.XthrlenConfig.AimTouchSniperIgKnock
                        igBot = _G.XthrlenConfig.AimTouchSniperIgBot
                        predVal = _G.XthrlenState.CustomTextData.AimTouchSniperPred or 0
                    elseif _G.XthrlenConfig.AimTouchScopeAll then
                        cond = _G.XthrlenState.CustomTextData.AimTouchScopeCond or 1
                        if cond == 1 and not isFiring then
                            return
                        end
                        prioMode = _G.XthrlenState.CustomTextData.AimTouchScopePrio or 1
                        boneIdx = 1
                        speedVal = _G.XthrlenState.CustomTextData.AimTouchScopeSpeed or 100
                        fovVal = _G.XthrlenState.CustomTextData.AimTouchScopeFOV or 30
                        maxDistMeters = _G.XthrlenState.CustomTextData.AimTouchScopeDist or 100
                        useVisCheck = _G.XthrlenConfig.AimTouchScopeVisCheck
                        igKnock = _G.XthrlenConfig.AimTouchScopeIgKnock
                        igBot = _G.XthrlenConfig.AimTouchScopeIgBot
                        predVal = _G.XthrlenState.CustomTextData.AimTouchScopePred or 0
                    else
                        return
                    end
                else
                    if not _G.XthrlenConfig.AimTouchHipfire then
                        return
                    end
                    cond = _G.XthrlenState.CustomTextData.AimTouchHipCond or 1
                    if cond == 1 and not isFiring then
                        return
                    end
                    prioMode = _G.XthrlenState.CustomTextData.AimTouchHipPrio or 1
                    boneIdx = 1
                    speedVal = _G.XthrlenState.CustomTextData.AimTouchHipSpeed or 100
                    fovVal = _G.XthrlenState.CustomTextData.AimTouchHipFOV or 30
                    maxDistMeters = _G.XthrlenState.CustomTextData.AimTouchHipDist or 100
                    useVisCheck = _G.XthrlenConfig.AimTouchHipVisCheck
                    igKnock = _G.XthrlenConfig.AimTouchHipIgKnock
                    igBot = _G.XthrlenConfig.AimTouchHipIgBot
                end

                local currentMaxDist = maxDistMeters * 100
                local enemies = _G.GetEnemyTargetsFromActors(currentMaxDist)
                if not enemies or #enemies == 0 then
                    return
                end

                local FVector2D = AimV2
                local UGameplayStatics = AimGameplayStatics
                local KismetMathLibrary = AimMath
                if not FVector2D or not UGameplayStatics or not KismetMathLibrary then
                    return
                end

                local camManager = UGameplayStatics.GetPlayerCameraManager(pc, 0)
                if not slua.isValid(camManager) then
                    return
                end

                local camLoc = camManager:GetCameraLocation()
                if not camLoc then
                    return
                end

                local ui_util = AimUI
                if not ui_util then
                    return
                end

                local viewportSize = ui_util.GetViewportSize()
                if not viewportSize then
                    return
                end

                local centerX = viewportSize.X * 0.5
                local centerY = viewportSize.Y * 0.5
                local dpiScale = 1
                pcall(function()
                    local v = AimLayout.GetViewportScale(pc)
                    if tonumber(v) and v > 0 then
                        dpiScale = v
                    end
                end)
                local FOV_RADIUS = _G.LunarFeatures.AimRadiusUI() * dpiScale

                local bestTarget = nil
                local bestScore = 99999999

                local selected = _G.LunarFeatures.Settings.AimTarget
                boneIdx = selected == 2 and 2 or (selected == 3 and 5 or 1)
                local selBoneName = selected == 2 and "spine_03" or (selected == 3 and "calf_l" or "head")

                for i, target in ipairs(enemies) do
                    repeat
                        if not slua.isValid(target) then
                            break
                        end

                        pcall(function()
                            if slua.isValid(target.Mesh) then
                                target.Mesh.MeshComponentUpdateFlag = 0
                            end
                        end)

                        if igKnock and target.HealthStatus == 1 then
                            break
                        end

                        if igBot then
                            local tIsBot = false
                            if target.bIsAI == true or target.IsAI == true then
                                tIsBot = true
                            end
                            local pState = target.PlayerState
                            if slua.isValid(pState) and (pState.bIsABot or pState.bIsBot) then
                                tIsBot = true
                            end
                            if tIsBot then
                                break
                            end
                        end

                        if useVisCheck then
                            local curTime = _G.LunarFeatures.Now()
                            local tId = type(target.GetUniqueID) == "function" and target:GetUniqueID()
                                or tostring(target)
                            _G.AimTouchVisCache = _G.AimTouchVisCache or {}
                            if
                                not _G.AimTouchVisCache[tId]
                                or curTime < _G.AimTouchVisCache[tId].time
                                or (curTime - _G.AimTouchVisCache[tId].time) > 0.2
                            then
                                local isHidden = true
                                pcall(function()
                                    if pc:LineOfSightTo(target) then
                                        isHidden = false
                                    end
                                end)
                                _G.AimTouchVisCache[tId] = { hidden = isHidden, time = curTime }
                            end
                            if _G.AimTouchVisCache[tId].hidden then
                                break
                            end
                        end

                        local tPos = target.GetBonePos and target:GetBonePos(selBoneName, { X = 0, Y = 0, Z = 0 })
                        if not tPos or (tPos.X == 0 and tPos.Y == 0 and tPos.Z == 0) then
                            if type(target.GetSocketLocation) == "function" then
                                tPos = target:GetSocketLocation(selBoneName)
                            end
                        end
                        if not tPos or (tPos.X == 0 and tPos.Y == 0 and tPos.Z == 0) then
                            if type(target.K2_GetActorLocation) == "function" then
                                tPos = target:K2_GetActorLocation()
                                if tPos then
                                    if boneIdx == 1 then
                                        tPos.Z = tPos.Z + 70
                                    elseif boneIdx == 2 then
                                        tPos.Z = tPos.Z + 40
                                    elseif boneIdx == 3 then
                                        tPos.Z = tPos.Z + 20
                                    elseif boneIdx == 5 then
                                        tPos.Z = tPos.Z - 60
                                    end
                                end
                            end
                        end
                        if not tPos or (tPos.X == 0 and tPos.Y == 0 and tPos.Z == 0) then
                            break
                        end

                        local screen = FVector2D()
                        local success, outScreen = pc:ProjectWorldLocationToScreen(tPos, screen, false)
                        if outScreen then
                            screen = outScreen
                        end
                        if not success or screen.X <= 0 or screen.Y <= 0 then
                            break
                        end

                        local dx = screen.X - centerX
                        local dy = screen.Y - centerY
                        local distScreen = math.sqrt(dx * dx + dy * dy)

                        if distScreen > FOV_RADIUS then
                            break
                        end

                        local currentScore = distScreen
                        if prioMode == 2 then
                            currentScore = player:GetDistanceTo(target)
                        elseif prioMode == 3 then
                            currentScore = target.Health or 100
                        elseif prioMode == 4 then
                            local hp = target.Health or 100
                            local maxhp = target.HealthMax or 100
                            if maxhp <= 0 then
                                maxhp = 100
                            end
                            currentScore = hp / maxhp
                        end

                        if currentScore < bestScore then
                            bestScore = currentScore
                            bestTarget = target
                        end

                    until true
                end

                local cache = _G.AimTouchVisCache
                local clock = _G.LunarFeatures.Now()
                if cache and (not _G.LunarFeatures.AimPruneDue or clock >= _G.LunarFeatures.AimPruneDue) then
                    for key, entry in pairs(cache) do
                        if clock < entry.time or clock - entry.time > 1 then
                            cache[key] = nil
                        end
                    end
                    _G.LunarFeatures.AimPruneDue = clock + 0.5
                end
                if not slua.isValid(bestTarget) then
                    return
                end

                local finalBonePos = bestTarget.GetBonePos and bestTarget:GetBonePos(
                    selBoneName,
                    { X = 0, Y = 0, Z = 0 }
                )
                if not finalBonePos or (finalBonePos.X == 0 and finalBonePos.Y == 0 and finalBonePos.Z == 0) then
                    if type(bestTarget.GetSocketLocation) == "function" then
                        finalBonePos = bestTarget:GetSocketLocation(selBoneName)
                    end
                end
                if not finalBonePos or (finalBonePos.X == 0 and finalBonePos.Y == 0 and finalBonePos.Z == 0) then
                    if type(bestTarget.K2_GetActorLocation) == "function" then
                        finalBonePos = bestTarget:K2_GetActorLocation()
                        if finalBonePos then
                            if boneIdx == 1 then
                                finalBonePos.Z = finalBonePos.Z + 70
                            elseif boneIdx == 2 then
                                finalBonePos.Z = finalBonePos.Z + 40
                            elseif boneIdx == 3 then
                                finalBonePos.Z = finalBonePos.Z + 20
                            elseif boneIdx == 5 then
                                finalBonePos.Z = finalBonePos.Z - 60
                            end
                        end
                    end
                end
                if not finalBonePos or (finalBonePos.X == 0 and finalBonePos.Y == 0 and finalBonePos.Z == 0) then
                    return
                end

                local tVelocity = nil
                pcall(function()
                    if type(bestTarget.GetVelocity) == "function" then
                        tVelocity = bestTarget:GetVelocity()
                    end
                end)

                if not isMortar and predVal > 0 then
                    pcall(function()
                        if tVelocity and (tVelocity.X ~= 0 or tVelocity.Y ~= 0) then
                            local distToEnemy = player:GetDistanceTo(bestTarget) / 100.0
                            local ToF = (distToEnemy / 800.0) * (predVal / 50.0)
                            finalBonePos.X = finalBonePos.X + (tVelocity.X * ToF)
                            finalBonePos.Y = finalBonePos.Y + (tVelocity.Y * ToF)
                        end
                    end)
                end

                if isADS and isFiring then
                    local dist = player:GetDistanceTo(bestTarget) / 100.0
                    finalBonePos.Z = finalBonePos.Z - (dist * 1.1)
                end

                local rot = KismetMathLibrary.FindLookAtRotation(camLoc, finalBonePos)
                if not rot then
                    return
                end

                local currentRot = pc:GetControlRotation()
                if not currentRot then
                    return
                end

                if not isADS then
                    _G.XthrlenState.offPitch = 0
                    _G.XthrlenState.offYaw = 0
                end

                local dPitch = rot.Pitch - currentRot.Pitch
                local dYaw = rot.Yaw - currentRot.Yaw

                if isADS then
                    local camRot = nil
                    if type(camManager.GetCameraRotation) == "function" then
                        camRot = camManager:GetCameraRotation()
                    end
                    if camRot then
                        dYaw = dYaw - (camRot.Yaw - currentRot.Yaw)
                        dPitch = dPitch - (camRot.Pitch - currentRot.Pitch)
                    end
                end

                if dPitch ~= dPitch or dYaw ~= dYaw or math.abs(dPitch) == math.huge or math.abs(dYaw) == math.huge then
                    return
                end
                dPitch = (dPitch + 180) % 360 - 180
                dYaw = (dYaw + 180) % 360 - 180

                local now = _G.LunarFeatures.Now()
                local previous = _G.LunarFeatures.AimLastClock
                local dt = previous and math.max(0.001, math.min(0.05, now - previous)) or 0.011
                _G.LunarFeatures.AimLastClock = now
                local normalized = (_G.LunarFeatures.Clamp(speedVal, 120, 150, 120) - 120) / 30.0
                local strength = 0.02 + 0.48 * normalized * normalized
                local alpha = math.min(0.5, 1.0 - (1.0 - strength) ^ (dt / 0.011))
                local maxTurnRate = 10.0 + 35.0 * normalized

                _G.XthrlenState.offPitch = 0
                _G.XthrlenState.offYaw = 0
                local apply = { Pitch = currentRot.Pitch + dPitch, Yaw = currentRot.Yaw + dYaw, Roll = 0 }

                local pitchDelta = (apply.Pitch - currentRot.Pitch + 180) % 360 - 180
                local yawDelta = (apply.Yaw - currentRot.Yaw + 180) % 360 - 180
                local pitchStep, yawStep = pitchDelta * alpha, yawDelta * alpha
                local stepLength = math.sqrt(pitchStep * pitchStep + yawStep * yawStep)
                local stepLimit = maxTurnRate * dt
                if stepLength > stepLimit then
                    local scale = stepLimit / stepLength
                    pitchStep = pitchStep * scale
                    yawStep = yawStep * scale
                end
                local out = { Pitch = currentRot.Pitch + pitchStep, Yaw = currentRot.Yaw + yawStep, Roll = 0 }

                out = clampAngles(out)
                pc:SetControlRotation(out, "AimTouch")
            end)
            if not ok then
                _G.LunarFeatures.Error("Aim", err)
            end
        end

        _G.LunarFeatures.Aim = { Tick = _G.AimTouch }
    end

    -- ============================================================================
    -- // WALL EFFECT / MESH LIFECYCLE //
    -- ============================================================================
    do
        local F = _G.LunarFeatures
        local valid = g_adityaorg_ESPValid
        local classes = {}
        for _, name in ipairs({ "SkeletalMeshComponent", "StaticMeshComponent" }) do
            local ok, value = pcall(import, name)
            if ok and value then
                classes[#classes + 1] = value
            end
        end
        local W = {
            Meshes = {},
            Pawns = {},
            LastTick = -999,
            LastCleanup = -999,
            CleanupInterval = MeowPerformance.WallCleanupSeconds,
            ConsoleWorld = nil,
            Applied = 0,
            ColorRevision = 0,
        }
        F.Wall = W
        local properties = {
            { "SetDrawDyeing", "bDrawDyeing" },
            { "SetDrawHighlight", "bDrawHighlight" },
            { "SetDrawIdeaOutline", "bDrawIdeaOutline" },
            { "SetRenderCustomDepth", "bRenderCustomDepth" },
        }
        -- calls
        local function calls(vis, occ)
            return {
                { "SetDrawDyeing", true },
                { "SetDrawDyeingMode", 1 },
                { "SetVisibleDyeingColor", vis },
                { "SetOccludedDyeingColor", occ },
                { "SetDyeingColorFadeDistance", 99999.0 },
                { "SetDyeingColorMinMaxDistance", 0.0, 99999.0 },
                { "SetDrawHighlight", true },
                { "OverrideHighlightColor", true, vis },
                { "SetHighlightCanBeOccluded", false },
                { "SetDrawIdeaOutline", true },
                { "SetIdeaOutlineNew", true },
                { "SetIdeaOutlineOcclusionHighlight", true },
                { "OverrideIdeaOutlineColor", true, vis },
                { "SetIdeaOutlineOcclusionColor", occ },
                { "OverrideIdeaOutlineThickness", true, 20.0 },
                { "SetIdeaOverrideOutlineAndOcclusion", true },
                { "SetRenderCustomDepth", true },
                { "SetCustomDepthStencilValue", 255 },
            }
        end

        local palette =
            { { 100, 0, 35 }, { 100, 100, 100 }, { 0, 100, 100 }, { 0, 100, 0 }, { 100, 100, 0 }, { 100, 1, 0 }, {
                100,
                0,
                0,
            } }
        W.Palette = palette
        local colorCalls
        W.UpdateColors = function()
            local a = palette[F.Settings.WallVisible] or palette[1]
            local b = palette[F.Settings.WallOccluded] or palette[2]
            local vis = g_adityaorg_ESPColor(a[1], a[2], a[3], 100)
            local occ = g_adityaorg_ESPColor(b[1], b[2], b[3], 100)
            colorCalls = calls(vis, occ)
            W.ColorRevision = W.ColorRevision + 1
            W.LastTick = -999
        end
        W.UpdateColors()
        -- invoke
        local function invoke(mesh, call)
            local method = mesh[call[1]]
            if not method then
                return
            end
            if call[3] ~= nil then
                method(mesh, call[2], call[3])
            else
                method(mesh, call[2])
            end
        end
        -- restore
        local function restore(mesh, state)
            if not valid(mesh) then
                return
            end
            for _, pair in ipairs(properties) do
                pcall(function()
                    if mesh[pair[1]] then
                        mesh[pair[1]](mesh, state[pair[2]] == true)
                    end
                end)
            end
        end
        W.Stop = function()
            for mesh, state in pairs(W.Meshes) do
                restore(mesh, state)
            end
            W.Meshes = {}
            W.Pawns = {}
            W.LastTick = -999
            W.LastCleanup = -999
        end
        -- relevant
        local function relevant(pawn, myLocation, maxRange, pc)
            local entry = ESPShared.GetFrameRecord(pawn)
            return entry.Alive
                and ESPShared.InRange(entry, myLocation, maxRange)
                and pc
                and ESPShared.ProbeActor(pc, pawn).OnScreen
        end
        W.Cleanup = function(myLocation, maxRange, pc)
            for pawn, meshes in pairs(W.Pawns) do
                if not relevant(pawn, myLocation, maxRange, pc) then
                    for mesh in pairs(meshes) do
                        local state = W.Meshes[mesh]
                        if state then
                            restore(mesh, state)
                            W.Meshes[mesh] = nil
                        end
                    end
                    W.Pawns[pawn] = nil
                end
            end
        end
        -- apply
        local function apply(mesh, pawn, seen)
            if not valid(mesh) or seen[mesh] then
                return
            end
            seen[mesh] = true
            local original = W.Meshes[mesh]
            if not original then
                original = {}
                for _, pair in ipairs(properties) do
                    pcall(function()
                        original[pair[2]] = mesh[pair[2]] == true
                    end)
                end
                W.Meshes[mesh] = original
            end
            if original.Pawn and original.Pawn ~= pawn then
                local old = W.Pawns[original.Pawn]
                if old then
                    old[mesh] = nil
                    if next(old) == nil then
                        W.Pawns[original.Pawn] = nil
                    end
                end
            end
            if original.Pawn ~= pawn then
                original.AppliedAt = nil
            end
            original.Pawn = pawn
            local owned = W.Pawns[pawn]
            if not owned then
                owned = {}
                W.Pawns[pawn] = owned
            end
            owned[mesh] = true

            local now = W.ApplyNow or F.Now()
            local dirty = original.Revision ~= W.ColorRevision
                or not original.AppliedAt
                or now < original.AppliedAt
                or now - original.AppliedAt >= MeowPerformance.WallRefreshSeconds
            -- Failed native calls also wait for the refresh window before retrying.
            -- Otherwise one incompatible call repeats every successful setter too.
            if original.FailedAt and now >= original.FailedAt
                and now - original.FailedAt < MeowPerformance.WallRefreshSeconds
                and original.AttemptRevision == W.ColorRevision then
                return
            end
            if not dirty then
                for _, pair in ipairs(properties) do
                    local ok, enabled = pcall(function()
                        return mesh[pair[2]]
                    end)
                    if ok and enabled == false then
                        dirty = true
                        break
                    end
                end
            end
            if not dirty then
                return
            end
            local applied = true
            for _, call in ipairs(colorCalls) do
                local ok, err = pcall(invoke, mesh, call)
                if not ok then
                    applied = false
                    F.Error("Wall." .. call[1], err)
                end
            end
            if applied then
                original.Revision, original.AppliedAt = W.ColorRevision, now
                original.FailedAt = nil
            else
                original.FailedAt, original.AttemptRevision = now, W.ColorRevision
            end
            W.Applied = W.Applied + 1
            MeowPerf.Count("WallMeshWrites")
        end
        W.Tick = function(now, me, pc)
            if not F.Settings.WallEnabled then
                return
            end
            now = now or F.Now()
            me = me or g_adityaorg_ESPGetLocalCharacter()
            pc = pc or g_adityaorg_ESPGetController()
            if not valid(me) or not valid(pc) then
                W.Stop()
                return
            end
            local maxRange = tonumber(_G.g_adityaorg_MasterShotESP.MaxRangeMeters) or 450.0
            if maxRange ~= maxRange or maxRange <= 0 or maxRange == math.huge then
                maxRange = 450.0
            end
            local myLocation = ESPShared.GetFrameRecord(me).Location
            if now < W.LastCleanup or now - W.LastCleanup >= W.CleanupInterval - 0.000001 then
                W.Cleanup(myLocation, maxRange, pc)
                W.LastCleanup = now
            end
            if now >= W.LastTick and now - W.LastTick < MeowPerformance.WallApplySeconds - 0.000001 then
                return
            end
            W.LastTick = now
            W.ApplyNow = now
            local world = g_adityaorg_ESPWorld()
            if world ~= W.ConsoleWorld then
                local ok = pcall(function()
                    if not world or not UKismetSystemLibrary.ExecuteConsoleCommand then
                        return
                    end
                    for _, command in ipairs({
                        "r.EnableDrawDyeingColor 1",
                        "r.CustomDepth 3",
                        "r.IdeaOutline.Enable 1",
                        "r.Highlight.Enable 1",
                    }) do
                        UKismetSystemLibrary.ExecuteConsoleCommand(world, command)
                    end
                end)
                if ok and world then
                    W.ConsoleWorld = world
                end
            end
            local pawns = ESPShared.GetFramePawns()
            if not pawns then
                return
            end
            local seen = {}
            local myTeam = me.TeamID or 0
            for _, pawn in pairs(pawns) do
                if
                    valid(pawn)
                    and pawn ~= me
                    and pawn.TeamID ~= myTeam
                    and relevant(pawn, myLocation, maxRange, pc)
                then
                    pcall(function()
                        apply(pawn.Mesh, pawn, seen)
                    end)
                    local avatar = nil
                    pcall(function()
                        avatar = pawn.CharacterAvatarComp2_BP
                        if not avatar and pawn.getAvatarComponent2 then
                            avatar = pawn:getAvatarComponent2()
                        end
                    end)
                    if avatar and avatar.GetMeshCompBySlot then
                        for slot = 0, 7 do
                            pcall(function()
                                apply(avatar:GetMeshCompBySlot(slot), pawn, seen)
                            end)
                        end
                    end
                    for _, class in ipairs(classes) do
                        pcall(function()
                            if not pawn.GetComponentsByClass then
                                return
                            end
                            local components = pawn:GetComponentsByClass(class)
                            if components then
                                for i = 0, components:Num() - 1 do
                                    apply(components:Get(i), pawn, seen)
                                end
                            end
                        end)
                    end
                    pcall(function()
                        local weapon = pawn.GetCurrentWeapon and pawn:GetCurrentWeapon()
                        if valid(weapon) then
                            apply(weapon.Mesh, pawn, seen)
                        end
                    end)
                end
            end
            for mesh, state in pairs(W.Meshes) do
                if not seen[mesh] then
                    restore(mesh, state)
                    W.Meshes[mesh] = nil
                    local owned = W.Pawns[state.Pawn]
                    if owned then
                        owned[mesh] = nil
                        if next(owned) == nil then
                            W.Pawns[state.Pawn] = nil
                        end
                    end
                end
            end
        end
        _G.StartWallhack = function()
            F.SetWall(true)
        end
        _G.StopWallhack = function()
            F.SetWall(false)
        end
    end

    -- ============================================================================
    -- // LEGACY V1 COMPATIBILITY CONTRACT //
    -- ============================================================================
    do
        _G.g_Botmater_ESPOptions = _G.g_Botmater_ESPOptions or {}
        _G.g_Botmater_MasterShotESP = _G.g_Botmater_MasterShotESP or { Enabled = false }

        local F = _G.LunarFeatures
        F.V1 = {
            State = {},
            Tick = function() end,
            Reset = function() end,
            Refresh = function() end,
            Cleanup = { Pump = function() end },
            Counter = {},
            Info = {},
            Draw = {},
            Flags = {},
        }
    end

    -- ============================================================================
    -- // MORTAR CONTROLLER //
    -- ============================================================================
    do
        local F = _G.LunarFeatures
        local MathLib, Layout, HealthStates, PawnStates
        pcall(function()
            MathLib = import("KismetMathLibrary")
        end)
        pcall(function()
            Layout = import("WidgetLayoutLibrary")
        end)
        pcall(function()
            HealthStates = import("ECharacterHealthStatus")
        end)
        pcall(function()
            PawnStates = import("EPawnState")
        end)
        -- finite
        local function finite(v)
            return type(v) == "number" and v == v and v > -math.huge and v < math.huge
        end
        -- get
        local function get(obj, key)
            if not obj then
                return nil
            end
            local ok, v = pcall(function()
                return obj[key]
            end)
            if ok then
                return v
            end
        end
        -- call
        local function call(obj, key, ...)
            local method = get(obj, key)
            if type(method) ~= "function" then
                return nil
            end
            local ok, v = pcall(method, obj, ...)
            if ok then
                return v
            end
        end
        -- valid
        local function valid(obj)
            return obj and g_adityaorg_ESPValid(obj)
        end
        -- pos
        local function pos(v)
            if v and finite(v.X) and finite(v.Y) and finite(v.Z) then
                return { X = v.X, Y = v.Y, Z = v.Z }
            end
        end
        -- nativeVector
        local function nativeVector(v)
            return g_adityaorg_ESPV3(v.X, v.Y, v.Z)
        end
        -- team
        local function team(actor)
            local id = call(actor, "GetTeamID") or get(actor, "TeamID")
            if id == nil then
                local state = call(actor, "GetPlayerStateSafety")
                id = call(state, "GetTeamID") or get(state, "TeamID")
            end
            return id
        end
        -- dead
        local function dead(actor)
            if not valid(actor) then
                return true
            end
            local hp = call(actor, "GetHealth") or get(actor, "Health") or get(actor, "HP")
            if finite(hp) and hp <= 0 then
                return true
            end
            if get(actor, "bIsDead") == true or get(actor, "bDead") == true or get(actor, "bIsDeadFlag") == true then
                return true
            end
            if
                HealthStates
                and HealthStates.FinishedLastBreath ~= nil
                and get(actor, "HealthStatus") == HealthStates.FinishedLastBreath
            then
                return true
            end
            if PawnStates and PawnStates.Dead ~= nil and call(actor, "HasPawnState", PawnStates.Dead) == true then
                return true
            end
            return false
        end
        -- weapon
        local function weapon(player)
            local w = call(player, "GetCurrentWeapon") or get(player, "CurrentWeapon")
            if not valid(w) then
                local wm = get(player, "WeaponManagerComponent")
                w = get(wm, "CurrentWeaponReplicated") or get(wm, "CurrentWeapon")
            end
            return valid(w) and w or nil
        end
        -- kind
        local function kind(w)
            local name = call(w, "GetWeaponName")
            if type(name) ~= "string" or not name:find("%S") then
                return "unknown"
            end
            name = name:lower()
            if name:find("mortar", 1, true) or name:find("cối", 1, true) or name:find("cỐi", 1, true) then
                return "mortar"
            end
            return "other"
        end
        -- context
        local function context()
            local pc = g_adityaorg_ESPGetController()
            local player = g_adityaorg_ESPGetLocalCharacter()
            if valid(pc) and not dead(player) then
                return g_adityaorg_ESPWorld(), pc, player, weapon(player)
            end
        end
        -- pelvis
        local function pelvis(actor)
            local p = pos(call(actor, "GetBonePos", "pelvis", { X = 0, Y = 0, Z = 0 }))
            if not p or (p.X == 0 and p.Y == 0 and p.Z == 0) then
                p = pos(call(actor, "GetSocketLocation", "pelvis"))
            end
            if not p or (p.X == 0 and p.Y == 0 and p.Z == 0) then
                p = pos(call(actor, "K2_GetActorLocation"))
            end
            return p
        end
        -- allPlayers
        local function allPlayers()
            local list
            pcall(function()
                if GameplayData.GetAllPlayerCharacters then
                    list = GameplayData.GetAllPlayerCharacters()
                end
            end)
            return type(list) == "table" and list or {}
        end
        -- viewport
        local function viewport(pc)
            local w, h = g_adityaorg_ESPViewport(pc)
            if not finite(w) or w <= 0 or not finite(h) or h <= 0 then
                return 1920, 1080
            end
            return w, h
        end
        -- project
        local function project(pc, p)
            local screen = FVector2D(0, 0)
            local ok, yes = pcall(function()
                return pc:ProjectWorldLocationToScreen(nativeVector(p), screen, false)
            end)
            if ok and (yes == true or yes == 1) and finite(screen.X) and finite(screen.Y) then
                return screen.X, screen.Y
            end
        end
        -- camera
        local function camera(pc, player, fallback)
            local cm = call(pc, "GetPlayerCameraManager")
            if not valid(cm) then
                pcall(function()
                    cm = GameplayStaticsESP.GetPlayerCameraManager(pc, 0)
                end)
            end
            return pos(call(cm, "GetCameraLocation")) or fallback or pos(call(player, "K2_GetActorLocation"))
        end
        -- rotation
        local function rotation(pc, target, source)
            if not target or not finite(target.Pitch) or not finite(target.Yaw) or not finite(target.Roll) then
                return false
            end
            local current = call(pc, "GetControlRotation")
            if
                current
                and finite(current.Pitch)
                and finite(current.Yaw)
                and finite(current.Roll or 0)
                and math.abs((target.Pitch - current.Pitch + 180) % 360 - 180) < 0.00001
                and math.abs((target.Yaw - current.Yaw + 180) % 360 - 180) < 0.00001
                and math.abs(target.Roll - (current.Roll or 0)) < 0.00001
            then
                return true
            end
            local ok, accepted = pcall(function()
                return pc:SetControlRotation(target, source)
            end)
            if not ok then
                F.Error(source, accepted)
            end
            return ok and accepted ~= false
        end

        local M =
            { Target = nil, Candidates = {}, ScanDue = 0, Due = 0, LastTime = nil, Status = "inactive", ActivePlaced = false }
        F.Mortar = M
        -- Stop
        function M.Stop()
            M.Target = nil
            M.Candidates = {}
            M.ScanDue = 0
            M.Due = 0
            M.LastTime = nil
            M.World = nil
            M.PC = nil
            M.Player = nil
            M.Weapon = nil
            M.ActivePlaced = false
            M.Status = "inactive"
        end
        -- distance
        local function distance(player, target)
            local d = call(player, "GetDistanceTo", target)
            if finite(d) and d >= 0 then
                return d
            end
            local a, b = pos(call(player, "K2_GetActorLocation")), pos(call(target, "K2_GetActorLocation"))
            if a and b then
                local dx, dy, dz = a.X - b.X, a.Y - b.Y, a.Z - b.Z
                d = math.sqrt(dx * dx + dy * dy + dz * dz)
                if finite(d) then
                    return d
                end
            end
        end
        -- enemy
        local function enemy(player, target)
            if target == player or dead(target) then
                return false
            end
            local mine, theirs = team(player), team(target)
            if mine ~= nil and theirs ~= nil and tostring(mine) == tostring(theirs) then
                return false
            end
            local d = distance(player, target)
            return finite(d) and d <= 200000
        end
        -- trajectory
        local function trajectory(launch, V, G, target)
            if not pos(launch) or not pos(target) or not finite(V) or V <= 0 or not finite(G) or G <= 0 then
                return false, 45, 0, 0
            end
            local dx = math.max(500, math.sqrt((target.X - launch.X) ^ 2 + (target.Y - launch.Y) ^ 2) - 80)
            local dy = target.Z - launch.Z
            local minVSq = G * (dy + math.sqrt(dx * dx + dy * dy))
            if not finite(dx) or not finite(minVSq) then
                return false, 45, 0, 0
            end
            if V * V < minVSq then
                V = math.sqrt(math.max(0, minVSq)) + 100
            end
            local v2 = V * V
            local root = v2 * v2 - G * (G * dx * dx + 2 * dy * v2)
            if not finite(root) or root < 0 then
                return false, 45, 0, dx
            end
            local rad = math.atan((v2 + math.sqrt(root)) / (G * dx))
            local deg, tof = math.deg(rad), dx / (V * math.cos(rad))
            if finite(deg) and finite(tof) and tof > 0 and deg >= 35 and deg <= 89.5 then
                return true, deg, tof, dx
            end
            return false, 45, 0, dx
        end
        -- solve
        local function solve(launch, target)
            local okN, aN, tN, dN = trajectory(launch, 9070, 2744, target)
            local okF, aF, tF, dF = trajectory(launch, 12520, 3920, target)
            local okU, aU, tU, dU = trajectory(launch, 16800, 4410, target)
            if okN and dN <= 25000 then
                return true, aN, tN, dN
            end
            if okF and dF <= 40000 then
                return true, aF, tF, dF
            end
            if okU then
                return true, aU, tU, dU
            end
            if okN then
                return true, aN, tN, dN
            end
            return false, 45, 0, dN
        end
        M.SolveTrajectory = solve
        -- predict
        local function predict(target, base, launch)
            local velocity = call(target, "GetVelocity")
            if
                not velocity
                or not finite(velocity.X)
                or not finite(velocity.Y)
                or math.abs(velocity.X) + math.abs(velocity.Y) < 0.01
            then
                return base
            end
            local predicted = { X = base.X, Y = base.Y, Z = base.Z }
            local fallback
            for _ = 1, 2 do
                local ok, a, tof, d = solve(launch, predicted)
                if not ok then
                    break
                end
                fallback = { ok, a, tof, d }
                if tof <= 0 or tof > 15 then
                    break
                end
                predicted.X = base.X + velocity.X * tof
                predicted.Y = base.Y + velocity.Y * tof
                if not pos(predicted) then
                    return base
                end
            end
            return predicted, fallback
        end
        -- NextInterval
        function M.NextInterval(now)
            if not F.Settings.MortarEnabled then
                return 0.5
            end
            return math.max(0.001, M.Due - (finite(now) and now or F.Now()))
        end
        -- Tick
        function M.Tick(now)
            now = finite(now) and now or F.Now()
            if not F.Settings.MortarEnabled then
                if M.Player then
                    M.Stop()
                end
                return false
            end
            local world, pc, player, w = context()
            if not world or not w or kind(w) ~= "mortar" or get(w, "MortarState") ~= 2 then
                M.Stop()
                M.Status = "not_placed_mortar"
                M.Due = now + 0.5
                return false
            end
            if M.World ~= world or M.PC ~= pc or M.Player ~= player or M.Weapon ~= w then
                M.Stop()
                M.World = world
                M.PC = pc
                M.Player = player
                M.Weapon = w
            end
            if now < M.Due - 0.000001 and (not M.LastTime or now >= M.LastTime) then
                return false
            end
            M.LastTime = now
            M.Due = now + 0.5
            M.ActivePlaced = true
            M.Status = "targeting"
            if not enemy(player, M.Target) then
                M.Target = nil
                if now >= M.ScanDue then
                    M.Candidates = allPlayers()
                    M.ScanDue = now + 0.25
                end
                local width, height = viewport(pc)
                local best, score = nil, math.huge
                for _, target in pairs(M.Candidates) do
                    if enemy(player, target) then
                        local p = pelvis(target)
                        if p then
                            local x, y = project(pc, p)
                            if x and x > 0 and y > 0 then
                                local dx, dy = x - width / 2, y - height / 2
                                local d = dx * dx + dy * dy
                                if finite(d) and d < score and d <= (3.6 * width / 2) ^ 2 then
                                    best, score = target, d
                                end
                            end
                        end
                    end
                end
                M.Target = best
            end
            local target = M.Target
            if not target then
                M.Status = "no_target"
                return false
            end
            local base, launch = pelvis(target), pos(call(player, "K2_GetActorLocation"))
            if not base or not launch then
                M.Status = "position_unavailable"
                return false
            end
            launch.Z = launch.Z + 50
            local predicted, fallback = predict(target, base, launch)
            local ok, angle, tof = solve(launch, predicted)
            if not ok and fallback then
                ok, angle, tof = fallback[1], fallback[2], fallback[3]
            end
            if not ok or not finite(tof) or not finite(angle) then
                M.Status = "unreachable"
                return false
            end
            if not MathLib or not MathLib.FindLookAtRotation then
                M.Status = "math_unavailable"
                return false
            end
            local desired =
                MathLib.FindLookAtRotation(nativeVector(camera(pc, player, launch)), nativeVector(predicted))
            local current = call(pc, "GetControlRotation")
            if
                not desired
                or not current
                or not finite(desired.Yaw)
                or not finite(current.Pitch)
                or not finite(current.Yaw)
            then
                return false
            end
            local pitch = ((angle - 45) / 43) * 90 - 60
            local dp, dy = (pitch - current.Pitch + 180) % 360 - 180, (desired.Yaw - current.Yaw + 180) % 360 - 180
            local final = { Pitch = current.Pitch + dp, Yaw = current.Yaw + dy, Roll = 0 }
            local world2, pc2, player2, w2 = context()
            if
                not F.Settings.MortarEnabled
                or world2 ~= world
                or pc2 ~= pc
                or player2 ~= player
                or w2 ~= w
                or get(w, "MortarState") ~= 2
                or not enemy(player, target)
            then
                M.Stop()
                return false
            end
            local accepted = rotation(pc, final, "MortarAim")
            M.Status = accepted and "rotation_call_accepted" or "rotation_failed"
            return accepted
        end
    end

    do
        local F = _G.LunarFeatures
        -- InstallNativeLiveSlider
        function F.InstallNativeLiveSlider(class)
            if type(class) ~= "table" then
                return false
            end
            local original = class.OnSliderValueChanged
            if type(original) ~= "function" then
                return false
            end
            local current = class.__LunarLiveRange
            if current and current.Version == 3 and current.Wrapper == original then
                return true
            end
            local record = { Version = 3, Original = original }
            -- capture
            local function capture(...)
                return { n = select("#", ...), ... }
            end
            local unpackValues = table.unpack or unpack
            record.Wrapper = function(self, ...)
                local data = self and self.Data
                local key = data and data.Key
                if key ~= "LunarAimSpeed" and key ~= "LunarAimCircle" then
                    return record.Original(self, ...)
                end
                local runtime = _G.LunarFeatures
                if not runtime or runtime.Token.Stopped then
                    return record.Original(self, ...)
                end
                local max = key == "LunarAimSpeed" and 150 or 240
                if self.Min ~= 120 or self.Max ~= max then
                    pcall(function()
                        self.UIRoot.Slider:SetStepSize(1 / (max - 120))
                    end)
                end
                self.Min = 120
                self.Max = max
                local results = capture(record.Original(self, ...))
                local v = tonumber(self.CurrentValue)
                if v and v == v and v >= 120 and v <= max then
                    local setter = key == "LunarAimSpeed" and runtime.SetAimSpeed or runtime.SetAimCircle
                    local ok, why = pcall(setter, v)
                    if ok then
                        self.LastAppliedValue = v
                    else
                        runtime.Error("Settings.LiveRange", why)
                    end
                end
                return unpackValues(results, 1, results.n)
            end
            class.OnSliderValueChanged = record.Wrapper
            class.__LunarLiveRange = record
            return true
        end
    end

    -- ============================================================================
    -- // FEATURE SCHEDULER / MENU MAINTENANCE //
    -- ============================================================================
    do
        local F = _G.LunarFeatures
        -- checked
        local function checked(fn, area, ...)
            local ok, err = pcall(fn, ...)
            if not ok then
                F.Error(area, err)
            end
        end
        F.V1Due = 0
        F.AimDue = 0
        F.IpadDue = 0
        F.SaveDue = 0
        F.Pump = function(now)
            F.TimerClock = g_adityaorg_ShotESP.TimerClock
            now = now or F.Now()
            if F.V1 and F.V1.Cleanup then
                F.V1.Cleanup.Pump(now)
            end
            local welcome = _G.LunarStandaloneWelcome
            if F.Dirty and now >= F.SaveDue then
                checked(F.Save, "Settings.Save")
                F.SaveDue = now + 0.5
            end
            if not (_G.LunarLoginRuntime and _G.LunarLoginRuntime.Authorized) then
                if not F.AuthLocked then
                    checked(F.V1.Reset, "V1.Lock")
                    checked(F.Wall.Stop, "Wall.Lock")
                    checked(F.Mortar.Stop, "Mortar.Lock")
                    _G.XthrlenState.offPitch = 0
                    _G.XthrlenState.offYaw = 0
                    F.AimLastClock = nil
                    if _G.LunarAimCircleHUD then
                        _G.LunarAimCircleHUD.Destroy()
                    end
                    if welcome then
                        welcome.DestroyUI()
                        welcome.ReadyAt = nil
                        welcome.Due = nil
                    end
                    checked(g_adityaorg_ApplyiPadView, "Ipad.Lock")
                end
                F.AuthLocked = true
                return
            end
            F.AuthLocked = false
            local world = g_adityaorg_ESPWorld()
            local pc = g_adityaorg_ESPGetController()
            local pawn = g_adityaorg_ESPGetLocalCharacter()
            if world ~= F.LastWorld or pc ~= F.LastPC or pawn ~= F.LastPawn then
                if welcome then
                    welcome.ContextChanged(world, pc, pawn, now)
                end
                if F.LastWorld ~= nil and welcome and welcome.WelcomeUI then
                    welcome.DestroyUI()
                end
                if _G.LunarAimCircleHUD then
                    _G.LunarAimCircleHUD.Destroy()
                end
                if _G.LunarAimCircleHUD then
                    _G.LunarAimCircleHUD.Due = now
                end
                checked(F.V1.Reset, "V1.Reset")
                checked(F.Wall.Stop, "Wall.Reset")
                checked(F.Mortar.Stop, "Mortar.Reset")
                F.Wall.ConsoleWorld = nil
                _G.AimTouchVisCache = {}
                _G.XthrlenState.offPitch = 0
                _G.XthrlenState.offYaw = 0
                F.AimLastClock = nil
                F.V1Due = 0
                F.AimDue = 0
                F.IpadDue = 0
                F.LastWorld, F.LastPC, F.LastPawn = world, pc, pawn
            end
            if F.V1.State.Canvas and not g_adityaorg_ESPValid(F.V1.State.Canvas) then
                checked(F.V1.Reset, "V1.CanvasReset")
                F.V1Due = 0
            end
            if welcome and welcome.NeedsUpdate then
                checked(welcome.Update, "Welcome.Update", now, world, pc, pawn)
            end
            if not pc or not pawn then
                if F.Mortar.Player then
                    checked(F.Mortar.Stop, "Mortar.NoPlayer")
                end
                if not F.V1Disabled then
                    checked(F.V1.Reset, "V1.NoPlayer")
                end
                F.V1Disabled = true
                return
            end
            local circle = _G.LunarAimCircleHUD
            if circle and circle.Due and (now >= circle.Due or now < (circle.LastClock or now)) then
                checked(circle.Update, "AimCircle.Update", now)
            end
            local o = _G.g_Botmater_ESPOptions
            local detail = o.Name
                or o.Line
                or o.Box
                or o.Health
                or o.Distance
                or o.Weapon
                or o.Flag
                or o.Visibility
                or o.Alert
            local active = detail or o.EnemyCounter
            if not active then
                if not F.V1Disabled then
                    checked(F.V1.Reset, "V1.Disable")
                end
                F.V1Disabled = true
            elseif now >= F.V1Due - 0.000001 or (F.V1LastClock and now < F.V1LastClock) then
                F.V1Disabled = false
                checked(F.V1.Tick, "V1.Render")
                F.V1LastClock = now
                local interval = detail and (tonumber(_G.g_Botmater_MasterShotESP.UpdateInterval) or 1 / 60) or 0.05
                if interval ~= interval or interval <= 0 or math.abs(interval) == math.huge then
                    interval = 1 / 60
                end
                F.V1Due = now + math.max(0.001, interval)

                local v2 = _G.g_adityaorg_ESPOptions
                local detailedV2 = _G.g_adityaorg_MasterShotESP.Enabled
                    and (v2.Name or v2.Line or v2.Box or v2.Health or v2.Distance or v2.Skeleton)
                local shared = g_adityaorg_ESPRunnerToken.RenderDue
                if
                    detail
                    and detailedV2
                    and shared
                    and shared > now
                    and math.abs(interval - (tonumber(_G.g_adityaorg_MasterShotESP.UpdateInterval) or 1 / 60)) < 0.000001
                then
                    F.V1Due = shared
                end
            end
            if
                F.Settings.MortarEnabled
                and (now >= F.Mortar.Due - 0.000001 or (F.Mortar.LastTime and now < F.Mortar.LastTime))
            then
                checked(F.Mortar.Tick, "Mortar.Tick")
            end

            if F.Settings.AimEnabled then
                if now >= F.AimDue - 0.000001 or (F.AimLastTick and now < F.AimLastTick) then
                    checked(F.Aim.Tick, "Aim.Render")
                    F.AimLastTick = now
                    F.AimDue = now + ((pawn and pawn.bIsWeaponFiring) and 0.011 or 0.05)
                    if not (pawn and pawn.bIsWeaponFiring) then
                        F.AimLastClock = nil
                    end
                end
            end
            if F.Settings.WallEnabled then
                checked(F.Wall.Tick, "Wall.Tick", now, pawn, pc)
            end
            if _G.LexusConfig.IpadView and now >= F.IpadDue then
                checked(g_adityaorg_ApplyiPadView, "Ipad")
                F.IpadDue = now + 0.5
            end
            if F.Dirty and now >= F.SaveDue then
                checked(F.Save, "Settings.Save")
                F.SaveDue = now + 0.5
            end
        end
        F.NextInterval = function(now)
            if not (_G.LunarLoginRuntime and _G.LunarLoginRuntime.Authorized) then
                return 0.50
            end
            if not F.LastPC or not F.LastPawn then
                return 0.50
            end
            local nextDelay = 0.50
            -- due
            local function due(deadline)
                nextDelay = math.min(nextDelay, math.max(0.001, (deadline or now) - now))
            end
            local welcome = _G.LunarStandaloneWelcome
            if welcome and welcome.NeedsUpdate and welcome.Due then
                due(welcome.Due)
            end
            local circle = _G.LunarAimCircleHUD
            if circle and circle.Due then
                due(circle.Due)
            end
            local o = _G.g_Botmater_ESPOptions
            if
                o.Name
                or o.Line
                or o.Box
                or o.Health
                or o.Distance
                or o.Weapon
                or o.Flag
                or o.Visibility
                or o.Alert
                or o.EnemyCounter
            then
                due(F.V1Due)
            end
            if F.Settings.AimEnabled then
                due(F.AimDue)
            end
            if F.Settings.MortarEnabled then
                nextDelay = math.min(nextDelay, F.Mortar.NextInterval(now))
            end
            if F.Settings.WallEnabled then
                due(F.Wall.LastTick + MeowPerformance.WallApplySeconds)
                due(F.Wall.LastCleanup + F.Wall.CleanupInterval)
            end
            if _G.LexusConfig.IpadView then
                due(F.IpadDue)
            end
            if F.Dirty then
                due(F.SaveDue)
            end
            return nextDelay
        end
        F.Wake = function()
            if F.Token.Stopped then
                return
            end
            F.V1Due = 0
            F.AimDue = 0
            if F.Mortar then
                F.Mortar.Due = 0
            end
            F.Wall.LastTick = -999
            local due = g_adityaorg_ESPRunnerToken.Due
            if not due or due - g_adityaorg_ESPNow() > 0.002 then
                g_adityaorg_ESPSchedule(0.001)
            end
        end
    end

    local g_adityaorg_FastRunnerToken = {}
    local previousSettingsRunner = _G.__MasterShotFastRunner
    if type(previousSettingsRunner) == "table" and previousSettingsRunner.Timer and previousSettingsRunner.Owner then
        pcall(function()
            previousSettingsRunner.Owner:RemoveGameTimer(previousSettingsRunner.Timer)
        end)
    end
    _G.__MasterShotFastRunner = g_adityaorg_FastRunnerToken
    -- g_adityaorg_FastTick
    local function g_adityaorg_FastTick()
        if _G.__MasterShotFastRunner ~= g_adityaorg_FastRunnerToken then
            return
        end
        local now = g_adityaorg_ESPNow()
        local state = _G.LunarNativeSettingsRuntime
        if
            not state
            or not state.Ready
            or not g_adityaorg_FastRunnerToken.MenuAt
            or now < g_adityaorg_FastRunnerToken.MenuAt
            or now - g_adityaorg_FastRunnerToken.MenuAt >= MeowPerformance.MenuMaintenanceSeconds
        then
            g_adityaorg_EnsureHackMenu()
            g_adityaorg_FastRunnerToken.MenuAt = now
        end
        local render = _G.__MasterShotESPRunner
        if not render or not render.Due then
            pcall(g_adityaorg_ApplyiPadView)
        end
    end
    do
        local token = g_adityaorg_FastRunnerToken
        -- member
        local function member(object, key)
            if object == nil then
                return nil
            end
            local ok, value = pcall(function()
                return object[key]
            end)
            if ok then
                return value
            end
        end
        -- valid
        local function valid(object)
            if object == nil then
                return false
            end
            if slua and type(slua.isValid) == "function" then
                local ok, value = pcall(slua.isValid, object)
                return ok and value == true
            end
            return false
        end
        -- timerOwnerReady
        local function timerOwnerReady(owner)
            return owner ~= nil and (owner == Game or valid(owner) or valid(member(owner, "Object")))
        end
        -- callback
        local function callback()
            if _G.__MasterShotFastRunner ~= token then
                if token.Timer and token.Owner then
                    pcall(function()
                        token.Owner:RemoveGameTimer(token.Timer)
                    end)
                end
                token.Timer = nil
                return
            end
            g_adityaorg_FastTick()
            g_adityaorg_StartSettingsMaintenance()
        end
        g_adityaorg_StartSettingsMaintenance = function(owner)
            if _G.__MasterShotFastRunner ~= token then
                return false
            end
            if token.Pending then
                return true
            end
            if token.Timer and (token.Provider == "ticker" or timerOwnerReady(token.Owner)) then
                return true
            end
            if token.Timer and token.Owner then
                pcall(function()
                    token.Owner:RemoveGameTimer(token.Timer)
                end)
            end
            token.Timer, token.Owner, token.Provider = nil, nil, nil

            local candidates = {}
            -- add
            local function add(candidate, kind)
                if not timerOwnerReady(candidate) or type(member(candidate, "AddGameTimer")) ~= "function" then
                    return
                end
                for _, entry in ipairs(candidates) do
                    if entry.Object == candidate then
                        return
                    end
                end
                candidates[#candidates + 1] = { Object = candidate, Kind = kind }
            end
            local pc
            pcall(function()
                if GameplayData.GetPlayerController then
                    pc = GameplayData.GetPlayerController()
                end
            end)
            if not valid(pc) then
                pcall(function()
                    if slua_GameFrontendHUD then
                        pc = slua_GameFrontendHUD:GetPlayerController()
                    end
                end)
            end
            add(pc, "controller")
            add(owner, "character")
            add(Game, "game")
            for _, entry in ipairs(candidates) do
                local ok, timer = pcall(function()
                    return entry.Object:AddGameTimer(1.0, true, callback)
                end)
                if ok and timer then
                    token.Timer, token.Owner, token.Provider = timer, entry.Object, entry.Kind
                    token.LastError = nil
                    g_adityaorg_FastTick()
                    return true
                end
            end
            local okTicker, ticker = pcall(require, "common.time_ticker")
            if okTicker and ticker then
                if type(ticker.AddTimer) == "function" then
                    local ok, timer = pcall(ticker.AddTimer, 1.0, true, callback)
                    if ok and timer then
                        token.Timer, token.Owner, token.Provider = timer, ticker, "ticker"
                        token.LastError = nil
                        return true
                    end
                end
                if type(ticker.AddTimerOnce) == "function" then
                    token.Pending, token.Provider = true, "ticker_once"
                    local ok, accepted = pcall(ticker.AddTimerOnce, 1.0, function()
                        token.Pending = false
                        callback()
                    end)
                    if ok and accepted ~= false then
                        token.LastError = nil
                        return true
                    end
                    token.Pending, token.Provider = false, nil
                    token.LastError = tostring(accepted)
                else
                    token.LastError = "SETTINGS_TIMER_API_UNAVAILABLE"
                end
            else
                if package and package.loaded and type(package.loaded["common.time_ticker"]) ~= "table" then
                    package.loaded["common.time_ticker"] = nil
                end
                token.LastError = tostring(ticker)
            end
            return false
        end
    end

    g_adityaorg_EnsureHackMenu()
    if _G.LunarStandaloneWelcome and not _G.__LUNAR_WELCOME_SHOWN then
        _G.LunarStandaloneWelcome.NeedsUpdate = true
    end
    g_adityaorg_FastTick()
    g_adityaorg_StartSettingsMaintenance()
    g_adityaorg_ShotESP.Running = true
    g_adityaorg_ESPTick()
end

-- ============================================================================
-- // AUTHORIZED START / LOCK CALLBACKS //
-- ============================================================================
local featureStarted = false
-- activateFeatures
local function activateFeatures()
    if not embeddedLogin.IsAuthorized() then
        return
    end
    if featureStarted then
        local F = _G.LunarFeatures
        if F and F.Wake and not F.Token.Stopped then
            F.Wake()
        end
        return
    end
    local ok, startError = pcall(startBaselineHacks)
    featureStarted = ok
    if not ok then
        _G.LunarOptionalStartupError = tostring(startError)
        if _G.LunarFeatures and _G.LunarFeatures.Error then
            _G.LunarFeatures.Error("Startup", startError)
        end
    end
end
-- lockFeatures
local function lockFeatures()
    if not featureStarted then
        return
    end
    local F = _G.LunarFeatures
    if F and F.Wake and not F.Token.Stopped then
        F.AuthLocked = false
        F.Wake()
    end
end

-- ============================================================================
-- // NATIVE FEATURE CONTEXT / TIMERS / PAWN CACHE //
-- ============================================================================
(function()
    do
        local ok, gp = pcall(require, "GameLua.GameCore.Data.GameplayData")
        local pc = (ok and gp and gp.GetPlayerController and gp.GetPlayerController())
            or (
                slua_GameFrontendHUD
                and slua_GameFrontendHUD.GetPlayerController
                and slua_GameFrontendHUD:GetPlayerController()
            )
        if pc and _G._MOD_LOADED and _G._MOD_PC == pc then
            return
        end
        if pc then
            _G._MOD_PC = pc
        end
        _G._MOD_LOADED = true
    end

    _G.bWriteLog = false
    _G.log_tree = _G.log_tree or function(...) end

    local ENetRole = import("ENetRole")
    local EPawnState = import("EPawnState")
    local ESpecialMovementType = import("ESpecialMovementType")
    local ESpiderSwingMoveState = import("ESpiderSwingMoveState")
    local ESurviveWeaponPropSlot = import("ESurviveWeaponPropSlot")
    local EParachuteState = import("EParachuteState")
    local EMovementMode = import("EMovementMode")
    local EStateType = import("EStateType")
    local ESTEPoseState = import("ESTEPoseState")
    local EGameModeType = import("EGameModeType")
    local STExtraGameStateBase = import("STExtraGameStateBase")
    local UKismetSystemLibrary = import("KismetSystemLibrary")
    local GameplayData = require("GameLua.GameCore.Data.GameplayData")
    local GamePlayTools = require("GameLua.Mod.BaseMod.Common.GamePlayTools")
    local InGameMarkTools = require("GameLua.Mod.BaseMod.Common.InGameMarkTools")
    local KismetMathLibrary = import("KismetMathLibrary")
    local GameplayStatics = import("GameplayStatics")
    local LinearColor = import("LinearColor")
    local FVec = FVector
        or (pcall(import, "Vector") and import("Vector"))
        or (pcall(import, "FVector") and import("FVector"))

    _G.InGameMarkTools = InGameMarkTools
    _G.GameplayData = GameplayData

    local _slua = rawget(_G, "slua")
    -- Valid
    local function Valid(obj)
        if not obj then
            return false
        end
        if _slua and _slua.isValid then
            local ok, v = pcall(_slua.isValid, obj)
            if not ok or not v then
                return false
            end
        end
        return true
    end
    _G.Valid = Valid

    -- SafeMethodCall
    local function SafeMethodCall(obj, method, ...)
        if not obj then
            return false, nil
        end
        local fn = obj[method]
        if type(fn) ~= "function" then
            return false, nil
        end
        return pcall(fn, obj, ...)
    end
    _G.SafeMethodCall = SafeMethodCall

    -- GetPawnKey
    local function GetPawnKey(pawn)
        if not Valid(pawn) then
            return nil
        end
        local uid = nil
        if pawn.GetUniqueID then
            local okID, id = pcall(pawn.GetUniqueID, pawn)
            if okID and id and id ~= 0 then
                uid = id
            end
        end
        if uid then
            return uid
        end
        local pk = pawn.PlayerKey
        if pk and pk ~= 0 then
            return pk
        end
        local uState = pawn.PlayerState
        if Valid(uState) and uState.PlayerKey and uState.PlayerKey ~= 0 then
            return uState.PlayerKey
        end
        local puid = pawn.PlayerUID
        if puid and puid ~= "" and puid ~= "0" then
            return tostring(puid)
        end
        return tostring(pawn)
    end
    _G.GetPawnKey = GetPawnKey

    -- IsPawnDead
    local function IsPawnDead(pawn)
        if not Valid(pawn) then
            return true
        end
        local hs = pawn.HealthStatus
        if hs == 2 or hs == 3 or pawn.bIsDead or pawn.bDead then
            return true
        end
        if pawn.Health and pawn.Health <= 0 and hs ~= 1 and hs ~= 0 then
            return true
        end
        return false
    end
    _G.IsPawnDead = IsPawnDead

    local AI_CACHE = {}
    local AI_CACHE_SIZE = 0
    -- ResolveIsAI
    local function ResolveIsAI(pKey_or_pawn, maybe_pawn)
        local pawn = maybe_pawn or pKey_or_pawn
        local pKey = maybe_pawn and pKey_or_pawn or (pawn and pawn.PlayerKey)
        if pKey and pKey ~= 0 and AI_CACHE[pKey] ~= nil then
            return AI_CACHE[pKey]
        end
        local isAI = false
        local g = _G.Game or Game
        if g and g.IsAI and pawn then
            local s, r = pcall(g.IsAI, g, pawn)
            if s and r == true then
                isAI = true
            end
        end
        if not isAI and pawn then
            if pawn.bIsAI == true or pawn.bAI == true then
                isAI = true
            end
            if not isAI and type(pawn.IsBot) == "function" then
                isAI = pawn:IsBot()
            end
            if not isAI and type(pawn.IsAI) == "function" then
                local s, r = pcall(pawn.IsAI, pawn)
                if s and r == true then
                    isAI = true
                end
            end
            if not isAI and (not pKey or pKey == 0) then
                pcall(function()
                    if pawn.PlayerState and (pawn.PlayerState.bIsABot == true or pawn.PlayerState.bIsAI == true) then
                        isAI = true
                    end
                end)
            end
        end
        if pKey and pKey ~= 0 and (AI_CACHE_SIZE or 0) < 512 then
            AI_CACHE_SIZE = (AI_CACHE_SIZE or 0) + 1
            AI_CACHE[pKey] = isAI
        end
        return isAI
    end
    _G.ResolveIsAI = ResolveIsAI

    -- InvalidateAICache
    local function InvalidateAICache()
        AI_CACHE = {}
        AI_CACHE_SIZE = 0
    end
    _G.InvalidateAICache = InvalidateAICache

    local _PAWN_CACHE = nil
    local _PAWN_CACHE_TIME = 0
    local _PAWN_CACHE_TTL = 1.5

    -- InvalidatePawnCache
    local function InvalidatePawnCache()
        _PAWN_CACHE = nil
        _PAWN_CACHE_TIME = 0
        MeowPerf.InvalidatePawns()
    end
    _G.InvalidatePawnCache = InvalidatePawnCache

    -- GetCachedPlayerPawns
    local function GetCachedPlayerPawns()
        if MeowPerf.PlayerPawns then
            return true, MeowPerf.PlayerPawns()
        end
        local now = os.clock()
        if _PAWN_CACHE and (now - _PAWN_CACHE_TIME) < _PAWN_CACHE_TTL then
            return true, _PAWN_CACHE
        end

        local pawnsList = {}
        local seenPawns = {}
        -- AddPawn
        local function AddPawn(p)
            if not Valid(p) then
                return
            end
            local key = GetPawnKey(p) or p
            if not seenPawns[key] then
                seenPawns[key] = true
                pawnsList[#pawnsList + 1] = p
            end
        end

        pcall(function()
            local ok, pawns = SafeMethodCall(_G.Game or Game, "GetAllPlayerPawns")
            if ok and pawns then
                for _, p in pairs(pawns) do
                    AddPawn(p)
                end
            end
        end)

        if #pawnsList == 0 then
            pcall(function()
                if GameplayData and GameplayData.GetAllCharacters then
                    local chars = GameplayData.GetAllCharacters()
                    if chars then
                        for _, c in pairs(chars) do
                            AddPawn(c)
                        end
                    end
                end
            end)
        end

        if #pawnsList == 0 then
            pcall(function()
                local okGS, GS = pcall(require, "GameLua.GameCore.Data.CGameState")
                if okGS and GS and GS.GetAllCharacters then
                    local chars = GS:GetAllCharacters()
                    if chars then
                        for _, c in pairs(chars) do
                            AddPawn(c)
                        end
                    end
                end
            end)
        end

        if #pawnsList > 0 then
            _PAWN_CACHE = pawnsList
            _PAWN_CACHE_TIME = now
            return true, _PAWN_CACHE
        end

        _PAWN_CACHE_TIME = now
        if _PAWN_CACHE then
            return true, _PAWN_CACHE
        end
        return false, {}
    end
    _G.GetCachedPlayerPawns = GetCachedPlayerPawns

    local _FrameCache = {
        frame = -1,
        pawn = nil,
        pos = nil,
        hud = nil,
        pc = nil,
        team = 0,
        time = 0,
        spectatedTarget = nil,
        isSpectating = false,
    }
    -- GetFrameCache
    local function GetFrameCache()
        local f = os.clock()
        if (f - (_FrameCache.time or 0)) > 0.05 then
            _FrameCache.time = f
            _FrameCache.frame = _FrameCache.frame + 1
            local pawn, pos, hud, pc = nil, nil, nil, nil
            pcall(function()
                if GameplayData then
                    if GameplayData.GetLocalCharacter then
                        pawn = GameplayData.GetLocalCharacter()
                    end
                    if not pawn and GameplayData.GetPlayerCharacter then
                        pawn = GameplayData.GetPlayerCharacter()
                    end
                end
            end)
            if not pc and slua_GameFrontendHUD then
                pcall(function()
                    pc = slua_GameFrontendHUD:GetPlayerController()
                end)
            end
            if not pc and GameplayData then
                pcall(function()
                    pc = GameplayData.GetPlayerController and GameplayData.GetPlayerController()
                end)
            end
            if not pawn and pc then
                pcall(function()
                    if pc.GetPlayerCharacterSafety then
                        pawn = pc:GetPlayerCharacterSafety()
                    end
                    if not pawn and pc.GetPawn then
                        pawn = pc:GetPawn()
                    end
                    if not pawn and pc.GetPlayerCharacter then
                        pawn = pc:GetPlayerCharacter()
                    end
                end)
            end

            local spectatedTarget = nil
            local isSpectating = false
            pcall(function()
                if pc and Valid(pc) then
                    local vt = nil
                    if pc.GetViewTarget then
                        vt = pc:GetViewTarget()
                    end
                    if not vt and pc.PlayerCameraManager and pc.PlayerCameraManager.ViewTarget then
                        vt = pc.PlayerCameraManager.ViewTarget.Target
                    end
                    local localIsDead = false
                    if pawn and Valid(pawn) then
                        local hs = pawn.HealthStatus
                        if
                            hs == 2
                            or hs == 3
                            or pawn.bIsDead
                            or pawn.bDead
                            or (pawn.Health and pawn.Health <= 0 and hs ~= 1)
                        then
                            localIsDead = true
                        end
                    else
                        localIsDead = true
                    end

                    if
                        (localIsDead or pc.bIsSpectating or (pc.IsInSpectatingMode and pc:IsInSpectatingMode()))
                        and vt
                        and Valid(vt)
                    then
                        isSpectating = true
                        spectatedTarget = vt
                    end
                end
            end)

            if isSpectating and spectatedTarget then
                pawn = spectatedTarget
                local okVT, vtPos = SafeMethodCall(spectatedTarget, "K2_GetActorLocation")
                if okVT and vtPos then
                    pos = vtPos
                end
                _FrameCache.team = spectatedTarget.TeamID or 0
            else
                if pawn then
                    local okLoc, pPos = SafeMethodCall(pawn, "K2_GetActorLocation")
                    if okLoc and pPos then
                        pos = pPos
                    end
                else
                    pawn = _FrameCache.pawn
                    pos = _FrameCache.pos
                end
                _FrameCache.team = pawn and pawn.TeamID or 0
            end

            if not hud and pawn and Valid(pawn) then
                pcall(function()
                    hud = pawn.MyHUD
                end)
            end
            if not hud and pc and Valid(pc) then
                pcall(function()
                    hud = pc.MyHUD or (pc.GetHUD and pc:GetHUD())
                end)
            end
            if not hud and slua_GameFrontendHUD and Valid(slua_GameFrontendHUD) then
                hud = slua_GameFrontendHUD
            end
            if not hud and _FrameCache.hud and Valid(_FrameCache.hud) then
                hud = _FrameCache.hud
            end
            _FrameCache.pawn = pawn
            _FrameCache.pos = pos
            _FrameCache.hud = hud
            _FrameCache.pc = pc
            _FrameCache.spectatedTarget = spectatedTarget
            _FrameCache.isSpectating = isSpectating
        end
        return _FrameCache.pawn,
            _FrameCache.pos,
            _FrameCache.hud,
            _FrameCache.pc,
            _FrameCache.team,
            _FrameCache.spectatedTarget,
            _FrameCache.isSpectating
    end
    _G.GetFrameCache = GetFrameCache

    -- GetActivePlayerController
    local function GetActivePlayerController(passedPc)
        if Valid(passedPc) and passedPc.AddGameTimer then
            return passedPc
        end
        local pc = nil
        pcall(function()
            if GameplayData and GameplayData.GetPlayerController then
                pc = GameplayData.GetPlayerController()
            end
        end)
        if Valid(pc) and pc.AddGameTimer then
            return pc
        end

        pcall(function()
            local world = _slua and _slua.getWorld and _slua.getWorld()
            local KSL = UKismetSystemLibrary or import("KismetSystemLibrary")
            if KSL and world and KSL.GetPlayerController then
                local retPc = KSL.GetPlayerController(world, 0)
                if Valid(retPc) and retPc.AddGameTimer then
                    pc = retPc
                end
            end
        end)
        if Valid(pc) and pc.AddGameTimer then
            return pc
        end

        if _G.Game and _G.Game.AddGameTimer then
            return _G.Game
        end

        pcall(function()
            if slua_GameFrontendHUD and Valid(slua_GameFrontendHUD) then
                local retPc = slua_GameFrontendHUD:GetPlayerController()
                if Valid(retPc) and retPc.AddGameTimer then
                    pc = retPc
                end
            end
        end)
        return pc
    end

    -- GetLocalPlayer
    local function GetLocalPlayer(pc)
        local p = nil
        if Valid(pc) then
            pcall(function()
                if pc.GetPlayerCharacterSafety then
                    p = pc:GetPlayerCharacterSafety()
                end
                if not Valid(p) and pc.GetCurPlayerCharacter then
                    p = pc:GetCurPlayerCharacter()
                end
                if not Valid(p) and pc.GetPawn then
                    p = pc:GetPawn()
                end
            end)
        end
        if not Valid(p) then
            pcall(function()
                if GameplayData then
                    if GameplayData.GetLocalCharacter then
                        p = GameplayData.GetLocalCharacter()
                    end
                    if not Valid(p) and GameplayData.GetPlayerCharacter then
                        p = GameplayData.GetPlayerCharacter()
                    end
                end
            end)
        end
        if not Valid(p) then
            local activePc = GetActivePlayerController()
            if Valid(activePc) and activePc ~= pc then
                pcall(function()
                    if activePc.GetPlayerCharacterSafety then
                        p = activePc:GetPlayerCharacterSafety()
                    end
                    if not Valid(p) and activePc.GetCurPlayerCharacter then
                        p = activePc:GetCurPlayerCharacter()
                    end
                end)
            end
        end
        return p
    end

    -- GetAllEnemies
    local function GetAllEnemies(localPlayer)
        local ok, pawns = GetCachedPlayerPawns()
        if not ok or not pawns then
            return {}
        end
        local localPawn, _, _, _, myTeam = GetFrameCache()
        local lp = localPlayer or localPawn
        local myTeamId = (lp and lp.TeamID) or myTeam or 0
        local enemies = {}
        for _, p in ipairs(pawns) do
            if Valid(p) and p ~= lp then
                local pTeam = p.TeamID or (type(p.GetTeamID) == "function" and p:GetTeamID())
                if not (myTeamId > 0 and pTeam and pTeam > 0 and pTeam == myTeamId) then
                    enemies[#enemies + 1] = p
                end
            end
        end
        return enemies
    end
