    -- ClearAllVehicleESP
    local function ClearAllVehicleESP()
        pcall(function()
            local _, _, hud = GetFrameCache()
            if Valid(hud) and hud.RemoveDebugText then
                for veh, _ in pairs(_ActiveVehicleActors) do
                    if Valid(veh) then
                        pcall(hud.RemoveDebugText, hud, veh, false)
                    end
