    -- GetVehicleDisplayName
    local function GetVehicleDisplayName(veh)
        if not Valid(veh) then
            return "Vehicle"
        end
        local n = veh.DisplayName
        if n and type(n) == "string" and n ~= "" then
            return n
        end

        pcall(function()
            local av = veh.VehicleAvatar
            if Valid(av) and av.GetDefaultAvatarID then
                local okId, id = pcall(av.GetDefaultAvatarID, av)
                if okId and id and id > 0 then
                    local baseId = math.floor(id / 1000) * 1000
                    n = VEH_NAMES[baseId] or VEH_NAMES[id]
                end
            end
        end)
        if n and n ~= "" then
            return n
        end

        local clsName = ""
        pcall(function()
            local clsObj = veh:GetClass()
            if clsObj and clsObj.GetName then
                clsName = clsObj:GetName()
            end
        end)
        if not clsName or clsName == "" then
            pcall(function()
                clsName = type(veh.GetName) == "function" and veh:GetName() or tostring(veh)
            end)
        end

        if clsName:find("UAZ") then
            return "UAZ"
        elseif clsName:find("Buggy") then
            return "Buggy"
        elseif clsName:find("Dacia") then
            return "Dacia"
        elseif clsName:find("Motorcycle") or clsName:find("Motorbike") or clsName:find("Bike01") then
            return "Motorcycle"
        elseif clsName:find("Coupe") then
            return "Coupe RB"
        elseif clsName:find("Mirado") then
            return "Mirado"
        elseif clsName:find("Monster") then
            return "Monster Truck"
        elseif clsName:find("BRDM") then
            return "BRDM-2"
        elseif clsName:find("Rony") then
            return "Rony"
        elseif clsName:find("Tuk") then
            return "Tukshai"
        elseif clsName:find("Scooter") then
            return "Scooter"
        elseif clsName:find("Snowmobile") then
            return "Snowmobile"
        elseif clsName:find("Glider") then
            return "Glider"
        elseif clsName:find("Boat") or clsName:find("PG117") then
            return "Boat"
        elseif clsName:find("JetSki") or clsName:find("Aqua") then
            return "Jet Ski"
        elseif clsName:find("UTV") then
            return "UTV"
        elseif clsName:find("Bike") then
            return "Bike"
        elseif clsName:find("Hovercraft") then
            return "Hovercraft"
        elseif clsName:find("Tank") then
            return "Tank"
        end
        return "Vehicle"
    end
    -- Tick_VehicleESP
    local function Tick_VehicleESP()
        local isEnabled = _G.LexusConfig and _G.LexusConfig.VehicleESPEnabled
        if not isEnabled then
            if next(_ActiveVehicleActors) ~= nil then
                ClearAllVehicleESP()
            end
            return
        end

        local localPawn, myPos, hud, pc = GetFrameCache()
        if not Valid(hud) then
            if slua_GameFrontendHUD and Valid(slua_GameFrontendHUD) then
                hud = slua_GameFrontendHUD
            elseif pc and Valid(pc) then
                pcall(function()
                    hud = pc.MyHUD or (pc.GetHUD and pc:GetHUD())
                end)
            elseif localPawn and Valid(localPawn) then
                pcall(function()
                    hud = localPawn.MyHUD
                end)
            end
        end
        if not localPawn or not myPos or not Valid(hud) then
            return
        end

        local nowSec = os.time()
        if (nowSec - _VEH_CACHE_TIME) >= 10 or not _VEH_CACHE then
            _VEH_CACHE_TIME = nowSec
            local vehList = nil
            pcall(function()
                if Game and Game.GetAllVehicles then
                    vehList = Game:GetAllVehicles()
                elseif _G.Game and _G.Game.GetAllVehicles then
                    vehList = _G.Game:GetAllVehicles()
                elseif CGame and CGame.GetAllVehicles then
                    vehList = CGame:GetAllVehicles()
                end
            end)
            if not vehList then
                pcall(function()
                    local cls = import("/Script/ShadowTrackerExtra.STExtraVehicleBase") or import("STExtraVehicleBase")
                    if cls and Game and Game.GetActorsByClass then
                        vehList = Game:GetActorsByClass(cls)
                    end
                end)
            end
            local flat = {}
            if vehList then
                local n = nil
                pcall(function()
                    if type(vehList.Num) == "function" then
                        n = vehList:Num()
                    end
                end)
                if n and n > 0 then
                    for i = 0, n - 1 do
                        local v = nil
                        pcall(function()
                            v = vehList:Get(i)
                        end)
                        if v and Valid(v) then
                            flat[#flat + 1] = v
                        end
                    end
                elseif type(vehList) == "table" then
                    for _, v in pairs(vehList) do
                        if v and Valid(v) then
                            flat[#flat + 1] = v
                        end
                    end
                end
            end
            _VEH_CACHE = flat
        end

        local currentVehicles = {}
        for _, veh in ipairs(_VEH_CACHE or {}) do
            if Valid(veh) then
                local okLoc, vPos = SafeMethodCall(veh, "K2_GetActorLocation")
                if okLoc and vPos then
                    local dx = vPos.X - myPos.X
                    local dy = vPos.Y - myPos.Y
                    local dz = vPos.Z - myPos.Z
                    local distSq = dx * dx + dy * dy + dz * dz
                    local maxVDist = (_G.LexusConfig and _G.LexusConfig.VehicleDistance) or 400
                    local maxVDistSq = (maxVDist * 100) * (maxVDist * 100)
                    if distSq > 0 and distSq <= maxVDistSq then
                        local vDist = math.floor(math.sqrt(distSq) / 100.0 + 0.5)
                        local vName = GetVehicleDisplayName(veh)
                        local txt
                        if _G.LexusConfig and _G.LexusConfig.VehicleShowDist == false then
                            txt = vName
                        else
                            txt = string.format("%s [%dm]", vName, vDist)
                        end
                        SafeMethodCall(
                            hud,
                            "AddDebugText",
                            txt,
                            veh,
                            11.5,
                            VEH_TEXT_OFFSET,
                            VEH_TEXT_OFFSET,
                            C_VEH_YELLOW,
                            false,
                            false,
                            true,
                            nil,
                            0.65,
                            true
                        )
                        currentVehicles[veh] = true
                    end
                end
            end
        end

        for veh, _ in pairs(_ActiveVehicleActors) do
            if not currentVehicles[veh] then
                if Valid(hud) and hud.RemoveDebugText and Valid(veh) then
                    pcall(hud.RemoveDebugText, hud, veh, false)
                end
                _ActiveVehicleActors[veh] = nil
            end
        end
        for veh, _ in pairs(currentVehicles) do
            _ActiveVehicleActors[veh] = true
        end
    end
    _G.Tick_VehicleESP = Tick_VehicleESP

