    -- GetPickUpWrapperClass
    local function GetPickUpWrapperClass()
        if _PickUpWrapperClass then
            return _PickUpWrapperClass
        end
        local candidates = {
            "/Script/ShadowTrackerExtra.PickUpWrapperActor",
            "PickUpWrapperActor",
            "/Script/ShadowTrackerExtra.STExtraPickUpWrapperActor",
            "STExtraPickUpWrapperActor",
        }
        for _, path in ipairs(candidates) do
            local ok, cls = pcall(import, path)
            if ok and cls then
                _PickUpWrapperClass = cls
                return cls
            end
        end
        if slua and slua.loadClass then
            for _, path in ipairs(candidates) do
                local ok, cls = pcall(slua.loadClass, path)
                if ok and cls then
                    _PickUpWrapperClass = cls
                    return cls
                end
            end
        end
        return nil
    end

    -- ResolveItemName
    local function ResolveItemName(item)
        if not Valid(item) then
            return nil
        end
        local id = nil

        pcall(function()
            if item.DefineID then
                id = item.DefineID.TypeSpecificID or item.DefineID.ID or item.DefineID
            end
        end)
        if not id then
            pcall(function()
                if item.ItemDefineID then
                    id = item.ItemDefineID.TypeSpecificID or item.ItemDefineID.ID
                end
            end)
        end
        if not id then
            pcall(function()
                if item.GetItemDefineID then
                    local def = item:GetItemDefineID()
                    if def then
                        id = def.TypeSpecificID or def.ID
                    end
                end
            end)
        end
        if not id then
            pcall(function()
                if item.GetPickUpDataList then
                    local list = item:GetPickUpDataList()
                    if list then
                        local first = (type(list.Get) == "function" and list:Get(0)) or list[1]
                        if first then
                            local fId = first.ID or first.DefineID
                            if fId then
                                id = fId.TypeSpecificID or fId.ID or fId
                            end
                        end
                    end
                end
            end)
        end
        if not id then
            pcall(function()
                if item.DefineId then
                    id = item.DefineId
                end
            end)
        end
        if not id then
            pcall(function()
                if item.ItemID then
                    id = item.ItemID
                end
            end)
        end

        if type(id) == "number" and id > 0 and HighTierLoot[id] then
            return HighTierLoot[id]
        end

        local name = ""
        pcall(function()
            if type(item.GetName) == "function" then
                name = item:GetName()
            else
                name = tostring(item)
            end
        end)
        if not name or name == "" then
            pcall(function()
                local cls = item:GetClass()
                if cls and cls.GetName then
                    name = cls:GetName()
                end
            end)
        end

        if name and name ~= "" then
            local lower = name:lower()
            if lower:find("flare") then
                return "Flare Gun"
            elseif lower:find("awm") then
                return "AWM"
            elseif lower:find("amr") then
                return "AMR"
            elseif lower:find("groza") then
                return "Groza"
            elseif lower:find("aug") then
                return "AUG"
            elseif lower:find("mg3") then
                return "MG3"
            elseif lower:find("mk14") then
                return "Mk14"
            elseif lower:find("p90") then
                return "P90"
            elseif lower:find("m416") then
                return "M416"
            elseif lower:find("akm") then
                return "AKM"
            elseif lower:find("m762") then
                return "M762"
            elseif lower:find("kar98") then
                return "Kar98K"
            elseif lower:find("m24") then
                return "M24"
            elseif lower:find("armor_3") or lower:find("armor_lv3") or lower:find("vest_3") or lower:find("vest3") then
                return "Lv3 Armor"
            elseif
                lower:find("helmet_3")
                or lower:find("helmet_lv3")
                or lower:find("head_3")
                or lower:find("head3")
            then
                return "Lv3 Helmet"
            elseif lower:find("bag_3") or lower:find("bag_lv3") or lower:find("backpack_3") then
                return "Lv3 Backpack"
            elseif lower:find("scope_4x") or lower:find("4x") or lower:find("largeequip_4x") then
                return "4x Scope"
            elseif lower:find("scope_6x") or lower:find("6x") or lower:find("largeequip_6x") then
                return "6x Scope"
            elseif lower:find("scope_8x") or lower:find("8x") or lower:find("largeequip_8x") then
                return "8x Scope"
            elseif lower:find("medkit") or lower:find("firstaid") then
                return "Med Kit"
            elseif lower:find("adrenaline") then
                return "Adrenaline"
            end
        end
        return nil
    end

    -- IsLootAllowed
    local function IsLootAllowed(itemName)
        local cfg = _G.LexusConfig
        if not cfg then
            return true
        end
        if itemName:find("Flare") then
            return cfg.LootFlares ~= false
        elseif
            itemName:find("Lv3")
            or itemName:find("Armor")
            or itemName:find("Helmet")
            or itemName:find("Backpack")
        then
            return cfg.LootArmor ~= false
        elseif itemName:find("Scope") then
            return cfg.LootScopes ~= false
        elseif itemName:find("Med") or itemName:find("Adrenaline") then
            return cfg.LootMeds ~= false
        else
            return cfg.LootWeapons ~= false
        end
    end

    -- Tick_LootESP
    local function Tick_LootESP()
        local isEnabled = _G.LexusConfig and _G.LexusConfig.LootESPEnabled
        if not isEnabled then
            if next(_ActiveLootActors) ~= nil then
                ClearAllLootESP()
            end
            return
        end

        local localPawn, myPos, hud, pc = GetFrameCache()
        if not Valid(hud) then
            if slua_GameFrontendHUD and Valid(slua_GameFrontendHUD) then
                hud = slua_GameFrontendHUD
            elseif pc and Valid(pc) then
                pcall(function()
                    hud = pc.MyHUD or (pc.GetHUD and pc:GetHUD())
                end)
            elseif localPawn and Valid(localPawn) then
                pcall(function()
                    hud = localPawn.MyHUD
                end)
            end
        end
        if not localPawn or not myPos or not Valid(hud) then
            return
        end

        local cls = GetPickUpWrapperClass()
        if not cls then
            return
        end

        local actors = nil
        pcall(function()
            if Game and Game.GetActorsByClass then
                actors = Game:GetActorsByClass(cls)
            elseif _G.Game and _G.Game.GetActorsByClass then
                actors = _G.Game:GetActorsByClass(cls)
            elseif CGame and CGame.GetActorsByClass then
                actors = CGame:GetActorsByClass(cls)
            end
        end)

        if not actors then
            pcall(function()
                local gi = (
                    slua_GameFrontendHUD
                    and slua_GameFrontendHUD.GetGameInstance
                    and slua_GameFrontendHUD:GetGameInstance()
                ) or (pc and pc.GetGameInstance and pc:GetGameInstance())
                if GameplayStatics and cls and gi then
                    local arr = (
                        slua
                        and slua.Array
                        and UEnums
                        and UEnums.EPropertyClass
                        and slua.Array(UEnums.EPropertyClass.Object, cls)
                    ) or {}
                    actors = GameplayStatics.GetAllActorsOfClass(gi, cls, arr)
                end
            end)
        end

        if not actors then
            return
        end

        local currentLoot = {}
        local displayedCount = 0

        -- ProcessItem
        local function ProcessItem(item)
            if not (item and Valid(item)) then
                return
            end
            local dist = nil
            pcall(function()
                dist = localPawn:GetDistanceTo(item) / 100.0
            end)
            if not dist then
                local okLoc, iPos = SafeMethodCall(item, "K2_GetActorLocation")
                if okLoc and iPos and myPos then
                    local dx = iPos.X - myPos.X
                    local dy = iPos.Y - myPos.Y
                    local dz = iPos.Z - myPos.Z
                    dist = math.sqrt(dx * dx + dy * dy + dz * dz) / 100.0
                end
            end

            local maxLootDist = (_G.LexusConfig and _G.LexusConfig.LootDistance) or 60.0
            if dist and dist <= maxLootDist then
                local itemName = ResolveItemName(item)
                if itemName and IsLootAllowed(itemName) then
                    local distM = math.floor(dist + 0.5)
                    local txt = string.format("%s [%dm]", itemName, distM)
                    SafeMethodCall(
                        hud,
                        "AddDebugText",
                        txt,
                        item,
                        11.5,
                        LOOT_TEXT_OFFSET,
                        LOOT_TEXT_OFFSET,
                        C_LOOT_COLOR,
                        false,
                        false,
                        true,
                        nil,
                        0.70,
                        true
                    )
                    currentLoot[item] = true
                    displayedCount = displayedCount + 1
                end
            end
        end

        local n = nil
        pcall(function()
            if type(actors.Num) == "function" then
                n = actors:Num()
            end
        end)
        if n and n > 0 then
            for i = 0, n - 1 do
                local item = nil
                pcall(function()
                    item = actors:Get(i)
                end)
                if item then
                    ProcessItem(item)
                    if displayedCount >= 20 then
                        break
                    end
                end
            end
        elseif type(actors) == "table" then
            for _, item in pairs(actors) do
                ProcessItem(item)
                if displayedCount >= 20 then
                    break
                end
            end
        end

        for itm, _ in pairs(_ActiveLootActors) do
            if not currentLoot[itm] then
                if Valid(hud) and hud.RemoveDebugText and Valid(itm) then
                    pcall(hud.RemoveDebugText, hud, itm, false)
                end
                _ActiveLootActors[itm] = nil
            end
        end
        for itm, _ in pairs(currentLoot) do
            _ActiveLootActors[itm] = true
        end
    end
    _G.Tick_LootESP = Tick_LootESP

    _G.LOOT_TIMER = nil
    _G.LOOT_TIMER_OWNER = nil

    -- StopLootTimer
    local function StopLootTimer()
        if _G.LOOT_TIMER and Valid(_G.LOOT_TIMER_OWNER) and _G.LOOT_TIMER_OWNER.RemoveGameTimer then
            pcall(_G.LOOT_TIMER_OWNER.RemoveGameTimer, _G.LOOT_TIMER_OWNER, _G.LOOT_TIMER)
        end
        _G.LOOT_TIMER = nil
        _G.LOOT_TIMER_OWNER = nil
        ClearAllLootESP()
    end
    _G.StopLootTimer = StopLootTimer

    -- StartLootTimer
    local function StartLootTimer(pc)
        local timerOwner = GetActivePlayerController(pc)
        if not Valid(timerOwner) or not timerOwner.AddGameTimer then
            return
        end
        if _G.LOOT_TIMER and _G.LOOT_TIMER_OWNER == timerOwner then
            return
        end
        if _G.LOOT_TIMER and Valid(_G.LOOT_TIMER_OWNER) and _G.LOOT_TIMER_OWNER.RemoveGameTimer then
            pcall(_G.LOOT_TIMER_OWNER.RemoveGameTimer, _G.LOOT_TIMER_OWNER, _G.LOOT_TIMER)
        end
        _G.LOOT_TIMER_OWNER = timerOwner
        _G.LOOT_TIMER = timerOwner:AddGameTimer(10.0, true, function()
            pcall(Tick_LootESP)
        end)
        pcall(Tick_LootESP)
    end
    _G.StartLootTimer = StartLootTimer

    -- ClearESPTimers
    local function ClearESPTimers()
        ClearAll1006Marks()
        ClearAllMapMarks()
        ClearAllBoxESP()
        ClearModTimers()
        if _G.StopSnaplineLoop then
            pcall(_G.StopSnaplineLoop)
        end
        if _G.ClearAllSnapLines then
            pcall(_G.ClearAllSnapLines)
        end
    end
    _G.ClearESPTimers = ClearESPTimers

    -- ============================================================================
    -- // ENEMY COUNTER //
    -- ============================================================================
    do
        local sluaRef = _slua or rawget(_G, "slua") or slua
        local isValid = (sluaRef and sluaRef.isValid) or function(o)
            return o ~= nil
        end
        local UEnums = UEnums
            or rawget(_G, "UEnums")
            or { ESlateVisibility = { Collapsed = 1, SelfHitTestInvisible = 2 } }

        -- importSafe
        local function importSafe(name)
            local ok, v = pcall(import, name)
            if ok and v then
                return v
            end
            return nil
        end
        local FLinearColor = rawget(_G, "FLinearColor") or importSafe("LinearColor") or LinearColor
        local FVector2D = rawget(_G, "FVector2D") or importSafe("Vector2D")
        local FMargin = rawget(_G, "FMargin") or importSafe("FMargin")

        -- color4
        local function color4(r, g, b, a)
            if FLinearColor then
                local ok, c = pcall(FLinearColor, r, g, b, a)
                if ok and c then
                    return c
                end
            end
            return { R = r, G = g, B = b, A = a, r = r, g = g, b = b, a = a }
        end
        -- vec2
        local function vec2(x, y)
            if FVector2D then
                local ok, v = pcall(FVector2D, x, y)
                if ok and v then
                    return v
                end
            end
            return { X = x, Y = y }
        end

        local C_BG_GREEN = color4(0.05, 0.80, 0.15, 0.92)
        local C_BG_RED = color4(0.85, 0.05, 0.05, 0.92)
        local C_TX_WHITE = color4(1.00, 1.00, 1.00, 1.00)

        local KC_BOX_W = 76
        local KC_BOX_H = 28
        local KC_Y = 30
        local KC_GAP = 4
        local KC_FONT = 13

        if _G.Mod_EnemyCounter_Enabled == nil then
            _G.Mod_EnemyCounter_Enabled = true
        end

        local CounterState = {
            boxReal = nil,
            txtReal = nil,
            boxBot = nil,
            txtBot = nil,
            lastText = nil,
            ctl = nil,
            pawn = nil,
            canvas = nil,
            ticks = 0,
            builds = 0,
            drops = 0,
            lastCount = nil,
        }

        -- NewUMG
        local function NewUMG(path, outer)
            local obj = nil
            local CG = rawget(_G, "CGame")
            pcall(function()
                if CG and CG.NewObjectFromPath then
                    obj = CG:NewObjectFromPath(path, outer)
                end
            end)
            if not obj or not isValid(obj) then
                pcall(function()
                    local cls = import(path)
                    if cls and cls.NewObject then
                        obj = cls:NewObject(outer)
                    end
                end)
            end
            if not obj or not isValid(obj) then
                pcall(function()
                    if sluaRef and sluaRef.NewObject then
                        obj = sluaRef.NewObject(path, outer)
                    end
                end)
            end
            return obj
        end

        -- SetFontSize
        local function SetFontSize(txt, size)
            if not isValid(txt) then
                return
            end
            pcall(function()
                if txt.SetFontSize then
                    txt:SetFontSize(size)
                end
            end)
            pcall(function()
                local f = txt.Font
                if f then
                    f.Size = size
                    if txt.SetFont then
                        txt:SetFont(f)
                    end
                end
            end)
            pcall(function()
                local SFC = import("SlateFontInfo")
                if SFC and txt.SetFont then
                    local f = SFC()
                    f.Size = size
                    txt:SetFont(f)
                end
            end)
        end

        -- ClearOutlineAndShadow
        local function ClearOutlineAndShadow(txt)
            if not isValid(txt) then
                return
            end
            pcall(function()
                if txt.SetShadowColorAndOpacity then
                    txt:SetShadowColorAndOpacity(color4(0, 0, 0, 0))
                end
            end)
            pcall(function()
                if txt.SetShadowOffset then
                    txt:SetShadowOffset(vec2(0, 0))
                end
            end)
            pcall(function()
                local f = txt.Font
                if f and f.OutlineSettings then
                    f.OutlineSettings.OutlineSize = 0
                    f.OutlineSettings.OutlineColor = color4(0, 0, 0, 0)
                    if txt.SetFont then
                        txt:SetFont(f)
                    end
                end
            end)
        end

        -- KC_IsBotOrAI
        local function KC_IsBotOrAI(pawn)
            if not pawn then
                return false
            end
            local r = false
            -- T
            local function T(v)
                if v == true or v == 1 then
                    r = true
                end
            end
            pcall(function()
                if Game and Game.IsAI then
                    T(Game:IsAI(pawn))
                end
            end)
            if r then
                return true
            end
            pcall(function()
                if Game and Game.IsBot then
                    T(Game:IsBot(pawn))
                end
            end)
            if r then
                return true
            end
            pcall(function()
                if pawn.IsAI then
                    T(pawn:IsAI())
                end
            end)
            if r then
                return true
            end
            pcall(function()
                if pawn.IsBot then
                    T(pawn:IsBot())
                end
            end)
            if r then
                return true
            end
            pcall(function()
                T(pawn.bIsAI)
            end)
            if r then
                return true
            end
            pcall(function()
                T(pawn.bIsBot)
            end)
            if r then
                return true
            end
            pcall(function()
                local ps = pawn.PlayerState
                if isValid(ps) then
                    if ps.IsAI then
                        T(ps:IsAI())
                    end
                    if ps.IsBot then
                        T(ps:IsBot())
                    end
                    T(ps.bIsAI)
                    T(ps.bIsBot)
                end
            end)
            return r
        end

        -- KC_IsAlive
        local function KC_IsAlive(pawn)
            if not isValid(pawn) then
                return false
            end
            local hs = nil
            pcall(function()
                hs = pawn.HealthStatus
            end)
            if hs ~= nil then
                return (hs ~= 2 and hs ~= 3)
            end
            local alive = false
            pcall(function()
                if pawn.IsAlive then
                    alive = (pawn:IsAlive() == true)
                end
            end)
            return alive
        end

        -- KC_GetTeamID
        local function KC_GetTeamID(pawn)
            local teamID = 0
            pcall(function()
                if pawn.TeamID ~= nil then
                    teamID = pawn.TeamID
                end
            end)
            if teamID == 0 then
                pcall(function()
                    local ps = pawn.PlayerState
                    if isValid(ps) and ps.TeamID ~= nil then
                        teamID = ps.TeamID
                    end
                end)
            end
            return teamID
        end

        -- KC_MakeBox
        local function KC_MakeBox(canvas, xPos, bgColor, label)
            if not canvas or not isValid(canvas) then
                return nil, nil
            end

            local border = NewUMG("/Script/UMG.Border", canvas)
            if not border or not isValid(border) then
                return nil, nil
            end
            local text = NewUMG("/Script/UMG.TextBlock", canvas)
            if not text or not isValid(text) then
                pcall(function()
                    border:RemoveFromParent()
                end)
                return nil, nil
            end

            pcall(function()
                if border.SetContent then
                    border:SetContent(text)
                end
            end)
            pcall(function()
                if border.SetPadding and FMargin then
                    border:SetPadding(FMargin(4, 2, 4, 2))
                end
            end)
            pcall(function()
                if border.SetBrushColor then
                    border:SetBrushColor(bgColor)
                end
            end)
            pcall(function()
                if border.SetVisibility then
                    border:SetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
                end
            end)

            pcall(function()
                if text.SetJustification then
                    text:SetJustification(1)
                end
            end)
            pcall(function()
                if text.SetColorAndOpacity then
                    text:SetColorAndOpacity(C_TX_WHITE)
                end
            end)
            pcall(function()
                if text.SetVisibility then
                    text:SetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
                end
            end)
            SetFontSize(text, KC_FONT)
            ClearOutlineAndShadow(text)
            pcall(function()
                if text.SetText then
                    text:SetText(label or "")
                end
            end)

            local slot = nil
            pcall(function()
                slot = canvas:AddChildToCanvas(border)
            end)
            if not slot then
                pcall(function()
                    border:RemoveFromParent()
                end)
                pcall(function()
                    text:RemoveFromParent()
                end)
                return nil, nil
            end

            pcall(function()
                if slot.SetAlignment then
                    slot:SetAlignment(vec2(0.5, 0.0))
                end
            end)
            pcall(function()
                if slot.SetAutoSize then
                    slot:SetAutoSize(false)
                end
            end)
            pcall(function()
                if slot.SetSize then
                    slot:SetSize(vec2(KC_BOX_W, KC_BOX_H))
                end
            end)
            pcall(function()
                if slot.SetZOrder then
                    slot:SetZOrder(12000)
                end
            end)
            pcall(function()
                if slot.SetPosition then
                    slot:SetPosition(vec2(xPos, KC_Y))
                end
            end)

            return border, text, slot
        end

        -- KC_Drop
        local function KC_Drop()
            if isValid(CounterState.boxReal) then
                pcall(function()
                    CounterState.boxReal:RemoveFromParent()
                end)
            end
            if isValid(CounterState.boxBot) then
                pcall(function()
                    CounterState.boxBot:RemoveFromParent()
                end)
            end
            CounterState.boxReal, CounterState.txtReal = nil, nil
            CounterState.boxBot, CounterState.txtBot = nil, nil
            CounterState.lastText = nil
            CounterState.drops = (CounterState.drops or 0) + 1
        end

        -- KC_EnsureBoxes
        local function KC_EnsureBoxes(canvas)
            if isValid(CounterState.boxReal) and isValid(CounterState.boxBot) then
                return true
            end

            KC_Drop()

            local vpX = 1920
            pcall(function()
                local UIUtil = nil
                local ok, mod = pcall(require, "client.common.ui_util")
                if ok then
                    UIUtil = mod
                end
                local vp = nil
                if UIUtil and UIUtil.GetViewportSize then
                    vp = UIUtil.GetViewportSize()
                end
                if vp and vp.X and vp.X > 0 then
                    vpX = vp.X
                end
            end)

            local centerX = vpX * 0
            local totalW = KC_BOX_W * 2 + KC_GAP
            local realX = centerX - totalW * -7.66 + KC_BOX_W * -7.66
            local botX = realX + KC_BOX_W + KC_GAP

            local rBox, rTxt = KC_MakeBox(canvas, realX, C_BG_RED, "REAL: 0")
            local bBox, bTxt = KC_MakeBox(canvas, botX, C_BG_GREEN, "BOT: 0")

            if not (isValid(rBox) and isValid(bBox)) then
                if isValid(rBox) then
                    pcall(function()
                        rBox:RemoveFromParent()
                    end)
                end
                if isValid(bBox) then
                    pcall(function()
                        bBox:RemoveFromParent()
                    end)
                end
                return false
            end

            CounterState.boxReal, CounterState.txtReal = rBox, rTxt
            CounterState.boxBot, CounterState.txtBot = bBox, bTxt
            CounterState.builds = (CounterState.builds or 0) + 1
            return true
        end

        -- KC_Parent
        local function KC_Parent()
            local tools = nil
            local ok, mod = pcall(require, "GameLua.Mod.BaseMod.Common.UI.InGameUITools")
            if ok then
                tools = mod
            end
            if not tools then
                return nil
            end
            local root = nil
            pcall(function()
                root = tools.GetMainControlBaseUI and tools.GetMainControlBaseUI()
            end)
            if not root or not isValid(root) then
                return nil
            end
            local p = root.CanvasPanel_0 or root.CanvasPanel_42
            if p and isValid(p) then
                return p
            end
            return nil
        end

        -- KC_Canvas
        local function KC_Canvas()
            if CounterState.canvas and isValid(CounterState.canvas) then
                return CounterState.canvas
            end
            if CounterState.boxReal or CounterState.boxBot then
                KC_Drop()
            end
            CounterState.canvas = nil
            local parent = KC_Parent()
            if not parent then
                return nil
            end
            local cv = NewUMG("/Script/UMG.CanvasPanel", parent)
            if not cv or not isValid(cv) then
                return nil
            end
            local slot = nil
            pcall(function()
                slot = parent:AddChildToCanvas(cv)
            end)
            if not slot then
                pcall(function()
                    cv:RemoveFromParent()
                end)
                return nil
            end
            pcall(function()
                slot:SetAutoSize(false)
            end)
            pcall(function()
                slot:SetZOrder(11900)
            end)
            CounterState.canvas = cv
            CounterState.lastText = nil
            return cv
        end

        local Counter = {
            Version = "EnemyCounter.1",
            State = CounterState,
        }
        _G.EnemyCounter = Counter

        -- IsEnabled
        function Counter.IsEnabled()
            local c = _G.LexusConfig
            if c and c.EnemyCounterEnabled ~= nil then
                return c.EnemyCounterEnabled == true
            end
            return _G.Mod_EnemyCounter_Enabled == true
        end

        Counter.TimerId = nil
        Counter.TimerOwner = nil

        -- EnsureTimer
        function Counter.EnsureTimer()
            local owner = Counter.TimerOwner
            if Counter.TimerId and isValid(owner) and owner.RemoveGameTimer then
                return true
            end
            Counter.TimerId = nil
            Counter.TimerOwner = nil
            local pc = (GetActivePlayerController and GetActivePlayerController()) or nil
            if not isValid(pc) or not pc.AddGameTimer then
                return false
            end
            local id = nil
            local ok = pcall(function()
                id = pc:AddGameTimer(0.5, true, function()
                    pcall(Counter.Tick)
                end)
            end)
            if ok and id then
                Counter.TimerId = id
                Counter.TimerOwner = pc
                return true
            end
            return false
        end

        -- StopTimer
        function Counter.StopTimer()
            local owner, id = Counter.TimerOwner, Counter.TimerId
            if id and isValid(owner) and owner.RemoveGameTimer then
                pcall(owner.RemoveGameTimer, owner, id)
            end
            Counter.TimerId = nil
            Counter.TimerOwner = nil
        end

        -- SetEnabled
        function Counter.SetEnabled(v)
            _G.Mod_EnemyCounter_Enabled = (v == true or v == 1)
            _G.LexusConfig = _G.LexusConfig or {}
            _G.LexusConfig.EnemyCounterEnabled = _G.Mod_EnemyCounter_Enabled
            if _G.Mod_EnemyCounter_Enabled then
                pcall(Counter.EnsureTimer)
            end
            if not _G.Mod_EnemyCounter_Enabled then
                if isValid(CounterState.boxReal) then
                    pcall(function()
                        CounterState.boxReal:SetVisibility(UEnums.ESlateVisibility.Collapsed)
                    end)
                end
                if isValid(CounterState.boxBot) then
                    pcall(function()
                        CounterState.boxBot:SetVisibility(UEnums.ESlateVisibility.Collapsed)
                    end)
                end
            else
                CounterState.lastText = nil
            end
            return true
        end

        -- Destroy
        function Counter.Destroy()
            Counter.StopTimer()
            KC_Drop()
            if CounterState.canvas and isValid(CounterState.canvas) then
                pcall(function()
                    CounterState.canvas:RemoveFromParent()
                end)
            end
            CounterState.canvas = nil
            CounterState.ctl = nil
            CounterState.pawn = nil
            CounterState.lastText = nil
            CounterState.lastCount = nil
        end

        -- KC_CollectPawns
        local function KC_CollectPawns()
            local list = nil
            if _G.GetCachedPlayerPawns then
                local ok, cached = pcall(_G.GetCachedPlayerPawns)
                if ok and type(cached) == "table" and #cached > 0 then
                    list = cached
                end
            end
            if not list then
                pcall(function()
                    if Game and Game.GetAllPlayerPawns then
                        list = Game:GetAllPlayerPawns()
                    end
                end)
            end
            return list or {}
        end

        -- Tick
        function Counter.Tick(controller, currentPawn)
            CounterState.ticks = (CounterState.ticks or 0) + 1

            if not Counter.IsEnabled() then
                if isValid(CounterState.boxReal) then
                    pcall(function()
                        CounterState.boxReal:SetVisibility(UEnums.ESlateVisibility.Collapsed)
                    end)
                end
                if isValid(CounterState.boxBot) then
                    pcall(function()
                        CounterState.boxBot:SetVisibility(UEnums.ESlateVisibility.Collapsed)
                    end)
                end
                return
            end

            local pc = controller
            if not isValid(pc) then
                pc = (GetActivePlayerController and GetActivePlayerController()) or nil
            end
            local pawn = currentPawn
            if not isValid(pawn) then
                pcall(function()
                    if GameplayData and GameplayData.GetLocalCharacter then
                        pawn = GameplayData.GetLocalCharacter()
                    end
                end)
            end
            if not isValid(pc) or not isValid(pawn) then
                return
            end

            local canvas = KC_Canvas()
            if not canvas then
                return
            end

            CounterState.ctl, CounterState.pawn = pc, pawn

            local myTeamID = KC_GetTeamID(pawn)
            local playerCount, botCount = 0, 0
            local livePawns = KC_CollectPawns()
            for _, p in pairs(livePawns) do
                if isValid(p) and p ~= pawn then
                    local sameTeam = false
                    pcall(function()
                        if p.TeamID ~= nil and p.TeamID == myTeamID then
                            sameTeam = true
                        end
                    end)
                    if not sameTeam and KC_IsAlive(p) then
                        if KC_IsBotOrAI(p) then
                            botCount = botCount + 1
                        else
                            playerCount = playerCount + 1
                        end
                    end
                end
            end
            CounterState.lastCount = { players = playerCount, bots = botCount }

            local key = playerCount .. "|" .. botCount
            if CounterState.lastText == key then
                if isValid(CounterState.boxReal) then
                    pcall(function()
                        CounterState.boxReal:SetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
                    end)
                end
                if isValid(CounterState.boxBot) then
                    pcall(function()
                        CounterState.boxBot:SetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
                    end)
                end
                return
            end

            if not KC_EnsureBoxes(canvas) then
                return
            end

            if isValid(CounterState.txtReal) then
                pcall(function()
                    CounterState.txtReal:SetText(string.format("REAL %d", playerCount))
                end)
            end
            if isValid(CounterState.txtBot) then
                pcall(function()
                    CounterState.txtBot:SetText(string.format("BOT %d", botCount))
                end)
            end

            if isValid(CounterState.boxReal) then
                pcall(function()
                    CounterState.boxReal:SetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
                end)
            end
            if isValid(CounterState.boxBot) then
                pcall(function()
                    CounterState.boxBot:SetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
                end)
            end

            CounterState.lastText = key
        end

        -- Debug
        function Counter.Debug()
            return {
                enabled = Counter.IsEnabled(),
                ticks = CounterState.ticks or 0,
                builds = CounterState.builds or 0,
                drops = CounterState.drops or 0,
                lastText = CounterState.lastText,
                hasCanvas = (CounterState.canvas and isValid(CounterState.canvas)) and true or false,
                hasBoxes = (isValid(CounterState.boxReal) and isValid(CounterState.boxBot)) and true or false,
            }
        end
    end

    -- ============================================================================
    -- // NATIVE ESP SWITCHES / PALETTE //
    -- ============================================================================
    -- StartESPTimers
    local function StartESPTimers(pc)
        local timerOwner = GetActivePlayerController(pc)
        if not Valid(timerOwner) then
            return
        end
        ClearModTimers(timerOwner)
        AddModTimer(timerOwner, 2.0, true, Tick_HealthBarESP)
        AddModTimer(timerOwner, 2.0, true, Tick_BoxESP)
        AddModTimer(timerOwner, 3.0, true, Tick_MapESP)
        if _G.EnemyCounter and _G.EnemyCounter.EnsureTimer then
            pcall(_G.EnemyCounter.EnsureTimer)
        end
    end
    _G.StartESPTimers = StartESPTimers

    local COLOR_PALETTE = {
        [0] = { R = 255, G = 0, B = 0 },
        [1] = { R = 0, G = 255, B = 255 },
        [2] = { R = 255, G = 255, B = 0 },
        [3] = { R = 0, G = 255, B = 0 },
        [4] = { R = 128, G = 0, B = 255 },
        [5] = { R = 255, G = 255, B = 255 },
        [6] = { R = 255, G = 0, B = 140 },
        [7] = { R = 55, G = 255, B = 20 },
    }
    _G._WH_ConfigVersion = _G._WH_ConfigVersion or 0
    local _WH_LINEAR_COLOR_CACHE = {}
    local _WH_LINEAR_COLOR_CACHE_COUNT = 0
    local _WH_LC_Class = LinearColor or (pcall(import, "LinearColor") and import("LinearColor")) or nil

    -- GetLinearColor
    local function GetLinearColor(idx)
        local intensity = (_G.LexusConfig and _G.LexusConfig.GlowIntensity) or 60
        local cacheKey = (idx or 0) * 1000 + intensity
        if not _G._WH_ForceUpdate and _WH_LINEAR_COLOR_CACHE[cacheKey] then
            return _WH_LINEAR_COLOR_CACHE[cacheKey]
        end
        local c = COLOR_PALETTE[idx] or COLOR_PALETTE[0]
        local mult = 1.0 + (intensity / 100.0) * 39.52
        local r = (c.R / 255.0) * mult
        local g = (c.G / 255.0) * mult
        local b = (c.B / 255.0) * mult
        local lc = nil
        if _WH_LC_Class then
            local ok, res = pcall(_WH_LC_Class, r, g, b, 1.0)
            if ok and res ~= nil then
                lc = res
            end
        end
        if not lc then
            lc = { R = r, G = g, B = b, A = 1.0, r = r, g = g, b = b, a = 1.0 }
        end
        if _WH_LINEAR_COLOR_CACHE_COUNT < 128 then
            _WH_LINEAR_COLOR_CACHE[cacheKey] = lc
            _WH_LINEAR_COLOR_CACHE_COUNT = _WH_LINEAR_COLOR_CACHE_COUNT + 1
        end
        return lc
    end

    -- GetSnaplineColor
    local function GetSnaplineColor(idx, alpha)
        local a = alpha or 0.95
        local c = COLOR_PALETTE[idx] or COLOR_PALETTE[0]
        local r, g, b = c.R / 255.0, c.G / 255.0, c.B / 255.0
        if _WH_LC_Class then
            local ok, res = pcall(_WH_LC_Class, r, g, b, a)
            if ok and res ~= nil then
                return res
            end
        end
        return { R = r, G = g, B = b, A = a }
    end

    local _ASTExtraVehicleBase = (pcall(import, "STExtraVehicleBase") and import("STExtraVehicleBase")) or nil

    -- IsVehicleActor
    local function IsVehicleActor(actor)
        if not actor or not Valid(actor) then
            return true
        end
        if _G.Game and type(_G.Game.IsVehicle) == "function" then
            local ok, isV = pcall(_G.Game.IsVehicle, _G.Game, actor)
            if ok and isV == true then
                return true
            end
        end
        if _ASTExtraVehicleBase and type(actor.IsA) == "function" then
            local ok, isA = pcall(actor.IsA, actor, _ASTExtraVehicleBase)
            if ok and isA == true then
                return true
            end
        end
        if actor.VehicleCommon or actor.VehicleMovement or actor.VehicleSeatComponent or actor.bIsVehicle then
            return true
        end
        if type(actor.GetVehicleCommon) == "function" then
            local ok, vc = pcall(actor.GetVehicleCommon, actor)
            if ok and Valid(vc) then
                return true
            end
        end
        local hasCharMove = false
        if actor.STCharacterMovement or actor.CharacterMovement then
            hasCharMove = true
        elseif type(actor.GetCharacterMovement) == "function" then
            local ok, cm = pcall(actor.GetCharacterMovement, actor)
            if ok and Valid(cm) then
                hasCharMove = true
            end
        end
        if not hasCharMove then
            return true
        end
        return false
    end

    -- ESP_Install
    function _G.ESP_Install(pc)
        pcall(function()
            if _G.LexusConfig.ESP_All then
                if _G.StartESPTimers then
                    _G.StartESPTimers(pc)
                end
            end
            if _G.LexusConfig.VehicleESPEnabled and _G.StartVehicleTimer then
                _G.StartVehicleTimer(pc)
            end
            if _G.LexusConfig.LootESPEnabled and _G.StartLootTimer then
                _G.StartLootTimer(pc)
            end
            if _G.LexusConfig.SmallCrosshairEnabled and _G.ApplySmallCrosshair then
                pcall(_G.ApplySmallCrosshair, true)
            end
            if _G.LexusConfig.TrackingMode == 2 or _G.LexusConfig.SnaplineESPEnabled then
                if _G.StartSnaplineLoop then
                    _G.StartSnaplineLoop(pc)
                end
            end
        end)
    end
    -- ESP_Uninstall
    function _G.ESP_Uninstall()
        pcall(function()
            if _G.ClearESPTimers then
                _G.ClearESPTimers()
            end
            if _G.ClearAllVehicleESP then
                _G.ClearAllVehicleESP()
            end
            if _G.ClearAllLootESP then
                _G.ClearAllLootESP()
            end
            if _G.StopSnaplineLoop then
                _G.StopSnaplineLoop()
            end
            if _G.ClearAllSnapLines then
                _G.ClearAllSnapLines()
            end
        end)
    end
    -- ESP_SetMaster
    function _G.ESP_SetMaster(on)
        _G.LexusConfig.ESP_All = (on ~= false)
        local pc = _G.GetActivePlayerController and _G.GetActivePlayerController()
        if on ~= false then
            _G.ESP_Install(pc)
        else
            _G.ESP_Uninstall()
        end
    end

    local LAG_CFG_FILE = "ADITYA_LAG_ESP_settings.lua"
    local LAG_CFG_KEYS = {
        "ESP_All",
        "HealthBarESPEnabled",
        "BoxESPEnabled",
        "MapESPEnabled",
        "EnemyCounterEnabled",
        "VehicleESPEnabled",
        "LootESPEnabled",
    }
    -- lagCfgPaths
    local function lagCfgPaths()
        local out = {}
        local ok, paths = pcall(g_adityaorg_ESPSettingsPaths)
        if ok and type(paths) == "table" then
            for _, p in ipairs(paths) do
                out[#out + 1] = (tostring(p):gsub("ADITYA_UMG_ESP_settings%.lua$", LAG_CFG_FILE))
            end
        end
        return out
    end
    -- lagSaveCfg
    local function lagSaveCfg()
        pcall(function()
            _G.LexusConfig = _G.LexusConfig or {}
            local lines = { "return {" }
            for _, k in ipairs(LAG_CFG_KEYS) do
                lines[#lines + 1] = "  " .. k .. " = " .. tostring(_G.LexusConfig[k] == true) .. ","
            end
            lines[#lines + 1] = "}"
            local payload = table.concat(lines, "\n")
            for _, p in ipairs(lagCfgPaths()) do
                local f = io.open(p, "w")
                if f then
                    f:write(payload)
                    f:flush()
                    f:close()
                    break
                end
            end
        end)
    end
    -- lagLoadCfg
    local function lagLoadCfg()
        pcall(function()
            _G.LexusConfig = _G.LexusConfig or {}
            for _, p in ipairs(lagCfgPaths()) do
                local f = io.open(p, "r")
                if f then
                    local c = f:read("*a")
                    f:close()
                    if type(c) == "string" then
                        for k, v in c:gmatch("([%w_]+)%s*=%s*(%a+)") do
                            if v == "true" or v == "false" then
                                _G.LexusConfig[k] = (v == "true")
                            end
                        end
                    end
                    break
                end
            end
        end)
    end
    lagLoadCfg()

    _G.LAG_ESP_Toggle = function(flag, val)
        _G.LexusConfig = _G.LexusConfig or {}
        _G.LexusConfig[flag] = (val == true or val == 1)
        if val == true or val == 1 then
            _G.LexusConfig.ESP_All = true
        end
        if flag == "EnemyCounterEnabled" and _G.EnemyCounter and _G.EnemyCounter.SetEnabled then
            pcall(_G.EnemyCounter.SetEnabled, _G.LexusConfig[flag])
        end
        local pc = GetActivePlayerController()
        if _G.ESP_Install and pc then
            pcall(function()
                _G.ESP_Install(pc)
            end)
        end
        lagSaveCfg()
        return true
    end

    _G.LAG_ESP_GetAll = function()
        local c = _G.LexusConfig
        return (
            c
            and c.HealthBarESPEnabled
            and c.BoxESPEnabled
            and c.MapESPEnabled
            and c.EnemyCounterEnabled
            and c.VehicleESPEnabled
            and c.LootESPEnabled
        )
                and true
            or false
    end
    _G.LAG_ESP_SetAll = function(val)
        val = (val == true or val == 1)
        _G.LexusConfig = _G.LexusConfig or {}
        for _, k in ipairs({
            "HealthBarESPEnabled",
            "BoxESPEnabled",
            "MapESPEnabled",
            "EnemyCounterEnabled",
            "VehicleESPEnabled",
            "LootESPEnabled",
            "SnaplineESPEnabled",
        }) do
            _G.LexusConfig[k] = val
        end
        _G.LexusConfig.ESP_All = val
        local pc = GetActivePlayerController()
        if _G.ESP_Install and pc then
            pcall(function()
                _G.ESP_Install(pc)
            end)
        end
        lagSaveCfg()
        return true
    end

    -- Shared palette helpers are defined once in native ESP configuration.

    -- ============================================================================
    -- // SNAPLINE / VISIBILITY / LINE WIDGETS //
    -- ============================================================================
    local _ci_KSL = UKismetSystemLibrary or import("KismetSystemLibrary")
    local _ci_GameplayStatics = GameplayStatics or import("GameplayStatics")
    local _ci_HitResultClass = import("HitResult") or import("/Script/Engine.HitResult")
    local _ci_FVector = FVector or import("Vector") or import("/Script/CoreUObject.Vector")
    local _ci_SBL = SlateBlueprintLibrary
        or import("SlateBlueprintLibrary")
        or import("/Script/UMG.SlateBlueprintLibrary")
    local _ci_WLL = WidgetLayoutLibrary or import("WidgetLayoutLibrary") or import("/Script/UMG.WidgetLayoutLibrary")
    local slua = _slua or rawget(_G, "slua") or slua or { isValid = Valid }
    local UEnums = UEnums or rawget(_G, "UEnums") or { ESlateVisibility = { Collapsed = 1, SelfHitTestInvisible = 2 } }
    local _cached_GameplayData = _cached_GameplayData or GameplayData

    local FLinearColor = import("LinearColor") or _G.FLinearColor or LinearColor
    local FVector2D = import("Vector2D") or _G.FVector2D
    local FVector = import("Vector") or _G.FVector

    local _SnaplinePawnsPool = {}
    local _tempHeadLoc = FVector and FVector(0, 0, 0) or { X = 0, Y = 0, Z = 0 }
    local CK_BOT_VIS, CK_BOT_HID = "BOT_VIS", "BOT_HID"
    local CK_ENEMY_VIS, CK_ENEMY_HID = "ENEMY_VIS", "ENEMY_HID"

    local SnaplineESP = {
        ESPCanvas = nil,
        _CurrentBaseUI = nil,
        SnapLineWidgets = {},
        _WidgetPool = {},
        bUseSnapLines = true,
        SnapLineThickness = 1.7,
        SnapLineOriginY = 50.0,
        SnapLineOriginOffsetX = 0.0,
        SnapLineHeadOffsetX = 0.0,
        SnapLineHeadOffsetY = -14.0,
        SnapLineEnemyColor = FLinearColor and FLinearColor(1.0, 0.15, 0.15, 0.85) or nil,
        SnapLineEnemyVisibleColor = FLinearColor and FLinearColor(0.0, 1.0, 0.2, 0.95) or nil,
        SnapLineBotColor = FLinearColor and FLinearColor(1.0, 1.0, 1.0, 0.85) or nil,
        SnapLineBotVisibleColor = FLinearColor and FLinearColor(1.0, 1.0, 0.0, 0.95) or nil,
        _CanvasScaleX = 1.0,
        _CanvasScaleY = 1.0,
        _CanvasOffsetX = 0.0,
        _CanvasOffsetY = 0.0,
        _lastTransformTime = 0,
        _CachedTopCenterPixel = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 },
        _cachedViewportW = 1920,
        _cachedViewportH = 1080,
        _CachedFromX = 0,
        _CachedFromY = 0,
        _lastStartPosTime = 0,
        _tempScreenPixelPos = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 },
        _tempCanvasPos = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 },
        _ZeroVector = nil,
        _CachedHitResult = nil,
    }
    _G.SnaplineESP = SnaplineESP

    -- GetMyControllerAndPlayer
    function SnaplineESP.GetMyControllerAndPlayer()
        local pc, player = nil, nil
        local GDP = _cached_GameplayData
        if not GDP then
            local ok
            ok, GDP = pcall(require, "GameLua.GameCore.Data.GameplayData")
            if ok then
                _cached_GameplayData = GDP
            end
        end
        if GDP then
            if GDP.GetPlayerController then
                pc = GDP.GetPlayerController()
            end
            if GDP.GetPlayerCharacter then
                player = GDP.GetPlayerCharacter()
            end
        end
        if (not pc or not slua.isValid(pc)) and slua_GameFrontendHUD then
            pcall(function()
                pc = slua_GameFrontendHUD:GetPlayerController()
            end)
        end
        if (not pc or not slua.isValid(pc)) and GetActivePlayerController then
            pc = GetActivePlayerController()
        end
        if pc and (not player or not slua.isValid(player)) and pc.GetPlayerCharacterSafety then
            pcall(function()
                player = pc:GetPlayerCharacterSafety()
            end)
        end
        if pc and (not player or not slua.isValid(player)) and pc.GetPawn then
            pcall(function()
                player = pc:GetPawn()
            end)
        end
        if (not player or not slua.isValid(player)) and GetLocalPlayer then
            player = GetLocalPlayer(pc)
        end
        return pc, player
    end

    -- GetAllPawns
    function SnaplineESP.GetAllPawns()
        local source = MeowPerf.PlayerPawns and MeowPerf.PlayerPawns()
        if source then
            return source
        end
        local ok, pawns = GetCachedPlayerPawns()
        return ok and pawns or _SnaplinePawnsPool
    end

    -- ClearAllSnapLines
    function SnaplineESP.ClearAllSnapLines()
        for KeyStr, LineData in pairs(SnaplineESP.SnapLineWidgets) do
            if LineData and LineData.Widget and slua.isValid(LineData.Widget) then
                MeowPerf.HideLine(LineData)
                local pool = SnaplineESP._WidgetPool
                if not pool then
                    pool = {}
                    SnaplineESP._WidgetPool = pool
                end
                table.insert(pool, LineData)
            end
        end
        SnaplineESP.SnapLineWidgets = {}
    end
    SnaplineESP.Clear = SnaplineESP.ClearAllSnapLines

    -- Reset
    function SnaplineESP.Reset()
        SnaplineESP.ClearAllSnapLines()
        SnaplineESP.ESPCanvas = nil
        SnaplineESP._WidgetPool = {}
        SnaplineESP._CurrentBaseUI = nil
        SnaplineESP._lastTransformTime = 0
        SnaplineESP._lastStartPosTime = 0
        SnaplineESP._CachedFromX = 0
        SnaplineESP._CachedFromY = 0
    end

    -- InitESPCanvas
    function SnaplineESP.InitESPCanvas()
        local ok, InGameUITools = pcall(require, "GameLua.Mod.BaseMod.Common.UI.InGameUITools")
        if not ok or not InGameUITools then
            return false
        end
        local MainControlBaseUI = nil
        pcall(function()
            MainControlBaseUI = InGameUITools.GetMainControlBaseUI and InGameUITools.GetMainControlBaseUI()
        end)
        if not MainControlBaseUI or not slua.isValid(MainControlBaseUI) then
            return false
        end

        if SnaplineESP._CurrentBaseUI ~= MainControlBaseUI then
            SnaplineESP.Reset()
            SnaplineESP._CurrentBaseUI = MainControlBaseUI
        end

        if SnaplineESP.ESPCanvas and slua.isValid(SnaplineESP.ESPCanvas) then
            return true
        end

        local ParentCanvas = nil
        if MainControlBaseUI.CanvasPanel_0 and slua.isValid(MainControlBaseUI.CanvasPanel_0) then
            ParentCanvas = MainControlBaseUI.CanvasPanel_0
        elseif MainControlBaseUI.CanvasPanel_42 and slua.isValid(MainControlBaseUI.CanvasPanel_42) then
            ParentCanvas = MainControlBaseUI.CanvasPanel_42
        end

        if not ParentCanvas or not slua.isValid(ParentCanvas) then
            return false
        end
        SnaplineESP.ESPCanvas = ParentCanvas
        return true
    end

    -- UpdateCanvasTransform
    function SnaplineESP.UpdateCanvasTransform(PC)
        if not SnaplineESP.ESPCanvas or not slua.isValid(SnaplineESP.ESPCanvas) then
            return
        end
        local now = os.clock()
        if
            SnaplineESP._lastTransformTime
            and (now - SnaplineESP._lastTransformTime < 0.05)
            and SnaplineESP._CanvasScaleX
            and SnaplineESP._CanvasScaleX > 0
        then
            return
        end
        SnaplineESP._lastTransformTime = now

        local success = false
        pcall(function()
            local SBL = _ci_SBL
            if SBL and SBL.AbsoluteToLocal then
                local cg = SnaplineESP.ESPCanvas:GetCachedGeometry()
                if cg then
                    if not SnaplineESP._tempScreenPixelPos then
                        SnaplineESP._tempScreenPixelPos = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 }
                    end
                    SnaplineESP._tempScreenPixelPos.X = 0
                    SnaplineESP._tempScreenPixelPos.Y = 0
                    local pt0 = SBL.AbsoluteToLocal(cg, SnaplineESP._tempScreenPixelPos)
                    SnaplineESP._tempScreenPixelPos.X = 100
                    SnaplineESP._tempScreenPixelPos.Y = 100
                    local pt1 = SBL.AbsoluteToLocal(cg, SnaplineESP._tempScreenPixelPos)
                    if pt0 and pt1 then
                        SnaplineESP._CanvasScaleX = (pt1.X - pt0.X) / 100
                        SnaplineESP._CanvasScaleY = (pt1.Y - pt0.Y) / 100
                        SnaplineESP._CanvasOffsetX = pt0.X
                        SnaplineESP._CanvasOffsetY = pt0.Y
                        success = true
                    end
                end
            end
        end)

        if not success then
            pcall(function()
                local WLL = _ci_WLL
                if WLL and WLL.ScreenToWidgetLocal then
                    local cg = SnaplineESP.ESPCanvas:GetCachedGeometry()
                    if cg then
                        local pt0 = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 }
                        local pt1 = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 }
                        local in0 = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 }
                        local in1 = FVector2D and FVector2D(100, 100) or { X = 100, Y = 100 }
                        WLL.ScreenToWidgetLocal(PC, cg, in0, pt0)
                        WLL.ScreenToWidgetLocal(PC, cg, in1, pt1)
                        SnaplineESP._CanvasScaleX = (pt1.X - pt0.X) / 100
                        SnaplineESP._CanvasScaleY = (pt1.Y - pt0.Y) / 100
                        SnaplineESP._CanvasOffsetX = pt0.X
                        SnaplineESP._CanvasOffsetY = pt0.Y
                        success = true
                    end
                end
            end)
        end

        if not success then
            local scale = 1.0
            local WLL = _ci_WLL
            if WLL and WLL.GetViewportScale then
                scale = WLL.GetViewportScale(PC) or 1.0
            end
            SnaplineESP._CanvasScaleX = 1.0 / scale
            SnaplineESP._CanvasScaleY = 1.0 / scale
            SnaplineESP._CanvasOffsetX = 0
            SnaplineESP._CanvasOffsetY = 0
        end
    end

    -- ScreenPixelToCanvasLocal
    function SnaplineESP.ScreenPixelToCanvasLocal(PC, ScreenPixelPos)
        if not ScreenPixelPos then
            return SnaplineESP._tempCanvasPos
        end
        local scaleX = SnaplineESP._CanvasScaleX or 1.0
        local scaleY = SnaplineESP._CanvasScaleY or 1.0
        local offsetX = SnaplineESP._CanvasOffsetX or 0
        local offsetY = SnaplineESP._CanvasOffsetY or 0
        local x = ScreenPixelPos.X * scaleX + offsetX
        local y = ScreenPixelPos.Y * scaleY + offsetY
        if not SnaplineESP._tempCanvasPos then
            SnaplineESP._tempCanvasPos = (FVector2D and FVector2D(x, y)) or { X = x, Y = y }
        else
            SnaplineESP._tempCanvasPos.X = x
            SnaplineESP._tempCanvasPos.Y = y
        end
        return SnaplineESP._tempCanvasPos
    end

    -- ProjectWorldToCanvasLocal
    function SnaplineESP.ProjectWorldToCanvasLocal(PC, WorldLoc)
        if not PC or not slua.isValid(PC) or not WorldLoc then
            return false, SnaplineESP._tempCanvasPos
        end
        if not SnaplineESP._tempScreenPixelPos then
            SnaplineESP._tempScreenPixelPos = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 }
        end
        SnaplineESP._tempScreenPixelPos.X = 0
        SnaplineESP._tempScreenPixelPos.Y = 0
        local bOK = false
        pcall(function()
            local res = PC:ProjectWorldLocationToScreen(WorldLoc, SnaplineESP._tempScreenPixelPos, true)
            if res == true or res == 1 then
                bOK = true
            end
        end)
        if not bOK or (SnaplineESP._tempScreenPixelPos.X == 0 and SnaplineESP._tempScreenPixelPos.Y == 0) then
            return false, SnaplineESP._tempCanvasPos
        end
        local CanvasLocalPos = SnaplineESP.ScreenPixelToCanvasLocal(PC, SnaplineESP._tempScreenPixelPos)
        return true, CanvasLocalPos
    end

    -- GetSnapLineStartPos
    function SnaplineESP.GetSnapLineStartPos(PC)
        local now = os.clock()
        if
            SnaplineESP._lastStartPosTime
            and (now - SnaplineESP._lastStartPosTime < 0.5)
            and SnaplineESP._CachedFromX
            and SnaplineESP._CachedFromX > 0
        then
            return SnaplineESP._CachedFromX, SnaplineESP._CachedFromY
        end
        SnaplineESP._lastStartPosTime = now

        local screenPixelW, screenPixelH = 0, 0
        local scale = 1.0

        pcall(function()
            if PC and PC.GetViewportSize then
                local vs = SnaplineESP._tempScreenPixelPos or (FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 })
                PC:GetViewportSize(vs)
                if vs and vs.X and vs.X > 200 then
                    screenPixelW = vs.X
                    screenPixelH = vs.Y
                end
            end
        end)
        if screenPixelW <= 200 then
            pcall(function()
                local WLL = _ci_WLL
                if WLL and WLL.GetViewportSize then
                    local vs = WLL.GetViewportSize(PC)
                    if vs and vs.X and vs.X > 200 then
                        screenPixelW = vs.X
                        screenPixelH = vs.Y
                    end
                end
            end)
        end
        pcall(function()
            local WLL = _ci_WLL
            if WLL and WLL.GetViewportScale then
                local s = WLL.GetViewportScale(PC)
                if s and type(s) == "number" and s > 0 then
                    scale = s
                end
            end
        end)
        if screenPixelW <= 200 then
            screenPixelW = (SnaplineESP._cachedViewportW or 1920) * scale
            screenPixelH = (SnaplineESP._cachedViewportH or 1080) * scale
        end

        if not SnaplineESP._CachedTopCenterPixel then
            SnaplineESP._CachedTopCenterPixel = FVector2D and FVector2D(0, 0) or { X = 0, Y = 0 }
        end
        SnaplineESP._CachedTopCenterPixel.X = screenPixelW / 2.0
        SnaplineESP._CachedTopCenterPixel.Y = (SnaplineESP.SnapLineOriginY or 50) * scale

        local fromCanvasPos = SnaplineESP.ScreenPixelToCanvasLocal(PC, SnaplineESP._CachedTopCenterPixel)
        local fromX = fromCanvasPos.X + (SnaplineESP.SnapLineOriginOffsetX or 0)
        local fromY = fromCanvasPos.Y

        SnaplineESP._CachedFromX = fromX
        SnaplineESP._CachedFromY = fromY
        return fromX, fromY
    end

    -- CreateSnapLine
    function SnaplineESP.CreateSnapLine()
        if not SnaplineESP.InitESPCanvas() then
            return nil
        end

        local pool = SnaplineESP._WidgetPool
        if not pool then
            pool = {}
            SnaplineESP._WidgetPool = pool
        end

        local Border = nil
        local Slot = nil

        for i = #pool, 1, -1 do
            local pooled = pool[i]
            if
                pooled
                and pooled.Widget
                and slua.isValid(pooled.Widget)
                and pooled.Slot
                and slua.isValid(pooled.Slot)
            then
                local isCurrent = false
                pcall(function()
                    if pooled.Widget.GetParent and pooled.Widget:GetParent() == SnaplineESP.ESPCanvas then
                        isCurrent = true
                    end
                end)
                if isCurrent then
                    Border = pooled.Widget
                    Slot = pooled.Slot
                    table.remove(pool, i)
                    break
                else
                    table.remove(pool, i)
                end
            else
                table.remove(pool, i)
            end
        end

        if not Border or not slua.isValid(Border) then
            pcall(function()
                Border = CGame:NewObjectFromPath("/Script/UMG.Border", SnaplineESP.ESPCanvas)
            end)
            if not Border or not slua.isValid(Border) then
                pcall(function()
                    Border = CGame.NewObjectFromPath("/Script/UMG.Border", SnaplineESP.ESPCanvas)
                end)
            end
            Slot = nil
        end
        if not Border or not slua.isValid(Border) then
            return nil
        end

        local color = SnaplineESP.SnapLineEnemyColor or (FLinearColor and FLinearColor(1.0, 0.15, 0.15, 0.85) or nil)
        if color then
            pcall(function()
                Border:SetBrushColor(color)
            end)
        end
        pcall(function()
            Border:SetWidgetVisibility(UEnums.ESlateVisibility.SelfHitTestInvisible)
        end)
        pcall(function()
            Border.RenderTransformPivot = FVector2D and FVector2D(0.0, 0.5) or { X = 0, Y = 0.5 }
        end)
        pcall(function()
            Border:SetRenderTransformPivot(FVector2D and FVector2D(0.0, 0.5) or { X = 0, Y = 0.5 })
        end)

        if not Slot or not slua.isValid(Slot) then
            pcall(function()
                Slot = SnaplineESP.ESPCanvas:AddChildToCanvas(Border)
                if Slot then
                    Slot:SetAutoSize(false)
                    Slot:SetZOrder(1)
                end
            end)
        end
        return { Widget = Border, Slot = Slot }
    end

    -- IsPlayerVisible
    function SnaplineESP.IsPlayerVisible(PC, Character)
        if not PC or not slua.isValid(PC) or not Character or not slua.isValid(Character) then
            return false
        end
        local now = MeowPerf.Now()
        local cache = SnaplineESP._VisibilityCache
        if not cache then
            cache = setmetatable({}, { __mode = "k" })
            SnaplineESP._VisibilityCache = cache
        end
        local record = cache[Character]
        if
            record
            and record.Controller == PC
            and now >= record.Time
            and now - record.Time < MeowPerformance.VisibilitySeconds
        then
            return record.Visible
        end
        if not record then
            record = {}
            cache[Character] = record
        end
        record.Controller, record.Time = PC, now
        local bVis = false
        pcall(function()
            if PC.LineOfSightTo then
                if not SnaplineESP._ZeroVector then
                    local VT = _ci_FVector
                    if VT then
                        SnaplineESP._ZeroVector = VT(0, 0, 0)
                    end
                end
                bVis = PC:LineOfSightTo(Character, SnaplineESP._ZeroVector, false)
            end
        end)
        if not bVis then
            local KismetSystemLibrary = _ci_KSL
            if KismetSystemLibrary and KismetSystemLibrary.LineTraceSingle then
                pcall(function()
                    local camMgr = nil
                    local GameplayStatics = _ci_GameplayStatics
                    if GameplayStatics and GameplayStatics.GetPlayerCameraManager then
                        camMgr = GameplayStatics.GetPlayerCameraManager(PC, 0)
                    end
                    local startLoc = camMgr and camMgr:GetCameraLocation()
                        or (
                            PC.GetPlayerCharacter
                            and PC:GetPlayerCharacter()
                            and PC:GetPlayerCharacter():K2_GetActorLocation()
                        )
                    local loc = Character.K2_GetActorLocation and Character:K2_GetActorLocation()
                    if startLoc and loc then
                        local hOffset = 75
                        if Character.bIsCrouched then
                            hOffset = 50
                        elseif Character.IsProne and Character:IsProne() then
                            hOffset = 25
                        end
                        _tempHeadLoc.X = loc.X
                        _tempHeadLoc.Y = loc.Y
                        _tempHeadLoc.Z = loc.Z + hOffset
                        if not SnaplineESP._CachedHitResult then
                            local HitResultClass = _ci_HitResultClass
                            SnaplineESP._CachedHitResult = HitResultClass and HitResultClass() or {}
                        end
                        local bHit = KismetSystemLibrary.LineTraceSingle(
                            PC,
                            startLoc,
                            _tempHeadLoc,
                            0,
                            false,
                            nil,
                            0,
                            SnaplineESP._CachedHitResult,
                            true
                        )
                        if bHit then
                            local hitActor = nil
                            if type(SnaplineESP._CachedHitResult.GetActor) == "function" then
                                hitActor = SnaplineESP._CachedHitResult:GetActor()
                            elseif SnaplineESP._CachedHitResult.Actor then
                                hitActor = SnaplineESP._CachedHitResult.Actor
                            end
                            if
                                hitActor
                                and (
                                    hitActor == Character
                                    or (type(hitActor.IsChildOf) == "function" and hitActor:IsChildOf(Character))
                                )
                            then
                                bVis = true
                            end
                        else
                            bVis = true
                        end
                    end
                end)
            end
        end
        record.Visible = bVis == true
        MeowPerf.Count("VisibilityTests")
        return record.Visible
    end

    -- UpdateSnapLine
    function SnaplineESP.UpdateSnapLine(KeyStr, CanvasPos, bOnScreen, fromX, fromY, Character, PC, isAI)
        if not SnaplineESP.ESPCanvas or not slua.isValid(SnaplineESP.ESPCanvas) then
            return
        end

        local LineData = SnaplineESP.SnapLineWidgets[KeyStr]

        if
            not bOnScreen
            or not CanvasPos
            or not Character
            or not slua.isValid(Character)
            or not PC
            or not slua.isValid(PC)
        then
            MeowPerf.HideLine(LineData)
            return
        end

        local bIsNew = false
        if not LineData then
            LineData = SnaplineESP.CreateSnapLine()
            if not LineData or not LineData.Widget or not LineData.Slot then
                return
            end
            SnaplineESP.SnapLineWidgets[KeyStr] = LineData
            bIsNew = true
        end

        local Widget = LineData.Widget
        local Slot = LineData.Slot

        if LineData._Visible ~= true then
            local shown = pcall(Widget.SetWidgetVisibility, Widget, UEnums.ESlateVisibility.SelfHitTestInvisible)
            if shown then
                LineData._Visible = true
            end
        end

        if not LineData._PivotSet then
            pcall(function()
                Widget.RenderTransformPivot = FVector2D and FVector2D(0.0, 0.5) or { X = 0, Y = 0.5 }
            end)
            pcall(function()
                Widget:SetRenderTransformPivot(FVector2D and FVector2D(0.0, 0.5) or { X = 0, Y = 0.5 })
            end)
            LineData._PivotSet = true
        end

        local bTargetVisible = SnaplineESP.IsPlayerVisible(PC, Character)
        local lineColor
        local cfg = _G.LexusConfig
        if cfg and cfg.WallHackEnabled then
            local colorIdx
            if isAI then
                colorIdx = bTargetVisible and (cfg.ColorBotWHVis or 1) or (cfg.ColorBotWHOcc or 3)
            else
                colorIdx = bTargetVisible and (cfg.ColorEnemyWHVis or 0) or (cfg.ColorEnemyWHOcc or 2)
            end
            lineColor = GetSnaplineColor(colorIdx, 0.95)
        else
            if isAI then
                lineColor = bTargetVisible and SnaplineESP.SnapLineBotVisibleColor or SnaplineESP.SnapLineBotColor
            else
                lineColor = bTargetVisible and SnaplineESP.SnapLineEnemyVisibleColor or SnaplineESP.SnapLineEnemyColor
            end
        end

        local paletteKey = MeowPerf.Palette(cfg)
        local colorKey = paletteKey
            .. ":"
            .. (
                isAI and (bTargetVisible and CK_BOT_VIS or CK_BOT_HID)
                or (bTargetVisible and CK_ENEMY_VIS or CK_ENEMY_HID)
            )
        if LineData._cachedColorKey ~= colorKey and lineColor then
            pcall(function()
                Widget:SetBrushColor(lineColor)
            end)
            LineData._cachedColorKey = colorKey
        end

        local toX = CanvasPos.X + (SnaplineESP.SnapLineHeadOffsetX or 0)
        local toY = CanvasPos.Y + (SnaplineESP.SnapLineHeadOffsetY or 0)

        local dx = toX - fromX
        local dy = toY - fromY
        local length = math.sqrt(dx * dx + dy * dy)
        local thickness = SnaplineESP.SnapLineThickness or 1.5

        local angle_rad = (math.atan2 and math.atan2(dy, dx)) or math.atan(dy, dx)
        local angle = angle_rad * 57.29577951308232

        if not LineData._CachedPosVec then
            LineData._CachedPosVec = FVector2D and FVector2D(fromX, fromY - thickness / 2.0)
                or { X = fromX, Y = fromY - thickness / 2.0 }
            LineData._CachedSizeVec = FVector2D and FVector2D(length, thickness) or { X = length, Y = thickness }
        else
            LineData._CachedPosVec.X = fromX
            LineData._CachedPosVec.Y = fromY - thickness / 2.0
            LineData._CachedSizeVec.X = length
            LineData._CachedSizeVec.Y = thickness
        end

        MeowPerf.LineGeometry(LineData, Widget, Slot, fromX, fromY - thickness / 2.0, length, thickness, angle, bIsNew)
    end

    -- RemoveSnapLine
    function SnaplineESP.RemoveSnapLine(KeyStr)
        local LineData = SnaplineESP.SnapLineWidgets[KeyStr]
        if LineData and LineData.Widget and slua.isValid(LineData.Widget) then
            MeowPerf.HideLine(LineData)
            local pool = SnaplineESP._WidgetPool
            if not pool then
                pool = {}
                SnaplineESP._WidgetPool = pool
            end
            table.insert(pool, LineData)
            SnaplineESP.SnapLineWidgets[KeyStr] = nil
        end
    end

    local _SnaplineSeen = {}
    -- Tick_SnaplineESP
    local function Tick_SnaplineESP()
        local isEnabled = _G.LunarLoginRuntime
            and _G.LunarLoginRuntime.Authorized
            and (_G.LexusConfig and (_G.LexusConfig.TrackingMode == 2 or _G.LexusConfig.SnaplineESPEnabled == true))
        if not isEnabled then
            if not SnaplineESP._Disabled then
                SnaplineESP.ClearAllSnapLines()
                SnaplineESP._Disabled = true
            end
            return
        end
        SnaplineESP._Disabled = false

        local pc, localPawn = SnaplineESP.GetMyControllerAndPlayer()
        if not pc or not slua.isValid(pc) or not localPawn or not slua.isValid(localPawn) then
            return
        end

        local myPos = nil
        pcall(function()
            myPos = localPawn:K2_GetActorLocation()
        end)
        if not myPos then
            return
        end

        local myTeamId = nil
        pcall(function()
            myTeamId = localPawn.TeamID or (localPawn.GetTeamID and localPawn:GetTeamID())
        end)

        if not SnaplineESP.InitESPCanvas() then
            return
        end
        local now = MeowPerf.Now()
        if
            SnaplineESP._TransformPC ~= pc
            or not SnaplineESP._TransformAt
            or now < SnaplineESP._TransformAt
            or now - SnaplineESP._TransformAt >= MeowPerformance.CanvasTransformSeconds
        then
            SnaplineESP.UpdateCanvasTransform(pc)
            SnaplineESP._TransformPC, SnaplineESP._TransformAt = pc, now
        end

        local allPawns = SnaplineESP.GetAllPawns()
        if not allPawns or #allPawns == 0 then
            if not SnaplineESP._Empty then
                SnaplineESP.ClearAllSnapLines()
                SnaplineESP._Empty = true
            end
            return
        end
        SnaplineESP._Empty = false

        local fromX, fromY = SnaplineESP.GetSnapLineStartPos(pc)

        for k in pairs(_SnaplineSeen) do
            _SnaplineSeen[k] = nil
        end

        for _, pawn in ipairs(allPawns) do
            if not pawn or not slua.isValid(pawn) or pawn == localPawn then
                goto continue
            end
            local hs = pawn.HealthStatus
            if not (pawn.TeamID and (myTeamId == nil or pawn.TeamID ~= myTeamId) and hs and hs ~= 2 and hs ~= 3) then
                goto continue
            end

            local pKey = pawn.PlayerKey
            if not pKey or pKey == 0 then
                goto continue
            end
            local isAI = ResolveIsAI(pKey, pawn)

            local pLoc = nil
            pcall(function()
                pLoc = pawn:K2_GetActorLocation()
            end)
            if not pLoc then
                goto continue
            end

            local dx = pLoc.X - myPos.X
            local dy = pLoc.Y - myPos.Y
            local dz = pLoc.Z - myPos.Z
            local distSq = dx * dx + dy * dy + dz * dz
            if distSq <= 0 or distSq > 1600000000 then
                goto continue
            end

            local hOffset = 75
            if pawn.bIsCrouched then
                hOffset = 50
            elseif pawn.IsProne and pawn:IsProne() then
                hOffset = 25
            end
            _tempHeadLoc.X = pLoc.X
            _tempHeadLoc.Y = pLoc.Y
            _tempHeadLoc.Z = pLoc.Z + hOffset

            local bOnScreen, CanvasPos = SnaplineESP.ProjectWorldToCanvasLocal(pc, _tempHeadLoc)
            local key = tostring(pKey)

            _SnaplineSeen[key] = true
            SnaplineESP.UpdateSnapLine(key, CanvasPos, bOnScreen, fromX, fromY, pawn, pc, isAI)
            ::continue::
        end

        for key, LineData in pairs(SnaplineESP.SnapLineWidgets) do
            if not _SnaplineSeen[key] then
                MeowPerf.HideLine(LineData)
            end
        end
    end

    _G._SnaplineLoopRunning = false
    _G._snaplineTimerStarted = false
    _G._snaplineTimerHandle = nil
    _G._snaplineTimerOwner = nil

    -- StartSnaplineLoop
    local function StartSnaplineLoop(passedOwner)
        if _G._snaplineTimerStarted and _G._snaplineTimerOwner and not Valid(_G._snaplineTimerOwner) then
            _G.StopSnaplineLoop()
        end
        if _G._snaplineTimerStarted and _G._snaplineTimerHandle then
            return
        end

        local timerOwner = nil
        if _G.Game and _G.Game.AddGameTimer then
            timerOwner = _G.Game
        elseif passedOwner and passedOwner.AddGameTimer and Valid(passedOwner) then
            timerOwner = passedOwner
        else
            local pc = GetActivePlayerController and GetActivePlayerController()
            if Valid(pc) and pc.AddGameTimer then
                timerOwner = pc
            end
            if not timerOwner and slua_GameFrontendHUD then
                pcall(function()
                    local pc2 = slua_GameFrontendHUD:GetPlayerController()
                    if Valid(pc2) and pc2.AddGameTimer then
                        timerOwner = pc2
                    end
                end)
            end
        end

        if not Valid(timerOwner) or not timerOwner.AddGameTimer then
            return
        end

        local ok, h = pcall(function()
            return timerOwner:AddGameTimer(1 / MeowPerformance.LineFPS, true, function()
                pcall(Tick_SnaplineESP)
            end)
        end)

        if ok and h then
            _G._snaplineTimerHandle = h
            _G._snaplineTimerOwner = timerOwner
            _G._snaplineTimerStarted = true
            _G._SnaplineLoopRunning = true
        end
    end

    -- StopSnaplineLoop
    local function StopSnaplineLoop()
        _G._SnaplineLoopRunning = false
        _G._snaplineTimerStarted = false

        if _G._snaplineTimerHandle and _G._snaplineTimerOwner and Valid(_G._snaplineTimerOwner) then
            pcall(function()
                if _G._snaplineTimerOwner.RemoveGameTimer then
                    _G._snaplineTimerOwner:RemoveGameTimer(_G._snaplineTimerHandle)
                end
            end)
        end
        _G._snaplineTimerHandle = nil
        _G._snaplineTimerOwner = nil
        SnaplineESP._VisibilityCache = nil
        SnaplineESP._TransformAt, SnaplineESP._TransformPC = nil, nil

        if SnaplineESP and SnaplineESP.Reset then
            pcall(SnaplineESP.Reset)
        end
    end

    _G.StartSnaplineLoop = StartSnaplineLoop
    _G.StopSnaplineLoop = StopSnaplineLoop
    _G.ClearAllSnapLines = function()
        if SnaplineESP and SnaplineESP.Reset then
            SnaplineESP.Reset()
        end
    end
    _G.Tick_SnaplineESP = Tick_SnaplineESP
    _G.PlayerMapMarker = SnaplineESP

    _G.LexusConfig = _G.LexusConfig or {}
    if _G.LexusConfig.SmallCrosshairEnabled == nil then
        _G.LexusConfig.SmallCrosshairEnabled = false
    end

    -- ============================================================================
    -- // SMALL CROSSHAIR //
    -- ============================================================================
    local crosshairOriginalCache = {}
    -- ApplySmallCrosshair
    local function ApplySmallCrosshair(force)
        pcall(function()
            local pc = GetActivePlayerController()
            local char = GetLocalPlayer(pc)
            if not Valid(char) then
                return
            end
            local wm = char.WeaponManagerComponent or (char.GetWeaponManager and char:GetWeaponManager())
            if not Valid(wm) then
                return
            end

            local targetWeapons = {}
            local curW = (wm.GetCurrentUsingWeapon and wm:GetCurrentUsingWeapon())
                or wm.CurrentWeaponReplicated
                or (char.GetCurrentWeapon and char:GetCurrentWeapon())
            if Valid(curW) then
                targetWeapons[curW] = true
            end

            pcall(function()
                if wm.GetAllInventoryWeaponList then
                    local list = wm:GetAllInventoryWeaponList(false)
                    if list then
                        for _, w in pairs(list) do
                            if Valid(w) then
                                targetWeapons[w] = true
                            end
                        end
                    end
                end
                for slot = 1, 3 do
                    if wm.GetInventoryWeaponByPropSlot then
                        local w = wm:GetInventoryWeaponByPropSlot(slot)
                        if Valid(w) then
                            targetWeapons[w] = true
                        end
                    end
                end
            end)

            local enabled = (_G.LexusConfig.SmallCrosshairEnabled == true)
            local currentState = tostring(enabled) .. "_" .. tostring(curW)
            if not force and currentState == _G.LastCrosshairState then
                return
            end
            _G.LastCrosshairState = currentState

            for w, _ in pairs(targetWeapons) do
                local entity = w.ShootWeaponEntityComp
                    or w.ShootWeaponComponent
                    or w.STExtraShootWeaponComponent
                    or (w.GetShootWeaponComponent and w:GetShootWeaponComponent())
                if Valid(entity) then
                    if not crosshairOriginalCache[entity] then
                        crosshairOriginalCache[entity] = {
                            GameDeviationAccuracy = entity.GameDeviationAccuracy,
                            GameDeviationFactor = entity.GameDeviationFactor,
                            ShotGunHorizontalSpread = entity.ShotGunHorizontalSpread,
                            ShotGunVerticalSpread = entity.ShotGunVerticalSpread,
                            DeviationMultiplier = entity.DeviationMultiplier,
                        }
                    end
                    local orig = crosshairOriginalCache[entity]
                    if not enabled then
                        if orig then
                            if orig.GameDeviationAccuracy ~= nil then
                                entity.GameDeviationAccuracy = orig.GameDeviationAccuracy
                            end
                            if orig.GameDeviationFactor ~= nil then
                                entity.GameDeviationFactor = orig.GameDeviationFactor
                            end
                            if orig.ShotGunHorizontalSpread ~= nil then
                                entity.ShotGunHorizontalSpread = orig.ShotGunHorizontalSpread
                            end
                            if orig.ShotGunVerticalSpread ~= nil then
                                entity.ShotGunVerticalSpread = orig.ShotGunVerticalSpread
                            end
                            if orig.DeviationMultiplier ~= nil then
                                entity.DeviationMultiplier = orig.DeviationMultiplier
                            end
                        end
                    else
                        if orig and orig.GameDeviationAccuracy then
                            entity.GameDeviationAccuracy = orig.GameDeviationAccuracy * 0.35
                        end
                        if orig and orig.GameDeviationFactor then
                            entity.GameDeviationFactor = orig.GameDeviationFactor * 0.35
                        end
                        if orig and orig.ShotGunHorizontalSpread then
                            entity.ShotGunHorizontalSpread = orig.ShotGunHorizontalSpread * 0.45
                        end
                        if orig and orig.ShotGunVerticalSpread then
                            entity.ShotGunVerticalSpread = orig.ShotGunVerticalSpread * 0.45
                        end
                        if orig and orig.DeviationMultiplier ~= nil then
                            entity.DeviationMultiplier = orig.DeviationMultiplier * 0.35
                        end
                    end
                end
            end
        end)
    end
    _G.ApplySmallCrosshair = ApplySmallCrosshair

    pcall(function()
        local ticker = require("common.time_ticker")
        if ticker and type(ticker.AddTimerOnce) == "function" then
            -- loop
            local function loop()
                pcall(function()
                    if _G.LexusConfig and _G.LexusConfig.SmallCrosshairEnabled and _G.ApplySmallCrosshair then
                        _G.ApplySmallCrosshair()
                    end
                end)
                pcall(ticker.AddTimerOnce, 1.0, loop)
            end
            pcall(ticker.AddTimerOnce, 1.0, loop)
        end
    end)
end)()

