    local function log(msg)
        pcall(function()
            local ts = "?"
            pcall(function()
                ts = os.date("%H:%M:%S")
            end)
            table.insert(_SKIN_BUF, ts .. " " .. tostring(msg))
            if #_SKIN_BUF > 200 then
                table.remove(_SKIN_BUF, 1)
            end
            _skinFlush()
        end)
